import { useState, useEffect, useRef } from "react";

// Hover keepalive: how long the delete X / add-note affordance stays revealed
// after the cursor leaves a highlight, so the user has time to travel onto the
// button before it disappears. Bumped from 100ms → 300ms so the hover-revealed
// X is comfortably reachable.
const HOVER_HIDE_DELAY_MS = 300;

// Minimum mouse-hold duration (mousedown → mouseup) before a drag-select is
// promoted to a highlight. Filters out the tiny accidental drags that would
// otherwise paint a highlight from the slightest mouse twitch.
const HIGHLIGHT_MIN_PRESS_MS = 100;

const createNoteId = () => {
  try {
    if (typeof crypto !== "undefined" && typeof crypto.randomUUID === "function") {
      return crypto.randomUUID();
    }
  } catch (error) { /* ignore */ }
  return `note-${Date.now()}-${Math.abs(Math.floor(Math.random() * 1_000_000))}`;
};

// Merge adjacent rects on the same line (handles inline elements like <strong>, <em>).
export const mergeRects = (rects) => {
  if (rects.length <= 1) return rects;
  const sorted = [...rects].sort((a, b) => {
    const yDiff = a.y - b.y;
    if (Math.abs(yDiff) > 5) return yDiff;
    return a.x - b.x;
  });
  const merged = [];
  let current = { ...sorted[0] };
  for (let i = 1; i < sorted.length; i++) {
    const next = sorted[i];
    const sameLine = Math.abs(next.y - current.y) < 5;
    const adjacent = next.x <= current.x + current.width + 3;
    if (sameLine && adjacent) {
      const newRight = Math.max(current.x + current.width, next.x + next.width);
      current.width = newRight - current.x;
      current.height = Math.max(current.height, next.height);
    } else {
      merged.push(current);
      current = { ...next };
    }
  }
  merged.push(current);
  return merged;
};

// Elements a highlight must never paint over — answer blanks meant to be filled
// in. `[data-answer-blank]` marks a whole blank unit (e.g. InlineBlank's number
// badge + its <input> wrapper); bare form controls are the fallback for blanks
// not yet wrapped with that marker, so at minimum the input box is excluded.
const ANSWER_BLANK_SELECTOR = "[data-answer-blank], input, textarea, select";

// Split a range into sub-ranges that skip over any answer-blank elements it
// spans. A highlight crossing a blank then renders as separate segments on
// either side of the fill-in box instead of painting across it. Returns the
// original range unchanged when it spans no blanks.
const splitRangeAroundBlanks = (range) => {
  const root = range.commonAncestorContainer;
  const rootEl = root instanceof Element ? root : root?.parentElement;
  if (!rootEl) return [range];

  const all = Array.from(rootEl.querySelectorAll(ANSWER_BLANK_SELECTOR)).filter(
    (el) => range.intersectsNode(el)
  );
  // Keep only the outermost blanks, so an <input> already covered by a
  // [data-answer-blank] wrapper doesn't get processed twice.
  const blanks = all.filter(
    (el) => !all.some((other) => other !== el && other.contains(el))
  );
  if (blanks.length === 0) return [range];

  const subRanges = [];
  let cursorNode = range.startContainer;
  let cursorOffset = range.startOffset;

  for (const blank of blanks) {
    try {
      const seg = document.createRange();
      seg.setStart(cursorNode, cursorOffset);
      seg.setEndBefore(blank);
      if (!seg.collapsed) subRanges.push(seg);
    } catch (error) {
      /* odd boundary — skip this segment */
    }
    try {
      const after = document.createRange();
      after.setStartAfter(blank);
      cursorNode = after.startContainer;
      cursorOffset = after.startOffset;
    } catch (error) {
      cursorNode = null; // can't advance past this blank; stop here
      break;
    }
  }

  if (cursorNode) {
    try {
      const tail = document.createRange();
      tail.setStart(cursorNode, cursorOffset);
      tail.setEnd(range.endContainer, range.endOffset);
      if (!tail.collapsed) subRanges.push(tail);
    } catch (error) {
      /* ignore */
    }
  }

  return subRanges.length > 0 ? subRanges : [range];
};

// Surface-relative {x,y,width,height} rects for a range, with answer-blank
// footprints removed (via splitRangeAroundBlanks). Shared by highlight creation
// and reflow re-anchoring so the blank stays carved out across font/zoom/resize.
export const collectSurfaceRects = (range, surfaceElement) => {
  if (!range || !surfaceElement) return [];
  const containerRect = surfaceElement.getBoundingClientRect();
  const scrollLeft = surfaceElement.scrollLeft || 0;
  const scrollTop = surfaceElement.scrollTop || 0;

  const rawRects = [];
  for (const sub of splitRangeAroundBlanks(range)) {
    for (const rect of Array.from(sub.getClientRects())) {
      if (rect.width <= 0 || rect.height <= 0) continue;
      rawRects.push({
        x: rect.left - containerRect.left + scrollLeft,
        y: rect.top - containerRect.top + scrollTop,
        width: rect.width,
        height: rect.height,
      });
    }
  }
  return rawRects;
};

const createHighlightEntryFromRange = (range, surfaceElement) => {
  if (!range || !surfaceElement) return null;

  const surfaceId =
    surfaceElement.getAttribute("data-highlight-surface-id") ||
    "exam-main-surface";

  const rects = mergeRects(collectSurfaceRects(range, surfaceElement));
  if (rects.length === 0) return null;

  return {
    id: createNoteId(),
    rects,
    text: range.toString(),
    createdAt: Date.now(),
    surfaceId,
  };
};

// A clamped highlight must contain at least this many non-whitespace chars,
// else it's discarded as empty / trivially small (e.g. a selection that started
// at a zone's trailing edge and spilled into the next zone, leaving nothing
// meaningful behind after clamping). Tune up to be stricter.
const HIGHLIGHT_MIN_CHARS = 2;

// Display values that flow inline — we climb *past* these when looking for the
// block-level container that visually bounds a run of text. Everything else
// (block, flex, grid, list-item, table-cell, …) is treated as a zone boundary.
const INLINE_DISPLAYS = new Set([
  "inline",
  "inline-block",
  "inline-flex",
  "inline-grid",
  "contents",
  "ruby",
  "ruby-base",
  "ruby-text",
]);

/**
 * Resolve the "highlight zone" a node sits in — the container a highlight is
 * not allowed to escape. Resolution order (strict, predictable, not smart):
 *   1. The nearest ancestor carrying an explicit `[data-highlight-zone]`
 *      attribute, if any — the designated escape hatch / override.
 *   2. Otherwise the nearest block-level (non-inline) ancestor: the visual
 *      paragraph / table cell / list item / MCQ option that bounds the text.
 *   3. Falls back to the surface itself if nothing block-level is found.
 */
const resolveHighlightZone = (node, surfaceElement) => {
  let el = node instanceof Element ? node : node?.parentElement;
  if (!el || !surfaceElement.contains(el)) return surfaceElement;

  const explicit = el.closest("[data-highlight-zone]");
  if (explicit && surfaceElement.contains(explicit)) return explicit;

  let cur = el;
  while (cur && cur !== surfaceElement) {
    let display = "block";
    try {
      display = window.getComputedStyle(cur).display;
    } catch (error) {
      /* detached / cross-doc node — treat as a boundary */
    }
    if (!INLINE_DISPLAYS.has(display)) return cur;
    cur = cur.parentElement;
  }
  return surfaceElement;
};

const isBlockLevelElement = (el) => {
  let display = "block";
  try {
    display = window.getComputedStyle(el).display;
  } catch (error) {
    return false;
  }
  return !INLINE_DISPLAYS.has(display);
};

/**
 * Find the first block-level element *inside* `zone` whose start lies within
 * `range` — i.e. the first block the selection crosses *into*. Used to stop a
 * highlight at a block boundary even when the start and end share one zone.
 *
 * This is the case that pure ancestor-zone clamping misses: malformed prompt
 * HTML like `<p>text<div><table>…</table></div></p>` auto-closes the <p>, so
 * the text becomes a loose node sibling to the table inside one big container.
 * The container "contains" both, so zone-escape clamping does nothing — but the
 * table is a block the highlight must not bleed into.
 */
const firstBlockBarrierInRange = (range, zone) => {
  const candidates = zone.querySelectorAll("*");
  for (const el of candidates) {
    if (!isBlockLevelElement(el)) continue;
    let position;
    try {
      // comparePoint((el, 0)): -1 before range start, 0 within, 1 after end.
      // An ancestor of the start resolves to -1 (its start precedes the start),
      // so only blocks the selection genuinely crosses into score 0.
      position = range.comparePoint(el, 0);
    } catch (error) {
      continue;
    }
    if (position === 0) return el;
  }
  return null;
};

/**
 * Clamp a raw selection Range to the zone its *start* (document-order first
 * point) sits in. Two barriers, both pulling the *end* back:
 *   1. If the end escaped the start's zone, snap it to the zone's trailing edge
 *      (cross-paragraph / cross-cell / cross-option case).
 *   2. If a block-level element begins inside the selection, stop before it
 *      (loose-text-then-block case — see firstBlockBarrierInRange).
 * So a highlight can never span paragraphs, cells, options, or bleed into a
 * following table/div. Returns a fresh (cloned) Range.
 */
const clampRangeToZone = (range, surfaceElement) => {
  const clamped = range.cloneRange();
  const zone = resolveHighlightZone(range.startContainer, surfaceElement);
  if (!zone || zone === surfaceElement) return clamped; // nothing to clamp to

  // Barrier 1: end left the zone entirely.
  if (!zone.contains(range.endContainer)) {
    try {
      clamped.setEnd(zone, zone.childNodes.length);
    } catch (error) {
      /* setEnd can throw on odd boundaries; keep the unclamped end */
    }
  }

  // Barrier 2: a block-level element starts inside the (possibly already
  // clamped) selection — stop before it.
  const barrier = firstBlockBarrierInRange(clamped, zone);
  if (barrier) {
    try {
      clamped.setEndBefore(barrier);
    } catch (error) {
      /* ignore — keep the current end */
    }
  }

  return clamped;
};

/**
 * Hover detection + drag-to-highlight + click-to-toggle-note.
 *
 * No selection menu — finishing a text selection immediately creates a
 * highlight. Clicking a highlight toggles its linked note (creates one if
 * missing). Clicking outside any highlight closes all open editors.
 */
export const useHighlightInteraction = ({
  highlightsForActiveContext,
  notesForActiveContext,
  activeNoteContextKey,
  addHighlightForContext,
  setNoteCollapsedForContext,
  createNoteForHighlightInContext,
}) => {
  const [hoveredHighlightId, setHoveredHighlightId] = useState(null);

  // Keep refs to the latest highlights/notes so document listeners don't need
  // to re-bind on every keystroke (note content updates `notesForActiveContext`
  // on every change).
  const highlightsRef = useRef(highlightsForActiveContext);
  highlightsRef.current = highlightsForActiveContext;
  const notesRef = useRef(notesForActiveContext);
  notesRef.current = notesForActiveContext;
  const activeContextRef = useRef(activeNoteContextKey);
  activeContextRef.current = activeNoteContextKey;

  // Press-start timestamp lives in a ref, not the effect closure: the mouseup
  // effect re-binds on every render (its `add*`/`set*` deps are recreated each
  // render upstream), which would otherwise reset a closure-local timestamp to
  // 0 mid-press — long holds spanning a re-render would lose their start time
  // and fail the duration gate.
  const pressStartedAtRef = useRef(0);

  // When a drag-select creates a highlight, the cursor is left sitting on top
  // of it — the next mouse-move would immediately flag it as hovered and pop
  // the add-note / delete toolbar right in the user's face at the moment of
  // creation. We suppress hover for that one highlight id until the cursor
  // leaves it once, so the toolbar is only ever a *deliberate* re-hover.
  const suppressHoverForIdRef = useRef(null);

  // Set when a mouseup-drag spawned a highlight, so the `click` the browser
  // fires from that same gesture doesn't immediately open the new highlight's
  // note editor. MUST be a ref, not an effect-closure local: the click/mouseup
  // effect re-binds on every render (its `add*`/`set*` deps are recreated
  // upstream), which would reset a closure local to `false` between mouseup and
  // click and let the editor pop intermittently.
  const suppressNextClickRef = useRef(false);

  // ── Hover detection via RAF ──
  useEffect(() => {
    if (typeof document === "undefined" || typeof window === "undefined") {
      return undefined;
    }

    const highlights = Array.isArray(highlightsForActiveContext)
      ? highlightsForActiveContext
      : [];

    if (highlights.length === 0) {
      setHoveredHighlightId((prev) => (prev == null ? prev : null));
      return undefined;
    }

    let rafId = null;
    let hideTimeoutId = null;

    const clearHideTimeout = () => {
      if (hideTimeoutId !== null) {
        window.clearTimeout(hideTimeoutId);
        hideTimeoutId = null;
      }
    };

    const resetHoverState = () => {
      clearHideTimeout();
      setHoveredHighlightId((prev) => (prev == null ? prev : null));
    };

    const scheduleHide = () => {
      clearHideTimeout();
      hideTimeoutId = window.setTimeout(() => {
        hideTimeoutId = null;
        setHoveredHighlightId((prev) => (prev == null ? prev : null));
      }, HOVER_HIDE_DELAY_MS);
    };

    const detectHighlightAtPoint = (clientX, clientY) => {
      for (let index = highlights.length - 1; index >= 0; index -= 1) {
        const highlight = highlights[index];
        if (!highlight || !Array.isArray(highlight.rects) || highlight.rects.length === 0) continue;
        const selector = highlight.surfaceId
          ? `[data-highlight-surface-id="${highlight.surfaceId}"]`
          : "[data-highlight-surface-id='exam-main-surface']";
        const surfaceElement = document.querySelector(selector);
        if (!surfaceElement) continue;
        const surfaceRect = surfaceElement.getBoundingClientRect();
        const scrollLeft = surfaceElement.scrollLeft || 0;
        const scrollTop = surfaceElement.scrollTop || 0;
        const relativeX = clientX - surfaceRect.left + scrollLeft;
        const relativeY = clientY - surfaceRect.top + scrollTop;
        const marginX = 5;
        const marginTop = 9;
        const marginBottom = 9;
        const intersects = highlight.rects.some((rect) => {
          if (!rect) return false;
          return (
            relativeX >= rect.x - marginX &&
            relativeX <= rect.x + rect.width + marginX &&
            relativeY >= rect.y - marginTop &&
            relativeY <= rect.y + rect.height + marginBottom
          );
        });
        if (intersects) return highlight.id;
      }
      return null;
    };

    const handlePointerMove = (event) => {
      const { clientX, clientY, buttons = 0 } = event;
      const eventTarget = event.target;
      if (rafId !== null) cancelAnimationFrame(rafId);

      // Cursor over a hover-revealed affordance (delete X or add-note button) —
      // treat as still hovering its parent highlight, even when mid-click.
      // Without this the button vanishes between mousedown and mouseup and the
      // click never registers, and the affordance would fade while the user is
      // travelling onto it.
      const deleteHighlightId =
        eventTarget instanceof Element
          ? eventTarget
              .closest('[data-highlight-delete="true"],[data-highlight-addnote="true"]')
              ?.getAttribute('data-highlight-id')
          : null;

      if (buttons !== 0) {
        if (deleteHighlightId) return; // keep hover alive during the click
        clearHideTimeout();
        rafId = window.requestAnimationFrame(() => {
          setHoveredHighlightId((prev) => (prev == null ? prev : null));
        });
        return;
      }

      rafId = window.requestAnimationFrame(() => {
        if (deleteHighlightId) {
          clearHideTimeout();
          setHoveredHighlightId((prev) => (prev === deleteHighlightId ? prev : deleteHighlightId));
          return;
        }
        const hoveredId = detectHighlightAtPoint(clientX, clientY);

        // Release the post-creation suppression the moment the cursor is no
        // longer on the just-created highlight (moved off it or onto another).
        if (suppressHoverForIdRef.current && hoveredId !== suppressHoverForIdRef.current) {
          suppressHoverForIdRef.current = null;
        }

        if (hoveredId && hoveredId !== suppressHoverForIdRef.current) {
          clearHideTimeout();
          setHoveredHighlightId((prev) => (prev === hoveredId ? prev : hoveredId));
        } else {
          scheduleHide();
        }
      });
    };

    const handlePointerLeave = () => {
      if (rafId !== null) {
        cancelAnimationFrame(rafId);
        rafId = null;
      }
      resetHoverState();
    };

    document.addEventListener("mousemove", handlePointerMove);
    document.addEventListener("mouseleave", handlePointerLeave);
    window.addEventListener("blur", handlePointerLeave);

    return () => {
      document.removeEventListener("mousemove", handlePointerMove);
      document.removeEventListener("mouseleave", handlePointerLeave);
      window.removeEventListener("blur", handlePointerLeave);
      if (rafId !== null) cancelAnimationFrame(rafId);
      clearHideTimeout();
    };
  }, [highlightsForActiveContext]);

  // Clear hovered highlight if it disappears.
  useEffect(() => {
    if (!hoveredHighlightId) return;
    const highlights = Array.isArray(highlightsForActiveContext)
      ? highlightsForActiveContext
      : [];
    const stillExists = highlights.some((h) => h?.id === hoveredHighlightId);
    if (!stillExists) setHoveredHighlightId(null);
  }, [hoveredHighlightId, highlightsForActiveContext]);

  // ── Drag-to-highlight + click-to-toggle-note + click-outside-saves ──
  //
  // Both flows share state via `suppressNextClickRef`: if mouseup spawned a
  // highlight from a drag-select, the click that follows would otherwise
  // re-toggle the brand-new highlight's note. Skip that click.
  useEffect(() => {
    if (typeof document === "undefined") return undefined;

    // Boundary-aware pipeline: raw Range → zone the selection STARTED in →
    // clamp the end down to that zone → discard if empty/trivial → create.
    const autoHighlight = () => {
      if (typeof window === "undefined") return false;
      const selection = window.getSelection();
      if (!selection || selection.rangeCount === 0 || selection.isCollapsed) return false;
      const range = selection.getRangeAt(0);
      if (!range || range.collapsed) return false;

      // Anchor everything on the selection's START (document-order first point):
      // that's the zone the highlight belongs to and the surface it lives in.
      const startNode = range.startContainer;
      const startElement = startNode instanceof Element ? startNode : startNode?.parentElement;

      const examSurface = document.querySelector("[data-exam-surface='true']");
      if (examSurface && startElement && !examSurface.contains(startElement)) return false;

      const surfaceElement =
        startElement?.closest("[data-highlight-surface-id]") ||
        document.querySelector("[data-highlight-surface-id='exam-main-surface']");
      if (!surfaceElement) return false;

      // Clamp to the start's zone, then reject anything empty or trivially small.
      const clampedRange = clampRangeToZone(range, surfaceElement);
      if (!clampedRange || clampedRange.collapsed) return false;
      if (clampedRange.toString().trim().length < HIGHLIGHT_MIN_CHARS) return false;

      const highlightEntry = createHighlightEntryFromRange(clampedRange, surfaceElement);
      if (!highlightEntry) return false;

      addHighlightForContext(activeContextRef.current, highlightEntry);
      // Don't let the hover toolbar pop the instant this highlight is born —
      // keep it suppressed until the cursor leaves and returns deliberately.
      suppressHoverForIdRef.current = highlightEntry.id;
      setHoveredHighlightId((prev) => (prev == null ? prev : null));
      selection.removeAllRanges();
      return true;
    };

    // Press-duration gate: only a deliberate hold-then-release becomes a
    // highlight. A flick shorter than HIGHLIGHT_MIN_PRESS_MS — the slightest
    // accidental drag — is ignored so it can't aggressively paint a highlight.
    // The timestamp is held in pressStartedAtRef (survives re-renders), not a
    // closure local, so a long press that spans a re-render keeps its start.
    const handlePressStart = () => {
      pressStartedAtRef.current = Date.now();
      // Start of a fresh gesture: any prior gesture's suppress flag should have
      // been consumed by its own click already. Clearing here prevents a stale
      // `true` (e.g. a drag that never produced a click) from swallowing this
      // gesture's click.
      suppressNextClickRef.current = false;
    };
    const heldLongEnough = () => {
      const startedAt = pressStartedAtRef.current;
      return startedAt > 0 && Date.now() - startedAt >= HIGHLIGHT_MIN_PRESS_MS;
    };

    const handleMouseUp = () => {
      if (heldLongEnough() && autoHighlight()) suppressNextClickRef.current = true;
      pressStartedAtRef.current = 0;
    };
    const handleTouchEnd = () => {
      if (heldLongEnough() && autoHighlight()) suppressNextClickRef.current = true;
      pressStartedAtRef.current = 0;
    };

    document.addEventListener("mousedown", handlePressStart);
    document.addEventListener("touchstart", handlePressStart);
    document.addEventListener("mouseup", handleMouseUp);
    document.addEventListener("touchend", handleTouchEnd);

    const cleanup = () => {
      document.removeEventListener("mousedown", handlePressStart);
      document.removeEventListener("touchstart", handlePressStart);
      document.removeEventListener("mouseup", handleMouseUp);
      document.removeEventListener("touchend", handleTouchEnd);
    };

    // The mouseup and click handlers coordinate through `suppressNextClickRef`
    // (a ref, so the flag survives the effect re-binding between the two events).
    const detectHighlightAtPoint = (clientX, clientY) => {
      const highlights = Array.isArray(highlightsRef.current) ? highlightsRef.current : [];
      for (let index = highlights.length - 1; index >= 0; index -= 1) {
        const highlight = highlights[index];
        if (!highlight || !Array.isArray(highlight.rects) || highlight.rects.length === 0) continue;
        const selector = highlight.surfaceId
          ? `[data-highlight-surface-id="${highlight.surfaceId}"]`
          : "[data-highlight-surface-id='exam-main-surface']";
        const surfaceElement = document.querySelector(selector);
        if (!surfaceElement) continue;
        const surfaceRect = surfaceElement.getBoundingClientRect();
        const scrollLeft = surfaceElement.scrollLeft || 0;
        const scrollTop = surfaceElement.scrollTop || 0;
        const relativeX = clientX - surfaceRect.left + scrollLeft;
        const relativeY = clientY - surfaceRect.top + scrollTop;
        const intersects = highlight.rects.some((rect) => {
          if (!rect) return false;
          return (
            relativeX >= rect.x &&
            relativeX <= rect.x + rect.width &&
            relativeY >= rect.y &&
            relativeY <= rect.y + rect.height
          );
        });
        if (intersects) return highlight.id;
      }
      return null;
    };

    const collapseAllExpanded = (exceptId = null) => {
      const notes = Array.isArray(notesRef.current) ? notesRef.current : [];
      notes.forEach((note) => {
        if (note && !note.isCollapsed && note.id !== exceptId) {
          setNoteCollapsedForContext?.(activeContextRef.current, note.id, true);
        }
      });
    };

    const handleClick = (event) => {
      if (suppressNextClickRef.current) {
        suppressNextClickRef.current = false;
        return;
      }

      const target = event.target;
      if (target instanceof Element && target.closest('[data-note-id]')) return;
      if (target instanceof Element && target.closest('[data-sticky-preview="true"]')) return;
      if (target instanceof Element && target.closest('[data-highlight-delete="true"]')) return;
      if (target instanceof Element && target.closest('[data-highlight-addnote="true"]')) return;

      const isTextInput =
        target instanceof Element &&
        target.closest('input, textarea, select, [contenteditable="true"]');

      const selection = typeof window !== "undefined" ? window.getSelection() : null;
      if (selection && selection.rangeCount > 0 && !selection.isCollapsed) return;

      const clickedHighlightId = detectHighlightAtPoint(event.clientX, event.clientY);

      // Label-induced synthetic click: clicking the text inside a <label> fires
      // both a click on the text AND a browser-dispatched click on the wrapped
      // <input>. The original click already toggled; this synthetic input
      // click would fall through and collapse — undoing it. Skip.
      if (isTextInput && clickedHighlightId) return;

      if (clickedHighlightId) {
        const notes = Array.isArray(notesRef.current) ? notesRef.current : [];
        const linkedNote = notes.find((n) => n?.highlightId === clickedHighlightId);
        if (linkedNote) {
          const nextCollapsed = !linkedNote.isCollapsed;
          setNoteCollapsedForContext?.(activeContextRef.current, linkedNote.id, nextCollapsed);
          if (!nextCollapsed) collapseAllExpanded(linkedNote.id);
        } else {
          const highlights = Array.isArray(highlightsRef.current) ? highlightsRef.current : [];
          const highlight = highlights.find((h) => h.id === clickedHighlightId);
          if (highlight) {
            collapseAllExpanded();
            createNoteForHighlightInContext?.(activeContextRef.current, highlight);
          }
        }
      } else {
        collapseAllExpanded();
      }
    };

    document.addEventListener("click", handleClick);

    return () => {
      cleanup();
      document.removeEventListener("click", handleClick);
    };
  }, [addHighlightForContext, setNoteCollapsedForContext, createNoteForHighlightInContext]);

  return {
    hoveredHighlightId,
  };
};
