import React from "react";

const RecoveryBanner = ({ isRecovering }) => {
  if (!isRecovering) return null;

  return (
    <div className="fixed top-0 left-0 right-0 z-modal flex items-center justify-center bg-amber-500 px-4 py-2.5 shadow-lg">
      <div className="flex items-center gap-3 text-white">
        <svg className="h-4 w-4 animate-spin" viewBox="0 0 24 24" fill="none">
          <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
          <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
        </svg>
        <span className="text-sm font-semibold">
          Đang khôi phục bài nộp của bạn từ phiên trước. Hãy giữ nguyên trang, hệ thống sẽ tự động đồng bộ...
        </span>
      </div>
      <p className="ml-4 text-xs text-amber-100">
        Đừng tắt trang hoặc F5.
      </p>
    </div>
  );
};

export default RecoveryBanner;
