import React, { useState, useEffect, useRef, useMemo } from "react";
import { getExamDefinition } from "../../controller/useFirebase";
import examTrackingService from '../../controller/examTrackingService';
import { motion } from "framer-motion";

const successMessage =
  "Microphone access granted. You can start the test.";
const errorMessage =
  "We need microphone access for the speaking section. Please allow it in your browser settings and try again.";

const DEFAULT_DURATIONS = {
  listening: "15 mins",
  reading: "25 mins",
  writing: "15 mins",
  grammar: "15 mins",
  speaking: "15 mins",
};

const CONTAINER_VARIANTS = {
  hidden: { opacity: 0, y: 20 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.6, staggerChildren: 0.1 } },
};

const ITEM_VARIANTS = {
  hidden: { opacity: 0, y: 10 },
  visible: { opacity: 1, y: 0, transition: { duration: 0.4 } },
};

const WelcomePage = ({ setStep, incomingExamCode }) => {
  const [examDefinition, setExamDefinition] = useState({});
  const [microphoneStatus, setMicrophoneStatus] = useState({ error: "", success: false });
  const [requestingPermission, setRequestingPermission] = useState(false);
  const audioRef = useRef(null);
  const [isAudioPlaying, setIsAudioPlaying] = useState(false);
  const onAudioEnded = () => setIsAudioPlaying(false);
  useEffect(() => {
    // Track phase welcome
    examTrackingService.setPhase('welcome');
    examTrackingService.track('welcomeView', {});

    const cleanup = () => {
      if (audioRef.current) {
        try {
          audioRef.current.pause();
          audioRef.current.currentTime = 0;
          audioRef.current.removeEventListener('ended', onAudioEnded);
        } catch (e) {
          // ignore
        }
      }
    };
    return cleanup;
  }, []);

  const SECTION_ITEMS = useMemo(() => [
    {
      key: "listening",
      label: "Listening",
      duration: DEFAULT_DURATIONS.listening,
      icon: (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          className="h-6 w-6 mb-2 !h-13 !w-13 fill-current text-orange-500"
          viewBox="0 0 48 48"
          data-test-id="listening-icon"
        >
          <path d="M34.2 8.3c-3.1-2-6.6-3-10.2-3 0 0 0 0 0 0 -3.6 0-7.1 1-10.2 3C6.2 13.2 2.4 22.9 3.4 34.9v0 .2s0 0 0 0c0 .1 0 .1 0 .2 0 2 .8 3.8 2.2 5.2 1.4 1.4 3.3 2.2 5.2 2.2h.9v-7.6 -.1 0 -.1V28v-.1 -.1h-.1 -.9c-2 0-3.8.8-5.2 2.2 -.3.3-.5.6-.8.9 0 0-.1.1-.1.1 0-10.7 4.2-17.9 9.8-21.5 2.9-1.8 6.1-2.8 9.4-2.8 3.2 0 6.5.9 9.4 2.8 0 0 0 0 0 0s.1 0 .1.1c0 0 0 0 0 0C38.9 13.2 43 20.3 43 31s0-.1-.1-.1c-.2-.3-.5-.6-.7-.9 -.1-.1-.1-.1-.2-.1 0 0-.1-.1-.1-.1 -1.4-1.2-3.1-1.9-5-1.9H36V35v.1 0 .1 7.6h.9c2 0 3.8-.8 5.2-2.2 1.4-1.4 2.2-3.3 2.2-5.2 0-.1 0-.2 0-.3 1.3-12.2-2.5-21.9-10.1-26.8ZM5.4 33.4s0-.1 0-.1c.3-.8.7-1.5 1.3-2.1 .8-.8 1.8-1.3 3-1.6 .1 0 .1 0 .2 0s.1 0 .2 0 .1 0 .2 0V35v0 0 .1 6c-1.3-.1-2.5-.7-3.5-1.7 -1.1-1.1-1.7-2.6-1.7-4.1 0-.1 0-.1 0-.2 0 0 0-.1 0-.1s0 0 0 0 0-.1 0-.1c0-.5.1-.9.3-1.4 0 0 0-.1 0-.1Zm32.4 1.7v0 0V35v-5.5c1.3.1 2.5.7 3.4 1.7v0c1 1 1.6 2.4 1.7 3.8 0 0 0 .1 0 .1s0 0 0 0 0 0 0 .1c0 0 0 .1 0 .1 0 1.5-.6 3-1.7 4.1 -.9.9-2.2 1.5-3.5 1.7v-6Z"></path>
        </svg>
      ),
    },
    {
      key: "reading",
      label: "Reading",
      duration: DEFAULT_DURATIONS.reading,
      icon: (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          className="h-6 w-6 mb-2 !h-13 !w-13 fill-current text-orange-500"
          viewBox="0 0 48 48"
          data-test-id="reading-icon"
        >
          <path d="M41.3 9V5.3L24 9 6.7 5.3V9H3.3v31.2h41.4V9h-3.4ZM24 9.7v0 0 0Zm.7.5L40 6.9v27.5l-15.3 4.3V10.2ZM8 6.9l15.3 3.3v28.5L8 34.4V6.9Zm-3.4 3.4h2.2v25.1l12.5 3.5H4.6V10.3Zm38.8 28.6H28.7l12.5-3.5V10.3h2.2v28.6Z"></path>
        </svg>
      ),
    },
    {
      key: "writing",
      label: "Writing",
      duration: DEFAULT_DURATIONS.writing,
      icon: (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          className="h-6 w-6 mb-2 !h-13 !w-13 fill-current text-orange-500"
          viewBox="0 0 48 48"
          data-test-id="writing-icon"
        >
          <path d="M41.9 5.2c-.2-.6-.7-1-1.4-1.2l-1.2-.5c-.6-.2-1.3-.3-2 0 -.6.2-1.1.6-1.4 1.1v0l-2.5 4.8H6.7c-.4 0-.8.3-.8.7V44c0 .4.4.7.8.7H35c.4 0 .8-.3.8-.7V18.7l6-11.7v0s0 0 0 0v-.1 0c.4-.6.4-1.2.1-1.7Zm-7.7 38.1H7.5V10.8h25.4l-8.7 16.9c0 .1 0 .1 0 .1l-.8 6.5v.1c0 .3.2.6.5.7 0 0 .1 0 .1 0H12.1c-.4 0-.8.3-.8.7 0 .4.4.7.8.7h17.5c.4 0 .8-.3.8-.7 0-.4-.4-.7-.8-.7h-5.2c.1 0 .3-.1.4-.2l5.1-4.8s.1-.1.1-.1l4.2-8.2v21.5ZM25.6 29l2.3.9 -2.7 2.5 .4-3.4Zm3.3-.3L26 27.6l9.9-19.3 2.9 1.1 -9.9 19.3ZM40.4 6.3V6.29v0l-.9 1.8 -2.9-1.1 .9-1.7v0 0c.1-.3.3-.4.5-.5v0c.2-.1.5-.1.7 0l1.2.5c.2.1.4.2.5.4v0c.1.2.1.4-.001.6Z"></path>
          <path d="M12.1 18.9h16c.4 0 .8-.3.8-.7 0-.4-.4-.7-.8-.7h-16c-.4 0-.8.3-.8.7 0 .4.4.7.8.7Z"></path>
          <path d="M12.1 27.8h10.4c.4 0 .8-.3.8-.7 0-.4-.4-.7-.8-.7H12.1c-.4 0-.8.3-.8.7 0 .4.4.7.8.7Z"></path>
        </svg>
      ),
    },
    {
      key: "grammar",
      label: "Grammar & Vocabulary",
      duration: DEFAULT_DURATIONS.grammar,
      icon: (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          className="h-6 w-6 mb-2 !h-13 !w-13 fill-current text-orange-500"
          viewBox="0 0 48 48"
          data-test-id="grammar-icon"
        >
          <path d="M9 8h30v4H9V8zm0 8h30v4H9v-4zm0 8h30v4H9v-4zm-4 12c0-2.2 1.8-4 4-4h26c2.2 0 4 1.8 4 4v8c0 2.2-1.8 4-4 4H9c-2.2 0-4-1.8-4-4v-8zm4-2c-1.1 0-2 .9-2 2v8c0 1.1.9 2 2 2h26c1.1 0 2-.9 2-2v-8c0-1.1-.9-2-2-2H9z"></path>
        </svg>
      ),
    },
    {
      key: "speaking",
      label: "Speaking",
      duration: DEFAULT_DURATIONS.speaking,
      icon: (
        <svg
          xmlns="http://www.w3.org/2000/svg"
          className="h-6 w-6 mb-2 !h-13 !w-13 fill-current text-orange-500"
          viewBox="0 0 48 48"
          data-test-id="speaking-icon"
        >
          <path d="M3.9 21c-.3 0-.6.3-.6.6v4.8c0 .3.3.6.6.6s.6-.3.6-.6v-4.8c0-.4-.3-.6-.6-.6Z"></path>
          <path d="M44.1 21c-.3 0-.6.3-.6.6v4.8c0 .3.3.6.6.6s.6-.3.6-.6v-4.8c0-.4-.3-.6-.6-.6Z"></path>
          <path d="M13.9 21c-.3 0-.6.3-.6.6v4.8c0 .3.3.6.6.6s.6-.3.6-.6v-4.8c.1-.4-.2-.6-.6-.6Z"></path>
          <path d="M34.1 21c-.3 0-.6.3-.6.6v4.8c0 .3.3.6.6.6s.6-.3.6-.6v-4.8c0-.4-.3-.6-.6-.6Z"></path>
          <path d="M7.2 18.1c-.3 0-.6.3-.6.6v10.5c0 .3.3.6.6.6s.6-.3.6-.6V18.7c.1-.3-.2-.6-.6-.6Z"></path>
          <path d="M40.8 18.1c-.3 0-.6.3-.6.6v10.5c0 .3.3.6.6.6s.6-.3.6-.6V18.7c0-.3-.3-.6-.6-.6Z"></path>
          <path d="M10.6 14.4c-.3 0-.6.3-.6.6v18c0 .3.3.6.6.6s.6-.3.6-.6V15c0-.4-.3-.6-.6-.6Z"></path>
          <path d="M37.4 14.4c-.3 0-.6.3-.6.6v18c0 .3.3.6.6.6s.6-.2.6-.6V15c0-.4-.3-.6-.6-.6Z"></path>
          <path d="M17.3 16.2c-.3 0-.6.3-.6.6v14.3c0 .3.3.6.6.6s.6-.3.6-.6V16.9c-.001-.4-.3-.7-.6-.7Z"></path>
          <path d="M30.7 16.2c-.3 0-.6.3-.6.6v14.3c0 .3.3.6.6.6s.6-.3.6-.6V16.9c0-.4-.3-.7-.6-.7Z"></path>
          <path d="M20.6 12.5c-.3 0-.6.3-.6.6v21.8c0 .3.3.6.6.6s.6-.3.6-.6V13.1c.1-.4-.2-.6-.6-.6Z"></path>
          <path d="M27.4 12.5c-.3 0-.6.3-.6.6v21.8c0 .3.3.6.6.6s.6-.3.6-.6V13.1c0-.4-.3-.6-.6-.6Z"></path>
          <path d="M24 8.7c-.3 0-.6.3-.6.6v29.4c0 .3.3.6.6.6s.6-.3.6-.6V9.3c0-.3-.3-.6-.6-.6Z"></path>
        </svg>
      ),
    },
  ], []);
  useEffect(() => {
    const loadDefinition = async () => {
      try {
        const pendingCode = localStorage.getItem("weaver:pendingExamCode");
        const lastExamCode = localStorage.getItem("weaver:lastExamCode");
        const examCode = pendingCode || incomingExamCode || lastExamCode || "placement-test";

        try {
          console.info("[Welcome] Loading exam definition", {
            pendingCode,
            incomingExamCode,
            lastExamCode,
            resolvedCode: examCode,
          });
        } catch (logErr) { }

        // 1. Try to load from localStorage first (for preview/custom exams)
        const normalizedCode = String(examCode || "").trim().toUpperCase().replace(/\s+/g, "_");
        const storageKey = `weaver_sections_${normalizedCode}`;
        const localData = localStorage.getItem(storageKey);

        if (localData) {
          try {
            console.log("✅ [Welcome] Loaded exam config from localStorage:", normalizedCode);
            const parsed = JSON.parse(localData);
            // If it's an array (sections list), convert to object
            if (Array.isArray(parsed)) {
              const def = {};
              parsed.forEach(section => {
                if (section && section.key) {
                  def[section.key] = section;
                }
              });
              setExamDefinition(def);
              return;
            } else if (parsed && typeof parsed === 'object') {
              setExamDefinition(parsed);
              return;
            }
          } catch (e) {
            console.warn("[Welcome] Failed to parse local exam data", e);
          }
        }

        // 2. If not in local storage, fetch from Firebase
        const def = await getExamDefinition(examCode);
        setExamDefinition(def || {});
      } catch (err) {
        console.warn('Unable to fetch exam definition', err);
        setExamDefinition({});
      }
    };
    loadDefinition();
  }, [incomingExamCode]);

  const availableSectionKeys = React.useMemo(() => {
    if (!examDefinition || typeof examDefinition !== "object") return [];
    return Object.keys(examDefinition || {}).map((k) => String(k || "").toLowerCase());
  }, [examDefinition]);

  // Check for speaking: either default 'speaking' key OR custom section with speaking parts
  const hasSpeaking = React.useMemo(() => {
    if (availableSectionKeys.includes("speaking")) return true;
    // Check for custom speaking sections (have 'parts' array like speaking)
    if (!examDefinition || typeof examDefinition !== "object") return false;
    return Object.keys(examDefinition).some((key) => {
      const section = examDefinition[key];
      // Check if section has speaking-like structure (parts array) or title contains "speaking"
      const hasParts = Array.isArray(section?.parts) && section.parts.length > 0;
      const titleHasSpeaking = String(section?.title || "").toLowerCase().includes("speaking") ||
        String(section?.title || "").toLowerCase().includes("nói");
      return hasParts || titleHasSpeaking;
    });
  }, [availableSectionKeys, examDefinition]);

  // Check for listening: either default 'listening' key OR custom section with listening title
  const hasListening = React.useMemo(() => {
    if (availableSectionKeys.includes("listening")) return true;
    if (!examDefinition || typeof examDefinition !== "object") return false;
    return Object.keys(examDefinition).some((key) => {
      const section = examDefinition[key];
      const titleHasListening = String(section?.title || "").toLowerCase().includes("listening") ||
        String(section?.title || "").toLowerCase().includes("nghe");
      return titleHasListening;
    });
  }, [availableSectionKeys, examDefinition]);

  const visibleSections = React.useMemo(() => {
    // If we don't yet know the exam sections, keep defaults to avoid empty UI
    if (availableSectionKeys.length === 0) return SECTION_ITEMS;

    // Filter sections that exist in exam definition
    const filtered = SECTION_ITEMS.filter((item) => availableSectionKeys.includes(item.key));

    // If no default speaking section but has custom speaking, add speaking to visible sections
    if (!availableSectionKeys.includes("speaking") && hasSpeaking) {
      const speakingItem = SECTION_ITEMS.find((item) => item.key === "speaking");
      if (speakingItem) {
        filtered.push(speakingItem);
      }
    }

    // If no default listening section but has custom listening, add listening to visible sections
    if (!availableSectionKeys.includes("listening") && hasListening) {
      const listeningItem = SECTION_ITEMS.find((item) => item.key === "listening");
      if (listeningItem && !filtered.find(i => i.key === "listening")) {
        // user might have custom listening so we just ensure the icon is there. 
        // Logic above only adds if NOT in availableSectionKeys, but filtered takes from there.
        // Actually, if it's a custom key, it won't be in SECTION_ITEMS by key.
        // But for visual consistency we might want to ensure the card appears if we detect it.
        // For now, let's just stick to the requested button logic, but I'll add this just in case like speaking.
        filtered.unshift(listeningItem);
      }
    }

    return filtered;
  }, [availableSectionKeys, hasSpeaking, hasListening, SECTION_ITEMS]);

  const requestMicrophonePermission = async () => {
    if (!hasSpeaking) {
      setMicrophoneStatus({ error: "", success: true });
      examTrackingService.track('welcomeAction', { action: 'checkMic', result: 'skipped_no_speaking' });
      return true;
    }
    if (!navigator?.mediaDevices?.getUserMedia) {
      setMicrophoneStatus({
        error:
          "Microphone access is not supported in this browser. Please update your browser or switch to a compatible one.",
        success: false,
      });
      examTrackingService.track('welcomeAction', { action: 'checkMic', result: 'not_supported' });
      return false;
    }

    try {
      setRequestingPermission(true);
      setMicrophoneStatus({ error: "", success: false });
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      stream.getTracks().forEach((track) => track.stop());
      setMicrophoneStatus({ error: "", success: true });
      examTrackingService.track('welcomeAction', { action: 'checkMic', result: 'granted' });
      return true;
    } catch (err) {
      console.error("Microphone permission denied", err);
      setMicrophoneStatus({ error: errorMessage, success: false });
      examTrackingService.track('welcomeAction', { action: 'checkMic', result: 'denied', error: err?.name });
      return false;
    } finally {
      setRequestingPermission(false);
    }
  };


  const handleProceed = async () => {
    // Only request mic if speaking is present
    if (hasSpeaking) {
      const granted = await requestMicrophonePermission();
      if (granted) {
        examTrackingService.track('welcomeAction', { action: 'proceed', micGranted: true });
        setStep((prev) => prev + 1);
      }
    } else {
      examTrackingService.track('welcomeAction', { action: 'proceed', micGranted: false });
      setStep((prev) => prev + 1);
    }
  };


  return (
    <div className="relative w-full h-full min-h-screen overflow-hidden bg-[#f8fafc] font-lexend flex items-start justify-center p-4 pt-5 md:pt-8">
      {/* Background Ambiance Orbs */}
      <div className="absolute inset-0 overflow-hidden pointer-events-none z-0">
        <div className="absolute -top-[10%] -left-[10%] w-[40rem] h-[40rem] rounded-full bg-orange-200/50 mix-blend-multiply blur-[120px] animate-[pulse_8s_ease-in-out_infinite]" />
        <div className="absolute top-[20%] -right-[10%] w-[35rem] h-[35rem] rounded-full bg-amber-200/40 mix-blend-multiply blur-[120px] animate-[pulse_10s_ease-in-out_infinite_reverse]" />
        <div className="absolute -bottom-[10%] left-[20%] w-[40rem] h-[40rem] rounded-full bg-orange-100/60 mix-blend-multiply blur-[120px] animate-[pulse_12s_ease-in-out_infinite]" />
      </div>

      <motion.div
        variants={CONTAINER_VARIANTS}
        initial="hidden"
        animate="visible"
        className="relative z-10 w-full max-w-5xl bg-white/70 backdrop-blur-3xl rounded-[2.5rem] shadow-[0_8px_30px_rgb(251,146,60,0.06)] border border-white/80 flex flex-col"
        style={{ maxHeight: '85vh' }}
      >
        <div className="absolute top-0 left-0 right-0 h-10 overflow-hidden rounded-t-[2.5rem] z-20 pointer-events-none">
           <div className="w-full h-2 bg-gradient-to-r from-orange-300 via-orange-500 to-amber-400" />
        </div>

        <div
          className="overflow-y-auto flex-1 flex flex-col pt-10 pb-6 px-4 md:px-12 relative z-10 orange-scrollbar"
        >
          {/* Header */}
          <motion.div variants={ITEM_VARIANTS} className="text-center mb-8 shrink-0">
            <h2 className="font-outfit text-3xl md:text-5xl font-extrabold tracking-tight text-slate-800 mb-3">Welcome to WEAVER</h2>
            <p className="text-slate-600 text-base md:text-lg font-medium">Bạn đã sẵn sàng bước vào bài thi?</p>
          </motion.div>

          {/* Sections grid */}
          <motion.div variants={ITEM_VARIANTS} className="w-full shrink-0 mb-8">
            <div className="flex flex-wrap justify-center gap-4">
              {visibleSections.map(({ label, duration, icon, key }) => {
                const time = (typeof examDefinition === "object" && key && examDefinition?.[key]?.timeAllotted) || duration;
                return (
                  <div
                    key={label}
                    className="flex flex-col items-center justify-start text-center bg-white/50 backdrop-blur-md rounded-2xl border border-white/80 shadow-sm p-4 w-[150px] md:w-[160px] h-[160px] hover:shadow-md hover:bg-white/80 transition-all duration-300"
                  >
                    <div className="w-12 h-12 shrink-0 rounded-2xl bg-gradient-to-br from-orange-400 to-amber-500 flex items-center justify-center text-white shadow-lg shadow-orange-500/30 mb-auto mt-1">
                      {React.cloneElement(icon, { className: "w-6 h-6 fill-current text-white mb-0" })}
                    </div>
                    <div className="flex flex-col items-center w-full mt-3">
                      <p className="font-bold text-slate-800 text-sm mb-1 line-clamp-2 leading-tight h-[2.5em] flex items-center">{label}</p>
                      <p className="font-medium text-slate-500 text-xs">{time}</p>
                    </div>
                  </div>
                );
              })}
            </div>
          </motion.div>

          {/* Instructions */}
          <motion.div variants={ITEM_VARIANTS} className="flex-1 flex flex-col justify-around shrink-0 px-2 lg:px-6">
            <div className="bg-white/50 backdrop-blur-xl rounded-2xl border border-white/80 p-6 shadow-sm mb-8 text-left">
              <p className="text-slate-600 text-sm md:text-base leading-relaxed font-medium mb-1">
                Trong lúc thi, <strong className="text-red-600">đừng chuyển tab, tắt hay thu nhỏ trình duyệt</strong> nhé — hệ thống sẽ tự động phát hiện và <strong className="text-red-600">tính là vi phạm</strong>, bạn sẽ <strong className="text-red-700 uppercase font-bold">không thể tiếp tục làm bài</strong>.
              </p>
              <div className="mt-4 pt-4 border-t border-slate-200/60">
                <p className="font-bold text-slate-700 text-sm md:text-base mb-2 flex items-center justify-start gap-2">
                  <span className="text-orange-500 text-lg">✦</span> Hãy chuẩn bị đầy đủ:
                </p>
                <ul className="list-disc text-left pl-8 text-slate-600 text-sm md:text-base space-y-1.5 font-medium">
                  <li>Kiểm tra kết nối Internet ổn định</li>
                  <li>Chuẩn bị giấy bút (Bắt buộc cho Listening và Speaking)</li>
                  <li>Đảm bảo không gian yên tĩnh</li>
                </ul>
              </div>
            </div>

            {/* Check Area */}
            <div className="w-full shrink-0 flex flex-col items-center">
              <div className="flex flex-wrap items-center justify-center gap-4 w-full">
                {hasListening && (
                  <button
                    type="button"
                    aria-pressed={isAudioPlaying}
                    onClick={async () => {
                      try {
                        if (!audioRef.current) {
                          audioRef.current = new Audio('/assets/audio/SoundCheckWelcome.mp3');
                          audioRef.current.addEventListener('ended', onAudioEnded, { once: true });
                        }
                        if (isAudioPlaying) {
                          audioRef.current.pause();
                          audioRef.current.currentTime = 0;
                          setIsAudioPlaying(false);
                        } else {
                          await audioRef.current.play();
                          setIsAudioPlaying(true);
                        }
                      } catch (err) {
                        console.warn('Unable to play audio:', err);
                        setIsAudioPlaying(false);
                      }
                    }}
                    className={`flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl border-2 font-bold transition-all duration-300 w-auto min-w-[200px] hover:scale-105 active:scale-95 ${isAudioPlaying
                      ? "bg-blue-50/90 border-blue-400 text-blue-600 shadow-sm ring-4 ring-blue-500/20"
                      : "bg-white/50 border-slate-200/60 text-slate-600 hover:border-blue-400 hover:text-blue-600 hover:bg-white"
                      }`}
                  >
                    <span className={`text-xl leading-none origin-bottom ${isAudioPlaying ? "animate-pulse" : "hover:animate-pulse"}`}>🔊</span>
                    <span className="text-sm">{isAudioPlaying ? "Đang phát..." : "Check Audio"}</span>
                  </button>
                )}

                {hasSpeaking && (
                  <button
                    onClick={requestMicrophonePermission}
                    disabled={requestingPermission || microphoneStatus.success}
                    className={`flex items-center justify-center gap-2 px-6 py-3.5 rounded-xl border-2 font-bold transition-all duration-300 w-auto min-w-[200px] ${microphoneStatus.success
                      ? "bg-emerald-50/80 border-emerald-400 text-emerald-700 shadow-sm cursor-default"
                      : "bg-white/50 border-slate-200/60 text-slate-600 hover:border-blue-400 hover:text-blue-600 hover:bg-white"
                      }`}
                  >
                    <span className="text-xl leading-none">{microphoneStatus.success ? "✓" : "🎤"}</span>
                    <span className="text-sm">{microphoneStatus.success ? "Mic Ready" : "Check Mic"}</span>
                  </button>
                )}
              </div>

              {hasSpeaking && microphoneStatus.error && (
                <motion.div initial={{ opacity: 0, y: -5 }} animate={{ opacity: 1, y: 0 }} className="mt-4 text-center">
                  <p className="inline-flex items-start gap-2 rounded-xl bg-red-50/90 backdrop-blur-sm shadow-sm border border-red-200 text-red-700 px-4 py-3 text-sm font-semibold max-w-sm text-left">
                    <span className="text-lg">⚠️</span> {microphoneStatus.error}
                  </p>
                </motion.div>
              )}
            </div>
          </motion.div>
        </div>

        {/* Sticky footer with Proceed button */}
        <motion.div variants={ITEM_VARIANTS} className="shrink-0 bg-white/50 backdrop-blur-xl border-t border-white/80 text-center flex items-center justify-center p-6 relative z-10 w-full rounded-b-[2.5rem]">
          <button
            onClick={handleProceed}
            disabled={requestingPermission}
            className="w-full max-w-[320px] bg-gradient-to-r from-orange-500 to-orange-600 hover:from-orange-600 hover:to-orange-700 text-white py-4 rounded-2xl shadow-[0_12px_25px_rgb(249,115,22,0.3)] hover:shadow-[0_15px_30px_rgb(249,115,22,0.4)] transition-all font-bold tracking-wide text-lg border border-white/10 disabled:opacity-70 disabled:cursor-not-allowed disabled:hover:shadow-none disabled:hover:from-orange-500 disabled:hover:to-orange-600 uppercase"
            data-test-id="test-session-welcome-screen-next-button"
          >
            {requestingPermission ? "Vui lòng chờ..." : "Vào làm bài thi"}
          </button>
        </motion.div>
      </motion.div>
    </div>
  );
};

export default WelcomePage;
