import React, { useMemo, useContext } from "react";
import MultipleChoicePreview from "../MultipleChoice/Preview";
import RegradeContext from "../../../contexts/RegradeContext";
import AnswerKeyEditor from "../_shared/AnswerKeyEditor";
import { matchesAnswer } from "../../../utils/normalizeAnswer";

const FillInBlankPreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  placeholder,
  name,
  questionNumber,
  sectionKey = '',
}) => {
  const displayValue = useMemo(() => {
    if (value === null || value === undefined) return "";
    if (Array.isArray(value)) return value.join(" / ");
    return String(value);
  }, [value]);

  const isInteractive = typeof onChange === "function";
  const { isRegrade, setKeyEdit } = useContext(RegradeContext);

  if (!question) {
    return null;
  }

  const baseNumber = parseInt(String(questionNumber).split("-")[0]) || 1;
  const inputMode = question.inputMode || "text";

  if (inputMode === "choices") {
    return (
      <MultipleChoicePreview
        question={question}
        value={value}
        onChange={onChange}
        disabled={disabled}
        reviewMode={reviewMode}
        correctAnswers={correctAnswers}
        allowMultiple={false}
        name={name}
        data-question-slot-number={baseNumber}
      />
    );
  }



  const inputClasses = [
    "w-full rounded-lg border bg-white px-3 py-2 text-sm text-slate-800 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200",
  ];

  if (reviewMode) {
    const correctList = Array.isArray(correctAnswers)
      ? correctAnswers.filter((answer) => answer !== null && answer !== undefined)
      : correctAnswers != null
      ? [correctAnswers]
      : [];

    if (correctList.length > 0) {
      // Shared matcher: handles "/" + "|" + bracket variants identically to
      // examScoring.js so review-mode highlighting can't drift from the grader.
      const hasMatch = correctList.some((answer) => matchesAnswer(value, answer));
      inputClasses.push(
        hasMatch ? "border-green-400 bg-green-50" : "border-red-300"
      );
    }
  }

  return (
    <>
      <input
        type="text"
        name={name || question.id || "fill-in-the-blanks"}
        value={displayValue}
        onChange={(event) => onChange?.(event.target.value)}
        disabled={disabled}
        readOnly={reviewMode || !isInteractive}
        placeholder={
          placeholder || question.placeholder || "Type your answer"
        }
        className={inputClasses.join(" ")}
        data-question-slot-number={questionNumber}
      />
      {isRegrade && reviewMode && (
        <AnswerKeyEditor
          correctAnswers={question.correctAnswers}
          questionType={question.type}
          onChange={(patch) => setKeyEdit(sectionKey, question.id, patch)}
        />
      )}
    </>
  );
};

export default FillInBlankPreview;
