import { useState, useEffect, useCallback, useRef } from "react";

const SPEED_OPTIONS = [0.5, 0.75, 1.0];

const useAudioPlayer = ({
  audioPlayerRef,
  audioTimestampsRef,
  pendingSeekRef,
  audioParts,
  activePartIndex,
  completedParts,
  currentAudioUrl,
  sectionKey,
  setActivePartIndex,
  setCompletedParts,
  isPreviewMode,
  reviewMode,
  showReadyPopup,
  restoredForThisSection,
  onAudioPlayingChange,
  onListeningPartStateChange,
}) => {
  const audioPlayingKey = `audio_playing_${sectionKey}`;

  const [isAudioPlaying, setIsAudioPlaying] = useState(false);
  const [audioPlayed, setAudioPlayed] = useState(false);
  const [shouldAutoPlay, setShouldAutoPlay] = useState(false);
  const [playbackSpeed, setPlaybackSpeed] = useState(1.0);

  // Ref always holds the latest activePartIndex/completedParts so callbacks
  // triggered by AudioPlayer unmount (pause event on DOM removal) read
  // current values instead of stale closures from the previous render.
  const latestStateRef = useRef({ activePartIndex, completedParts });
  latestStateRef.current = { activePartIndex, completedParts };

  const pushPartStateNow = useCallback(() => {
    if (!onListeningPartStateChange) return;
    const { activePartIndex: idx, completedParts: cp } = latestStateRef.current;
    onListeningPartStateChange(sectionKey, {
      activePartIndex: idx,
      completedParts: cp,
      audioTimestamps: audioTimestampsRef.current,
      audioTimestamp: audioTimestampsRef.current[idx] ?? 0,
    });
  }, [onListeningPartStateChange, sectionKey, audioTimestampsRef]);

  const handleSpeedChange = useCallback(
    (speed) => {
      setPlaybackSpeed(speed);
      try {
        const audio = audioPlayerRef.current?.audio?.current;
        if (audio) audio.playbackRate = speed;
      } catch (e) {}
    },
    [audioPlayerRef]
  );

  const handleAudioPlay = useCallback(() => {
    setIsAudioPlaying(true);
    sessionStorage.setItem(audioPlayingKey, "true");
    onAudioPlayingChange?.(true);
    setAudioPlayed(true);
  }, [audioPlayingKey, onAudioPlayingChange]);

  const handleAudioPause = useCallback(() => {
    setIsAudioPlaying(false);
    sessionStorage.removeItem(audioPlayingKey);
    onAudioPlayingChange?.(false);
    pushPartStateNow();
  }, [audioPlayingKey, onAudioPlayingChange, pushPartStateNow]);

  const handleAudioEnded = useCallback(() => {
    setIsAudioPlaying(false);
    sessionStorage.removeItem(audioPlayingKey);
    onAudioPlayingChange?.(false);
    pushPartStateNow();

    const { activePartIndex: curPart, completedParts: curCompleted } = latestStateRef.current;
    if (!curCompleted.includes(curPart)) {
      setCompletedParts([...curCompleted, curPart]);
    }

    if (audioParts.length > 1 && curPart < audioParts.length - 1) {
      const nextPart = curPart + 1;
      audioTimestampsRef.current[nextPart] = 0;
      pendingSeekRef.current = null;
      setActivePartIndex(nextPart);
      setAudioPlayed(false);
      setShouldAutoPlay(true);
    }
  }, [
    audioPlayingKey,
    onAudioPlayingChange,
    pushPartStateNow,
    setCompletedParts,
    audioParts.length,
    setActivePartIndex,
    audioTimestampsRef,
    pendingSeekRef,
  ]);

  // Stop audio when entering review mode
  useEffect(() => {
    if (reviewMode) {
      if (audioPlayerRef.current?.audio?.current) {
        try {
          audioPlayerRef.current.audio.current.pause();
        } catch (e) {}
      }
      setIsAudioPlaying(false);
    }
  }, [reviewMode, audioPlayerRef]);

  // Auto-play when shouldAutoPlay is true
  useEffect(() => {
    if (shouldAutoPlay && !showReadyPopup && audioPlayerRef.current) {
      const timer = setTimeout(() => {
        try {
          const audio = audioPlayerRef.current?.audio?.current;
          if (audio) {
            audio.play().catch((err) => {
              console.warn("Auto-play failed:", err);
            });
          }
        } catch (e) {
          console.warn("Auto-play error:", e);
        }
        setShouldAutoPlay(false);
      }, 500);
      return () => clearTimeout(timer);
    }
  }, [shouldAutoPlay, activePartIndex, showReadyPopup, audioPlayerRef]);

  // Periodic audio timestamp push
  useEffect(() => {
    if (!onListeningPartStateChange || !isAudioPlaying) return;
    const interval = setInterval(() => {
      onListeningPartStateChange(sectionKey, {
        activePartIndex,
        completedParts,
        audioTimestamps: audioTimestampsRef.current,
        audioTimestamp: audioTimestampsRef.current[activePartIndex] ?? 0,
      });
    }, 7000);
    return () => clearInterval(interval);
  }, [
    onListeningPartStateChange,
    sectionKey,
    activePartIndex,
    completedParts,
    isAudioPlaying,
    audioTimestampsRef,
  ]);

  // Clean up when unmounting
  useEffect(() => {
    return () => {
      if (isAudioPlaying) {
        sessionStorage.removeItem(audioPlayingKey);
        onAudioPlayingChange?.(false);
      }
    };
  }, [isAudioPlaying, audioPlayingKey, onAudioPlayingChange]);

  // Fallback seek: when pendingSeekRef has a target but onLoadedMetadata
  // didn't fire, or fired before the ref was set. Retries aggressively
  // but does NOT consume the seek target — that's confirmed in onListen.
  useEffect(() => {
    const ts = pendingSeekRef.current;
    if (ts == null || ts <= 0) return;
    const attemptSeek = () => {
      const audio = audioPlayerRef.current?.audio?.current;
      if (
        audio &&
        audio.readyState >= 1 &&
        Math.abs(audio.currentTime - ts) > 0.5
      ) {
        audio.currentTime = ts;
        console.log(
          "🎧 [Audio-Seek-Fallback] Seeking to restored timestamp:",
          ts,
          "currentTime was:",
          audio.currentTime
        );
      }
    };
    attemptSeek();
    const t1 = setTimeout(attemptSeek, 100);
    const t2 = setTimeout(attemptSeek, 300);
    const t3 = setTimeout(attemptSeek, 700);
    const t4 = setTimeout(attemptSeek, 1500);
    return () => {
      clearTimeout(t1);
      clearTimeout(t2);
      clearTimeout(t3);
      clearTimeout(t4);
    };
  }, [restoredForThisSection?.audioTimestamp, currentAudioUrl, audioPlayerRef, pendingSeekRef]);

  return {
    isAudioPlaying,
    audioPlayed,
    setAudioPlayed,
    shouldAutoPlay,
    playbackSpeed,
    handleSpeedChange,
    handleAudioPlay,
    handleAudioPause,
    handleAudioEnded,
    SPEED_OPTIONS,
    audioPlayingKey,
  };
};

export default useAudioPlayer;