import React, { createContext, useContext, useMemo } from "react";
import { getQuestionSlotCount } from "../utils/question/questionMetrics";

const NumberingContext = createContext();

export const NumberingProvider = ({ sections = {}, customSections = [], children }) => {
  // Calculate global question numbering across ALL sections and passages
  const questionNumbering = useMemo(() => {
    const numbering = {};
    let globalNumber = 1;
    
    // Get section order from customSections if provided, otherwise use default order
    let sectionOrder;
    if (Array.isArray(customSections) && customSections.length > 0) {
      // Use custom sections order (respects user's section arrangement)
      sectionOrder = customSections
        .filter(s => s.enabled !== false)
        .map(s => s.key);
    } else {
      // Default section order for consistent numbering
      sectionOrder = ["listening", "grammar", "reading", "writing", "speaking"];
    }

    // Iterate through sections in order
    sectionOrder.forEach((sectionKey) => {
      const section = sections[sectionKey];
      if (!section) return;

      // For reading section with passages
      if (sectionKey === "reading" && section?.passages) {
        section.passages.forEach((passage) => {
          if (passage?.questions) {
            passage.questions.forEach((question) => {
              const key = `${sectionKey}-${passage.id}-${question.id}`;
              const itemCount = getQuestionSlotCount(question);
              const slots = itemCount;

              numbering[key] = {
                start: globalNumber,
                end: globalNumber + slots - 1,
                slots,
              };

              globalNumber += slots;
            });
          }
        });
      }
      // For listening section with questionGroups
      else if (sectionKey === "listening" && section?.questionGroups) {
        section.questionGroups.forEach((group) => {
          if (group?.questions) {
            group.questions.forEach((question) => {
              const key = `${sectionKey}-${group.id}-${question.id}`;
              const itemCount = getQuestionSlotCount(question);
              const slots = itemCount;

              numbering[key] = {
                start: globalNumber,
                end: globalNumber + slots - 1,
                slots,
              };

              globalNumber += slots;
            });
          }
        });
      }
      // For grammar, writing, speaking, custom sections with direct questions or groups
      else if ((sectionKey === "grammar" || sectionKey === "writing" || sectionKey === "speaking" || sectionKey === "custom" || sectionKey.startsWith("custom_")) && section) {
        // Handle direct questions
        if (section?.questions) {
          section.questions.forEach((question) => {
            const key = `${sectionKey}-${question.id}`;
            const itemCount = getQuestionSlotCount(question);
            const slots = itemCount;

            numbering[key] = {
              start: globalNumber,
              end: globalNumber + slots - 1,
              slots,
            };

            globalNumber += slots;
          });
        }
        // Handle groups with questions (for custom section structure)
        if (section?.groups) {
          section.groups.forEach((group) => {
            if (group?.questions) {
              group.questions.forEach((question) => {
                const key = `${sectionKey}-${group.id}-${question.id}`;
                const itemCount = getQuestionSlotCount(question);
                const slots = itemCount;

                numbering[key] = {
                  start: globalNumber,
                  end: globalNumber + slots - 1,
                  slots,
                };

                globalNumber += slots;
              });
            }
          });
        }
      }
    });

    return numbering;
  }, [sections, customSections]);

  // Get question display label (single number or range like "1-3")
  const getQuestionNumber = (sectionKey, passageOrGroupId, questionId) => {
    // Support both passage-based (reading) and group-based (listening/custom) keys
    const key = passageOrGroupId 
      ? `${sectionKey}-${passageOrGroupId}-${questionId}`
      : `${sectionKey}-${questionId}`;
    
    const num = questionNumbering[key];
    if (!num) {
      // Fallback: try to find any key matching this questionId
      const fallbackKey = Object.keys(questionNumbering).find(k => k.endsWith(`-${questionId}`));
      if (fallbackKey) {
        const fallbackNum = questionNumbering[fallbackKey];
        return fallbackNum.start === fallbackNum.end ? String(fallbackNum.start) : `${fallbackNum.start}-${fallbackNum.end}`;
      }
      return "1";
    }
    return num.start === num.end ? String(num.start) : `${num.start}-${num.end}`;
  };

  // Get starting number of the question
  const getQuestionStart = (sectionKey, passageOrGroupId, questionId) => {
    const key = passageOrGroupId 
      ? `${sectionKey}-${passageOrGroupId}-${questionId}`
      : `${sectionKey}-${questionId}`;
    
    const num = questionNumbering[key];
    if (!num) {
      // Fallback: try to find any key matching this questionId
      const fallbackKey = Object.keys(questionNumbering).find(k => k.endsWith(`-${questionId}`));
      if (fallbackKey) {
        return questionNumbering[fallbackKey]?.start || 1;
      }
      return 1;
    }
    return num?.start || 1;
  };

  // Get ending number of the question
  const getQuestionEnd = (sectionKey, passageOrGroupId, questionId) => {
    const key = passageOrGroupId 
      ? `${sectionKey}-${passageOrGroupId}-${questionId}`
      : `${sectionKey}-${questionId}`;
    
    const num = questionNumbering[key];
    if (!num) {
      // Fallback: try to find any key matching this questionId
      const fallbackKey = Object.keys(questionNumbering).find(k => k.endsWith(`-${questionId}`));
      if (fallbackKey) {
        return questionNumbering[fallbackKey]?.end || 1;
      }
      return 1;
    }
    return num?.end || 1;
  };

  const value = {
    questionNumbering,
    getQuestionNumber,
    getQuestionStart,
    getQuestionEnd,
  };

  return (
    <NumberingContext.Provider value={value}>
      {children}
    </NumberingContext.Provider>
  );
};

export const useNumbering = () => {
  const context = useContext(NumberingContext);
  if (!context) {
    throw new Error("useNumbering must be used within NumberingProvider");
  }
  return context;
};
