import { useState, useEffect } from 'react';
import { saveHomeworkAnswerKey, resolveParentOrigin } from '../../../controller/useFirebase';
import { gradeExam } from '../utils/examScoring';

export function useRegradeMode({
  isRegradeMode,
  isEmbedded,
  examCode,
  answers,
  setAnswers,
  setReviewMode,
}) {
  const [keyEdits, setKeyEditsState] = useState({});
  const [savedKeyPatch, setSavedKeyPatch] = useState({});
  const [teacherUid, setTeacherUid] = useState('unknown');
  const [regradeError, setRegradeError] = useState(null);
  const [isSavingRegrade, setIsSavingRegrade] = useState(false);

  const hasPendingKeyEdits = Object.keys(keyEdits).length > 0;

  const setKeyEdit = (sectionKey, questionId, patch) => {
    setKeyEditsState((prev) => ({
      ...prev,
      [sectionKey]: {
        ...(prev[sectionKey] || {}),
        [questionId]: patch,
      },
    }));
  };

  useEffect(() => {
    if (!isRegradeMode || !isEmbedded) return;
    console.log('[Regrade] Listener mounted, waiting for REVIEW_INIT...');

    const handler = (e) => {
      if (e.data?.type !== 'REVIEW_INIT') return;
      const { answers: prefilled, examCode: initExamCode, teacherUid: uid } = e.data.payload || {};
      console.log('[Regrade] REVIEW_INIT received', {
        examCode: initExamCode,
        sectionKeys: prefilled ? Object.keys(prefilled) : [],
        teacherUid: uid,
      });
      if (prefilled && typeof prefilled === 'object') {
        setAnswers(prefilled);
        setReviewMode(true);
        if (uid) setTeacherUid(uid);
        console.log('[Regrade] Answers pre-filled, reviewMode ON. Sending ACK.');
        if (window.parent !== window) {
          window.parent.postMessage({ type: 'REVIEW_ACK' }, '*');
        }
      } else {
        console.warn('[Regrade] REVIEW_INIT received but no answers in payload');
      }
    };

    window.addEventListener('message', handler);
    return () => window.removeEventListener('message', handler);
  }, [isRegradeMode, isEmbedded, setAnswers, setReviewMode]);

  // Shared with the submit paths — derives the parent origin from
  // document.referrer so it honors the Portal's actual scheme (http or https)
  // instead of hardcoding https. See useFirebase.js § resolveParentOrigin.
  const getRegradeTargetOrigin = () => resolveParentOrigin();

  const handleSaveAndRegrade = async (currentExamContent, currentAnswerKeyMap, setScoreSummary, setQuestionResults) => {
    if (!isRegradeMode) return;
    setRegradeError(null);

    const targetOrigin = getRegradeTargetOrigin();

    if (!hasPendingKeyEdits) {
      console.log('[Regrade] No key edits — pure re-score');
      const { summary, questionResults: results } = gradeExam(answers, currentAnswerKeyMap);
      setScoreSummary(summary);
      setQuestionResults(results);
      if (isEmbedded && window.parent !== window) {
        window.parent.postMessage(
          { type: 'EXAM_RESULT', payload: { examCode, summary, answers } },
          targetOrigin,
        );
        console.log('[Regrade] Sent EXAM_RESULT (no key change) to', targetOrigin);
      }
      return;
    }

    setIsSavingRegrade(true);
    try {
      const sectionPatches = {};
      Object.keys(keyEdits).forEach((sectionKey) => {
        if (currentExamContent?.[sectionKey]) {
          sectionPatches[sectionKey] = currentExamContent[sectionKey];
        }
      });

      const { keyVersion } = await saveHomeworkAnswerKey(examCode, sectionPatches, {
        lastKeyUpdatedBy: teacherUid,
      });
      console.log('[Regrade] Saved answer key patches. keyVersion:', keyVersion);

      const { summary, questionResults: results } = gradeExam(answers, currentAnswerKeyMap);

      setScoreSummary(summary);
      setQuestionResults(results);
      setSavedKeyPatch((prev) => ({ ...prev, ...sectionPatches }));
      setKeyEditsState({});

      if (isEmbedded && window.parent !== window) {
        window.parent.postMessage(
          { type: 'EXAM_RESULT', payload: { examCode, summary, answers, keyVersion } },
          targetOrigin,
        );
        window.parent.postMessage(
          {
            type: 'ANSWER_KEY_PATCHED',
            payload: { examCode, keyVersion, changedSections: Object.keys(sectionPatches) },
          },
          targetOrigin,
        );
        console.log('[Regrade] Sent EXAM_RESULT + ANSWER_KEY_PATCHED to', targetOrigin, {
          keyVersion,
          changedSections: Object.keys(sectionPatches),
        });
      }
    } catch (err) {
      console.error('[Regrade] Failed to save answer key:', err);
      setRegradeError(err.message || 'Failed to save answer key. Please try again.');
    } finally {
      setIsSavingRegrade(false);
    }
  };

  return {
    keyEdits,
    savedKeyPatch,
    setKeyEdit,
    hasPendingKeyEdits,
    teacherUid,
    regradeError,
    clearRegradeError: () => setRegradeError(null),
    isSavingRegrade,
    handleSaveAndRegrade,
  };
}
