import React, { useState, useEffect } from "react";
import { useLocation } from "react-router-dom";
import ExamBuilder from "./examBuilder";
import { getExamDefinition } from "../../controller/useFirebase";

const VIEW = {
  START: "start",
  CODE: "code",
  BUILDER: "builder",
  AI_BUILDER: "ai_builder",
};

const ExamManager = () => {
  const location = useLocation();
  const [view, setView] = useState(VIEW.START);
  const [examCode, setExamCode] = useState("");
  const [initialExamData, setInitialExamData] = useState(null);
  const [lookupCode, setLookupCode] = useState("");
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  useEffect(() => {
    if (location.state?.returnedFromPreview && location.state.examCode) {
      const loadExam = async () => {
        try {
          const examData = await getExamDefinition(location.state.examCode);
          setExamCode(location.state.examCode);
          setInitialExamData(examData);
          setView(VIEW.BUILDER);
        } catch (error) {
          console.error('Failed to restore exam data:', error);
          setError('Failed to restore exam data. Please try again.');
        }
      };
      loadExam();
    }
  }, [location.state]);

  const clearAllStorage = () => {
    if (typeof window === "undefined") return;

    const clearStorage = (storage) => {
      const keysToRemove = [];
      for (let i = 0; i < storage.length; i++) {
        const key = storage.key(i);
        if (key && (key.startsWith('weaver_draft_') || key.startsWith('weaver_sections_'))) {
          keysToRemove.push(key);
        }
      }
      keysToRemove.forEach(key => storage.removeItem(key));
    };

    clearStorage(window.localStorage);
    clearStorage(window.sessionStorage);
    console.log("🧹 Cleared all exam-related storage");
  };

  const handleCreateNew = () => {
    clearAllStorage();
    setInitialExamData(null);
    setExamCode("");
    setView(VIEW.BUILDER);
  };

  const handleCreateWithAI = () => {
    clearAllStorage();
    setInitialExamData(null);
    setExamCode("");
    setView(VIEW.AI_BUILDER);
  };

  const handleRequestEdit = () => {
    clearAllStorage();
    setLookupCode("");
    setError("");
    setView(VIEW.CODE);
  };

  const handleFetchExam = async () => {
    const trimmed = lookupCode.trim();
    if (!trimmed) {
      setError("Please enter an exam code.");
      return;
    }

    const normalizedCode = trimmed.toUpperCase();

    setLoading(true);
    setError("");

    try {
      const data = await getExamDefinition(normalizedCode);
      const hasData = data && Object.keys(data).length > 0;

      if (!hasData) {
        setError("No exam found with this code. Please double-check and try again.");
        return;
      }

      setInitialExamData(data);
      setExamCode(normalizedCode);
      setLookupCode(normalizedCode);
      setView(VIEW.BUILDER);
    } catch (err) {
      setError(err.message || "Unable to load exam. Please try again.");
    } finally {
      setLoading(false);
    }
  };

  const renderStartView = () => (
    <div className="mx-auto flex min-h-screen max-w-4xl flex-col items-center justify-center px-6 py-16">
      <div className="w-full rounded-3xl bg-white/10 p-10 text-white shadow-2xl backdrop-blur">
        <p className="text-sm uppercase tracking-widest text-blue-100">
          Weaver test online
        </p>
        <h1 className="mt-2 text-3xl font-semibold">
          Build or update an IELTS simulation test
        </h1>
        <p className="mt-4 max-w-2xl text-sm text-blue-100">
          Craft immersive listening, reading, writing, and speaking experiences
          with audio playback, rich text prompts, and speaking recordings that
          mirror the study4.com layout your candidates are familiar with.
        </p>

        <div className="mt-10 grid gap-6 md:grid-cols-2">
          <button
            type="button"
            onClick={handleCreateNew}
            className="rounded-2xl border border-white/20 bg-blue-500/80 px-6 py-6 text-left text-white transition hover:-translate-y-1 hover:bg-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
          >
            <h2 className="text-xl font-semibold">Create a new exam</h2>
            <p className="mt-2 text-sm text-blue-50">
              Start from our scaffold that follows the IELTS four-skill format.
            </p>
          </button>

          <button
            type="button"
            onClick={handleCreateWithAI}
            className="rounded-2xl border border-white/20 bg-gradient-to-br from-purple-500/80 to-pink-500/80 px-6 py-6 text-left text-white transition hover:-translate-y-1 hover:from-purple-500 hover:to-pink-500 focus:outline-none focus:ring-2 focus:ring-purple-200"
          >
            <h2 className="text-xl font-semibold flex items-center gap-2">
              <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 10V3L4 14h7v7l9-11h-7z" />
              </svg>
              Build exam with AI
            </h2>
            <p className="mt-2 text-sm text-purple-50">
              Create questions using AI assistance with blank sections ready to fill.
            </p>
          </button>

          <button
            type="button"
            onClick={handleRequestEdit}
            className="rounded-2xl border border-white/20 bg-white/10 px-6 py-6 text-left transition hover:-translate-y-1 hover:bg-white/20 focus:outline-none focus:ring-2 focus:ring-blue-200 md:col-span-2"
          >
            <h2 className="text-xl font-semibold">Edit an existing exam</h2>
            <p className="mt-2 text-sm text-blue-50">
              Enter an exam code to retrieve questions and media from Firestore.
            </p>
          </button>
        </div>
      </div>
    </div>
  );

  const renderCodeView = () => (
    <div className="mx-auto flex min-h-screen max-w-xl flex-col justify-center px-6 py-16">
      <div className="rounded-3xl bg-white/10 p-10 text-white shadow-2xl backdrop-blur">
        <h2 className="text-2xl font-semibold">Edit existing exam</h2>
        <p className="mt-2 text-sm text-blue-100">
          Enter the exam code you want to load. You can modify any section and
          re-publish instantly.
        </p>

        <label className="mt-6 block text-sm font-medium text-blue-100">
          Exam code
        </label>
        <input
          type="text"
          value={lookupCode}
          onChange={(event) => setLookupCode(event.target.value)}
          onKeyDown={(event) => event.key === "Enter" && handleFetchExam()}
          className="mt-2 w-full rounded-xl border border-white/30 bg-white/10 px-4 py-3 text-base text-white placeholder:text-blue-200 focus:border-white focus:outline-none focus:ring-2 focus:ring-blue-200"
          placeholder="e.g. IELTS_SILVER_112"
        />

        {error && (
          <p className="mt-3 text-sm text-rose-200">
            {error}
          </p>
        )}

        <div className="mt-8 flex items-center gap-4">
          <button
            type="button"
            onClick={handleFetchExam}
            disabled={loading}
            className="rounded-xl bg-blue-500 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-blue-600 disabled:cursor-not-allowed disabled:bg-blue-400"
          >
            {loading ? "Loading…" : "Load exam"}
          </button>
          <button
            type="button"
            onClick={() => setView(VIEW.START)}
            className="rounded-xl border border-white/30 px-5 py-2.5 text-sm font-semibold text-white transition hover:bg-white/10"
          >
            Back
          </button>
        </div>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-900 via-blue-900 to-slate-800">
      {view === VIEW.BUILDER || view === VIEW.AI_BUILDER ? (
        <ExamBuilder
          examCode={examCode}
          initialData={initialExamData}
          onBack={() => setView(VIEW.START)}
          onExamCodeChange={setExamCode}
          isAIMode={view === VIEW.AI_BUILDER}
        />
      ) : view === VIEW.CODE ? (
        renderCodeView()
      ) : (
        renderStartView()
      )}
    </div>
  );
};

export default ExamManager;
