import { getQuestionSlotCount } from "../../../utils/question/questionMetrics";

export const ROOT_CONTAINER_ID = "__root__";
const SECTION_FALLBACK = "__section__";
const QUESTION_FALLBACK = "__question__";

export const resolveListeningContainerId = (group, index = 0) => {
  if (group?.id) return group.id;
  return `listening-group-${index}`;
};

export const resolveReadingContainerId = (passage, index = 0) => {
  if (passage?.id) return passage.id;
  return `reading-passage-${index}`;
};

export const resolveCustomGroupId = (group, index = 0) => {
  if (group?.id) return group.id;
  return `custom-group-${index}`;
};

const makeKey = (sectionKey, containerId, questionId) => {
  const safeSection = sectionKey || SECTION_FALLBACK;
  const safeContainer = containerId || ROOT_CONTAINER_ID;
  const safeQuestion = questionId || QUESTION_FALLBACK;
  return `${safeSection}::${safeContainer}::${safeQuestion}`;
};

const registerQuestion = (options) => {
  const {
    numberingMap,
    sectionKey,
    containerId,
    question,
    questionIndex,
    currentNumberRef,
  } = options;

  if (!question) return;

  const slots = Math.max(getQuestionSlotCount(question), 1);
  const start = currentNumberRef.value;
  const end = start + slots - 1;
  const key = makeKey(sectionKey, containerId, question.id || `${QUESTION_FALLBACK}-${questionIndex}`);

  numberingMap.set(key, {
    start,
    end,
    slots,
  });

  currentNumberRef.value = end + 1;
};

export const buildGlobalNumbering = (sectionTabs = []) => {
  const numberingMap = new Map();
  const sectionOffsets = {};
  const currentNumberRef = { value: 1 };

  // Use sectionTabs order directly - don't re-sort by priority
  // This ensures grammar comes between listening and reading when defined that way
  const orderedTabs = sectionTabs;

  orderedTabs.forEach((tab, sectionIndex) => {
    const sectionKey = tab?.key;
    const sectionType = tab?.type;
    const data = tab?.data;

    // Reset numbering for each section (each skill starts from 1)
    currentNumberRef.value = 1;

    // Ensure we track offset even if data missing (offset is always 0 since we reset)
    if (sectionKey) {
      sectionOffsets[sectionKey] = 0; // Each section starts from 1, so offset is 0
    } else {
      sectionOffsets[`section-${sectionIndex}`] = 0;
    }

    if (!sectionKey || !data) {
      return;
    }

    if (sectionType === "listening") {
      const groups = Array.isArray(data?.questionGroups) ? data.questionGroups : [];
      groups.forEach((group, groupIndex) => {
        const containerId = resolveListeningContainerId(group, groupIndex);
        const questions = Array.isArray(group?.questions) ? group.questions : [];
        questions.forEach((question, questionIndex) => {
          registerQuestion({
            numberingMap,
            sectionKey,
            containerId,
            question,
            questionIndex,
            currentNumberRef,
          });
        });
      });
      return;
    }

    if (sectionType === "reading") {
      const passages = Array.isArray(data?.passages) ? data.passages : [];
      passages.forEach((passage, passageIndex) => {
        const containerId = resolveReadingContainerId(passage, passageIndex);
        const questions = Array.isArray(passage?.questions) ? passage.questions : [];
        questions.forEach((question, questionIndex) => {
          registerQuestion({
            numberingMap,
            sectionKey,
            containerId,
            question,
            questionIndex,
            currentNumberRef,
          });
        });
      });
      return;
    }

    // Custom or other sections may have standalone questions or groups
    const standaloneQuestions = Array.isArray(data?.questions)
      ? data.questions
      : [];
    standaloneQuestions.forEach((question, questionIndex) => {
      registerQuestion({
        numberingMap,
        sectionKey,
        containerId: ROOT_CONTAINER_ID,
        question,
        questionIndex,
        currentNumberRef,
      });
    });

    const groups = Array.isArray(data?.groups) ? data.groups : [];
    groups.forEach((group, groupIndex) => {
      const containerId = resolveCustomGroupId(group, groupIndex);
      const questions = Array.isArray(group?.questions) ? group.questions : [];
      questions.forEach((question, questionIndex) => {
        registerQuestion({
          numberingMap,
          sectionKey,
          containerId,
          question,
          questionIndex,
          currentNumberRef,
        });
      });
    });
  });

  const getQuestionMeta = (sectionKey, containerId, questionId) => {
    if (!sectionKey || !questionId) return null;
    const key = makeKey(sectionKey, containerId, questionId);
    return numberingMap.get(key) || null;
  };

  const getQuestionLabel = (sectionKey, containerId, questionId) => {
    const meta = getQuestionMeta(sectionKey, containerId, questionId);
    if (!meta) return null;
    return meta.start === meta.end ? `${meta.start}` : `${meta.start}-${meta.end}`;
  };

  const getQuestionRangeForContainer = (sectionKey, containerId, questions = []) => {
    if (!Array.isArray(questions) || questions.length === 0) return null;
    const metas = questions
      .map((question) =>
        getQuestionMeta(sectionKey, containerId, question?.id)
      )
      .filter(Boolean);
    if (metas.length === 0) return null;
    const start = Math.min(...metas.map((meta) => meta.start));
    const end = Math.max(...metas.map((meta) => meta.end));
    const slots = metas.reduce((sum, meta) => sum + (meta?.slots || 0), 0);
    return {
      start,
      end,
      slots,
    };
  };

  return {
    sectionOffsets,
    totalQuestions: currentNumberRef.value - 1,
    getQuestionMeta,
    getQuestionLabel,
    getQuestionRangeForContainer,
  };
};
