import { useState, useMemo, useEffect } from 'react';
import { Services, useFirebase } from '../../../controller/useFirebase';
import { normalizeExamData, extractQuestionItems } from '../../../utils/examData';
import { applyKeyEdits, deriveAnswerKey } from '../utils/examScoring';
import { buildSectionTabs } from '../utils/sectionHelpers';
import { buildGlobalNumbering } from '../utils/numbering';
import { parseTimeAllottedToSeconds } from '../utils/timeParser';

/**
 * useExamData
 *
 * Handles fetching exam data from Firestore, applying regrade key patches,
 * deriving section tabs, custom section ordering, and navigation structures.
 */
export function useExamData({
  examCode,
  examCollection,
  previewDraft,
  savedKeyPatch,
  hasPendingKeyEdits,
  keyEdits,
  isPreviewMode,
  LAST_EXAM_KEY,
}) {
  const {
    data: remoteExamData,
    loading,
    error: remoteExamError,
  } = useFirebase(Services.GET_DOCUMENT_BY_NAME, examCollection, examCode);

  const isEmptyRemoteExam =
    remoteExamData &&
    typeof remoteExamData === 'object' &&
    Object.keys(remoteExamData).length === 0;

  const fetchFailed =
    !isPreviewMode && !loading && (!!remoteExamError || remoteExamData === null || isEmptyRemoteExam);

  const examContent = useMemo(() => {
    if (previewDraft) return previewDraft;
    if (loading) return null;
    if (fetchFailed) return null;
    if (!remoteExamData) return null;
    const baseData = Object.keys(savedKeyPatch).length
      ? { ...remoteExamData, ...savedKeyPatch }
      : remoteExamData;
    const content = normalizeExamData(baseData);

    return hasPendingKeyEdits ? applyKeyEdits(content, keyEdits) : content;
  }, [
    previewDraft,
    remoteExamData,
    savedKeyPatch,
    loading,
    fetchFailed,
    keyEdits,
    hasPendingKeyEdits,
  ]);

  // Clear localStorage exam codes when fetch fails to prevent stale codes after F5 refresh
  useEffect(() => {
    if (fetchFailed && !isPreviewMode) {
      try {
        localStorage.removeItem('weaver:pendingExamCode');
        if (LAST_EXAM_KEY) localStorage.removeItem(LAST_EXAM_KEY);
      } catch (e) {
        console.warn('Failed to clear localStorage:', e);
      }
    }
  }, [fetchFailed, isPreviewMode, LAST_EXAM_KEY]);

  const [customSections, setCustomSections] = useState(() => {
    const normalizedCode = String(examCode || '')
      .trim()
      .toUpperCase()
      .replace(/\s+/g, '_');
    if (normalizedCode && typeof window !== 'undefined') {
      const storageKey = `weaver_sections_${normalizedCode}`;
      const stored = window.localStorage.getItem(storageKey);
      if (stored) {
        try {
          return JSON.parse(stored);
        } catch (error) {
          console.warn('Failed to parse stored sections', error);
        }
      }
    }
    return [];
  });

  // Auto-generate customSections based on examContent
  useEffect(() => {
    if (!examContent) return;

    const sectionLabelMap = {
      listening: 'Listening',
      grammar: 'Grammar & Vocabulary',
      reading: 'Reading',
      writing: 'Writing',
      speaking: 'Speaking',
    };

    setCustomSections((prevSections) => {
      // If already loaded from localStorage, don't override
      if (prevSections.length > 0) return prevSections;

      // If examContent has customSections, use it (preserves order from exam builder)
      if (Array.isArray(examContent.customSections) && examContent.customSections.length > 0) {
        return examContent.customSections;
      }

      // Fallback: Generate sections from examContent keys
      const sortedKeys = Object.keys(examContent).sort((a, b) => {
        const order = ['listening', 'reading', 'grammar', 'writing', 'speaking'];
        const idxA = order.indexOf(a);
        const idxB = order.indexOf(b);
        if (idxA !== -1 && idxB !== -1) return idxA - idxB;
        if (idxA !== -1) return -1;
        if (idxB !== -1) return 1;
        return a.localeCompare(b);
      });

      const generatedSections = sortedKeys.map((key) => {
        let label = sectionLabelMap[key];
        if (!label && examContent[key]?.title) label = examContent[key].title;
        if (!label) label = key.charAt(0).toUpperCase() + key.slice(1);

        return { key, label, enabled: true };
      });

      return generatedSections;
    });
  }, [examContent]);

  const sectionTabsAll = useMemo(() => {
    if (!examContent) return [];
    return buildSectionTabs(customSections, examContent);
  }, [customSections, examContent]);

  // Hide ALL speaking tabs (default and custom) when speakingMode is set to '1v1'
  const sectionTabs = useMemo(() => {
    if (Array.isArray(sectionTabsAll) && examContent?.options?.speakingMode === '1v1') {
      return sectionTabsAll.filter((t) => {
        const key = (t.key || '').toLowerCase();
        const type = (t.type || '').toLowerCase();
        return key !== 'speaking' && type !== 'speaking';
      });
    }
    return sectionTabsAll;
  }, [sectionTabsAll, examContent]);

  const hideSectionTabs = Array.isArray(sectionTabs) && sectionTabs.length <= 1;

  const numberingContext = useMemo(() => buildGlobalNumbering(sectionTabs), [sectionTabs]);

  // Calculate non-speaking keys & count (non-speaking sections only) for the modal
  const nonSpeakingKeys = useMemo(() => {
    if (!Array.isArray(sectionTabsAll) || sectionTabsAll.length === 0) return [];
    return sectionTabsAll
      .filter((t) => {
        const key = (t.key || '').toLowerCase();
        const type = (t.type || '').toLowerCase();
        return (
          key !== 'speaking' && type !== 'speaking' && (t.enabled === undefined || t.enabled === true)
        );
      })
      .map((t) => t.key);
  }, [sectionTabsAll]);

  const answerKeyMap = useMemo(() => deriveAnswerKey(examContent), [examContent]);

  const navigationSections = useMemo(() => {
    const offsets = numberingContext?.sectionOffsets || {};
    return sectionTabs.map((tab) => {
      const baseOffset = offsets?.[tab.key] ?? 0;
      const timeStr =
        tab?.data?.timeAllotted || (tab.key && examContent?.[tab.key]?.timeAllotted) || '0';
      const durationSeconds = parseTimeAllottedToSeconds(timeStr);
      return {
        key: tab.key,
        label: tab.label,
        items: extractQuestionItems(tab.key, tab.data, baseOffset + 1),
        timeAllottedSeconds: durationSeconds,
      };
    });
  }, [sectionTabs, numberingContext, examContent]);

  return {
    examContent,
    loading,
    fetchFailed,
    remoteExamError,
    customSections,
    setCustomSections,
    sectionTabsAll,
    sectionTabs,
    hideSectionTabs,
    answerKeyMap,
    numberingContext,
    nonSpeakingKeys,
    navigationSections,
  };
}
