import React, { useState, useRef, useEffect } from 'react';
import { MessageSquare, X, Send, Upload, Sparkles, ChevronLeft, ChevronRight, RotateCcw, FileText } from 'lucide-react';
import { API_BASE_URL } from '../../constants';
import mammoth from 'mammoth';

const AISidebar = ({ currentExam, onExamUpdate, isOpen: propIsOpen, onToggle, onPendingImagesChange }) => {
  // Use internal state if props are not provided (backward compatibility)
  const [internalIsOpen, setInternalIsOpen] = useState(true);

  const isControlled = typeof propIsOpen !== 'undefined';
  const isOpen = isControlled ? propIsOpen : internalIsOpen;
  const setIsOpen = isControlled ? onToggle : setInternalIsOpen;

  const [messages, setMessages] = useState(() => {
    // Load from sessionStorage if available
    try {
      const saved = window.sessionStorage.getItem('weaver_ai_chat_history');
      if (saved) return JSON.parse(saved);
    } catch (e) {
      console.warn('Failed to load chat history', e);
    }
    return [
      {
        role: 'assistant',
        content: '👋 Hi! I\'m your AI assistant. I can help you create exam questions. Tell me what you need or upload an image!'
      }
    ];
  });

  // Persist messages to sessionStorage
  useEffect(() => {
    window.sessionStorage.setItem('weaver_ai_chat_history', JSON.stringify(messages));
  }, [messages]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [uploadedImage, setUploadedImage] = useState(null);
  const [uploadedFile, setUploadedFile] = useState(null); // Store file for later upload
  const [attachedDoc, setAttachedDoc] = useState(null); // Defer docx parsing until send
  const [pendingImages, setPendingImages] = useState([]); // Track images for batch upload on save
  const fileInputRef = useRef(null);
  const messagesEndRef = useRef(null);
  const textareaRef = useRef(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const handleResetChat = () => {
    // Clear State
    setMessages([
      {
        role: 'assistant',
        content: '👋 Hi! I\'m your AI assistant. I can help you create exam questions. Tell me what you need or upload an image!'
      }
    ]);
    setUploadedImage(null);
    setUploadedFile(null);
    setAttachedDoc(null);
    setPendingImages([]);

    // Clear SessionStorage
    window.sessionStorage.removeItem('weaver_ai_chat_history');
    console.log('🔄 Chat history reset.');
  };

  const [isDragging, setIsDragging] = useState(false);

  const processFile = async (file) => {
    if (!file) return;

    // Handle Images
    if (file.type.startsWith('image/')) {
      const reader = new FileReader();
      reader.onload = (event) => {
        setUploadedImage(event.target.result);
        setUploadedFile(file); // Store file reference for upload

        // Add to pending images
        const newPendingImage = {
          dataUrl: event.target.result,
          file: file,
          fileName: file.name
        };
        setPendingImages(prev => {
          const updated = [...prev, newPendingImage];
          // Notify parent about pending images
          onPendingImagesChange?.(updated);
          return updated;
        });
      };
      reader.readAsDataURL(file);
    }
    // Handle Word Documents (.docx)
    else if (file.name.endsWith('.docx') || file.type === 'application/vnd.openxmlformats-officedocument.wordprocessingml.document') {
      // Just attach the file, don't read yet
      setAttachedDoc(file);

      // Notify user via UI (not chat message) that file is attached
      console.log(`📎 Attached file: ${file.name}`);

      // Reset file input so same file can be selected again
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleFileUpload = (e) => {
    processFile(e.target.files[0]);
  };

  // Drag and Drop Handlers
  const handleDragOver = (e) => {
    e.preventDefault();
    setIsDragging(true);
  };

  const handleDragLeave = (e) => {
    e.preventDefault();
    setIsDragging(false);
  };

  const handleDrop = (e) => {
    e.preventDefault();
    setIsDragging(false);

    if (e.dataTransfer.files && e.dataTransfer.files.length > 0) {
      processFile(e.dataTransfer.files[0]);
    }
  };

  const handleSendMessage = async () => {
    if (!input.trim() && !uploadedImage && !attachedDoc) return;

    let textToSend = input;

    // Process Attached Docx if exists
    if (attachedDoc) {
      setIsLoading(true);
      // Add a temporary system message to show we are reading
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: `📖 Reading content from ${attachedDoc.name}...`
      }]);

      try {
        const arrayBuffer = await attachedDoc.arrayBuffer();
        const result = await mammoth.extractRawText({ arrayBuffer });
        const extractedText = result.value;

        console.log(`📝 [Frontend] Extracted ${extractedText.length} chars from ${attachedDoc.name}`);

        // Append extracted text to the user input wrapper
        textToSend = (textToSend ? textToSend + '\n\n' : '') + `[Extracted from ${attachedDoc.name}]:\n` + extractedText;

      } catch (error) {
        console.error("Failed to read DOCX:", error);
        setMessages(prev => [...prev, {
          role: 'assistant',
          content: `❌ Failed to read Word file: ${error.message}`
        }]);
        setIsLoading(false);
        return; // Stop if failed
      }
    }

    const userMessage = {
      role: 'user',
      content: textToSend,
      image: uploadedImage
    };

    setMessages(prev => [...prev, {
      role: 'user',
      content: input + (attachedDoc ? `\n[Attached: ${attachedDoc.name}]` : ''), // Display simple version to user
      image: uploadedImage
    }]);

    setInput('');
    setUploadedImage(null);
    setAttachedDoc(null);

    // Reset textarea height
    if (textareaRef.current) {
      textareaRef.current.style.height = '52px';
    }

    setIsLoading(true);

    try {
      // Only send minimal context, NOT the full exam JSON (which confuses the AI)
      // The AI should focus on the image content, not the existing exam structure
      const examContext = ''; // Disabled - full exam structure was confusing the vision model

      // Use Backend API
      const response = await fetch(`${API_BASE_URL}/api/generate-exam`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          messages: [...messages, {
            ...userMessage,
            content: userMessage.content + examContext
          }]
        })
      });

      const data = await response.json();

      if (data.success) {
        setMessages(prev => [...prev, {
          role: 'assistant',
          content: data.explanation,
          code: data.generatedCode
        }]);

        if (data.generatedCode) {
          // Try to parse and update exam
          try {
            // Guard: ensure we have non-empty string code
            if (!data.generatedCode || typeof data.generatedCode !== 'string' || !data.generatedCode.trim()) {
              throw new Error('Empty or invalid generated code');
            }

            // Extract the question object from generated code
            let codeToEval = data.generatedCode;

            // Remove export statements and clean up
            codeToEval = codeToEval
              .replace(/export\s+(const|let|var)\s+\w+\s*=\s*/, '')
              .replace(/;?\s*$/, '')
              .trim();

            console.log('🔧 Parsing code:', codeToEval);

            // Use Function constructor instead of eval for safety
            const generatedQuestion = new Function(`return ${codeToEval}`)();

            console.log('✅ Parsed question:', generatedQuestion);

            // Call parent to update exam
            if (onExamUpdate && generatedQuestion) {
              onExamUpdate(generatedQuestion);
              console.log('📤 Sent to parent component');
            } else {
              console.warn('⚠️ Missing onExamUpdate or generatedQuestion');
            }
          } catch (parseError) {
            console.error('❌ Failed to parse generated question:', parseError);
            console.error('Code:', data.generatedCode);

            setMessages(prev => [...prev, {
              role: 'assistant',
              content: `⚠️ Couldn't parse generated code. Error: ${parseError.message}`
            }]);
          }
        }
      } else {
        // Backend returned success: false
        // Extract main error message
        let errorMsg = data.error || 'Unknown error';

        setMessages(prev => [...prev, {
          role: 'assistant',
          content: `❌ AI Error: ${errorMsg}`
        }]);
      }
    } catch (error) {
      // Network or Server error
      setMessages(prev => [...prev, {
        role: 'assistant',
        content: `❌ Server Connection Error: ${error.message}. Ensure API server is running on port 3001.`
      }]);
    } finally {
      setIsLoading(false);
    }
  };

  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSendMessage();
    }
    // Shift+Enter will allow newline (default behavior)
  };

  // Handle paste from clipboard
  const handlePaste = async (e) => {
    const items = e.clipboardData?.items;
    if (!items) return;

    for (let i = 0; i < items.length; i++) {
      const item = items[i];

      // Check if item is an image
      if (item.type.indexOf('image') !== -1) {
        e.preventDefault();
        const blob = item.getAsFile();

        if (blob) {
          const reader = new FileReader();
          reader.onload = (e) => {
            setUploadedImage(e.target.result);
            // Show notification
            const notification = document.createElement('div');
            notification.className = 'fixed top-4 right-4 bg-green-500 text-white px-4 py-2 rounded-lg shadow-lg z-50 animate-fade-in';
            notification.textContent = '📋 Image pasted from clipboard!';
            document.body.appendChild(notification);
            setTimeout(() => notification.remove(), 2000);
          };
          reader.readAsDataURL(blob);
        }
        break;
      }
    }
  };

  return (
    <>
      {/* Collapsed Icon */}
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="fixed left-0 top-1/2 -translate-y-1/2 z-50 bg-gradient-to-br from-purple-500 to-pink-500 text-white p-1 rounded-r-2xl shadow-2xl hover:shadow-purple-500/50 transition-all hover:scale-110 group"
          title="Open AI Assistant"
        >
          <Sparkles className="w-5 h-5 group-hover:animate-pulse" />
          <span className="absolute left-14 top-1/2 -translate-y-1/2 bg-slate-900 text-white text-sm px-3 py-1 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap pointer-events-none">
            Open AI Assistant
          </span>
        </button>
      )}

      {/* Sidebar */}
      {isOpen && (
        <div
          className="fixed left-0 top-0 h-full w-[420px] bg-gradient-to-b from-slate-900 via-slate-800 to-slate-900 border-r border-purple-500/30 shadow-2xl z-[60] flex flex-col"
          onDragOver={handleDragOver}
          onDragLeave={handleDragLeave}
          onDrop={handleDrop}
        >
          {/* Drag Overlay */}
          {isDragging && (
            <div className="absolute inset-0 z-[70] bg-purple-500/20 backdrop-blur-sm border-4 border-dashed border-purple-400 m-4 rounded-3xl flex flex-col items-center justify-center animate-pulse pointer-events-none">
              <Upload className="w-16 h-16 text-purple-200 mb-4" />
              <h3 className="text-2xl font-bold text-white drop-shadow-lg">Drop file to upload</h3>
              <p className="text-purple-200 mt-2">Images or Word Documents</p>
            </div>
          )}

          {/* Header */}
          <div className="bg-gradient-to-r from-purple-600 via-pink-600 to-purple-600 p-5 flex items-center justify-between shadow-lg">
            <div className="flex items-center gap-3">
              <div className="bg-white/20 p-2 rounded-lg backdrop-blur">
                <Sparkles className="w-6 h-6 text-white animate-pulse" />
              </div>
              <div>
                <h2 className="text-white font-bold text-lg leading-tight">AI Assistant</h2>
                <p className="text-purple-100 text-xs opacity-90">Powered by Gemini (Backend)</p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <button
                onClick={handleResetChat}
                className="p-2 hover:bg-white/20 rounded-lg text-white/90 hover:text-white transition-colors"
                title="Reset Chat & Context"
              >
                <RotateCcw className="w-5 h-5" />
              </button>
              <button
                onClick={() => setIsOpen(false)}
                className="p-2 hover:bg-white/20 rounded-lg text-white/90 hover:text-white transition-colors"
              >
                <ChevronLeft className="w-5 h-5" />
              </button>
            </div>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-5 space-y-4 bg-slate-900/50">
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[95%] rounded-2xl p-4 shadow-lg ${msg.role === 'user'
                    ? 'bg-gradient-to-br from-blue-500 to-blue-600 text-white'
                    : 'bg-gradient-to-br from-slate-700 to-slate-800 text-slate-100 border border-purple-500/20'
                    }`}
                >
                  {msg.image && (
                    <img src={msg.image} alt="Upload" className="rounded-lg mb-3 max-h-48 border-2 border-white/20" />
                  )}
                  <p className="text-sm leading-relaxed whitespace-pre-wrap break-words" style={{ wordBreak: 'break-word', overflowWrap: 'break-word' }}>{msg.content}</p>
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-gradient-to-br from-slate-700 to-slate-800 text-slate-100 rounded-2xl p-4 border border-purple-500/20">
                  <div className="flex items-center gap-3">
                    <div className="flex gap-1">
                      <div className="w-2.5 h-2.5 bg-purple-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                      <div className="w-2.5 h-2.5 bg-pink-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }} />
                      <div className="w-2.5 h-2.5 bg-purple-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }} />
                    </div>
                    <span className="text-sm text-purple-300">AI is thinking...</span>
                  </div>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input */}
          <div className="border-t border-purple-500/30 p-5 bg-slate-800/80 backdrop-blur">
            {uploadedImage && (
              <div className="mb-3 relative inline-block">
                <img src={uploadedImage} alt="Preview" className="h-24 rounded-lg border-2 border-purple-500/50 shadow-lg" />
                <button
                  onClick={() => setUploadedImage(null)}
                  className="absolute -top-2 -right-2 bg-red-500 hover:bg-red-600 text-white rounded-full p-1.5 shadow-lg transition"
                >
                  <X className="w-4 h-4" />
                </button>
              </div>
            )}

            {attachedDoc && (
              <div className="mb-3 relative inline-flex items-center gap-2 bg-slate-700/80 px-4 py-3 rounded-xl border border-purple-500/30 shadow-lg">
                <FileText className="w-8 h-8 text-blue-400" />
                <div>
                  <p className="text-white text-sm font-medium truncate max-w-[200px]">{attachedDoc.name}</p>
                  <p className="text-slate-400 text-xs">{(attachedDoc.size / 1024).toFixed(1)} KB</p>
                </div>
                <button
                  onClick={() => setAttachedDoc(null)}
                  className="absolute -top-2 -right-2 bg-red-500 hover:bg-red-600 text-white rounded-full p-1.5 shadow-lg transition"
                >
                  <X className="w-3 h-3" />
                </button>
              </div>
            )}
            <div className="flex items-center gap-2">
              <input
                type="file"
                ref={fileInputRef}
                onChange={handleFileUpload}
                accept="image/*,.docx,application/vnd.openxmlformats-officedocument.wordprocessingml.document"
                className="hidden"
              />
              <button
                onClick={() => fileInputRef.current?.click()}
                className="flex-shrink-0 bg-purple-600 hover:bg-purple-700 text-white p-3.5 rounded-2xl transition-all shadow-lg hover:shadow-purple-500/50 hover:scale-105 active:scale-95"
                title="Upload image"
              >
                <Upload className="w-5 h-5" />
              </button>
              <textarea
                ref={textareaRef}
                value={input}
                onChange={(e) => setInput(e.target.value)}
                onKeyDown={handleKeyPress}
                onPaste={handlePaste}
                placeholder="Type message or paste image"
                rows={1}
                className="flex-1 bg-slate-700/80 text-white px-4 py-3 rounded-2xl focus:outline-none focus:ring-2 focus:ring-purple-500/50 focus:bg-slate-700 border border-slate-600/50 placeholder:text-slate-400 resize-none min-h-[52px] max-h-[200px] overflow-y-auto transition-all"
                style={{
                  height: 'auto',
                  minHeight: '52px'
                }}
                onInput={(e) => {
                  e.target.style.height = 'auto';
                  e.target.style.height = Math.min(e.target.scrollHeight, 200) + 'px';
                }}
              />
              <button
                onClick={handleSendMessage}
                disabled={isLoading || (!input.trim() && !uploadedImage && !attachedDoc)}
                className="flex-shrink-0 bg-gradient-to-r from-purple-500 to-pink-500 hover:from-purple-600 hover:to-pink-600 text-white p-3.5 rounded-2xl transition-all shadow-lg hover:shadow-pink-500/50 disabled:opacity-40 disabled:cursor-not-allowed disabled:shadow-none hover:scale-105 active:scale-95 disabled:hover:scale-100"
              >
                <Send className="w-5 h-5" />
              </button>
            </div>
          </div>
        </div>
      )}
    </>
  );
};

export default AISidebar;
