import React, { useCallback } from "react";

import { normalizeAnswer, normalizeTFNG, formatTFNG } from "../../../utils/normalizeAnswer";


const ensureArray = (value) => {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined) return [];
  return [value];
};

const renderContentWithPlaceholders = (content = "", startIndex = 1) => {
  const parts = String(content).split(/_{2,}/g);
  const blanks = (content.match(/_{2,}/g) || []).length;
  const nodes = [];

  parts.forEach((part, idx) => {
    if (part) {
      nodes.push(
        <span key={`mc-text-${idx}`} className="align-middle">
          {part}
        </span>
      );
    }

    if (idx < blanks) {
      const number = startIndex + idx;
      nodes.push(
        <span
          key={`mc-blank-${idx}`}
          className="inline-flex items-center gap-1 align-middle"
        >
          <span className="inline-flex h-5 px-0.5 items-center justify-center rounded-md border border-orange-200 bg-orange-50 text-[9px] font-semibold text-orange-600 shadow-sm">
            {number}
          </span>
          <span className="inline-block align-middle px-2 font-semibold text-yellow-700 leading-6 tracking-[0.2em]">
            __________
          </span>
        </span>
      );
    }
  });

  return nodes;
};

const MultipleChoicePreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  allowMultiple,
  questionNumber = "1",
  name,
  // === NEW: Edit Mode Props ===
  editMode = false,
  onQuestionChange,
}) => {
  const safeIdPieces = [
    question?.surfaceId,
    question?.id,
    name,
    questionNumber,
    "default",
  ].filter(Boolean);
  const surfaceId = `mc-surface-${safeIdPieces[0]}`;

  // === EDIT MODE HANDLERS (MUST be before any conditional returns) ===
  const handleOptionLabelChange = useCallback((index, newLabel) => {
    if (!editMode || !onQuestionChange) return;
    onQuestionChange(prev => {
      const newOptions = [...(prev.options || [])];
      newOptions[index] = { ...newOptions[index], label: newLabel, value: newLabel };
      return { ...prev, options: newOptions };
    });
  }, [editMode, onQuestionChange]);

  const handleAddOption = useCallback(() => {
    if (!editMode || !onQuestionChange) return;
    onQuestionChange(prev => {
      const newOptions = [...(prev.options || [])];
      const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
      const nextLetter = letters[newOptions.length] || `${newOptions.length + 1}`;
      newOptions.push({ value: nextLetter, label: `Option ${nextLetter}` });
      return { ...prev, options: newOptions };
    });
  }, [editMode, onQuestionChange]);

  const handleRemoveOption = useCallback((index) => {
    if (!editMode || !onQuestionChange) return;
    onQuestionChange(prev => {
      const newOptions = [...(prev.options || [])];
      newOptions.splice(index, 1);
      return { ...prev, options: newOptions };
    });
  }, [editMode, onQuestionChange]);

  const handleCorrectAnswerChange = useCallback((optionValue, isChecked) => {
    if (!editMode || !onQuestionChange) return;
    const multiSelect = allowMultiple != null ? allowMultiple : (question?.allowMultiple ?? question?.type === "checkbox");

    onQuestionChange(prev => {
      if (multiSelect) {
        const currentAnswers = ensureArray(prev.correctAnswers);
        const newAnswers = isChecked
          ? [...currentAnswers, optionValue]
          : currentAnswers.filter(a => normalizeAnswer(a) !== normalizeAnswer(optionValue));
        return { ...prev, correctAnswers: newAnswers };
      } else {
        return { ...prev, correctAnswers: [optionValue] };
      }
    });
  }, [editMode, onQuestionChange, allowMultiple, question?.type, question?.allowMultiple]);

  // Early return AFTER all hooks
  if (!question) return null;

  // Handle subQuestions format (content-based with multiple questions)
  const hasSubQuestions = Array.isArray(question.subQuestions) && question.subQuestions.length > 0;

  if (hasSubQuestions) {
    // Extract starting number from questionNumber (handle "1-10" format)
    const startingNumber = parseInt(String(questionNumber).split("-")[0]) || 1;

    return (
      <div
        className="flex flex-col relative"
      >
        {/* Fixed header with content */}
        {question.content && (
          <div className="flex-shrink-0 bg-slate-50 p-4 rounded border border-slate-200 mb-4">
            <p className="text-sm text-slate-700 whitespace-pre-wrap">
              {renderContentWithPlaceholders(question.content, startingNumber)}
            </p>
          </div>
        )}

        {/* Scrollable questions area */}
        <div
          className="space-y-6 relative"
          data-highlight-surface-id={surfaceId}
        >
          {question.subQuestions.map((subQuestion, qIndex) => {
            const subQuestionNumber = startingNumber + qIndex;
            const hasOwnOptions = Array.isArray(subQuestion.options) && subQuestion.options.length > 0;
            const subOptions = hasOwnOptions
              ? subQuestion.options
              : (Array.isArray(question.options) ? question.options : []);
            // Use select box when subQuestions share parent-level options
            const useSelectBox = !hasOwnOptions && Array.isArray(question.options) && question.options.length > 0;

            if (subOptions.length === 0) {
              return (
                <div key={`subq-${qIndex}`} className="rounded border border-dashed border-slate-300 bg-slate-50 px-3 py-2 text-sm text-slate-500">
                  Add options to preview question {subQuestionNumber}.
                </div>
              );
            }

            const subValue = Array.isArray(value) ? value[qIndex] : value?.[subQuestion.id];
            const subCorrectAnswers = ensureArray(subQuestion.correctAnswers);
            const normalizedSubCorrect = subCorrectAnswers.map(normalizeAnswer);

            const toggleOption = (optionValue) => {
              if (!onChange || disabled || (reviewMode)) return;

              // Always use array format for subQuestions
              const currentArray = Array.isArray(value) ? [...value] : new Array(question.subQuestions.length);
              currentArray[qIndex] = optionValue;
              onChange(currentArray);
            };

            const isUserChoice = (optionValue) => {
              if (Array.isArray(value)) {
                return normalizeAnswer(value[qIndex]) === normalizeAnswer(optionValue);
              }
              return normalizeAnswer(subValue) === normalizeAnswer(optionValue);
            };

            const isCorrectOption = (optionValue) => {
              return normalizedSubCorrect.some(
                (answer) => answer === normalizeAnswer(optionValue)
              );
            };

            const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

            // --- SELECT BOX MODE for shared options ---
            if (useSelectBox) {
              const normalizedUserValue = normalizeAnswer(subValue);
              const isTFNG = normalizedSubCorrect.some(a => ["t", "f", "true", "false", "yes", "no", "y", "n", "not given"].includes(a));

              const isAnswerCorrect = reviewMode && normalizedSubCorrect.length > 0
                ? (isTFNG
                  ? normalizedSubCorrect.some(a => normalizeTFNG(a) === normalizeTFNG(normalizedUserValue))
                  : normalizedSubCorrect.includes(normalizedUserValue))
                : false;
              const isAnswerIncorrect = reviewMode && normalizedSubCorrect.length > 0
                && normalizedUserValue
                && !isAnswerCorrect;

              return (
                <div key={`subq-${qIndex}`} className="py-2">
                  <div className="mb-2 flex items-start gap-2.5">
                    <span className="inline-flex h-7 min-w-[2rem] flex-shrink-0 items-center justify-center rounded-lg border border-orange-200 bg-orange-50 px-2 text-xs font-semibold text-orange-500 shadow-sm">
                      {subQuestionNumber}
                    </span>
                    <p className="text-sm font-medium text-slate-800 rich-text-content [&_div]:w-fit" dangerouslySetInnerHTML={{ __html: (subQuestion.prompt || '').replace(/^\s*\d+\.?\s*/, '') }} />
                  </div>
                  <div className="ml-10">
                    <select
                      value={(() => {
                        const match = subOptions.find(opt => {
                          const optVal = typeof opt === 'string' ? opt : (opt.value ?? opt.label ?? '');
                          return normalizeAnswer(optVal) === normalizeAnswer(subValue);
                        });
                        return match !== undefined ? (typeof match === 'object' ? match.value : match) : (subValue ?? "");
                      })()}
                      onChange={(event) => toggleOption(event.target.value)}
                      disabled={disabled || (reviewMode) || !onChange}
                      data-testid={`mc-select-q${subQuestionNumber}`}
                      data-question-slot-number={subQuestionNumber}
                      className={`w-full max-w-xs rounded-lg border px-3 py-1.5 text-sm shadow-sm focus:outline-none focus:ring-2 appearance-none cursor-pointer bg-white ${reviewMode
                        ? isAnswerCorrect
                          ? "border-green-400 bg-green-50 focus:ring-green-200"
                          : isAnswerIncorrect
                            ? "border-red-300 focus:ring-red-200"
                            : "border-slate-200 focus:ring-blue-200"
                        : "border-slate-200 focus:border-blue-500 focus:ring-blue-200"
                        }`}
                    >
                      <option value="">Select answer...</option>
                      {subOptions.map((option, oIndex) => {
                        const optVal = typeof option === 'string' ? option : (option.value ?? option.label ?? `option-${oIndex}`);
                        const optLabel = typeof option === 'string' ? option : (option.label || optVal);
                        const displayText = typeof option === 'object' && option.label && option.value !== option.label
                          ? `${option.value} - ${option.label.length > 60 ? option.label.substring(0, 60) + '...' : option.label}`
                          : optLabel;
                        return (
                          <option key={optVal} value={optVal}>
                            {displayText}
                          </option>
                        );
                      })}
                    </select>
                    {reviewMode && (
                      <div className="mt-1 flex items-center gap-2 text-xs">
                        {isAnswerCorrect && (
                          <span className="font-semibold text-green-600">✓ Correct</span>
                        )}
                        {isAnswerIncorrect && (
                          <span className="font-semibold text-red-600">
                            ✗ Incorrect (Answer: {subCorrectAnswers.map(a => formatTFNG(a)).join(" / ")})
                          </span>
                        )}
                      </div>
                    )}
                  </div>
                </div>
              );
            }

            // --- RADIO BUTTON MODE for per-subQuestion options ---
            return (
              <div key={`subq-${qIndex}`} className="py-2">
                <div className="mb-3 flex items-start gap-2.5">
                  <span className="inline-flex h-7 min-w-[2rem] flex-shrink-0 items-center justify-center rounded-lg border border-orange-200 bg-orange-50 px-2 text-xs font-semibold text-orange-500 shadow-sm">
                    {subQuestionNumber}
                  </span>
                  <p className="text-sm font-medium text-slate-800 rich-text-content [&_div]:w-fit" dangerouslySetInnerHTML={{ __html: (subQuestion.prompt || '').replace(/^\s*\d+\.?\s*/, '') }} />
                </div>

                <div className="space-y-2 ml-0">
                  {subOptions.map((option, oIndex) => {
                    const optionValue = typeof option === 'string' ? option : (option.value ?? option.label ?? `option-${oIndex}`);
                    const optionLabel = typeof option === 'string' ? option : (option.label || optionValue);
                    const userSelected = isUserChoice(optionValue);
                    const correct = isCorrectOption(optionValue);

                    const highlightClass = reviewMode
                      ? correct
                        ? ""
                        : userSelected
                          ? "border-red-300"
                          : "border-transparent"
                      : userSelected
                        ? "border-orange-300 bg-orange-50"
                        : "border-transparent";

                    const displayLabel = letters[oIndex] || `${oIndex + 1}`;

                    return (
                      <label
                        key={`option-${subQuestion.id}-${oIndex}`}
                        className={`flex cursor-pointer items-center gap-3 rounded-lg border ${highlightClass} px-3 py-2 text-sm transition hover:border-orange-300 hover:bg-orange-50`}
                      >
                        <span className="font-semibold text-slate-700 min-w-[1.5rem]">{displayLabel}</span>
                        <input
                          type="radio"
                          name={`${name || question.id}-${qIndex}`}
                          value={optionValue}
                          checked={userSelected}
                          onChange={() => toggleOption(optionValue)}
                          disabled={disabled || (reviewMode) || !onChange}
                          data-testid={`mc-radio-q${subQuestionNumber}-${displayLabel}`}
                          data-question-slot-number={subQuestionNumber}
                          className="h-4 w-4 text-blue-600 focus:ring-blue-500 flex-shrink-0"
                        />
                        <span className="text-sm text-slate-700">{optionLabel}</span>
                        {reviewMode && correct && userSelected && (
                          <span className="ml-auto text-xs font-semibold text-green-600">Correct</span>
                        )}
                      </label>
                    );
                  })}
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  // Original single-question multiple choice logic
  const options = Array.isArray(question.options) ? question.options : [];

  if (options.length === 0 && !editMode) {
    return (
      <div className="rounded border border-dashed border-slate-300 bg-slate-50 px-3 py-2 text-sm text-slate-500">
        Add options to preview this question.
      </div>
    );
  }

  // Extract starting number from questionNumber (handle both "1" and "1 - 3" format)
  const startingNumber = parseInt(String(questionNumber).split(" ")[0]) || 1;

  const multiSelect =
    allowMultiple != null ? allowMultiple : (question.allowMultiple ?? question.type === "checkbox");
  const currentSelections = ensureArray(value);
  const baseCorrectAnswers = ensureArray(question.correctAnswers || correctAnswers);
  const normalizedCorrect = baseCorrectAnswers.map(normalizeAnswer);
  const isInteractive = typeof onChange === "function";

  // Maximum selections = number of correct answers for checkbox
  const maxSelections = multiSelect ? normalizedCorrect.length || options.length : 1;

  const toggleOption = (optionValue) => {
    if (!isInteractive) return;
    if (multiSelect) {
      const normalized = normalizeAnswer(optionValue);
      const nextSelections = [...currentSelections];
      const existingIndex = nextSelections.findIndex(
        (entry) => normalizeAnswer(entry) === normalized
      );
      if (existingIndex >= 0) {
        nextSelections.splice(existingIndex, 1);
      } else {
        // Only allow if haven't reached max selections
        if (nextSelections.length < maxSelections) {
          nextSelections.push(optionValue);
        }
      }
      onChange(nextSelections);
    } else {
      onChange(optionValue);
    }
  };

  // Generate letter labels (A, B, C, D, E, F, G, H, ...)
  const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ".split("");

  return (
    <div
      className="space-y-2 relative"
      data-highlight-surface-id={surfaceId}
    >
      {/* Edit mode toolbar */}
      {editMode && (
        <div className="flex items-center justify-between rounded-lg border border-blue-200 bg-blue-50 px-3 py-2 mb-3">
          <div className="text-xs text-blue-600">
            <span className="font-semibold">📝 Edit Mode</span> — Click option text to edit. Check ✓ to mark correct answer.
          </div>
          <button
            type="button"
            onClick={handleAddOption}
            className="rounded border border-emerald-300 bg-emerald-50 px-2 py-1 text-xs font-semibold text-emerald-600 transition hover:bg-emerald-100"
          >
            + Add Option
          </button>
        </div>
      )}

      {question.content ? (
        <p className="text-sm text-slate-700 whitespace-pre-wrap">
          {renderContentWithPlaceholders(question.content, startingNumber)}
        </p>
      ) : null}

      {options.map((option, index) => {
        const optionValue = typeof option === 'string' ? option : (option.value ?? option.label ?? `option-${index}`);
        const normalizedOption = normalizeAnswer(optionValue);
        const isUserChoice = currentSelections.some(
          (selection) => normalizeAnswer(selection) === normalizedOption
        );
        const isCorrect = normalizedCorrect.some(
          (answer) => answer === normalizedOption
        );

        const highlightClass = reviewMode
          ? isCorrect && isUserChoice
            ? "border-green-300 bg-green-50"
            : isUserChoice
              ? "border-red-300"
              : "border-transparent"
          : editMode
            ? isCorrect
              ? "border-green-300 bg-green-50"
              : "border-blue-200"
            : isUserChoice
              ? "border-orange-300 bg-orange-50"
              : "border-transparent";

        // Always show letter (A, B, C, ...)
        const displayLabel = letters[index] || `${index + 1}`;

        const isSelectionDisabled = disabled || (reviewMode) || !isInteractive || (multiSelect && !isUserChoice && currentSelections.length >= maxSelections);
        const RowTag = editMode ? 'div' : 'label';

        return (
          <RowTag
            key={`option-${question.id}-${index}`}
            className={`flex items-center gap-3 rounded-lg border ${highlightClass} px-3 py-2 text-sm transition ${editMode ? "" : isSelectionDisabled ? "cursor-not-allowed opacity-60" : "cursor-pointer hover:border-orange-300 hover:bg-orange-50"}`}
          >
            {/* Correct answer checkbox in edit mode */}
            {editMode && (
              <input
                type={multiSelect ? "checkbox" : "radio"}
                name={`correct-${question.id}`}
                checked={isCorrect}
                onChange={(e) => handleCorrectAnswerChange(optionValue, e.target.checked)}
                className="h-4 w-4 text-green-600 focus:ring-green-500 flex-shrink-0"
                title="Mark as correct answer"
              />
            )}

            <span className="font-semibold text-slate-700 min-w-[1.5rem]">{displayLabel}</span>

            {/* Option label - editable in edit mode */}
            {editMode ? (
              <input
                type="text"
                value={option.label || optionValue}
                onChange={(e) => handleOptionLabelChange(index, e.target.value)}
                className="flex-1 rounded border border-slate-300 px-2 py-1 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                placeholder="Option text..."
              />
            ) : (
              <>
                <input
                  type={multiSelect ? "checkbox" : "radio"}
                  name={name || question.id || "multiple-choice"}
                  value={optionValue}
                  checked={isUserChoice}
                  onChange={() => toggleOption(optionValue)}
                  data-testid={`mc-${multiSelect ? 'checkbox' : 'radio'}-q${startingNumber}-${displayLabel}`}
                  data-question-slot-index={index}
                  data-question-slot-number={startingNumber + index}
                  data-question-slot-id={option.id || `${question.id || "option"}-${index}`}
                  disabled={isSelectionDisabled}
                  className="h-4 w-4 text-blue-600 focus:ring-blue-500 flex-shrink-0"
                />
                <span className="text-sm text-slate-700">{typeof option === 'string' ? option : (option.label || optionValue)}</span>
              </>
            )}

            {/* Delete button in edit mode */}
            {editMode && (
              <button
                type="button"
                onClick={() => handleRemoveOption(index)}
                className="ml-auto text-red-400 hover:text-red-600 text-xs"
                title="Remove option"
              >
                🗑
              </button>
            )}

            {reviewMode && isCorrect && isUserChoice ? (
              <span className="ml-auto text-xs font-semibold text-green-600">Correct</span>
            ) : null}
          </RowTag>
        );
      })}

      {/* Empty state for edit mode */}
      {editMode && options.length === 0 && (
        <div className="rounded border border-dashed border-slate-300 bg-slate-50 px-3 py-4 text-center text-sm text-slate-500">
          No options yet. Click "Add Option" to create options.
        </div>
      )}
    </div>
  );
};

export default MultipleChoicePreview;
