// Helper: parse timeAllotted strings like '15 mins', '0.5 minutes', or '30 seconds' to seconds
export const parseTimeAllottedToSeconds = (value) => {
  if (!value) return 0;
  if (typeof value === 'number') return Math.max(0, Math.round(value));
  if (typeof value === 'string') {
    const m = value.match(/([\d.]+)\s*\b(mins?|minutes?|m)\b/i);
    if (m) return Math.round(parseFloat(m[1]) * 60);
    const s = value.match(/([\d.]+)\s*\b(sec|secs?|seconds?|s)\b/i);
    if (s) return Math.round(parseFloat(s[1]));
    // fallback to numeric value in minutes
    const raw = Number(value);
    if (!Number.isNaN(raw) && raw > 0) return Math.round(raw * 60);
  }
  return 0;
};
