const determineSectionType = (section) => {
  const key = String(section?.key || "").toLowerCase();
  const label = String(section?.label || "").toLowerCase();

  if (key.includes("listening") || label.includes("listening") || label.includes("nghe")) {
    return "listening";
  }
  if (key.includes("grammar") || label.includes("grammar") || label.includes("ngữ pháp")) {
    return "grammar";
  }
  if (key.includes("reading") || label.includes("reading") || label.includes("đọc")) {
    return "reading";
  }
  if (key.includes("writing") || label.includes("writing") || label.includes("viết")) {
    return "writing";
  }
  if (key.includes("speaking") || label.includes("speaking") || label.includes("nói")) {
    return "speaking";
  }
  return "custom";
};

const listeningHasData = (data) => {
  if (!data) return false;
  if (Array.isArray(data.questionGroups) && data.questionGroups.length > 0) {
    return data.questionGroups.some((group) => {
      const hasQuestions = Array.isArray(group?.questions) && group.questions.length > 0;
      const hasAudio = Boolean(group?.audioUrl || group?.audioPreviewUrl);
      return hasQuestions || hasAudio;
    });
  }
  return Boolean(data.audioUrl);
};

const readingHasData = (data) => Array.isArray(data?.passages) && data.passages.length > 0;
const grammarHasData = (data) => Array.isArray(data?.questions) && data.questions.length > 0;
const writingHasData = (data) => Array.isArray(data?.tasks) && data.tasks.length > 0;
const speakingHasData = (data) => Array.isArray(data?.parts) && data.parts.length > 0;

const customHasData = (data) => {
  if (!data) return false;
  const standalone = Array.isArray(data.questions) && data.questions.length > 0;
  const groups = Array.isArray(data.groups) && data.groups.some((group) => Array.isArray(group?.questions) && group.questions.length > 0);
  return standalone || groups;
};

const sectionHasData = (type, data) => {
  switch (type) {
    case "listening":
      return listeningHasData(data);
    case "grammar":
      return grammarHasData(data);
    case "reading":
      return readingHasData(data);
    case "writing":
      return writingHasData(data);
    case "speaking":
      return speakingHasData(data);
    default:
      return customHasData(data);
  }
};

export const getSectionsWithData = (customSections = [], examData = {}) => {
  if (!Array.isArray(customSections)) return [];

  return customSections
    .filter((section) => section && section.enabled !== false)
    .map((section) => {
      const type = determineSectionType(section);
      const data = examData?.[section.key];
      return {
        key: section.key,
        label: section.label,
        type,
        hasData: sectionHasData(type, data),
      };
    })
    .filter((section) => section.hasData);
};

export const buildSectionTabs = (customSections = [], examData = {}) => {
  const sections = getSectionsWithData(customSections, examData);
  return sections.map((section) => ({
    key: section.key,
    label: section.label,
    type: section.type,
    data: examData?.[section.key] || null,
  }));
};

export const determineSectionComponentType = determineSectionType;
