/**
 * Scan a value tree for types Firestore cannot serialize.
 * Returns an array of { path, value } for each unsupported field.
 */
export function findUnsupported(val, currentPath = "") {
  const issues = [];
  if (val === undefined) {
    issues.push({ path: currentPath || "root", value: "undefined" });
    return issues;
  }
  if (val === null) return issues;
  if (typeof val === "function") {
    issues.push({ path: currentPath, value: "function" });
    return issues;
  }
  try {
    if (typeof Blob !== "undefined" && val instanceof Blob) {
      issues.push({ path: currentPath, value: "Blob" });
      return issues;
    }
  } catch (e) {}
  if (typeof val !== "object") return issues;
  if (Array.isArray(val)) {
    val.forEach((item, idx) => {
      issues.push(...findUnsupported(item, `${currentPath}[${idx}]`));
    });
    return issues;
  }
  if (val && val.constructor !== Object) return issues;
  for (const k in val) {
    if (Object.prototype.hasOwnProperty.call(val, k)) {
      issues.push(
        ...findUnsupported(val[k], currentPath ? `${currentPath}.${k}` : k)
      );
    }
  }
  return issues;
}

/**
 * Reverse of preparePayloadForFirestore: unwrap { _nestedArray: [...] } objects
 * back into plain arrays. Call this when reading payload back from localStorage.
 */
export function restorePayloadFromFirestore(val) {
  if (val === null || val === undefined) return val;
  if (typeof val !== "object") return val;
  if (Array.isArray(val)) {
    return val.map(restorePayloadFromFirestore);
  }
  if (val._nestedArray !== undefined) {
    return restorePayloadFromFirestore(val._nestedArray);
  }
  const next = {};
  for (const [k, v] of Object.entries(val)) {
    next[k] = restorePayloadFromFirestore(v);
  }
  return next;
}

/**
 * Recursively convert undefined / NaN / Blob / sparse-array holes to null,
 * and wrap nested arrays in { _nestedArray: [...] } so Firestore accepts them.
 * Non-plain objects (FieldValue, Timestamp, etc.) are preserved.
 */
export function preparePayloadForFirestore(val) {
  if (val === undefined) return null;
  if (val === null) return null;
  if (typeof val === "number" && Number.isNaN(val)) return null;
  if (typeof val !== "object") return val;
  try {
    if (typeof Blob !== "undefined" && val instanceof Blob) return null;
  } catch (e) {}
  if (Array.isArray(val)) {
    const result = Array.from(val).map((v) => preparePayloadForFirestore(v));
    if (result.some((item) => Array.isArray(item))) {
      return result.map((item) =>
        Array.isArray(item) ? { _nestedArray: item } : item
      );
    }
    return result;
  }
  if (val && val.constructor !== Object) {
    if (typeof val.toJSON === "function") {
      return preparePayloadForFirestore(val.toJSON());
    }
    return val;
  }
  const next = {};
  for (const [k, v] of Object.entries(val)) {
    next[k] = preparePayloadForFirestore(v);
  }
  return next;
}
