import { initializeApp } from "firebase/app";
import { getFirestore, connectFirestoreEmulator } from "firebase/firestore";
import { getAuth, connectAuthEmulator } from "firebase/auth";
import { getStorage } from "firebase/storage";
import { getFunctions, connectFunctionsEmulator } from "firebase/functions";

const firebaseConfig = {
  apiKey: "AIzaSyCnG9WCrQ1vW8eAL5pEXLE67Vd8IgU-4NU",
  authDomain: "weaver-crm-uat-cefb3.firebaseapp.com",
  projectId: "weaver-crm-uat-cefb3",
  storageBucket: "weaver-test-online.appspot.com",
  messagingSenderId: "315279737377",
  appId: "1:315279737377:web:28808dbc5c897958941960"
};

console.log(`🔥 Initializing Firebase`, {
  project: firebaseConfig.projectId,
  authDomain: firebaseConfig.authDomain
});

const app = initializeApp(firebaseConfig);

// NOTE: the public booking callables are NOT guarded by Firebase App Check. App Check's
// reCAPTCHA-Enterprise token exchange kept 403-ing, so the booking flow instead mints a
// reCAPTCHA Enterprise *score* token (src/Pages/Booking/recaptcha.js) that the booking
// Cloud Function verifies server-side via createAssessment. See booking_consultation_flow.md.

export const db = getFirestore(app);
export const auth = getAuth(app);
export const storage = getStorage(app);
// Same region + app as bookingData.js's getFunctions(getApp(),'asia-southeast1'),
// so the SDK hands back THIS (already emulator-wired) instance there too.
export const functions = getFunctions(app, "asia-southeast1");

// ── Emulator wiring ──────────────────────────────────────────────────────────
// Gated by REACT_APP_USE_EMULATOR so it can't be forgotten. When ON, all
// Firestore / Auth / Functions traffic goes to the LOCAL CRM emulator suite
// (`npm run emu`, ports match WeaverCRM_NEW/backend/firebase.json) — zero
// production reads/writes. Storage stays on prod: the CRM emulator runs no Storage
// emulator and WTO's bucket files live only in prod.
//
// The flag lives in `.env.development.local`, which `react-scripts start` loads but
// `react-scripts build` (production) does NOT — so it can never leak into a deployed
// bundle (no build guard needed). The localhost check is a second safety net.
//
// NOTE: WTO's OWN callables (savePendingLead / createConsultationLead) live in
// WeaverTestOnline/functions, which the CRM simulator does NOT load. In emulator
// mode they 404 unless WTO's functions are also emulated — see the repo README /
// booking_consultation_flow.md for adding them as a second codebase.
const useEmulator = process.env.REACT_APP_USE_EMULATOR === 'true';
const onLocalhost = typeof window !== 'undefined' &&
  (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');

if (useEmulator && onLocalhost && !window.__WEAVER_EMULATORS_CONNECTED__) {
  // connectXxxEmulator throws if called twice (CRA fast-refresh re-imports) or
  // after the instance has been used — guard with a one-shot global.
  window.__WEAVER_EMULATORS_CONNECTED__ = true;
  console.log(
    '%c[Firebase] REACT_APP_USE_EMULATOR=true → using LOCAL emulators (no prod reads). Run `npm run emu` if they are not up.',
    'color:#16a34a;font-weight:bold',
  );
  try {
    connectFirestoreEmulator(db, 'localhost', 8080);
    connectAuthEmulator(auth, 'http://localhost:9099', { disableWarnings: true });
    connectFunctionsEmulator(functions, 'localhost', 5001);
  } catch (err) {
    console.error('[Firebase] Emulator connect failed — is `npm run emu` running?', err?.message);
  }
} else if (!useEmulator && onLocalhost) {
  console.warn(
    '%c[Firebase] DEV on localhost but REACT_APP_USE_EMULATOR is OFF — reads/writes hit PRODUCTION (weaver-crm-uat-cefb3). ' +
      'Set REACT_APP_USE_EMULATOR=true in .env.development.local and run `npm run emu`.',
    'color:#dc2626;font-weight:bold',
  );
}

export default app;
