import React, { useCallback, useEffect, useId, useMemo } from "react";
import { QuestionProvider } from "../../../../contexts/QuestionContext";
import { useQuestionState } from "./hooks/useQuestionState";
import { useNumbering } from "../../../../contexts/NumberingContext";
import QuestionTypeRouter from "./QuestionTypeRouter";
import { cloneDefaultOptions } from "../../../../utils/question/questionUtils";
import { getQuestionSlotCount } from "../../../../utils/question/questionMetrics";
import {
  createDefaultGapFillTable,
  synchronizeGapFillTableQuestion,
} from "../../../../utils/question/gapFillTable";
import {
  DEFAULT_MATCHING_HEADING_TITLE,
  MATCHING_HEADINGS_DEFAULT_DESCRIPTION,
} from "../../../../utils/question/questionDefaults";
import {
  BLANK_TOKEN,
  INLINE_BLANK_TOKEN,
  computeInlineTemplateWithBlank,
  computePromptWithBlank,
} from "../../../../utils/question/questionTokens";
import { generateId } from "../../../../utils/question/idUtils";

const QUESTION_TYPE_OPTIONS = [
  { value: "fill-in-the-blanks", label: "Fill in the Blanks" },
  { value: "multiple-choice", label: "Multiple Choice" },
  { value: "checkbox", label: "Checkbox" },
  { value: "inline-blank", label: "Sentence with inline blank" },
  { value: "matching-headings", label: "Matching Headings" },
  { value: "which-true", label: "Which True" },
  { value: "true-false-not-given", label: "True / False / Not Given" },
  { value: "complete-sentences", label: "Complete Sentences" },
  { value: "gap-filling", label: "Gap Filling" },
  { value: "gap-fill-table", label: "Gap Fill Table" },
];

const restoreCursorPosition = (fieldId, cursorPosition) => {
  if (cursorPosition === null || cursorPosition === undefined) return;
  if (typeof document === "undefined") return;

  const restore = () => {
    const textarea = document.getElementById(fieldId);
    if (textarea && textarea === document.activeElement) {
      // Only restore if textarea is already focused (i.e., the user was actively editing)
      textarea.setSelectionRange(cursorPosition, cursorPosition);
    }
  };

  if (typeof requestAnimationFrame === "function") {
    requestAnimationFrame(restore);
  } else {
    setTimeout(restore, 0);
  }
};

const QuestionCard = ({
  question,
  onChange,
  questionNumber,
  numberingPrefix,
  sectionMeta,
  renderActions,
}) => {
  const promptFieldId = useId();
  const inlineFieldId = useId();
  const displayLabel = questionNumber != null ? String(questionNumber) : "";
  const numberingLabel =
    numberingPrefix != null && numberingPrefix !== ""
      ? String(numberingPrefix)
      : displayLabel;

  const { updateQuestion, updateField } = useQuestionState({ question, onChange });

  const addPromptBlank = useCallback(() => {
    const baseValue = question.prompt || "";
    const { nextValue, cursorPosition } = computePromptWithBlank(promptFieldId, baseValue);
    const existingBlanks = baseValue.match(new RegExp(BLANK_TOKEN, "g")) || [];
    const newBlankNumber = existingBlanks.length + 1;

    updateQuestion((current = question) => {
      const normalizedSubQuestions = Array.isArray(current.subQuestions)
        ? current.subQuestions.map((sub, index) => ({
          ...sub,
          number: `${numberingLabel}.${index + 1}`,
        }))
        : [];

      const newSubQuestion = {
        id: generateId("SQ"),
        number: `${numberingLabel}.${newBlankNumber}`,
        type: "text",
        correctAnswers: [""],
        prompt: `Answer for blank ${newBlankNumber}`,
      };

      return {
        ...current,
        prompt: nextValue,
        subQuestions: [...normalizedSubQuestions, newSubQuestion],
      };
    });

    restoreCursorPosition(promptFieldId, cursorPosition);
  }, [numberingLabel, promptFieldId, question, updateQuestion]);

  const handlePromptChange = useCallback(
    (nextPrompt) => {
      updateQuestion((current = question) => {
        if ((current.type || question.type) !== "fill-in-the-blanks") {
          return { ...current, prompt: nextPrompt };
        }

        const blankCount = nextPrompt.split(BLANK_TOKEN).length - 1;
        const existing = Array.isArray(current.subQuestions) ? current.subQuestions : [];
        const nextSubQuestions = [];

        for (let index = 0; index < blankCount; index += 1) {
          if (existing[index]) {
            nextSubQuestions.push({
              ...existing[index],
              number: `${numberingLabel}.${index + 1}`,
            });
          } else {
            nextSubQuestions.push({
              id: generateId("SQ"),
              number: `${numberingLabel}.${index + 1}`,
              type: "text",
              correctAnswers: [""],
              prompt: `Answer for blank ${index + 1}`,
            });
          }
        }

        return {
          ...current,
          prompt: nextPrompt,
          subQuestions: nextSubQuestions,
        };
      });
    },
    [numberingLabel, question, updateQuestion]
  );

  const addInlineBlank = useCallback(() => {
    const baseValue = question.inlineTemplate || "";
    const { nextValue, cursorPosition } = computeInlineTemplateWithBlank(
      inlineFieldId,
      baseValue
    );
    const existingBlanks = baseValue.match(new RegExp(INLINE_BLANK_TOKEN, "g")) || [];
    const newBlankNumber = existingBlanks.length + 1;

    updateQuestion((current = question) => {
      const normalizedSubQuestions = Array.isArray(current.subQuestions)
        ? current.subQuestions.map((sub, index) => ({
          ...sub,
          number: `${numberingLabel}.${index + 1}`,
        }))
        : [];

      return {
        ...current,
        inlineTemplate: nextValue,
        subQuestions: [
          ...normalizedSubQuestions,
          {
            id: generateId("SQ"),
            number: `${numberingLabel}.${newBlankNumber}`,
            type: "text",
            correctAnswers: [""],
            prompt: `Answer for blank ${newBlankNumber}`,
          },
        ],
      };
    });

    restoreCursorPosition(inlineFieldId, cursorPosition);
  }, [inlineFieldId, numberingLabel, question, updateQuestion]);

  const handleInlineTemplateChange = useCallback(
    (nextTemplate) => {
      updateQuestion((current = question) => {
        const blankCount = nextTemplate.split(INLINE_BLANK_TOKEN).length - 1;
        const existing = Array.isArray(current.subQuestions) ? current.subQuestions : [];
        const nextSubQuestions = [];

        for (let index = 0; index < blankCount; index += 1) {
          if (existing[index]) {
            nextSubQuestions.push({
              ...existing[index],
              number: `${numberingLabel}.${index + 1}`,
            });
          } else {
            nextSubQuestions.push({
              id: generateId("SQ"),
              number: `${numberingLabel}.${index + 1}`,
              type: "text",
              correctAnswers: [""],
              prompt: `Answer for blank ${index + 1}`,
            });
          }
        }

        return {
          ...current,
          inlineTemplate: nextTemplate,
          subQuestions: nextSubQuestions,
        };
      });
    },
    [numberingLabel, question, updateQuestion]
  );

  const handleQuestionTypeChange = useCallback(
    (nextType) => {
      updateQuestion((current = question) => {
        const baseQuestion = { ...current, type: nextType };

        if (nextType === "fill-in-the-blanks") {
          const nextMode = current.inputMode || "text";
          return {
            ...baseQuestion,
            inputMode: nextMode,
            options: current.options?.length ? current.options.slice() : cloneDefaultOptions(),
            inlineTemplate: "",
            subQuestions: [],
            prompt: current.prompt || "",
          };
        }

        if (nextType === "inline-blank") {
          return {
            ...baseQuestion,
            inlineTemplate: current.inlineTemplate || "",
            subQuestions: [],
            inputMode: "text",
            options: [],
            prompt: "",
          };
        }

        if (nextType === "multiple-choice" || nextType === "checkbox") {
          return {
            ...baseQuestion,
            options: current.options?.length ? current.options.slice() : cloneDefaultOptions(),
            subQuestions: [],
            inlineTemplate: "",
          };
        }

        if (nextType === "matching-headings") {
          const existingItems = Array.isArray(current.matchingHeadingItems)
            ? [...current.matchingHeadingItems]
            : ["", "", ""];
          while (existingItems.length < 3) {
            existingItems.push("");
          }
          const existingAnswers = Array.isArray(current.matchingHeadingAnswers)
            ? [...current.matchingHeadingAnswers]
            : ["", "", ""];
          while (existingAnswers.length < 3) {
            existingAnswers.push("");
          }
          const normalizedAnswers = existingAnswers
            .slice(0, 3)
            .map((answer) => (typeof answer === "string" ? answer.trim() : answer));
          return {
            ...baseQuestion,
            description:
              current.description && current.description.trim().length > 0
                ? current.description
                : MATCHING_HEADINGS_DEFAULT_DESCRIPTION,
            prompt:
              current.prompt && current.prompt.trim().length > 0
                ? current.prompt
                : "Questions 1-3",
            inputMode: "text",
            options: [],
            inlineTemplate: "",
            subQuestions: [],
            matchingHeadingListTitle:
              current.matchingHeadingListTitle || DEFAULT_MATCHING_HEADING_TITLE,
            matchingHeadingItems: existingItems,
            matchingHeadingAnswers: normalizedAnswers,
            correctAnswers: normalizedAnswers.slice(),
          };
        }

        if (nextType === "which-true") {
          const existingItems = Array.isArray(current.whichTrueItems)
            ? [...current.whichTrueItems]
            : ["", "", ""];
          while (existingItems.length < 3) {
            existingItems.push("");
          }
          const existingAnswers = Array.isArray(current.whichTrueAnswers)
            ? [...current.whichTrueAnswers]
            : ["", "", ""];
          while (existingAnswers.length < 3) {
            existingAnswers.push("");
          }
          const normalizedAnswers = existingAnswers
            .slice(0, 3)
            .map((answer) => (typeof answer === "string" ? answer.trim() : answer));
          return {
            ...baseQuestion,
            description:
              current.description && current.description.trim().length > 0
                ? current.description
                : "Which of the following are TRUE according to the passage?",
            prompt:
              current.prompt && current.prompt.trim().length > 0
                ? current.prompt
                : "Questions 1-3",
            inputMode: "text",
            options: [],
            inlineTemplate: "",
            subQuestions: [],
            whichTrueItems: existingItems,
            whichTrueAnswers: normalizedAnswers,
            correctAnswers: normalizedAnswers.slice(),
          };
        }

        if (nextType === "true-false-not-given") {
          const existingSubQuestions = Array.isArray(current.subQuestions)
            ? [...current.subQuestions]
            : [{ id: generateId("SQ"), prompt: "", correctAnswers: [""] }];
          const existingAnswers = Array.isArray(current.correctAnswers)
            ? [...current.correctAnswers]
            : [""];
          return {
            ...baseQuestion,
            description:
              current.description && current.description.trim().length > 0
                ? current.description
                : "Do the following statements agree with the information given in the Reading Passage?",
            prompt:
              current.prompt && current.prompt.trim().length > 0
                ? current.prompt
                : "Questions 1-5",
            inputMode: "text",
            options: [],
            inlineTemplate: "",
            useTableView: true,
            answerText1: "TRUE",
            answerText2: "FALSE",
            answerText3: "NOT GIVEN",
            hint: "Write\nTRUE - if the statement agrees with the information\nFALSE - if the statement contradicts the information\nNOT GIVEN - if there is no information on this.",
            whichTrueItems: [],
            whichTrueAnswers: [],
            matchingHeadingItems: [],
            matchingHeadingAnswers: [],
            subQuestions: existingSubQuestions,
            correctAnswers: existingSubQuestions.map((sq) => sq.correctAnswers?.[0] || ""),
          };
        }

        if (nextType === "complete-sentences") {
          const existingSubQuestions = Array.isArray(current.subQuestions)
            ? [...current.subQuestions]
            : [];
          return {
            ...baseQuestion,
            description:
              current.description && current.description.trim().length > 0
                ? current.description
                : "Complete the sentences.",
            prompt:
              current.prompt && current.prompt.trim().length > 0
                ? current.prompt
                : "Choose NO MORE THAN TWO WORDS from the passage for each answer.",
            inputMode: "text",
            options: [],
            inlineTemplate: "",
            matchingHeadingItems: [],
            matchingHeadingAnswers: [],
            whichTrueItems: [],
            whichTrueAnswers: [],
            subQuestions: existingSubQuestions,
            correctAnswers: existingSubQuestions.map((sq) => sq.correctAnswers?.[0] || ""),
          };
        }

        if (nextType === "gap-filling") {
          const existingSubQuestions = Array.isArray(current.subQuestions)
            ? [...current.subQuestions]
            : [];
          return {
            ...baseQuestion,
            description:
              current.description && current.description.trim().length > 0
                ? current.description
                : "Complete the passage by filling in the gaps.",
            prompt:
              current.prompt && current.prompt.trim().length > 0
                ? current.prompt
                : "Questions 1-5",
            inputMode: "text",
            options: [],
            inlineTemplate: "",
            content: current.content || "",
            hint: current.hint || "Choose NO MORE THAN THREE WORDS from the passage for each answer.",
            matchingHeadingItems: [],
            matchingHeadingAnswers: [],
            whichTrueItems: [],
            whichTrueAnswers: [],
            subQuestions: existingSubQuestions,
            correctAnswers: existingSubQuestions.map((sq) => sq.correctAnswers?.[0] || ""),
          };
        }

        if (nextType === "gap-fill-table") {
          const preparedQuestion = {
            ...baseQuestion,
            table: current.table || createDefaultGapFillTable(),
            content: "",
            options: [],
            inlineTemplate: "",
            matchingHeadingItems: [],
            matchingHeadingAnswers: [],
            whichTrueItems: [],
            whichTrueAnswers: [],
            correctAnswers: Array.isArray(current.correctAnswers)
              ? current.correctAnswers.slice()
              : [],
            subQuestions: Array.isArray(current.subQuestions)
              ? current.subQuestions.slice()
              : [],
          };

          return synchronizeGapFillTableQuestion(preparedQuestion);
        }

        return {
          ...baseQuestion,
          inlineTemplate: "",
          subQuestions: [],
        };
      });
    },
    [question, updateQuestion]
  );

  const handleInputModeChange = useCallback(
    (nextMode) => {
      updateQuestion((current = question) => {
        const baseQuestion = { ...current, inputMode: nextMode };
        if (nextMode === "choices") {
          return {
            ...baseQuestion,
            options: current.options?.length ? current.options.slice() : cloneDefaultOptions(),
          };
        }
        return baseQuestion;
      });
    },
    [question, updateQuestion]
  );

  useEffect(() => {
    if (!Array.isArray(question?.subQuestions) || question.subQuestions.length === 0) return;
    const needsUpdate = question.subQuestions.some(
      (sub, index) => sub.number !== `${numberingLabel}.${index + 1}`
    );
    if (!needsUpdate) return;

    updateQuestion((current = question) => {
      const existing = Array.isArray(current.subQuestions) ? current.subQuestions : [];
      return {
        ...current,
        subQuestions: existing.map((sub, index) => ({
          ...sub,
          number: `${numberingLabel}.${index + 1}`,
        })),
      };
    });
  }, [numberingLabel, question, updateQuestion]);

  // Auto-update prompt text for complete-sentences with question numbering
  useEffect(() => {
    if (question?.type !== "complete-sentences") return;
    if (!displayLabel) return;

    const prompt = question?.prompt || "";
    // Check if prompt contains "Questions X-Y" pattern
    const questionsMatch = prompt.match(/^Questions\s+\d+-\d+/i);
    if (!questionsMatch) return;

    // Extract question numbers from displayLabel and calculate end number
    const labelParts = String(displayLabel).split('-');
    const startNum = parseInt(labelParts[0]) || 1;
    let endNum = parseInt(labelParts[1]);

    // If no end number in displayLabel, calculate from subQuestions count
    if (isNaN(endNum)) {
      const subQuestionsCount = Array.isArray(question?.subQuestions) ? question.subQuestions.length : 0;
      endNum = startNum + subQuestionsCount - 1;
    }

    const newPrefix = `Questions ${startNum}-${endNum}`;
    const newPrompt = prompt.replace(/^Questions\s+\d+-\d+/i, newPrefix);

    if (newPrompt !== prompt) {
      updateQuestion((current = question) => ({
        ...current,
        prompt: newPrompt,
      }));
    }
  }, [displayLabel, question, updateQuestion]);

  const showPromptActions = question?.type === "fill-in-the-blanks";
  const showDefaultCorrectAnswer = ![
    "fill-in-the-blanks",
    "inline-blank",
    "matching-headings",
    "which-true",
    "true-false-not-given",
    "yes-no-not-given",
    "complete-sentences",
    "gap-filling",
    "notes-completion",
    "short-answer",
    "summary-completion",
    "gap-fill-table",
    "checkbox",
  ].includes(question?.type);

  // Use NumberingContext to get the correct question number across entire exam
  let displayQuestionLabel = displayLabel;

  try {
    const numberingContext = useNumbering();
    if (numberingContext && question?.id && sectionMeta?.sectionKey) {
      const sectionKey = sectionMeta.sectionKey;
      const passageOrGroupId =
        sectionMeta.passageId != null
          ? sectionMeta.passageId
          : sectionMeta.groupId != null
            ? sectionMeta.groupId
            : null; // Support both passage and group identifiers

      const contextLabel = numberingContext.getQuestionNumber(
        sectionKey,
        passageOrGroupId,
        question.id
      );

      // Use context label if it's valid (not default "1" or is a range)
      // The context label will be a range like "21-29" or a single number like "21"
      if (contextLabel && contextLabel !== "1") {
        displayQuestionLabel = contextLabel;
      } else if (contextLabel === "1" && (Array.isArray(question?.correctAnswers) && question.correctAnswers.length > 1) || (Array.isArray(question?.subQuestions) && question.subQuestions.length > 1)) {
        // If context returns "1" but we know this question has multiple answers/subquestions,
        // still use context label (means this is the first question with multiple slots)
        displayQuestionLabel = contextLabel;
      }
    }
  } catch (e) {
    // If NumberingContext not available, fall back to local calculation
    // This handles cases where NumberingProvider isn't wrapping the component
  }

  // Final fallback: calculate locally if not set from context
  if (displayQuestionLabel === displayLabel) {
    const startNum = parseInt(String(displayLabel).split('-')[0]) || 1;
    const itemCount = getQuestionSlotCount(question) || 1;

    // Return range if multiple items, otherwise just the starting number
    if (itemCount > 1) {
      const endNum = startNum + itemCount - 1;
      displayQuestionLabel = `${startNum}-${endNum}`;
    }
  }

  const questionHeading = useMemo(() => {
    if (!displayQuestionLabel) {
      return "Question";
    }

    const labelString = String(displayQuestionLabel);
    const hasRange = labelString.includes("-");
    return `${hasRange ? "Questions" : "Question"} ${labelString}`;
  }, [displayQuestionLabel]);

  const contextValue = useMemo(
    () => ({
      question,
      questionNumber: displayLabel,
      numberingPrefix: numberingLabel,
      sectionMeta,
      promptFieldId,
      inlineFieldId,
      addPromptBlank,
      handlePromptChange,
      addInlineBlank,
      handleInlineTemplateChange,
      handleInputModeChange,
      updateQuestion,
      updateField,
    }),
    [
      addInlineBlank,
      addPromptBlank,
      displayLabel,
      handleInlineTemplateChange,
      handleInputModeChange,
      handlePromptChange,
      inlineFieldId,
      numberingLabel,
      promptFieldId,
      question,
      sectionMeta,
      updateField,
      updateQuestion,
    ]
  );

  return (
    <QuestionProvider value={contextValue}>
      <div
        data-question-id={question.id}
        className="space-y-4 rounded-xl border border-slate-200 bg-white p-4 shadow-sm"
      >
        <div className="flex items-center justify-between">
          <p className="text-sm font-semibold text-slate-800">{questionHeading}</p>
          {typeof renderActions === "function" ? renderActions(contextValue) : null}
        </div>

        <div className="grid gap-4 md:grid-cols-2">
          <div>
            <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
              Question type
            </label>
            <select
              value={question.type || "fill-in-the-blanks"}
              onChange={(event) => handleQuestionTypeChange(event.target.value)}
              className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            >
              {QUESTION_TYPE_OPTIONS.map(({ value, label }) => (
                <option key={value} value={value}>
                  {label}
                </option>
              ))}
            </select>
          </div>

          {question.type === "fill-in-the-blanks" ? (
            <div>
              <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
                Response format
              </label>
              <select
                value={question.inputMode || "text"}
                onChange={(event) => handleInputModeChange(event.target.value)}
                className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              >
                <option value="text">Enter text</option>
                <option value="choices">Select from choices</option>
              </select>
            </div>
          ) : null}
        </div>

        <div className="flex items-center justify-between gap-3">
          <label
            htmlFor={promptFieldId}
            className="text-xs font-medium uppercase tracking-wide text-slate-500"
          >
            Prompt
          </label>
          {showPromptActions ? <QuestionTypeRouter mode="actions" /> : null}
        </div>

        <textarea
          id={promptFieldId}
          value={question.prompt || ""}
          onChange={(event) => handlePromptChange(event.target.value)}
          rows={3}
          className="w-full rounded-xl border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
          placeholder="Write the question prompt."
        />

        <div>
          <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Description (optional)
          </label>
          <textarea
            value={question.description || ""}
            onChange={(event) => updateField("description", event.target.value)}
            rows={2}
            className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            placeholder="Add supporting instructions displayed above this question"
          />
        </div>

        {question.type === "true-false-not-given" || question.type === "yes-no-not-given" || question.type === "complete-sentences" || question.type === "gap-filling" || question.type === "notes-completion" || question.type === "short-answer" || question.type === "summary-completion" ? (
          <div className="space-y-4">
            <div>
              <div className="flex items-center gap-2 mb-2">
                <span className="inline-flex h-6 items-center justify-center rounded bg-orange-100 px-2 text-xs font-semibold text-orange-600">
                  Hint
                </span>
              </div>
              <textarea
                value={question.hint || ""}
                onChange={(event) => updateField("hint", event.target.value)}
                rows={3}
                className="w-full rounded-xl border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                placeholder={question.type === "gap-filling" ? "e.g., Choose NO MORE THAN THREE WORDS from the passage for each answer." : question.type === "complete-sentences" ? "e.g., Choose NO MORE THAN TWO WORDS from the passage for each answer." : "Add hint about TRUE/FALSE/NOT GIVEN"}
              />
            </div>

            {(question.type === "true-false-not-given" || question.type === "yes-no-not-given") && (
              <div>
                <div className="flex items-center justify-between mb-2">
                  <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
                    Answer Options
                  </label>
                  <button
                    type="button"
                    onClick={() => {
                      const answerTexts = [];
                      let i = 1;
                      while (question[`answerText${i}`] !== undefined) {
                        answerTexts.push(question[`answerText${i}`]);
                        i++;
                      }
                      const nextTexts = [...answerTexts, ""];
                      const updates = {};
                      nextTexts.forEach((text, idx) => {
                        updates[`answerText${idx + 1}`] = text;
                      });
                      updateQuestion((current = question) => ({
                        ...current,
                        ...updates,
                      }));
                    }}
                    className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
                  >
                    + Add option
                  </button>
                </div>
                <div className="space-y-2">
                  {(() => {
                    const answerTexts = [];
                    let i = 1;
                    while (question[`answerText${i}`] !== undefined || i <= 3) {
                      const value = question[`answerText${i}`];
                      answerTexts.push({ index: i, value });
                      i++;
                      if (i > 10) break; // Safety limit
                    }
                    return answerTexts.map(({ index, value }) => (
                      <div key={`answer-text-${index}`} className="flex items-center gap-2">
                        <input
                          type="text"
                          value={value !== undefined && value !== null ? value : ""}
                          onChange={(event) =>
                            updateField(`answerText${index}`, event.target.value)
                          }
                          className="flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                          placeholder={`Answer ${index} (e.g., TRUE, YES, Y)`}
                        />
                        {index > 1 && (
                          <button
                            type="button"
                            onClick={() => {
                              const updates = {};
                              // Shift all answers after the removed one
                              for (let j = index; j <= 10; j++) {
                                if (question[`answerText${j + 1}`] !== undefined) {
                                  updates[`answerText${j}`] = question[`answerText${j + 1}`];
                                } else {
                                  updates[`answerText${j}`] = undefined;
                                }
                              }
                              updateQuestion((current = question) => ({
                                ...current,
                                ...updates,
                              }));
                            }}
                            className="rounded border border-red-200 px-2 py-2 text-xs font-semibold text-red-500 hover:bg-red-50"
                          >
                            Remove
                          </button>
                        )}
                      </div>
                    ));
                  })()}
                </div>
              </div>
            )}
          </div>
        ) : null}

        <QuestionTypeRouter mode="builder" questionNumber={displayLabel} />

        {question.type === "checkbox" ? (
          <div>
            <div className="flex items-center justify-between mb-2">
              <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
                Correct answer(s)
              </label>
              <button
                type="button"
                onClick={() => {
                  const options = Array.isArray(question.options) ? question.options : [];
                  const nextCorrect = Array.isArray(question.correctAnswers)
                    ? [...question.correctAnswers]
                    : [];
                  // Add next unchecked option
                  const uncheckedOption = options.find(
                    (opt) => !nextCorrect.includes(opt.value)
                  );
                  if (uncheckedOption) {
                    nextCorrect.push(uncheckedOption.value);
                    updateField("correctAnswers", nextCorrect);
                  }
                }}
                className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
              >
                + Add answer
              </button>
            </div>
            <div className="space-y-2">
              {Array.isArray(question.correctAnswers) && question.correctAnswers.length > 0 ? (
                question.correctAnswers.map((answer, index) => (
                  <div key={`correct-answer-${index}`} className="flex items-center gap-2">
                    <select
                      value={answer || ""}
                      onChange={(event) => {
                        const nextCorrect = [...question.correctAnswers];
                        nextCorrect[index] = event.target.value;
                        updateField("correctAnswers", nextCorrect);
                      }}
                      className="flex-1 rounded-xl border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                    >
                      <option value="">Select option</option>
                      {Array.isArray(question.options) &&
                        question.options.map((opt) => (
                          <option key={opt.value} value={opt.value}>
                            {opt.label || opt.value}
                          </option>
                        ))}
                    </select>
                    <button
                      type="button"
                      onClick={() => {
                        const nextCorrect = question.correctAnswers.filter(
                          (_, idx) => idx !== index
                        );
                        updateField("correctAnswers", nextCorrect);
                      }}
                      className="rounded border border-red-200 px-2 py-2 text-xs font-semibold text-red-500 hover:bg-red-50"
                    >
                      Remove
                    </button>
                  </div>
                ))
              ) : (
                <p className="text-sm text-slate-500">
                  No correct answers selected. Click "Add answer" to add one.
                </p>
              )}
            </div>
          </div>
        ) : null}

        {showDefaultCorrectAnswer ? (
          <div>
            <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
              Correct answer(s)
            </label>
            <input
              type="text"
              value={question.correctAnswers?.[0] || ""}
              onChange={(event) => updateField("correctAnswers", [event.target.value])}
              className="mt-1 w-full rounded-xl border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              placeholder="Enter correct answer (separate multiple with |)"
            />
          </div>
        ) : null}
      </div>
    </QuestionProvider>
  );
};

export default QuestionCard;
