/**
 * gradingCore.js — SHARED answer-grading engine (zero-dependency CommonJS).
 *
 * NOTE: `.js`, not `.cjs` — both consuming packages are CommonJS, and Create
 * React App (react-scripts 5) bundles a client-imported `.cjs` as a static
 * ASSET instead of a module (no babel-loader rule for `.cjs`), so the import
 * resolves to a URL string and every grading helper is `undefined` at runtime.
 * Keep this `.js`; do NOT rename back to `.cjs`.
 *
 * BYTE-IDENTICAL MIRROR across two repos, enforced by `npm run check:grading-sync`
 * (sha256 byte-equality):
 *   • CANONICAL: WeaverTestOnline/src/utils/gradingCore.js
 *   • MIRROR:    WeaverPortal/functions/utils/gradingCore.js
 *
 * Consumed by:
 *   • WeaverPortal/functions — CF `commitExamResult` + `batchRescoreHomework`,
 *     and scripts/rescore_all.js — via `require('./gradingCore.js')`.
 *   • WeaverTestOnline client — real-time exam grading + review-mode green/red
 *     painting — via the thin ESM shims:
 *        src/utils/normalizeAnswer.js
 *        src/Pages/Examp/utils/examScoring.js
 *
 * This file is the SINGLE SOURCE OF TRUTH for "what counts as a correct answer".
 * The historic three-file copy (CF grading.js ↔ examScoring.js ↔ normalizeAnswer.js)
 * drifted silently — a whole `checkbox` branch was missing from the CF, so
 * "Choose TWO letters" questions counted as 1 and shrank the rescore denominator
 * (40 → 38). One gated core makes that class of bug impossible.
 *
 * RULES:
 *   • DO NOT edit the mirror directly — edit the CANONICAL and copy it verbatim
 *     (`cp -f`), then run `npm run check:grading-sync`.
 *   • Pinned to LF in .gitattributes so Windows autocrlf can't break the check.
 *   • Zero-dependency and DOM-FREE on purpose: it runs in Node (CF) AND the
 *     browser bundle. The writing word-counter therefore uses a regex tag-strip,
 *     not DOMParser. Writing is never auto-scored for correctness (only the
 *     "meets minimum words" flag), so this has no effect on any numeric score.
 *
 * See TheWeaverWiki/features/exam_grading_pipeline.md for the architecture.
 */

"use strict";

// ─── Single-token normalisation ───────────────────────────────────────────────

/**
 * Normalize a single answer string for comparison.
 *   - Trims whitespace + lowercases
 *   - Strips trailing punctuation (. , ; : !) but NOT "?"
 *   - Time "1:30" → "1.30"
 *   - Phone-like (≥6 digits, only digits/space/-/./()/+) → digits only
 *   - Decimal numbers normalised via parseFloat (drop trailing zeros)
 */
function normalizeAnswer(value) {
  if (value === null || value === undefined) return "";
  let normalized = String(value).trim().toLowerCase();

  normalized = normalized.replace(/[.,;:!]+$/, "");

  if (/^\d{1,2}:\d{2}$/.test(normalized)) {
    normalized = normalized.replace(":", ".");
  }

  const digitCount = (normalized.match(/\d/g) || []).length;
  const likelyPhone = digitCount >= 6 && /^[\d\s\-().+]+$/.test(normalized);
  if (likelyPhone) {
    normalized = normalized.replace(/[^\d]+/g, "");
  } else if (/^[\d\s]+$/.test(normalized)) {
    normalized = normalized.replace(/\s+/g, "");
  } else if (!isNaN(parseFloat(normalized)) && isFinite(normalized)) {
    normalized = parseFloat(normalized).toString();
  }

  return normalized;
}

/**
 * Comparison-only normaliser: collapses to the bare alphanumeric skeleton on
 * top of normalizeAnswer(), so cosmetic spacing/separator differences don't
 * mark a correct answer wrong ("PE9 7QT" ≡ "PE97QT"). Keeps a dot only between
 * two digits ("10.5" survives; "st.john" → "stjohn"). EQUALITY matching only.
 */
function normalizeForMatch(value) {
  const base = normalizeAnswer(value);
  if (!base) return "";
  return base
    .replace(/[^\p{L}\p{N}.]+/gu, "")
    .replace(/(?<!\d)\.(?!\d)/g, "");
}

/**
 * TFNG / YNNG collapse: TRUE/YES/T/Y → "true_yes", FALSE/NO/F/N → "false_no",
 * "not given" → "not_given". TRUE and YES are interchangeable in IELTS.
 */
function normalizeTFNG(value) {
  const norm = normalizeAnswer(value);
  if (norm === "true" || norm === "yes" || norm === "t" || norm === "y") return "true_yes";
  if (norm === "false" || norm === "no" || norm === "f" || norm === "n") return "false_no";
  if (norm === "not given") return "not_given";
  return norm;
}

/**
 * Partial word match for correction/underline bag-matching.
 *   - User words must be a contiguous subsequence of key words (order preserved)
 *   - ≥ 2 user words, ratio matched/key ≥ 2/3, 1-of-2 does NOT count
 */
function isPartialWordMatch(userNorm, keyNorm) {
  if (!userNorm || !keyNorm) return false;

  const userWords = userNorm.split(/\s+/).filter(Boolean);
  const keyWords = keyNorm.split(/\s+/).filter(Boolean);

  if (keyWords.length <= 1) return false;
  if (userWords.length < 2) return false;
  if (userWords.length > keyWords.length) return false;
  if (userWords.length === 1 && keyWords.length === 2) return false;

  const ratio = userWords.length / keyWords.length;
  if (ratio < 2 / 3 - 0.001) return false;

  const userJoined = userWords.join(" ");
  const keyJoined = keyWords.join(" ");
  return keyJoined.includes(userJoined);
}

// ─── Answer-key expansion ─────────────────────────────────────────────────────

/**
 * Expand a raw answer-key value into the full set of acceptable string variants.
 * SINGLE SOURCE OF TRUTH for answer-key expansion.
 *   - "|" and "/" separators (with or without surrounding spaces)
 *   - Bracket expansion: "habitat(s)" → ["habitats","habitat"];
 *     "flavour (flavor)" → ["flavour flavor","flavour","flavor"];
 *     single-char bracket content like "(s)" is NOT a standalone variant
 *   - Arrays flattened; non-string primitives returned as-is
 * Returns deduplicated RAW (un-normalised) variants — callers normalise before
 * comparing.
 */
function expandAcceptableAnswers(value) {
  if (value === undefined || value === null || value === false) return [];
  if (Array.isArray(value)) {
    return value.flatMap((item) => expandAcceptableAnswers(item)).filter(Boolean);
  }
  if (typeof value !== "string") return [value];

  const parts = value.split(/[|]\s*|\s*\/\s*/);
  const expanded = parts.flatMap((p) => {
    const s = p.trim();
    if (!s) return [];
    const hasBrackets = s.includes("(") && s.includes(")");

    if (!hasBrackets) return [s];

    const variants = [];
    // Variant 1: remove brackets, keep content — "habitat(s)" → "habitats"
    variants.push(s.replace(/[()]/g, ""));
    // Variant 2: remove brackets AND content — "habitat(s)" → "habitat"
    variants.push(s.replace(/\([^)]*\)/g, "").replace(/\s+/g, " ").trim());

    // Variant 3: each bracketed group standalone, length > 1 only (skip "(s)")
    const bracketMatches = [...s.matchAll(/\(([^)]+)\)/g)];
    bracketMatches.forEach((m) => {
      const content = m[1].trim();
      if (content.length > 1) variants.push(content);
    });
    return variants;
  });

  return [...new Set(expanded)].filter(Boolean);
}

// Alias kept for the grading engine's historic local name.
const ensureArray = expandAcceptableAnswers;

/** Ensure an array with preserved indices for multi-slot questions. */
function ensureArrayPreserveSlots(value, expectedLength = 0) {
  if (value === undefined || value === null || (value === "" && expectedLength > 0)) {
    return expectedLength > 0 ? Array(expectedLength).fill("") : [];
  }
  if (Array.isArray(value)) {
    const arr = value.slice();
    while (expectedLength && arr.length < expectedLength) arr.push("");
    return arr.map((v) => (v === null || v === undefined ? "" : v));
  }
  if (typeof value === "string") {
    const split = value.split("|").map((s) => s.trim()).map((v) => (v == null ? "" : v));
    while (expectedLength && split.length < expectedLength) split.push("");
    return split;
  }
  if (expectedLength) {
    const arr = Array(expectedLength).fill("");
    arr[0] = value == null ? "" : value;
    return arr;
  }
  return [value];
}

/**
 * Does `userValue` match any acceptable variant of `correctValue`?
 * Review-mode convenience wrapper (green/red paint). Empty user input is never
 * a match.
 */
function matchesAnswer(userValue, correctValue) {
  const userNorm = normalizeForMatch(userValue);
  if (!userNorm) return false;
  const alternatives = expandAcceptableAnswers(correctValue);
  if (alternatives.length === 0) return false;
  return alternatives.some((alt) => normalizeForMatch(alt) === userNorm);
}

// ─── Answer-key derivation ────────────────────────────────────────────────────

/**
 * Build a normalised answer-key map from an exam/homework content object.
 * Sections are top-level keys (grammar, listening, reading, …) holding a
 * questions[], questionGroups[], or passages[] array.
 */
function deriveAnswerKey(examContent = {}) {
  const map = {};

  const processQuestions = (sectionKey, questions = []) => {
    if (!Array.isArray(questions)) return;
    map[sectionKey] = map[sectionKey] || {};

    questions.forEach((question) => {
      if (Array.isArray(question.subQuestions) && question.subQuestions.length > 0) {
        const parentCorrectAnswers = ensureArray(question.correctAnswers);
        const subAnswers = [];
        let parentAnswerIndex = 0;
        question.subQuestions.forEach((sq) => {
          if (sq.isExample) return;
          const sqAnswers = ensureArray(sq.correctAnswers);
          if (sqAnswers.length > 0) {
            subAnswers.push(sqAnswers);
          } else if (parentCorrectAnswers[parentAnswerIndex] !== undefined) {
            subAnswers.push(ensureArray(parentCorrectAnswers[parentAnswerIndex]));
          } else {
            subAnswers.push([""]);
          }
          parentAnswerIndex++;
        });
        const normalizedAnswers = subAnswers.map((answerArray) =>
          Array.isArray(answerArray)
            ? answerArray.map(normalizeAnswer)
            : [normalizeAnswer(answerArray)]
        );
        map[sectionKey][question.id] = {
          correctAnswers: normalizedAnswers,
          questionType: question.type,
          inputMode: question.inputMode || null,
          isSubQuestions: true,
        };
      } else if (question.type === "correction") {
        const correctAnswersList = question.correctAnswers || [];
        const normalizedAnswers = correctAnswersList.map((answer) =>
          ensureArray(answer).map(normalizeAnswer)
        );
        map[sectionKey][question.id] = {
          correctAnswers: normalizedAnswers,
          questionType: "correction",
          isCorrection: true,
          numberOfErrors: question.numberOfErrors || correctAnswersList.length,
        };
      } else if (question.type === "underline") {
        const correctAnswersList = question.correctAnswers || [];
        const normalizedAnswers = correctAnswersList.map((answer) =>
          ensureArray(answer).map(normalizeAnswer)
        );
        map[sectionKey][question.id] = {
          correctAnswers: normalizedAnswers,
          questionType: "underline",
          isUnderline: true,
          numberOfSelections: question.numberOfSelections || correctAnswersList.length,
        };
      } else {
        const correctAnswers = question.correctAnswers || [];
        const multiBlankTypes = [
          "gap-fill-table", "gap-filling", "fill-in-the-blanks",
          "inline-blank", "notes-completion", "short-answer", "summary-completion",
        ];
        const isMultiBlank = multiBlankTypes.includes(question.type)
          && Array.isArray(correctAnswers)
          && correctAnswers.length > 1;

        if (isMultiBlank) {
          const normalizedAnswers = correctAnswers.map((answer) =>
            ensureArray(answer).map(normalizeAnswer)
          );
          map[sectionKey][question.id] = {
            correctAnswers: normalizedAnswers,
            questionType: question.type,
            inputMode: question.inputMode || null,
            isMultiBlank: true,
          };
        } else {
          const normalizedAnswers = ensureArray(correctAnswers).map((answer) =>
            normalizeAnswer(answer)
          );
          map[sectionKey][question.id] = {
            correctAnswers: normalizedAnswers,
            questionType: question.type,
            inputMode: question.inputMode || null,
            minimumWords: question.minimumWords || 100,
            allowMultiple: question.allowMultiple || false,
          };
        }
      }
    });
  };

  // Listening: nested under questionGroups[].questions[]
  if (examContent?.listening?.questionGroups) {
    const allQuestions = [];
    examContent.listening.questionGroups.forEach((group) => {
      if (Array.isArray(group.questions)) allQuestions.push(...group.questions);
    });
    processQuestions("listening", allQuestions);
  }

  // Reading: nested under passages[].questions[]
  if (examContent?.reading?.passages) {
    const allQuestions = [];
    examContent.reading.passages.forEach((passage) => {
      if (Array.isArray(passage.questions)) allQuestions.push(...passage.questions);
    });
    processQuestions("reading", allQuestions);
  }

  // Grammar: flat questions[]
  if (examContent?.grammar?.questions) {
    processQuestions("grammar", examContent.grammar.questions);
  }

  // Any other custom sections (dynamic)
  Object.keys(examContent || {}).forEach((sectionKey) => {
    if (["listening", "reading", "grammar"].includes(sectionKey)) return;
    const section = examContent[sectionKey];
    if (!section) return;
    if (Array.isArray(section.questions)) processQuestions(sectionKey, section.questions);
    else if (Array.isArray(section.tasks)) processQuestions(sectionKey, section.tasks);
    else if (Array.isArray(section.parts)) processQuestions(sectionKey, section.parts);
  });

  return map;
}

// ─── Word count (DOM-free) ────────────────────────────────────────────────────

// Writing word count for the "meets minimum" flag only. DOM-free regex strip so
// the SAME function runs in Node and the browser; handles &nbsp; like the old
// client fallback. Writing is never auto-scored for correctness.
function getWordCountFromHtml(html) {
  if (!html) return 0;
  const withoutTags = String(html).replace(/<[^>]+>/g, " ").replace(/&nbsp;/g, " ");
  const normalized = withoutTags.replace(/\s+/g, " ").trim();
  if (!normalized) return 0;
  return normalized.split(/\s+/).length;
}

// ─── Exam grading ─────────────────────────────────────────────────────────────

/**
 * Grade a student's answers against a map produced by deriveAnswerKey().
 * Returns { summary, questionResults }.
 */
function gradeExam(answers = {}, answerKeyMap = {}) {
  const sectionsToGrade = Object.keys(answerKeyMap).filter(
    (section) => Object.keys(answerKeyMap[section] || {}).length > 0
  );

  const summary = {
    sections: {},
    totalCorrect: 0,
    totalIncorrect: 0,
    totalSkipped: 0,
    totalQuestions: 0,
  };

  const questionResults = {};
  sectionsToGrade.forEach((sectionKey) => {
    // Writing: word-minimum check only, never auto-graded for correctness and
    // never folded into the global totals.
    if (sectionKey === "writing") {
      const sectionAnswers = answers[sectionKey] || {};
      const keyMap = answerKeyMap[sectionKey] || {};
      const sectionQuestionResults = {};
      let total = 0;
      Object.entries(keyMap).forEach(([questionId, meta]) => {
        total += 1;
        const userAnswer = sectionAnswers[questionId] || "";
        const wordCount = getWordCountFromHtml(userAnswer);
        const minimumWords = meta?.minimumWords || 100;
        sectionQuestionResults[questionId] = {
          userAnswer,
          wordCount,
          meetsMinimum: wordCount >= minimumWords,
          minimumWords,
        };
      });
      const meetsCount = Object.values(sectionQuestionResults).filter((r) => r.meetsMinimum).length;
      summary.sections[sectionKey] = {
        correct: 0,
        incorrect: 0,
        skipped: 0,
        total: Object.keys(keyMap || {}).length || total,
        score: null,
        meetsMinimumCount: meetsCount,
      };
      questionResults[sectionKey] = sectionQuestionResults;
      return;
    }
    questionResults[sectionKey] = {};
  });

  sectionsToGrade.forEach((sectionKey) => {
    if (sectionKey === "writing") return;
    const keyMap = answerKeyMap[sectionKey] || {};
    const sectionAnswers = answers[sectionKey] || {};
    let correct = 0;
    let incorrect = 0;
    let skipped = 0;
    let total = 0;

    Object.entries(keyMap).forEach(([questionId, meta]) => {
      const acceptableAnswers = meta.correctAnswers || [];
      if (!acceptableAnswers.length) return;

      const userAnswer = sectionAnswers[questionId];
      const questionType = meta.questionType;
      const inputMode = meta.inputMode;
      const isSubQuestions = meta.isSubQuestions || false;
      const isMultiBlank = meta.isMultiBlank || false;
      const allowMultiple = meta.allowMultiple || false;

      // ── subQuestions: one mark per sub-answer ──
      if (isSubQuestions) {
        const userArray = Array.isArray(userAnswer) ? userAnswer : [];
        let subCorrect = 0;
        let subIncorrect = 0;
        let subSkipped = 0;
        const slots = [];

        acceptableAnswers.forEach((expectedAnswers, index) => {
          const userAns = userArray[index];
          const isEmpty = normalizeAnswer(userAns) === "";

          total += 1;

          if (isEmpty) {
            skipped += 1;
            subSkipped += 1;
            const expectedDisplay = Array.isArray(expectedAnswers) ? expectedAnswers[0] : expectedAnswers;
            slots.push({
              userRaw: userAns === undefined || userAns === null ? "" : userAns,
              expectedRaw: expectedAnswers,
              user: normalizeAnswer(userAns),
              expected: normalizeAnswer(expectedDisplay),
              isCorrect: false,
              isSkipped: true,
            });
          } else {
            const expectedAnswerArray = ensureArray(expectedAnswers);
            const isTFNGType = questionType === "true-false-not-given" || questionType === "yes-no-not-given";
            const matched = isTFNGType
              ? expectedAnswerArray.some((candidate) => normalizeTFNG(candidate) === normalizeTFNG(userAns))
              : expectedAnswerArray.some((candidate) => normalizeForMatch(candidate) === normalizeForMatch(userAns));
            const expectedDisplay = Array.isArray(expectedAnswers) ? expectedAnswers[0] : expectedAnswers;

            if (matched) {
              correct += 1;
              subCorrect += 1;
              slots.push({
                userRaw: userAns, expectedRaw: expectedAnswers,
                user: normalizeAnswer(userAns), expected: normalizeAnswer(expectedDisplay),
                isCorrect: true, isSkipped: false,
              });
            } else {
              incorrect += 1;
              subIncorrect += 1;
              slots.push({
                userRaw: userAns, expectedRaw: expectedAnswers,
                user: normalizeAnswer(userAns), expected: normalizeAnswer(expectedDisplay),
                isCorrect: false, isSkipped: false,
              });
            }
          }
        });

        questionResults[sectionKey][questionId] = {
          isCorrect: subCorrect === acceptableAnswers.length,
          correctAnswers: acceptableAnswers,
          userAnswer,
          subResults: {
            correct: subCorrect, incorrect: subIncorrect, skipped: subSkipped,
            total: acceptableAnswers.length, slots,
          },
        };
        return;
      }

      // ── correction (bag-match) ──
      if (meta.isCorrection) {
        const userArray = Array.isArray(userAnswer) ? userAnswer : [];
        const numSlots = meta.numberOfErrors || acceptableAnswers.length;
        const pool = acceptableAnswers.flatMap((ansArr) => (Array.isArray(ansArr) ? ansArr : [ansArr]));
        const remainingPool = [...pool];
        let corrCorrect = 0;
        let corrIncorrect = 0;
        let corrSkipped = 0;
        const slots = [];

        for (let i = 0; i < numSlots; i++) {
          const slot = userArray[i];
          const userCorrection = normalizeAnswer(slot?.correction || "");
          total += 1;

          if (!userCorrection) {
            corrSkipped += 1;
            skipped += 1;
            slots.push({ userRaw: slot?.correction || "", errorRaw: slot?.error || "", isCorrect: false, isSkipped: true });
          } else {
            let matchIndex = remainingPool.findIndex((a) => a === userCorrection);
            if (matchIndex === -1) {
              matchIndex = remainingPool.findIndex((a) => isPartialWordMatch(userCorrection, a));
            }
            if (matchIndex !== -1) {
              remainingPool.splice(matchIndex, 1);
              corrCorrect += 1;
              correct += 1;
              slots.push({ userRaw: slot?.correction || "", errorRaw: slot?.error || "", isCorrect: true, isSkipped: false });
            } else {
              corrIncorrect += 1;
              incorrect += 1;
              slots.push({ userRaw: slot?.correction || "", errorRaw: slot?.error || "", isCorrect: false, isSkipped: false });
            }
          }
        }

        questionResults[sectionKey][questionId] = {
          isCorrect: corrCorrect === numSlots,
          correctAnswers: acceptableAnswers,
          userAnswer,
          subResults: { correct: corrCorrect, incorrect: corrIncorrect, skipped: corrSkipped, total: numSlots, slots },
        };
        return;
      }

      // ── underline (bag-match + reverse partial) ──
      if (meta.isUnderline) {
        const userArray = Array.isArray(userAnswer) ? userAnswer : [];
        const numSlots = meta.numberOfSelections || acceptableAnswers.length;
        const pool = acceptableAnswers.flatMap((ansArr) => (Array.isArray(ansArr) ? ansArr : [ansArr]));
        const remainingPool = [...pool];
        let ulCorrect = 0;
        let ulIncorrect = 0;
        let ulSkipped = 0;
        const slots = [];

        for (let i = 0; i < numSlots; i++) {
          const userText = normalizeAnswer(userArray[i] || "");
          total += 1;

          if (!userText) {
            ulSkipped += 1;
            skipped += 1;
            slots.push({ userRaw: userArray[i] || "", isCorrect: false, isSkipped: true });
          } else {
            let matchIndex = remainingPool.findIndex((a) => a === userText);
            if (matchIndex === -1) {
              matchIndex = remainingPool.findIndex((a) => isPartialWordMatch(userText, a));
            }
            if (matchIndex === -1) {
              matchIndex = remainingPool.findIndex((a) => isPartialWordMatch(a, userText));
            }
            if (matchIndex !== -1) {
              remainingPool.splice(matchIndex, 1);
              ulCorrect += 1;
              correct += 1;
              slots.push({ userRaw: userArray[i] || "", isCorrect: true, isSkipped: false });
            } else {
              ulIncorrect += 1;
              incorrect += 1;
              slots.push({ userRaw: userArray[i] || "", isCorrect: false, isSkipped: false });
            }
          }
        }

        questionResults[sectionKey][questionId] = {
          isCorrect: ulCorrect === numSlots,
          correctAnswers: acceptableAnswers,
          userAnswer,
          subResults: { correct: ulCorrect, incorrect: ulIncorrect, skipped: ulSkipped, total: numSlots, slots },
        };
        return;
      }

      const isEmpty =
        userAnswer === undefined ||
        userAnswer === null ||
        normalizeAnswer(userAnswer) === "";

      let isCorrect = false;

      // ── checkbox / multiple-choice (multi-select): SET-based, one mark per
      //    expected answer (a "Choose TWO letters" question is 2 questions). ──
      if (questionType === "checkbox" || (questionType === "multiple-choice" && allowMultiple)) {
        const expectedArray = ensureArray(acceptableAnswers);
        const userArray = ensureArrayPreserveSlots(userAnswer, expectedArray.length);

        const userSelectionsRaw = userArray
          .filter((v) => v !== "" && v !== null && v !== undefined)
          .sort((a, b) => String(a).localeCompare(String(b)));
        const normalizedExpected = expectedArray.map((e) => normalizeAnswer(e));

        let checkboxCorrect = 0;
        let checkboxIncorrect = 0;
        let checkboxSkipped = 0;
        const slots = [];

        expectedArray.forEach((expectedAnswer, index) => {
          const normalizedExp = normalizeAnswer(expectedAnswer);
          const userRawAtPosition = userSelectionsRaw[index];
          const userNormAtPosition = userRawAtPosition ? normalizeAnswer(userRawAtPosition) : "";
          const hasUserSelection = !!userRawAtPosition;

          total += 1;

          if (!hasUserSelection) {
            checkboxSkipped += 1;
            skipped += 1;
            slots.push({ userRaw: "", expectedRaw: expectedAnswer, user: "", expected: normalizedExp, isCorrect: false, isSkipped: true });
          } else if (normalizedExpected.includes(userNormAtPosition)) {
            checkboxCorrect += 1;
            correct += 1;
            slots.push({ userRaw: userRawAtPosition, expectedRaw: expectedAnswer, user: userNormAtPosition, expected: normalizedExp, isCorrect: true, isSkipped: false });
          } else {
            checkboxIncorrect += 1;
            incorrect += 1;
            slots.push({ userRaw: userRawAtPosition, expectedRaw: expectedAnswer, user: userNormAtPosition, expected: normalizedExp, isCorrect: false, isSkipped: false });
          }
        });

        isCorrect = checkboxCorrect === expectedArray.length && checkboxIncorrect === 0;

        questionResults[sectionKey][questionId] = {
          isCorrect,
          correctAnswers: acceptableAnswers,
          userAnswer,
          subResults: { correct: checkboxCorrect, incorrect: checkboxIncorrect, skipped: checkboxSkipped, total: expectedArray.length, slots },
        };
        return;
      }

      // ── multi-blank (gap-fill, inline-blank, etc.): one mark per blank ──
      const multiBlankTypes = [
        "gap-fill-table", "gap-filling", "fill-in-the-blanks",
        "inline-blank", "notes-completion", "short-answer", "summary-completion",
      ];
      if (multiBlankTypes.includes(questionType)) {
        // isMultiBlank=false → acceptableAnswers is a flat array of alternatives
        // for ONE blank (slash/pipe already expanded). Wrap as a single slot.
        const expectedArray = isMultiBlank ? acceptableAnswers : [acceptableAnswers];
        const userArray = ensureArrayPreserveSlots(userAnswer, expectedArray.length);

        let blankCorrect = 0;
        let blankIncorrect = 0;
        let blankSkipped = 0;
        const slots = [];

        expectedArray.forEach((expectedAnswer, index) => {
          const userAns = userArray[index];
          const isBlankEmpty =
            userAns === undefined ||
            userAns === null ||
            normalizeAnswer(userAns) === "";

          total += 1;

          if (isBlankEmpty) {
            blankSkipped += 1;
            skipped += 1;
            const expectedAlternatives = isMultiBlank ? expectedAnswer : ensureArray(expectedAnswer);
            const displayExpected = expectedAlternatives[0] || expectedAnswer;
            slots.push({
              userRaw: userAns === undefined || userAns === null ? "" : userAns,
              expectedRaw: expectedAnswer === undefined || expectedAnswer === null ? "" : expectedAnswer,
              user: normalizeAnswer(userAns),
              expected: normalizeAnswer(displayExpected),
              isCorrect: false, isSkipped: true,
            });
          } else {
            const expectedAlternatives = isMultiBlank ? expectedAnswer : ensureArray(expectedAnswer);
            const normalizedUser = normalizeAnswer(userAns);
            const userMatchKey = normalizeForMatch(userAns);
            const matched = expectedAlternatives.some((alt) => normalizeForMatch(alt) === userMatchKey);
            const displayExpected = expectedAlternatives[0] || expectedAnswer;

            if (matched) {
              blankCorrect += 1;
              correct += 1;
              slots.push({ userRaw: userAns, expectedRaw: expectedAnswer, user: normalizedUser, expected: normalizeAnswer(displayExpected), isCorrect: true, isSkipped: false });
            } else {
              blankIncorrect += 1;
              incorrect += 1;
              slots.push({ userRaw: userAns, expectedRaw: expectedAnswer, user: normalizedUser, expected: normalizeAnswer(displayExpected), isCorrect: false, isSkipped: false });
            }
          }
        });

        isCorrect = blankCorrect === expectedArray.length;

        questionResults[sectionKey][questionId] = {
          isCorrect,
          correctAnswers: acceptableAnswers,
          userAnswer,
          subResults: { correct: blankCorrect, incorrect: blankIncorrect, skipped: blankSkipped, total: expectedArray.length, slots },
        };
        return;
      }

      // ── single-answer ──
      if (!isEmpty) {
        if (
          questionType === "multiple-choice" ||
          (questionType === "fill-in-the-blanks" && inputMode === "choices")
        ) {
          isCorrect = acceptableAnswers.some((candidate) => normalizeForMatch(candidate) === normalizeForMatch(userAnswer));
        } else if (
          questionType === "true-false-not-given" ||
          questionType === "yes-no-not-given" ||
          questionType === "which-true" ||
          questionType === "matching-headings"
        ) {
          const isTFNGType = questionType === "true-false-not-given" || questionType === "yes-no-not-given";
          const normFn = isTFNGType ? normalizeTFNG : normalizeAnswer;
          if (Array.isArray(userAnswer) && Array.isArray(acceptableAnswers)) {
            isCorrect =
              userAnswer.length === acceptableAnswers.length &&
              userAnswer.every((answer, index) => normFn(answer) === normFn(acceptableAnswers[index]));
          } else {
            isCorrect = acceptableAnswers.some((candidate) => normFn(candidate) === normFn(userAnswer));
          }
        } else {
          isCorrect = acceptableAnswers.some((candidate) => normalizeForMatch(candidate) === normalizeForMatch(userAnswer));
        }
      }

      total += 1;
      if (isCorrect) correct += 1;
      else if (isEmpty) skipped += 1;
      else incorrect += 1;

      questionResults[sectionKey][questionId] = {
        isCorrect,
        correctAnswers: acceptableAnswers,
        userAnswer,
      };
    });

    summary.sections[sectionKey] = {
      correct, incorrect, skipped, total,
      score: total ? Math.round((correct / total) * 100) : null,
    };

    summary.totalCorrect += correct;
    summary.totalIncorrect += incorrect;
    summary.totalSkipped += skipped;
    summary.totalQuestions += total;
  });

  return { summary, questionResults };
}

// ─── Regrade overlay ──────────────────────────────────────────────────────────

/**
 * Apply in-memory answer-key edits on top of examContent without mutating it.
 * keyEdits shape: { [sectionKey]: { [questionId]: patchObj } }.
 */
function applyKeyEdits(examContent, keyEdits) {
  if (!examContent || !keyEdits || Object.keys(keyEdits).length === 0) return examContent;

  const patchQuestion = (q, sectionEdits) => {
    const patch = sectionEdits[q.id];
    if (!patch) return q;
    return { ...q, ...patch };
  };

  const result = { ...examContent };

  Object.entries(keyEdits).forEach(([sectionKey, sectionEdits]) => {
    if (!sectionEdits || Object.keys(sectionEdits).length === 0) return;
    const section = result[sectionKey];
    if (!section) return;

    if (sectionKey === "listening" && Array.isArray(section.questionGroups)) {
      result[sectionKey] = {
        ...section,
        questionGroups: section.questionGroups.map((group) => ({
          ...group,
          questions: (group.questions || []).map((q) => patchQuestion(q, sectionEdits)),
        })),
      };
    } else if (sectionKey === "reading" && Array.isArray(section.passages)) {
      result[sectionKey] = {
        ...section,
        passages: section.passages.map((passage) => ({
          ...passage,
          questions: (passage.questions || []).map((q) => patchQuestion(q, sectionEdits)),
        })),
      };
    } else if (Array.isArray(section.questions)) {
      result[sectionKey] = {
        ...section,
        questions: section.questions.map((q) => patchQuestion(q, sectionEdits)),
      };
    } else if (Array.isArray(section.tasks)) {
      result[sectionKey] = {
        ...section,
        tasks: section.tasks.map((q) => patchQuestion(q, sectionEdits)),
      };
    } else if (Array.isArray(section.parts)) {
      result[sectionKey] = {
        ...section,
        parts: section.parts.map((q) => patchQuestion(q, sectionEdits)),
      };
    }
  });

  return result;
}

module.exports = {
  normalizeAnswer,
  normalizeForMatch,
  normalizeTFNG,
  isPartialWordMatch,
  expandAcceptableAnswers,
  ensureArray,
  ensureArrayPreserveSlots,
  matchesAnswer,
  deriveAnswerKey,
  gradeExam,
  applyKeyEdits,
};
