import React from "react";
import { formatAlternatives } from "../../../utils/normalizeAnswer";

/**
 * Custom Section Component for displaying custom skill sections in exam/preview
 */
const CustomSection = ({
  sectionKey,
  section,
  answers = {},
  onAnswerChange,
  reviewMode = false,
  answerKey = {},
  questionResults = {},
}) => {
  if (!section) {
    return (
      <div className="flex h-full items-center justify-center bg-white">
        <p className="text-sm text-gray-500">
          Custom section content is not available.
        </p>
      </div>
    );
  }

  const handleInputChange = (questionId, value) => {
    onAnswerChange?.(sectionKey, questionId, value);
  };

  const standaloneQuestions = section.questions || [];
  const groups = section.groups || [];
  let questionNumber = 0; // Track question numbering across standalone and groups

  return (
    <div className="flex h-full min-h-0 flex-col overflow-hidden bg-white">
      {/* Header */}
      <div className="border-b border-gray-200 bg-white px-5 py-5">
        <h2 className="text-xl font-semibold text-blue-950">{section.title}</h2>
        {section.instructions && (
          <p className="mt-2 text-sm text-gray-600 whitespace-pre-wrap">{section.instructions}</p>
        )}
      </div>

      {/* Content */}
      <div
        className="flex-1 min-h-0 overflow-y-auto bg-white relative"
        data-highlight-surface-id="custom-content-surface"
      >
        <div className="space-y-8 px-3 py-2">
          {/* Standalone Questions */}
          {standaloneQuestions.map((question) => {
            questionNumber++;
            const currentQuestionNumber = questionNumber;
            const questionResult = questionResults?.[question.id];
            const correctAnswers =
              questionResult?.correctAnswers ||
              answerKey?.[question.id]?.correctAnswers ||
              [];
            const userAnswer = answers[question.id];
            const isCorrect =
              reviewMode && questionResult
                ? questionResult.isCorrect
                : null;

            const cardHighlight = reviewMode
              ? isCorrect === true
                ? ""
                : isCorrect === false
                  ? "border-red-300"
                  : "border-gray-200 bg-gray-50"
              : "border-gray-200 bg-gray-50";

            const formattedUserAnswer = (() => {
              const slots = questionResult?.subResults?.slots;
              if (Array.isArray(slots) && slots.length > 0) {
                return slots.map((s) => ({ raw: s.userRaw || "", isCorrect: !!s.isCorrect, isSkipped: !!s.isSkipped }));
              }
              const fallback = Array.isArray(userAnswer)
                ? userAnswer.map((entry) => {
                  if (entry == null) return "";
                  if (typeof entry === "object" && entry.error !== undefined && entry.correction !== undefined) {
                    return `"${entry.error}" → "${entry.correction}"`;
                  }
                  return String(entry).trim();
                }).filter(Boolean)
                : userAnswer != null && userAnswer !== "" ? [String(userAnswer)] : [];
              return fallback.map((r) => ({ raw: r, isCorrect: null, isSkipped: false }));
            })();

            const formattedCorrect = (() => {
              const slots = questionResult?.subResults?.slots;
              if (Array.isArray(slots) && slots.length > 0) {
                return slots.map((s) => ({ raw: s.expectedRaw || s.expected || "", isCorrect: !!s.isCorrect }));
              }
              return correctAnswers.length > 0 ? correctAnswers.map((c) => ({ raw: c, isCorrect: null })) : null;
            })();

            return (
              <div
                key={question.id}
                id={`question-${sectionKey}-${question.id}`}
                className={`rounded-lg border p-4 ${cardHighlight}`}
              >
                <div className="mb-3">
                  <span className="inline-block rounded bg-purple-100 px-2 py-0.5 text-xs font-semibold text-purple-700">
                    Question {currentQuestionNumber}
                  </span>
                </div>

                <p className="mb-3 text-sm font-medium text-gray-800 whitespace-pre-wrap">
                  {question.prompt}
                </p>

                {/* Answer Input */}
                <input
                  type="text"
                  value={userAnswer || ""}
                  onChange={(e) => handleInputChange(question.id, e.target.value)}
                  disabled={reviewMode}
                  placeholder={question.placeholder || "Your answer"}
                  className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm focus:border-purple-500 focus:outline-none focus:ring-1 focus:ring-purple-500 disabled:bg-gray-100 disabled:text-gray-600"
                />

                {/* Review Mode: Show Results */}
                {reviewMode && (
                  <div className="mt-3 space-y-2">
                    {isCorrect === true && (
                      <p className="text-sm font-semibold text-green-600">✓ Correct!</p>
                    )}
                    {isCorrect === false && (
                      <div className="text-sm">
                        <p className="font-semibold text-red-600">✗ Incorrect</p>
                        <p className="mt-1 text-gray-700">
                          <strong>Your answer:</strong>{" "}
                          {Array.isArray(formattedUserAnswer) ? (
                            formattedUserAnswer.map((slot, idx) => (
                              <span key={idx} className={`${slot.isCorrect === true ? 'text-green-600' : slot.isCorrect === false ? 'text-red-600' : slot.isSkipped ? 'text-red-600' : 'text-gray-900'}`}>{slot.raw || (slot.isSkipped ? 'Not answered' : '')}{idx < formattedUserAnswer.length - 1 ? ' / ' : ''}</span>
                            ))
                          ) : (
                            formattedUserAnswer && formattedUserAnswer.raw
                              ? formattedUserAnswer.raw
                              : <span className="text-red-600">Not answered</span>
                          )}
                        </p>
                        {formattedCorrect && (
                          <p className={`mt-1 text-gray-700 ${isCorrect === true ? 'text-green-600' : 'text-red-600'}`}>
                            <strong>Correct answer:</strong> {Array.isArray(formattedCorrect) ? (
                              formattedCorrect.map((slot, idx) => (
                                <span
                                  key={idx}
                                  className={isCorrect === true ? 'text-green-600' : 'text-red-600'}
                                >
                                  {formatAlternatives(slot.raw)}{idx < formattedCorrect.length - 1 ? ' / ' : ''}
                                </span>
                              ))
                            ) : (
                              formattedCorrect || ''
                            )}
                          </p>
                        )}
                      </div>
                    )}
                  </div>
                )}
              </div>
            );
          })}

          {/* Groups */}
          {groups.map((group, groupIndex) => (
            <article key={group.id} className="space-y-4">
              {/* Group Header */}
              <div className="border-l-4 border-purple-500 pl-4">
                <h3 className="text-lg font-semibold text-purple-800">
                  {group.title}
                </h3>
                {group.description && (
                  <p className="mt-1 text-sm text-gray-600">
                    {group.description}
                  </p>
                )}
              </div>

              {/* Questions */}
              <div className="space-y-5">
                {(group.questions || []).map((question) => {
                  questionNumber++;
                  const currentQuestionNumber = questionNumber;
                  const questionResult = questionResults?.[question.id];
                  const correctAnswers =
                    questionResult?.correctAnswers ||
                    answerKey?.[question.id]?.correctAnswers ||
                    [];
                  const userAnswer = answers[question.id];
                  const isCorrect =
                    reviewMode && questionResult
                      ? questionResult.isCorrect
                      : null;

                  const cardHighlight = reviewMode
                    ? isCorrect === true
                      ? ""
                      : isCorrect === false
                        ? "border-red-300"
                        : "border-gray-200 bg-gray-50"
                    : "border-gray-200 bg-gray-50";

                  const formattedCorrect =
                    correctAnswers.length > 0
                      ? correctAnswers.join(" / ")
                      : null;

                  return (
                    <div
                      key={question.id}
                      id={`question-${sectionKey}-${question.id}`}
                      className={`rounded-lg border p-4 ${cardHighlight}`}
                    >
                      <div className="mb-3">
                        <span className="inline-block rounded bg-purple-100 px-2 py-0.5 text-xs font-semibold text-purple-700">
                          Question {currentQuestionNumber}
                        </span>
                      </div>

                      <p className="mb-3 text-sm font-medium text-gray-800 whitespace-pre-wrap">
                        {question.prompt}
                      </p>

                      {/* Answer Input */}
                      <input
                        type="text"
                        value={userAnswer || ""}
                        onChange={(e) => handleInputChange(question.id, e.target.value)}
                        disabled={reviewMode}
                        placeholder={question.placeholder || "Your answer"}
                        className="w-full rounded-md border border-gray-300 px-3 py-2 text-sm focus:border-purple-500 focus:outline-none focus:ring-1 focus:ring-purple-500 disabled:bg-gray-100 disabled:text-gray-600"
                      />

                      {/* Review Mode: Show Results */}
                      {reviewMode && (
                        <div className="mt-3 space-y-2">
                          {isCorrect === true && (
                            <p className="text-sm font-semibold text-green-600">
                              ✓ Correct!
                            </p>
                          )}
                          {isCorrect === false && (
                            <div className="text-sm">
                              <p className="font-semibold text-red-600">✗ Incorrect</p>
                              {formattedCorrect && (
                                <p className="mt-1 text-gray-700">
                                  <strong>Correct answer:</strong> {formattedCorrect}
                                </p>
                              )}
                            </div>
                          )}
                        </div>
                      )}
                    </div>
                  );
                })}
              </div>
            </article>
          ))}

          {groups.length === 0 && standaloneQuestions.length === 0 && (
            <div className="flex items-center justify-center py-12">
              <p className="text-sm text-gray-500">
                No questions available for this section.
              </p>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default CustomSection;
