import React from "react";

const ResultModal = ({
  isOpen,
  scoreSummary,
  questionResults = {},
  onClose,
  onReview,
  isPreviewMode,
  hasReportBlob,
  isGeneratingReport,
  onPreviewReport,
  sectionTabsAll = [],
  isPracticeMode,
  isEmbedded = false,
  ackStatus = null,
}) => {
  if (!isOpen) return null;

  // Get sections - may be at root level or nested
  const sections = scoreSummary?.sections || scoreSummary || {};

  const renderSection = (key, label) => {
    const data = sections[key];
    if (!data) return null;
    // Special rendering for writing: show minimum word count info per task
    if (key === 'writing') {
      const results = questionResults?.writing || {};
      const taskKeys = Object.keys(results);
      const meetsCount = data?.meetsMinimumCount ?? taskKeys.filter((id) => results[id]?.meetsMinimum).length;
      return (
        <div key={key} className="rounded-xl border border-gray-200 bg-gray-50 p-4">
          <div className="flex items-center justify-between">
            <p className="text-sm font-semibold text-blue-900">{label}</p>
            <span className="text-sm font-bold text-orange-500">{meetsCount}/{taskKeys.length}</span>
          </div>
          <div className="mt-3 grid gap-2 text-xs text-gray-600">
            {taskKeys.length === 0 ? (
              <p className="text-center text-gray-500 py-2">No writing tasks found</p>
            ) : (
              taskKeys.map((qid, index) => (
                <div key={qid} className="flex items-center justify-between px-2">
                  <div className="text-sm text-gray-700">Task {index + 1}</div>
                  <div className={`text-sm ${results[qid]?.meetsMinimum ? 'text-green-600' : 'text-red-600'}`}>
                    {results[qid]?.meetsMinimum ? 'Meets minimum' : 'Below minimum'} ({results[qid]?.wordCount || 0}/{(results[qid]?.minimumWords || 100)})
                  </div>
                </div>
              ))
            )}
          </div>
        </div>
      );
    }
    return (
      <div key={key} className="rounded-xl border border-gray-200 bg-gray-50 p-4">
        <div className="flex items-center justify-between">
          <p className="text-sm font-semibold text-blue-900">{label}</p>
          {key === 'writing' ? (
            <span className="text-sm font-bold text-orange-500">{data?.meetsMinimumCount || 0}/{(data?.total || 0)}</span>
          ) : (
            typeof data.score === "number" && (
              <span className="text-sm font-bold text-orange-500">
                {data.score}%
              </span>
            )
          )}
        </div>
        {key !== 'writing' ? (
          <div className="mt-2 grid grid-cols-3 gap-2 text-xs text-gray-600">
            <span>
              Correct:{" "}
              <strong className="text-green-600">{data.correct}</strong>
            </span>
            <span>
              Incorrect:{" "}
              <strong className="text-red-500">{data.incorrect}</strong>
            </span>
            <span>
              Skipped:{" "}
              <strong className="text-gray-500">{data.skipped}</strong>
            </span>
          </div>
        ) : null}
      </div>
    );
  };

  // Map of section keys to display labels
  const sectionLabels = {
    listening: "Listening",
    grammar: "Grammar & Vocabulary",
    reading: "Reading",
    writing: "Writing",
    speaking: "Speaking",
  };

  // Create label lookup from sectionTabsAll for custom sections
  const customSectionLabels = {};
  if (Array.isArray(sectionTabsAll)) {
    sectionTabsAll.forEach((tab) => {
      if (tab.key && tab.label) {
        customSectionLabels[tab.key] = tab.label;
        customSectionLabels[tab.key.toLowerCase()] = tab.label;
      }
    });
  }

  // Render all sections dynamically
  const renderedSections = Object.keys(sections)
    .filter(key => key !== 'sections' && typeof sections[key] === 'object' && sections[key] !== null)
    .sort((a, b) => {
      const order = ["listening", "grammar", "reading", "writing", "speaking"];
      const aIndex = order.indexOf(a);
      const bIndex = order.indexOf(b);
      if (aIndex === -1 && bIndex === -1) return a.localeCompare(b);
      if (aIndex === -1) return 1;
      if (bIndex === -1) return -1;
      return aIndex - bIndex;
    })
    .map((key) => {
      const label = customSectionLabels[key] || sectionLabels[key] || key.charAt(0).toUpperCase() + key.slice(1);
      return renderSection(key, label);
    });

  return (
    <div className="fixed inset-0 z-modal flex items-center justify-center bg-black/40 p-4 backdrop-blur-sm">
      <div className="w-full max-w-md rounded-2xl bg-white p-6 shadow-xl max-h-[80vh] overflow-y-auto">
        <h2 className="text-xl font-semibold text-blue-950">
          {isPracticeMode ? 'Nice job!' : 'Submission received'}
        </h2>
        <p className="mt-1 text-sm text-gray-600">
          {isPracticeMode
            ? 'Here\'s how you did. You can review your answers or close this to finish.'
            : 'Listening and Reading have been graded automatically. Review the breakdown below, then close to inspect your answers.'}
        </p>

        <div className="mt-4 space-y-3">
          {renderedSections.length > 0 ? renderedSections : (
            <p className="text-center text-gray-500 py-4">No score data available</p>
          )}
        </div>

        {isEmbedded && ackStatus === 'pending' && (
          <div className="mt-4 flex items-start gap-2 rounded-md bg-blue-50 border border-blue-200 px-3 py-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 shrink-0 text-blue-500 mt-0.5 animate-spin" fill="none" viewBox="0 0 24 24">
              <circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" />
              <path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4z" />
            </svg>
            <p className="text-xs text-blue-700">Đang đồng bộ kết quả với Portal, vui lòng đợi trong giây lát.<br /><span className="text-blue-500">Syncing your result with the Portal — please wait a moment before leaving.</span></p>
          </div>
        )}

        {isEmbedded && ackStatus === 'timeout' && (
          <div className="mt-4 flex items-start gap-2 rounded-md bg-amber-50 border border-amber-200 px-3 py-2">
            <svg xmlns="http://www.w3.org/2000/svg" className="h-4 w-4 shrink-0 text-amber-500 mt-0.5" viewBox="0 0 20 20" fill="currentColor">
              <path fillRule="evenodd" d="M8.257 3.099c.765-1.36 2.722-1.36 3.486 0l5.58 9.92c.75 1.334-.213 2.98-1.742 2.98H4.42c-1.53 0-2.493-1.646-1.743-2.98l5.58-9.92zM11 13a1 1 0 11-2 0 1 1 0 012 0zm-1-8a1 1 0 00-1 1v3a1 1 0 002 0V6a1 1 0 00-1-1z" clipRule="evenodd" />
            </svg>
            <p className="text-xs text-amber-700">Bài làm đã được lưu, nhưng kết quả có thể chưa hiển thị trên Portal ngay. Giáo viên vẫn sẽ thấy điểm số của bạn.<br /><span className="text-amber-500">Your submission was saved, but the Portal may not display the result immediately. Your teacher will still see your score.</span></p>
          </div>
        )}

        <div className="mt-6 flex flex-col gap-2">
          <button
            onClick={onReview}
            className="w-full rounded-lg bg-orange-400 px-4 py-2 text-sm font-semibold text-white transition hover:bg-orange-500 focus:outline-none focus:ring-2 focus:ring-orange-200"
          >
            Review Your Answers
          </button>

          {isPreviewMode && !isPracticeMode && (
            <button
              onClick={onPreviewReport}
              disabled={isGeneratingReport}
              className="w-full rounded-lg bg-green-500 px-4 py-2 text-sm font-semibold text-white transition hover:bg-green-600 focus:outline-none focus:ring-2 focus:ring-green-200 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {isGeneratingReport ? (
                <span className="flex items-center justify-center gap-2">
                  <span className="inline-block h-4 w-4 animate-spin rounded-full border-2 border-white border-t-transparent" />
                  Creating Report
                </span>
              ) : (
                "Preview Report"
              )}
            </button>
          )}

          <button
            onClick={onClose}
            className="w-full rounded-lg border border-gray-300 px-4 py-2 text-sm font-semibold text-gray-700 transition hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-gray-200"
          >
            {isPracticeMode ? 'Done' : 'Close'}
          </button>

          {isEmbedded && (
            <button
              onClick={() => {
                if (window.parent !== window) {
                  window.parent.postMessage({ type: 'EXAM_CLOSE' }, '*');
                }
              }}
              disabled={ackStatus === 'pending'}
              className="w-full rounded-lg bg-blue-500 px-4 py-2 text-sm font-semibold text-white transition hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-200 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              {ackStatus === 'pending' ? 'Syncing...' : 'Return to Portal'}
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

export default ResultModal;
