import React from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";

const FillInBlankActions = () => {
  const { addPromptBlank } = useQuestionContext();

  if (typeof addPromptBlank !== "function") {
    return null;
  }

  return (
    <button
      type="button"
      onClick={addPromptBlank}
      className="text-xs font-semibold text-blue-600 hover:text-blue-700"
    >
      + Add blank
    </button>
  );
};

export default FillInBlankActions;
