import React, { useCallback, useRef, useState, useContext } from "react";
import { normalizeAnswer, splitAlternatives, isPartialWordMatch } from "../../../utils/normalizeAnswer";
import RegradeContext from "../../../contexts/RegradeContext";
import AnswerKeyEditor from "../_shared/AnswerKeyEditor";

const UnderlinePreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  name,
  questionNumber = 1,
  sectionKey = '',
}) => {
  const passageRef = useRef(null);
  const [activeSlotIndex, setActiveSlotIndex] = useState(null);

  const isInteractive = typeof onChange === "function";
  const { isRegrade, setKeyEdit } = useContext(RegradeContext);
  const example = question?.example || null;
  const hasSubQuestions =
    Array.isArray(question?.subQuestions) && question.subQuestions.length > 0;

  // Filter out example subQuestions for answerable list
  const answerableSubQuestions = hasSubQuestions
    ? question.subQuestions.filter((sq) => !sq.isExample)
    : [];

  const numberOfSlots = hasSubQuestions
    ? answerableSubQuestions.length
    : question?.numberOfSelections || (question?.correctAnswers || []).length;

  // Value is a flat array of strings (one per slot)
  const userSlots = Array.isArray(value) ? [...value] : [];
  while (userSlots.length < numberOfSlots) userSlots.push("");

  const startingNumber =
    typeof questionNumber === "string"
      ? parseInt(String(questionNumber).split(" ")[0]) || 1
      : parseInt(String(questionNumber)) || 1;

  const updateSlot = useCallback(
    (index, val) => {
      if (!isInteractive || disabled || (reviewMode)) return;
      const next = [...userSlots];
      next[index] = val;
      onChange(next);
    },
    [userSlots, isInteractive, disabled, reviewMode, onChange]
  );

  const handleTextSelect = useCallback(() => {
    if (!isInteractive || disabled || (reviewMode)) return;
    const selection = window.getSelection();
    const text = selection?.toString().trim();
    if (!text) return;

    // Ensure the selection is within our passage
    if (
      passageRef.current &&
      !passageRef.current.contains(selection?.anchorNode)
    )
      return;

    // Target: the active slot if set and empty, otherwise next empty slot
    let targetIndex = activeSlotIndex;
    if (targetIndex === null || (targetIndex >= 0 && userSlots[targetIndex])) {
      targetIndex = userSlots.findIndex((s) => !s);
    }
    if (targetIndex === -1 || targetIndex === null) return;

    const next = [...userSlots];
    next[targetIndex] = text;
    onChange(next);

    // Clear browser selection
    selection?.removeAllRanges();

    // Auto-advance to next empty slot
    const nextEmpty = next.findIndex((s, i) => i > targetIndex && !s);
    setActiveSlotIndex(nextEmpty !== -1 ? nextEmpty : null);
  }, [
    userSlots,
    activeSlotIndex,
    isInteractive,
    disabled,
    reviewMode,
    onChange,
  ]);

  if (!question) return null;

  // Review scoring
  const reviewResults = (() => {
    if (!reviewMode) return null;

    if (hasSubQuestions) {
      // Per-slot scoring: each slot matched against its own correctAnswers pool
      return userSlots.map((slot, index) => {
        const sq = answerableSubQuestions[index];
        if (!sq) return { isSkipped: true, isCorrect: false };

        const userText = normalizeAnswer(slot || "");
        if (!userText) return { isSkipped: true, isCorrect: false };

        const pool = (sq.correctAnswers || [])
          .flatMap((a) => splitAlternatives(String(a)))
          .map(normalizeAnswer);

        // Try exact match
        let matched = pool.some((a) => a === userText);
        // Try partial: user ⊂ key
        if (!matched) matched = pool.some((a) => isPartialWordMatch(userText, a));
        // Try reverse partial: key ⊂ user's selection
        if (!matched) matched = pool.some((a) => isPartialWordMatch(a, userText));

        return { isSkipped: false, isCorrect: matched };
      });
    }

    // Bag-match scoring for flat correctAnswers
    const pool = (question.correctAnswers || correctAnswers || [])
      .flatMap((a) => splitAlternatives(String(a)))
      .map(normalizeAnswer);
    const remainingPool = [...pool];

    return userSlots.map((slot) => {
      const userText = normalizeAnswer(slot || "");
      if (!userText) return { isSkipped: true, isCorrect: false };

      // Try exact match
      let matchIndex = remainingPool.findIndex((a) => a === userText);
      // Try partial: user ⊂ key
      if (matchIndex === -1) {
        matchIndex = remainingPool.findIndex((a) =>
          isPartialWordMatch(userText, a)
        );
      }
      // Try reverse partial: key ⊂ user's selection
      if (matchIndex === -1) {
        matchIndex = remainingPool.findIndex((a) =>
          isPartialWordMatch(a, userText)
        );
      }
      if (matchIndex !== -1) {
        remainingPool.splice(matchIndex, 1);
        return { isSkipped: false, isCorrect: true };
      }
      return { isSkipped: false, isCorrect: false };
    });
  })();

  // Expected answers for review display
  const allExpectedAnswers = hasSubQuestions
    ? answerableSubQuestions.flatMap((sq) => sq.correctAnswers || [])
    : question.correctAnswers || correctAnswers || [];

  return (
    <div className="flex flex-col gap-4">
      {/* Passage */}
      <div
        ref={passageRef}
        className="rounded-lg border border-slate-200 bg-slate-50 px-4 py-3 text-[15px] leading-relaxed text-slate-700 select-text cursor-text rich-text-content [&_u]:underline [&_u]:decoration-orange-400 [&_u]:decoration-2 [&_u]:underline-offset-2"
        dangerouslySetInnerHTML={{ __html: question.content }}
        onMouseUp={handleTextSelect}
        onTouchEnd={handleTextSelect}
      />

      {!reviewMode && !disabled && (
        <p className="text-xs text-slate-400 -mt-2">
          Highlight text in the passage above to fill the answer slots below.
          You can also type directly.
        </p>
      )}

      {/* Answer slots */}
      <div className="flex flex-col gap-2">
        {/* Example row */}
        {example && (
          <div className="flex items-center gap-2 py-2 border-b border-slate-100">
            <span className="inline-flex h-7 min-w-[2.5rem] flex-shrink-0 items-center justify-center rounded bg-blue-100 px-2 text-xs font-semibold text-blue-600">
              Ex.
            </span>
            <span className="inline-flex items-center gap-1 rounded-full bg-green-50 border border-green-200 px-2.5 py-1 text-sm font-semibold text-green-700">
              <svg
                width="11"
                height="11"
                viewBox="0 0 12 12"
                fill="none"
                className="flex-shrink-0"
              >
                <path
                  d="M2 6.5L4.5 9L10 3"
                  stroke="currentColor"
                  strokeWidth="1.8"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                />
              </svg>
              {example.text}
            </span>
          </div>
        )}

        {/* Answerable slots */}
        {userSlots.map((slot, index) => {
          const rowNumber = startingNumber + index;
          const result = reviewResults?.[index];
          const isActive = activeSlotIndex === index;
          const subQ = hasSubQuestions ? answerableSubQuestions[index] : null;

          return (
            <div
              key={index}
              className="flex flex-col sm:flex-row sm:items-center gap-2 py-2.5 border-b border-slate-100 last:border-0"
            >
              <div className="flex items-center gap-2 shrink-0">
                <span
                  className={`inline-flex h-7 min-w-[1.75rem] flex-shrink-0 items-center justify-center rounded px-2 text-xs font-medium ${
                    isActive
                      ? "bg-blue-100 text-blue-700"
                      : "bg-slate-100 text-slate-600"
                  }`}
                >
                  {rowNumber}
                </span>
                {subQ?.prompt && (
                  <span
                    className="text-sm text-slate-600 leading-snug rich-text-content"
                    dangerouslySetInnerHTML={{ __html: subQ.prompt }}
                  />
                )}
              </div>
              <div className="flex flex-1 items-center gap-2">
                <input
                  type="text"
                  value={slot || ""}
                  onChange={(e) => updateSlot(index, e.target.value)}
                  onFocus={() => setActiveSlotIndex(index)}
                  disabled={disabled || (reviewMode)}
                  placeholder={
                    isActive
                      ? "Now highlight text above..."
                      : "Click to activate, then highlight"
                  }
                  data-question-slot-number={rowNumber}
                  data-question-slot-index={index}
                  className={`w-full rounded-lg border px-3 py-2 text-sm shadow-sm transition-all focus:outline-none focus:ring-2 ${
                    reviewMode
                      ? result?.isCorrect
                        ? "border-green-400 bg-green-50"
                        : result?.isSkipped
                          ? "border-slate-200 bg-slate-50"
                          : "border-red-300 bg-red-50"
                      : isActive
                        ? "border-blue-400 bg-blue-50 ring-2 ring-blue-200"
                        : "border-slate-200 focus:border-blue-500 focus:ring-blue-200"
                  }`}
                />
                {!reviewMode && !disabled && slot && (
                  <button
                    type="button"
                    onClick={() => updateSlot(index, "")}
                    className="flex-shrink-0 rounded p-1 text-slate-400 hover:text-red-500 hover:bg-red-50 transition-colors"
                    title="Clear"
                  >
                    <svg
                      width="14"
                      height="14"
                      viewBox="0 0 16 16"
                      fill="none"
                    >
                      <path
                        d="M4 4l8 8m0-8l-8 8"
                        stroke="currentColor"
                        strokeWidth="1.5"
                        strokeLinecap="round"
                      />
                    </svg>
                  </button>
                )}
              </div>
              {/* Review feedback */}
              {reviewMode && (
                <div className="flex-shrink-0 text-xs font-semibold">
                  {result?.isCorrect && (
                    <span className="text-green-600">&#10003;</span>
                  )}
                  {!result?.isCorrect && !result?.isSkipped && (
                    <span className="text-red-600">&#10007;</span>
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* Review: show expected answers */}
      {reviewMode && (
        <div className="mt-2 rounded-lg border border-slate-200 bg-slate-50 px-4 py-3">
          <p className="text-xs font-semibold text-slate-500 mb-1">
            Expected answers:
          </p>
          <div className="flex flex-wrap gap-2">
            {allExpectedAnswers.map((ans, i) => (
              <span
                key={i}
                className="inline-block rounded-full bg-green-50 border border-green-200 px-2.5 py-0.5 text-xs font-medium text-green-700"
              >
                {ans}
              </span>
            ))}
          </div>
        </div>
      )}
      {isRegrade && reviewMode && (
        <AnswerKeyEditor
          correctAnswers={question.correctAnswers}
          subQuestions={hasSubQuestions ? question.subQuestions : undefined}
          questionType={question.type}
          onChange={(patch) => setKeyEdit(sectionKey, question.id, patch)}
        />
      )}
    </div>
  );
};

export default UnderlinePreview;
