import { useState } from 'react';
import { gradeExam } from '../utils/examScoring';

/**
 * useExamGrading manages the execution and state of grading operations.
 * It handles the creation of the score payload (questionResults, scoreSummary)
 * and exports functions to trigger partial or complete grading.
 */
export function useExamGrading({
  answers,
  setAnswers,
  answerKeyMap,
  isPreviewMode,
  isPracticeMode,
}) {
  const [questionResults, setQuestionResults] = useState({
    listening: {},
    reading: {},
  });
  const [scoreSummary, setScoreSummary] = useState(null);

  const gradeSection = async (sectionKey) => {
    if (!sectionKey) return null;
    try {
      const answersSubset = { [sectionKey]: answers[sectionKey] || {} };
      const keySubset = { [sectionKey]: answerKeyMap[sectionKey] || {} };
      const { summary, questionResults: results } = gradeExam(answersSubset, keySubset);
      setQuestionResults((prev) => ({ ...prev, ...results }));
      return { summary, results };
    } catch (err) {
      console.error('Error grading section', sectionKey, err);
      return null;
    }
  };

  const handleFillAnswers = () => {
    // Check if the user explicitly added ?preview=true to the URL
    const isExplicitPreviewOverride = typeof window !== 'undefined' && new URLSearchParams(window.location.search).get('preview') === 'true';

    // Block fill answers in practice mode unless an explicit ?preview=true flag is provided via URL
    if (!isPreviewMode || (isPracticeMode && !isExplicitPreviewOverride)) {
      console.warn('Fill answers is securely bound to Preview mode.');
      return;
    }

    // Start with a copy of current answers to preserve data for sections we don't fill (like writing)
    const filledAnswers = { ...answers };

    Object.keys(answerKeyMap).forEach((sectionKey) => {
      const sectionAnswers = {};
      const questionMap = answerKeyMap[sectionKey] || {};

      Object.keys(questionMap).forEach((questionId) => {
        const questionData = questionMap[questionId];
        const { correctAnswers, isSubQuestions, questionType } = questionData;

        if (questionType === 'essay' || questionType === 'writing') {
          // Skip essay/writing questions - no correct answer
          return;
        }

        if (isSubQuestions) {
          // All question types with subQuestions expect answers as an array
          const arrayAnswers = [];
          correctAnswers.forEach((answerArray) => {
            if (Array.isArray(answerArray) && answerArray.length > 0) {
              arrayAnswers.push(answerArray[0]); // Take the first acceptable answer
            } else {
              arrayAnswers.push('');
            }
          });
          sectionAnswers[questionId] = arrayAnswers;
        } else if (questionData.isMultiBlank) {
          // Multi-blank without subQuestions: correctAnswers is array-of-arrays
          sectionAnswers[questionId] = correctAnswers.map((slotAlts) =>
            Array.isArray(slotAlts) && slotAlts.length > 0 ? slotAlts[0] : ''
          );
        } else if (questionData.isCorrection) {
          // Correction: build {error, correction} slot objects for auto-fill
          const slots = correctAnswers.map((ansArr) => ({
            error: '',
            correction: Array.isArray(ansArr) && ansArr.length > 0 ? ansArr[0] : ''
          }));
          sectionAnswers[questionId] = slots;
        } else if (questionData.isUnderline) {
          // Underline: flat array of first alternative per slot
          sectionAnswers[questionId] = correctAnswers.map((ansArr) =>
            Array.isArray(ansArr) && ansArr.length > 0 ? ansArr[0] : ''
          );
        } else if (questionType === 'checkbox') {
          // Checkbox answers are stored as an array of selected values
          sectionAnswers[questionId] = correctAnswers;
        } else {
          // For single-answer questions (non-subQuestions), use the array directly
          sectionAnswers[questionId] = Array.isArray(correctAnswers)
            ? correctAnswers.map(a => (typeof a === 'string' ? a.split('|')[0] : a))
            : correctAnswers;
        }
      });

      if (Object.keys(sectionAnswers).length > 0) {
        filledAnswers[sectionKey] = sectionAnswers;
      }
    });

    setAnswers(filledAnswers);
  };

  return {
    questionResults,
    setQuestionResults,
    scoreSummary,
    setScoreSummary,
    gradeSection,
    handleFillAnswers,
  };
}
