import React, { useEffect, useMemo, useState } from "react";

const DEFAULT_DURATION = 60 * 60;

const QuestionsNavigation = ({
  sections = [],
  activeSectionKey,
  onSelectSection,
  onSelectQuestion,
  answers = {},
  reviewMode = false,
  questionResults = {},
  totalSeconds = DEFAULT_DURATION,
  onSubmit,
  isSubmitting = false,
  hasSubmitted = false,
  isPreviewMode = false,
  showSubmitButton = true,
  isSectionSelectable = () => true,
  isSkillTimedMode = false,
  submittedSections = [],
  isTimerPaused = false,
  fontLevel = 1,
  onToggleFont,
  isRegradeMode = false,
  onRegrade,
  isSavingRegrade = false,
  hasPendingKeyEdits = false,
}) => {
  const activeSectionObj = sections.find((s) => s.key === activeSectionKey) || null;
  const timerInitializedRef = React.useRef(false);
  // Track if the parent has ever sent a real (> 0) timer value for the current section
  if (Number.isFinite(totalSeconds) && totalSeconds > 0) {
    timerInitializedRef.current = true;
  }
  const effectiveTotalSeconds = isSkillTimedMode
    ? (Number.isFinite(totalSeconds) && (totalSeconds > 0 || timerInitializedRef.current) ? totalSeconds : (activeSectionObj?.timeAllottedSeconds || 0))
    : totalSeconds;
  const [timeLeft, setTimeLeft] = useState(effectiveTotalSeconds);

  // Reset the initialized flag when section changes
  useEffect(() => { timerInitializedRef.current = false; }, [activeSectionKey]);
  useEffect(() => { setTimeLeft(effectiveTotalSeconds); }, [effectiveTotalSeconds, activeSectionKey]);

  useEffect(() => {
    if (!Number.isFinite(effectiveTotalSeconds) || effectiveTotalSeconds <= 0) return undefined;
    setTimeLeft(effectiveTotalSeconds);
    if (isTimerPaused) return undefined;
    const interval = setInterval(() => {
      setTimeLeft((prev) => { if (prev <= 1) { clearInterval(interval); return 0; } return prev - 1; });
    }, 1000);
    return () => clearInterval(interval);
  }, [effectiveTotalSeconds, activeSectionKey, isTimerPaused]);

  const formattedTime = useMemo(() => formatTime(timeLeft), [timeLeft]);
  const submitDisabled = isSubmitting || (reviewMode && !isPreviewMode && !isRegradeMode) || (isSkillTimedMode && submittedSections.includes(activeSectionKey) && !hasSubmitted) || (isPreviewMode && hasSubmitted && !isRegradeMode);
  const currentSection = sections.find(s => s.key === activeSectionKey);
  const isCurrentSectionSubmitted = submittedSections.includes(currentSection?.key);

  // Grouping Logic
  const groups = useMemo(() => {
    if (!currentSection || !Array.isArray(currentSection.items)) return [];
    const uniqueGroups = [];
    const groupMap = new Map();
    const isGrammar = currentSection.label?.toLowerCase().includes("grammar") || currentSection.key?.toLowerCase().includes("grammar") || currentSection.label?.toLowerCase().includes("ngữ pháp");

    currentSection.items.forEach(item => {
      // For grammar: group by his own id (the exercise id like ex4, ex5)
      // For reading/listening: use existing passageId/groupId
      let groupId = "default";
      let groupLabel = "";

      if (isGrammar) {
        groupId = item.id || "default";
        groupLabel = String(groupId).toUpperCase().replace(/^EX(\d+)$/, 'EX. $1');
      } else {
        groupId = item.meta?.passageId || item.meta?.groupId || "default";
      }

      if (!groupMap.has(groupId)) {
        const index = uniqueGroups.length + 1;
        const label = groupLabel || `Part ${index}`;
        const groupObj = { id: groupId, label, items: [] };
        groupMap.set(groupId, groupObj);
        uniqueGroups.push(groupObj);
      }
      groupMap.get(groupId).items.push(item);
    });

    if (uniqueGroups.length === 1 && uniqueGroups[0].id === "default") return [];
    return uniqueGroups;
  }, [currentSection]);

  const [activeGroupId, setActiveGroupId] = useState(null);

  useEffect(() => {
    if (groups.length > 0) {
      if (!activeGroupId || !groups.find(g => g.id === activeGroupId)) {
        setActiveGroupId(groups[0].id);
      }
    } else {
      setActiveGroupId(null);
    }
  }, [groups, activeSectionKey]);

  // All items for display (when no groups, show all)
  const allItems = currentSection?.items || [];

  const visibleItems = useMemo(() => {
    const base = groups.length === 0 ? allItems : (groups.find(g => g.id === activeGroupId)?.items || allItems);
    return base.filter(item => !item?.meta?.isGrouped);
  }, [groups, activeGroupId, allItems]);

  // Navigate prev/next question
  const handleNav = (direction) => {
    if (!currentSection || allItems.length === 0) return;
    // Find current question index globally
    const currentIdx = allItems.findIndex(item => {
      // Try to match by focus or just pick first
      return false; // We'll just go to next/prev from active group
    });
    if (direction === 'next') {
      // Find next group
      if (groups.length > 0) {
        const gIdx = groups.findIndex(g => g.id === activeGroupId);
        if (gIdx < groups.length - 1) {
          const nextGroup = groups[gIdx + 1];
          setActiveGroupId(nextGroup.id);
          if (nextGroup.items.length > 0 && onSelectQuestion) {
            onSelectQuestion(currentSection.key, nextGroup.items[0]);
          }
        }
      }
    } else {
      if (groups.length > 0) {
        const gIdx = groups.findIndex(g => g.id === activeGroupId);
        if (gIdx > 0) {
          const prevGroup = groups[gIdx - 1];
          setActiveGroupId(prevGroup.id);
          if (prevGroup.items.length > 0 && onSelectQuestion) {
            onSelectQuestion(currentSection.key, prevGroup.items[0]);
          }
        }
      }
    }
  };

  const getAnsweredState = (item) => {
    const rawAnswer = answers?.[currentSection?.key]?.[item.id];
    const slotIndex = item?.meta?.slotIndex;
    const questionType = item?.meta?.questionType;
    let answered = false;

    if (questionType === "checkbox") {
      const requiredSelections = item?.meta?.requiredSelections || 1;
      const selectedCount = Array.isArray(rawAnswer)
        ? rawAnswer.filter((e) => { if (e === null || e === undefined) return false; if (typeof e === "string") return e.trim().length > 0; return true; }).length : 0;
      answered = selectedCount >= requiredSelections;
    } else if (slotIndex != null) {
      if (Array.isArray(rawAnswer)) {
        const sv = rawAnswer[slotIndex];
        answered = typeof sv === "string" ? sv.trim().length > 0 : sv !== null && sv !== undefined;
      } else if (rawAnswer && typeof rawAnswer === 'object') {
        const sv = rawAnswer[slotIndex];
        answered = typeof sv === "string" ? sv.trim().length > 0 : sv !== null && sv !== undefined;
      }
    } else {
      if (Array.isArray(rawAnswer)) answered = rawAnswer.some(v => v);
      else if (typeof rawAnswer === 'object' && rawAnswer !== null) answered = Object.values(rawAnswer).some(v => v);
      else if (typeof rawAnswer === 'string') answered = rawAnswer.trim().length > 0;
      else answered = !!rawAnswer;
    }
    return answered;
  };

  const getStateClass = (item) => {
    const answered = getAnsweredState(item);
    const slotIndex = item?.meta?.slotIndex;
    if (reviewMode) {
      const result = questionResults?.[currentSection?.key]?.[item.id];
      let isCorrect = false;
      if (result?.subResults && slotIndex != null) {
        const slotObj = result.subResults?.slots?.[slotIndex];
        isCorrect = slotObj ? !!slotObj.isCorrect : !!result.isCorrect;
      } else if (result) {
        isCorrect = result.isCorrect;
      }
      if (result) {
        return isCorrect ? "bg-green-100 text-green-700 font-medium border-green-300" : "bg-red-50 text-red-600 font-medium border-red-300";
      }
    }
    if (answered) return "bg-orange-400 text-white font-medium border-orange-500";
    return "text-gray-500 hover:bg-gray-100 border-gray-200";
  };

  // Render section tabs if multiple sections
  const hasMultipleSections = sections.length > 1;

  // Theme helper based on skill code
  const getThemeBySkill = (skill) => {
    const s = String(skill || "").toUpperCase();
    if (s.includes("LISTENING") || s.includes("LIS") || s.includes("NGHE") || s === "LST") {
      return { code: "LIS", active: "bg-orange-50 text-orange-600 border-orange-200", badge: "bg-orange-50 text-orange-700 border-orange-200" };
    }
    if (s.includes("READING") || s.includes("REA") || s.includes("ĐỌC")) {
      return { code: "REA", active: "bg-orange-50 text-orange-600 border-orange-200", badge: "bg-orange-50 text-orange-700 border-orange-200" };
    }
    if (s.includes("WRITING") || s.includes("WRI") || s.includes("VIẾT")) {
      return { code: "WRI", active: "bg-orange-50 text-orange-600 border-orange-200", badge: "bg-orange-50 text-orange-700 border-orange-200" };
    }
    if (s.includes("GRAMMAR") || s.includes("GRM") || s.includes("NGỮ PHÁP")) {
      return { code: "GRM", active: "bg-orange-50 text-orange-600 border-orange-200", badge: "bg-orange-50 text-orange-700 border-orange-200" };
    }
    if (s.includes("SPEAKING") || s.includes("SPK") || s.includes("NÓI")) {
      return { code: "SPK", active: "bg-orange-50 text-orange-600 border-orange-200", badge: "bg-orange-50 text-orange-700 border-orange-200" };
    }
    return { code: "GEN", active: "bg-orange-50 text-orange-600 border-orange-200", badge: "bg-orange-50 text-orange-700 border-orange-200" };
  };

  const currentTheme = getThemeBySkill(currentSection?.label || currentSection?.key);

  return (
    <div
      className="relative z-app-nav flex min-h-[28px] items-center justify-between gap-2 bg-white border-t border-gray-200 px-4 shadow-[0_-2px_10px_rgba(0,0,0,0.05)] text-[11px] shrink-0"
      style={{ paddingBottom: 'env(safe-area-inset-bottom)' }}
    >
      {/* Left: Section tabs + Part tabs + Questions */}
      <div className="flex flex-1 items-center gap-3 overflow-x-auto no-scrollbar h-full">
        {/* Section tabs (mini) */}
        {hasMultipleSections && (
          <div className="flex items-center gap-1 shrink-0 border-r border-gray-200 pr-2 h-full">
            {sections.map(section => {
              const theme = getThemeBySkill(section.label || section.key);
              const isActive = section.key === activeSectionKey;
              return (
                <button
                  key={section.key}
                  disabled={!isSectionSelectable(section.key) && !hasSubmitted}
                  onClick={() => (isSectionSelectable(section.key) || hasSubmitted) && onSelectSection?.(section.key)}
                  className={`px-2 h-[20px] flex items-center justify-center rounded transition-all text-[10px] font-bold ${isActive
                    ? theme.active + " border"
                    : (isSectionSelectable(section.key) || hasSubmitted)
                      ? "text-gray-500 hover:bg-gray-100 border border-transparent"
                      : "text-gray-300 cursor-not-allowed"
                    }`}
                >
                  {section.label.substring(0, 3).toUpperCase()}
                </button>
              );
            })}
          </div>
        )}

        {/* Part tabs (EX. 4, EX. 5 or Part 1, Part 2) */}
        {groups.length > 0 && (
          <div className="flex items-center gap-1 shrink-0 border-r border-gray-200 pr-2 h-full">
            {groups.map(group => {
              const isActive = activeGroupId === group.id;
              return (
                <button
                  key={group.id}
                  onClick={() => {
                    setActiveGroupId(group.id);
                    if (group.items?.length > 0 && onSelectQuestion && (!isCurrentSectionSubmitted || hasSubmitted)) {
                      onSelectQuestion(currentSection.key, group.items[0]);
                    }
                  }}
                  className={`px-2 h-[20px] flex items-center justify-center rounded transition-colors text-[10px] font-semibold border ${isActive
                    ? currentTheme.active
                    : "text-gray-500 hover:bg-gray-100 border-transparent"
                    }`}
                  title={group.label}
                >
                  {group.label}
                </button>
              );
            })}
          </div>
        )}

        {/* Question numbers */}
        <div className="flex items-center gap-1 shrink-0 h-full">
          {visibleItems.map((item) => {
            const displayNumber = item?.meta?.slotNumber ?? item?.label ?? item?.order ?? "";
            const stateClass = getStateClass(item);
            return (
              <button
                key={item.key || `${item.id}-${item?.meta?.slotIndex || 'main'}`}
                onClick={() => (!isCurrentSectionSubmitted || hasSubmitted) && onSelectQuestion?.(currentSection?.key, item)}
                className={`min-w-[18px] h-[18px] px-1 flex items-center justify-center rounded text-[10px] transition-all duration-200 ${stateClass} ${isCurrentSectionSubmitted && !hasSubmitted ? 'opacity-50 cursor-not-allowed' : ''}`}
                title={`Question ${displayNumber}`}
              >
                {displayNumber}
              </button>
            );
          })}
        </div>
      </div>

      {/* Right: Nav arrows + Time + Submit */}
      <div className="flex items-center gap-3 bg-white pl-3 border-l border-gray-100 shrink-0 h-full">
        {onToggleFont && (
          <button
            onClick={onToggleFont}
            className="flex h-[20px] w-[20px] items-center justify-center rounded text-gray-500 hover:bg-gray-100 transition relative"
            title={`Toggle Font Size (Current Level: ${fontLevel})`}
          >
            <span className="text-[12px] font-bold">Aa</span>
          </button>
        )}
        {groups.length > 0 && (
          <div className="flex items-center gap-1">
            <button onClick={() => handleNav('prev')} className="w-5 h-5 flex items-center justify-center rounded text-gray-500 hover:bg-gray-100 transition" title="Previous part">
              <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M15 18l-6-6 6-6" /></svg>
            </button>
            <button onClick={() => handleNav('next')} className="w-5 h-5 flex items-center justify-center rounded text-gray-500 hover:bg-gray-100 transition" title="Next part">
              <svg className="w-3.5 h-3.5" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M9 18l6-6-6-6" /></svg>
            </button>
          </div>
        )}
        {!hasSubmitted && Number.isFinite(timeLeft) && timeLeft > 0 && (
          <div className="flex items-center gap-1.5 text-gray-600">
            <span className={`font-mono font-bold leading-none ${timeLeft <= 60 ? "text-red-500" : "text-gray-800"}`} style={{ fontSize: '12px' }}>
              {formattedTime}
            </span>
          </div>
        )}
        {showSubmitButton && (typeof onSubmit === "function" || (isRegradeMode && typeof onRegrade === "function")) && (
          <button
            onClick={() => {
              if (isRegradeMode && typeof onRegrade === "function") { onRegrade(); return; }
              if (submitDisabled) { alert(isSubmitting ? "Submitting..." : "Action Disabled"); return; }
              onSubmit?.(activeSectionKey);
            }}
            disabled={isRegradeMode ? isSavingRegrade : submitDisabled}
            style={isRegradeMode ? { backgroundColor: hasPendingKeyEdits ? '#f97316' : '#3b82f6', color: '#fff' } : undefined}
            className={`h-[20px] px-4 rounded font-bold text-[10px] uppercase tracking-wide active:scale-95 transition-all disabled:opacity-50 disabled:cursor-not-allowed min-w-[80px] ${isRegradeMode ? "" : "bg-orange-500 text-white hover:bg-orange-600"}`}
          >
            {isRegradeMode
              ? (isSavingRegrade ? "Saving..." : (hasPendingKeyEdits ? "Save & Regrade" : "Regrade"))
              : isSubmitting ? "Submitting..." : (isPreviewMode && hasSubmitted ? "Submitted" : (reviewMode && !isPreviewMode ? "Recorded" : "Submit"))}
          </button>
        )}
      </div>
    </div>
  );
};

function formatTime(totalSeconds) {
  const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, "0");
  const seconds = (totalSeconds % 60).toString().padStart(2, "0");
  return `${minutes}:${seconds}`;
}

export default QuestionsNavigation;
