import React from "react";
import FillInBlankPreview from "./FillInBlank/Preview";
import InlineBlankPreview from "./InlineBlank/Preview";
import MultipleChoicePreview from "./MultipleChoice/Preview";
import CheckboxPreview from "./Checkbox/Preview";
import MatchingHeadingsPreview from "./MatchingHeadings/Preview";
import WhichTruePreview from "./WhichTrue/Preview";
import TrueFalseNotGivenPreview from "./TrueFalseNotGiven/Preview";
import CompleteSentencesPreview from "./CompleteSentences/Preview";
import GapFillingPreview from "./GapFilling/Preview";
import GapFillTablePreview from "./GapFillTable/Preview";
import CorrectionPreview from "./Correction/Preview";
import UnderlinePreview from "./Underline/Preview";
import DefaultPreview from "./shared/DefaultPreview";

const previewMap = {
  "fill-in-the-blanks": FillInBlankPreview,
  "inline-blank": InlineBlankPreview,
  "multiple-choice": MultipleChoicePreview,
  checkbox: CheckboxPreview,
  "matching-headings": MatchingHeadingsPreview,
  "which-true": WhichTruePreview,
  "true-false-not-given": TrueFalseNotGivenPreview,
  "complete-sentences": CompleteSentencesPreview,
  "gap-filling": GapFillingPreview,
  "gap-fill-table": GapFillTablePreview,
  "correction": CorrectionPreview,
  "underline": UnderlinePreview,
  // Aliases for question types used in exam data
  "yes-no-not-given": TrueFalseNotGivenPreview,
  "notes-completion": GapFillingPreview,
  "short-answer": GapFillingPreview,
  "summary-completion": GapFillingPreview,
};

const QuestionTypePreviewRouter = (props) => {
  const type = props?.question?.type || "fill-in-the-blanks";
  const PreviewComponent = previewMap[type] || DefaultPreview;
  return <PreviewComponent {...props} />;
};

export default QuestionTypePreviewRouter;
