export const isAnswerEmpty = (value) => {
  if (value === null || value === undefined) return true;
  if (Array.isArray(value)) return value.length === 0;
  if (typeof value === "string") return value.trim() === "";
  return false;
};

export const checkIncompleteReadingPassages = (examContent, answers) => {
  if (!examContent?.reading?.passages || examContent.reading.passages.length <= 1) {
    return [];
  }

  const readingAnswers = answers.reading || {};
  const incomplete = [];

  examContent.reading.passages.forEach((passage) => {
    if (!passage.questions || passage.questions.length === 0) return;

    let answeredCount = 0;
    passage.questions.forEach((question) => {
      const userAnswer = readingAnswers[question.id];
      const isEmpty = userAnswer === undefined || userAnswer === null ||
        (Array.isArray(userAnswer) && userAnswer.length === 0) ||
        userAnswer === "";
      if (!isEmpty) {
        answeredCount++;
      }
    });

    if (answeredCount < passage.questions.length) {
      incomplete.push({
        id: passage.id,
        title: passage.title || `Passage ${examContent.reading.passages.indexOf(passage) + 1}`,
        questionsAnswered: answeredCount,
        totalQuestions: passage.questions.length,
      });
    }
  });

  return incomplete;
};

export const findIncompleteQuestions = (sectionKey, examContent, answers) => {
  const result = [];
  const sectionData = examContent?.[sectionKey];
  const sectionAnswers = answers?.[sectionKey] || {};
  if (!sectionData) return result;
  const order = { current: 1 };
  try { console.debug('🧐 checkIncompleteQuestions', { sectionKey, sectionDataKeys: Object.keys(sectionData || {}), sectionAnswers }); } catch (e) { }

  const pushEntry = (question, slotIndex = 0) => {
    result.push({
      id: question.id,
      label: `Question ${order.current}`,
      meta: { slotIndex },
    });
  };

  const processQuestion = (question) => {
    if (!question) return;
    // Handle grouped sub-questions (e.g., grammar multi-blank)
    if (Array.isArray(question.subQuestions) && question.subQuestions.length > 0) {
      const ans = sectionAnswers[question.id];
      question.subQuestions.forEach((sub, idx) => {
        const subVal = Array.isArray(ans) ? ans[idx] : ans?.[sub?.id];
        if (isAnswerEmpty(subVal)) {
          pushEntry(question, idx);
        }
        order.current += 1;
      });
      return;
    }

    const val = sectionAnswers[question.id];
    if (isAnswerEmpty(val)) {
      pushEntry(question, 0);
    }
    order.current += 1;
  };

  const processList = (list) => {
    if (!Array.isArray(list)) return;
    list.forEach(processQuestion);
  };

  // Listening groups
  if (Array.isArray(sectionData.questionGroups)) {
    sectionData.questionGroups.forEach((group) => {
      if (!group?.questions) return;
      processList(group.questions);
    });
    return result;
  }

  // Standalone questions array
  processList(sectionData.questions);

  // Groups (custom)
  if (Array.isArray(sectionData.groups)) {
    sectionData.groups.forEach((group) => {
      if (!group?.questions) return;
      processList(group.questions);
    });
  }

  // Reading passages
  if (Array.isArray(sectionData.passages)) {
    sectionData.passages.forEach((passage) => {
      if (!passage?.questions) return;
      processList(passage.questions);
    });
  }

  // Writing tasks
  if (Array.isArray(sectionData.tasks)) {
    sectionData.tasks.forEach((task, index) => {
      // Check essay content
      const essayVal = sectionAnswers[task.id];
      const taskLabel = task.title ? task.title.replace(/<[^>]*>?/gm, "") : `Task ${index + 1}`;

      if (isAnswerEmpty(essayVal)) {
        result.push({
          id: task.id,
          label: taskLabel,
          meta: { isWriting: true },
        });
      }

      // Check topic selection if required
      if (task.requireTopicSelection) {
        const topicVal = sectionAnswers[`${task.id}_topic`];
        if (isAnswerEmpty(topicVal)) {
          result.push({
            id: `${task.id}_topic`,
            label: `${taskLabel} (Topic Selection)`,
            meta: { isTopic: true },
          });
        }
      }
    });
  }

  return result.filter((item, index, self) =>
    index === self.findIndex((t) => t.id === item.id)
  );
};
