import { useState, useEffect, useRef } from "react";

const useReadyPopup = (sectionKey, reviewMode, audioPlayerRef, onReadyPopupChange) => {
  const readyPopupKey = `listening_ready_${sectionKey}`;
  const volumeCheckAudioRef = useRef(null);

  const [showReadyPopup, setShowReadyPopup] = useState(() => {
    if (reviewMode) return false;
    return sessionStorage.getItem(readyPopupKey) !== "started";
  });

  const [isVolumeCheckPlaying, setIsVolumeCheckPlaying] = useState(false);

  // Clear ready popup state on page reload (F5) so it shows again
  useEffect(() => {
    const handleUnload = () => {
      sessionStorage.removeItem(readyPopupKey);
    };
    window.addEventListener("beforeunload", handleUnload);
    return () => window.removeEventListener("beforeunload", handleUnload);
  }, [readyPopupKey]);

  // Notify parent when Ready popup visibility changes (for timer pause)
  useEffect(() => {
    onReadyPopupChange?.(showReadyPopup);
  }, [showReadyPopup, onReadyPopupChange]);

  // Stop volume check audio when entering review mode
  useEffect(() => {
    if (reviewMode) {
      if (volumeCheckAudioRef.current) {
        try {
          volumeCheckAudioRef.current.pause();
        } catch (e) {}
        setIsVolumeCheckPlaying(false);
      }
    }
  }, [reviewMode]);

  const handleReadyClick = () => {
    if (volumeCheckAudioRef.current) {
      try {
        volumeCheckAudioRef.current.pause();
        volumeCheckAudioRef.current.currentTime = 0;
      } catch (e) {}
    }
    setIsVolumeCheckPlaying(false);
    setShowReadyPopup(false);
    sessionStorage.setItem(readyPopupKey, "started");
    // Auto-play Part 1 audio after a short delay
    setTimeout(() => {
      try {
        const audio = audioPlayerRef.current?.audio?.current;
        if (audio) {
          audio.play().catch((err) => {
            console.warn("Auto-play after ready failed:", err);
          });
        }
      } catch (e) {
        console.warn("Auto-play error:", e);
      }
    }, 300);
  };

  const handleVolumeCheck = async () => {
    try {
      if (!volumeCheckAudioRef.current) {
        volumeCheckAudioRef.current = new Audio(
          "/assets/audio/SoundCheckWelcome.mp3"
        );
        volumeCheckAudioRef.current.addEventListener("ended", () =>
          setIsVolumeCheckPlaying(false)
        );
      }
      if (isVolumeCheckPlaying) {
        volumeCheckAudioRef.current.pause();
        volumeCheckAudioRef.current.currentTime = 0;
        setIsVolumeCheckPlaying(false);
      } else {
        await volumeCheckAudioRef.current.play();
        setIsVolumeCheckPlaying(true);
      }
    } catch (err) {
      console.warn("Unable to play volume check audio:", err);
      setIsVolumeCheckPlaying(false);
    }
  };

  return {
    showReadyPopup,
    isVolumeCheckPlaying,
    handleReadyClick,
    handleVolumeCheck,
  };
};

export default useReadyPopup;
