import { useEffect, useRef, useState } from 'react';
// Note: isSkillTimedMode is now passed in from index.jsx (single source of truth)
// rather than computed internally. This ensures the same value is used by both
// useSkillTimer and useSectionNavigation.
import { parseTimeAllottedToSeconds } from '../utils/timeParser';

const DEFAULT_SECTION_DURATION = '15 minutes';

/**
 * useSkillTimer
 *
 * Manages the per-skill countdown timer for timed exam mode.
 *
 * ── What this hook owns ──
 *   • isSkillTimedMode  — received as prop from index.jsx (single source of truth)
 *   • currentSkillIndex — which section tab is currently active
 *   • skillTimeLeftSeconds — countdown value for the running section
 *   • skillTimerRef     — the setInterval ref (also read by auto-advance in index.jsx)
 *   • autoAdvanceRef    — re-entrancy guard (also read by submitted-sections effect)
 *   • startSkillTimerAtIndex / clearExistingSkillTimer / getSkillDurationSeconds
 *   • Sync effects: keep currentSkillIndex aligned with activeSection
 *   • Pause/resume: freeze timer during the Listening "Ready?" popup
 *   • Re-init: recover a 0-second timer when sectionTabs arrives late from Firestore
 *
 * ── What stays in index.jsx ──
 *   • Auto-advance at skillTimeLeftSeconds === 0
 *     (needs gradeSection, setActiveSection, handleConfirmSubmit — too many callers)
 *   • Submitted-sections advance effect
 *     (driven by submission flow state, not timer state)
 *
 * ── Bug history (pre-isolation) ──
 *   • Ghost-section: sessionStorage timer keys survived reload → wrong section, no answers
 *   • Zero-timer: exam data arrived late → timer initialized to 0, never fired
 *   • Double-advance: two unguarded effects raced on section submit
 *   All three bugs lived in the auto-advance logic, not in what's here.
 */
export function useSkillTimer({
  isSkillTimedMode,
  sectionTabs,
  activeSection,
  isListeningReadyPopup,
  hasSubmitted,
  examContent,
}) {
  const [currentSkillIndex, setCurrentSkillIndex] = useState(0);
  const [skillTimeLeftSeconds, setSkillTimeLeftSeconds] = useState(0);

  const skillTimerRef = useRef(null);
  const savedTimeRef = useRef(null);
  // autoAdvanceRef: re-entrancy guard used by the submitted-sections effect in index.jsx
  const autoAdvanceRef = useRef(false);
  // skillTimeLeftRef: ref mirror of skillTimeLeftSeconds.
  // Refs are always live (never stale), so bail-out guards in index.jsx
  // can read this instead of the state value without needing it in a dep array.
  const skillTimeLeftRef = useRef(0);
  // skillEndAtRef: wall-clock deadline (Date.now() ms) the countdown is racing to.
  // The interval recomputes remaining = endAt - now on every tick instead of
  // subtracting 1 per tick. This makes the timer ANTI-CHEAT / drift-proof:
  // background-tab throttling and device sleep slow or freeze setInterval, but
  // each tick (and each visibility/focus snap) reads the real clock, so the
  // student keeps losing time while the tab is hidden and the display snaps to
  // the true remaining value the moment a tick fires. null when no timer is armed.
  const skillEndAtRef = useRef(null);

  // ── Helpers ──────────────────────────────────────────────────────────────────

  const clearExistingSkillTimer = () => {
    if (skillTimerRef.current) {
      clearInterval(skillTimerRef.current);
      skillTimerRef.current = null;
    }
  };

  // Remaining whole seconds until the wall-clock deadline (never negative).
  const computeRemaining = (endAt) =>
    endAt == null ? 0 : Math.max(0, Math.round((endAt - Date.now()) / 1000));

  // Arm a deadline-based countdown: set the wall-clock target and start an
  // interval that, on every tick, derives the remaining time from the real
  // clock rather than decrementing a counter. A throttled/frozen background tab
  // therefore self-corrects — when a tick finally fires it snaps to the true
  // value. Shared by the initial start and the Listening resume path.
  //
  // Deliberately does NOT clear the interval when it reaches 0: the auto-advance
  // effect in index.jsx needs skillTimerRef.current to stay non-null so it can
  // fire, and it owns teardown/advance. (Same contract as the pre-deadline code.)
  const startCountdownInterval = (endAt) => {
    skillEndAtRef.current = endAt;
    skillTimerRef.current = setInterval(() => {
      const next = computeRemaining(endAt);
      skillTimeLeftRef.current = next; // keep ref in sync on every tick
      setSkillTimeLeftSeconds(next);
    }, 1000);
  };

  const getSkillDurationSeconds = (idx) => {
    const tab = sectionTabs?.[idx];
    if (!tab) return 0;
    const fromTab = tab?.data?.timeAllotted;
    const fromExam = tab.key && examContent?.[tab.key]?.timeAllotted;
    const durationStr = fromTab || fromExam || DEFAULT_SECTION_DURATION;
    const seconds = parseTimeAllottedToSeconds(durationStr);
    if (!fromTab && !fromExam) {
      console.warn(
        '⏱️ [Duration] idx', idx, 'key:', tab.key,
        '— missing timeAllotted, using default:', DEFAULT_SECTION_DURATION
      );
    }
    return seconds;
  };

  const startSkillTimerAtIndex = (idx, seconds) => {
    clearExistingSkillTimer();
    setCurrentSkillIndex(idx);
    skillTimeLeftRef.current = seconds;   // keep ref in sync immediately (before state flush)
    setSkillTimeLeftSeconds(seconds);
    console.log('⏱️ [SkillTimer-Start] idx:', idx, 'seconds:', seconds);
    if (seconds > 0) {
      startCountdownInterval(Date.now() + seconds * 1000);
    } else {
      skillEndAtRef.current = Date.now(); // already expired → pause reads 0
      // Sentinel: keep ref non-null so the auto-advance effect in index.jsx can
      // fire on the next render. Without this, restore-with-zero leaves the
      // timer permanently stuck — auto-advance bails on `!skillTimerRef.current`.
      // The setTimeout body is intentionally a no-op; it never fires anything,
      // it just gives the ref an opaque truthy handle. clearExistingSkillTimer
      // calls clearInterval, which is a no-op on a setTimeout handle in browsers
      // (the underlying timer system is unified) — so it safely tears down.
      console.warn('⏱️ [SkillTimer-Sentinel] seconds <= 0 — installing zero-second sentinel so auto-advance can fire. idx:', idx);
      skillTimerRef.current = setTimeout(() => {}, 0);
    }
  };

  // ── Sync: activeSection → currentSkillIndex (skill-timed mode) ───────────────
  // When the active section changes while the timer is running, restart the timer
  // for the new section so the countdown reflects the correct skill duration.
  useEffect(() => {
    if (!isSkillTimedMode) return undefined;
    if (!activeSection) return undefined;
    if (!Array.isArray(sectionTabs) || sectionTabs.length === 0) return undefined;
    const idx = sectionTabs.findIndex((t) => t.key === activeSection);
    if (idx < 0) return undefined;
    if (idx !== currentSkillIndex) {
      const duration = getSkillDurationSeconds(idx) || 0;
      console.log(
        '⏰ [Sync] activeSection changed → idx', idx, 'key:', sectionTabs[idx]?.key,
        '!= currentSkillIndex', currentSkillIndex, '→ restarting with', duration, 's'
      );
      startSkillTimerAtIndex(idx, duration);
    }
    return undefined;
  }, [activeSection, sectionTabs, isSkillTimedMode, currentSkillIndex]);

  // ── Sync: activeSection → currentSkillIndex (non-skill-timed mode) ───────────
  // No timer running — just keep the index aligned for display purposes.
  useEffect(() => {
    if (isSkillTimedMode) return undefined;
    if (!activeSection) return undefined;
    if (!Array.isArray(sectionTabs) || sectionTabs.length === 0) return undefined;
    const idx = sectionTabs.findIndex((t) => t.key === activeSection);
    if (idx < 0) return undefined;
    if (idx !== currentSkillIndex) {
      setCurrentSkillIndex(idx);
    }
    return undefined;
  }, [activeSection, sectionTabs, isSkillTimedMode, currentSkillIndex]);

  // ── Pause/resume: Listening "Ready?" popup ────────────────────────────────────
  // When the popup appears the student hasn't started listening yet — freeze the
  // countdown so they don't lose time before the audio begins.
  //
  // skillTimeLeftRef.current is used instead of skillTimeLeftSeconds (state) because
  // this effect fires on isListeningReadyPopup change — at that moment the state
  // snapshot could be one render stale. The ref is always the live value.
  useEffect(() => {
    if (!isSkillTimedMode) return;
    console.log(
      '🎧 [Listening pause/resume] isListeningReadyPopup:', isListeningReadyPopup,
      'savedTimeRef:', savedTimeRef.current,
      'skillTimerRef:', skillTimerRef.current,
      'skillTimeLeftRef:', skillTimeLeftRef.current
    );
    if (isListeningReadyPopup) {
      // Pause: snapshot remaining from the live deadline (more accurate than the
      // tick-mirrored ref, which can be up to ~1s stale) and clear the interval.
      const paused = computeRemaining(skillEndAtRef.current);
      savedTimeRef.current = paused;
      clearExistingSkillTimer();
      console.log('🎧 [Listening] PAUSED. Saved time:', paused);
    } else if (savedTimeRef.current !== null && !skillTimerRef.current) {
      // Resume: re-arm a fresh deadline from the saved remaining time. (Pausing
      // is the one place we legitimately stop the wall-clock — the student
      // hasn't started listening yet, so this isn't a cheat window.)
      const resumeTime = savedTimeRef.current;
      savedTimeRef.current = null;
      console.log('🎧 [Listening] RESUMING with time:', resumeTime);
      if (resumeTime > 0) {
        startCountdownInterval(Date.now() + resumeTime * 1000);
      } else {
        // Sentinel: timer paused while at 0 (e.g. student opened the Ready popup
        // at the moment the timer expired). Keep ref non-null so auto-advance
        // can fire instead of silently dying.
        console.warn('🎧 [Listening-Resume-Sentinel] resumeTime is 0 — installing zero-second sentinel so auto-advance can fire.');
        skillTimerRef.current = setTimeout(() => {}, 0);
      }
    }
  }, [isListeningReadyPopup, isSkillTimedMode]);

  // ── Anti-cheat catch-up: snap to the real clock on visibility/focus ───────────
  // Background tabs throttle setInterval (and device sleep freezes it), so a tab
  // that was hidden for a while comes back with a stale displayed value until the
  // next tick fires. Recompute immediately from the wall-clock deadline the moment
  // the tab becomes visible or regains focus. Combined with the deadline-based
  // ticks, this means time lost while hidden is fully charged to the student — and
  // a section that expired off-screen drops to 0 at once so index.jsx auto-advance
  // fires without waiting on a throttled tick.
  useEffect(() => {
    if (!isSkillTimedMode) return undefined;
    const snap = () => {
      if (!skillTimerRef.current) return;        // no live timer armed
      if (savedTimeRef.current !== null) return; // paused for the Listening popup — leave frozen
      const next = computeRemaining(skillEndAtRef.current);
      skillTimeLeftRef.current = next;
      setSkillTimeLeftSeconds(next);
    };
    document.addEventListener('visibilitychange', snap);
    window.addEventListener('focus', snap);
    return () => {
      document.removeEventListener('visibilitychange', snap);
      window.removeEventListener('focus', snap);
    };
  }, [isSkillTimedMode]);

  // ── Re-init: LIVES IN index.jsx (AFTER auto-advance) ────────────────────────
  // Moving it here caused a race condition: re-init sets skillTimerRef.current
  // (immediate, it's a ref) but skillTimeLeftSeconds stays 0 until the next
  // render. Auto-advance, running after hook effects, saw non-null ref + 0
  // seconds and thought the timer expired → skipped the section.
  //
  // Keeping re-init AFTER auto-advance in index.jsx preserves the original
  // effect ordering that avoids this race.

  return {
    currentSkillIndex,
    skillTimeLeftSeconds,
    skillTimerRef,          // read by auto-advance effect in index.jsx
    skillTimeLeftRef,       // live ref mirror — use for bail-out guards (never stale)
    autoAdvanceRef,         // re-entrancy guard for submitted-sections effect
    startSkillTimerAtIndex,
    clearExistingSkillTimer,
    getSkillDurationSeconds,
  };
}
