import React, { useState, useEffect } from "react";

const PendingSubmissionBanner = () => {
  const [pendingExams, setPendingExams] = useState([]);
  const [isModalOpen, setIsModalOpen] = useState(false);

  useEffect(() => {
    try {
      const keys = Object.keys(localStorage || {});
      const pending = keys
        .filter((k) => k.startsWith("weaver_") && k.endsWith("_pending_submission"))
        .map((key) => {
          try {
            const raw = localStorage.getItem(key);
            if (!raw) return null;
            const payload = JSON.parse(raw);
            if (payload?.synced) return null;

            // Prefer examCode from payload (accurate), fall back to key extraction
            const examCode = payload?.examCode || key
              .replace(/^weaver_/, "")
              .replace(/_pending_submission$/, "");

            return {
              key,
              examCode,
              savedAt: payload?.syncedAt || payload?._startedAt || null,
              studentName: payload?.studentName || payload?.candidate?.fullName || null,
              rawCandidate: payload?.candidate || null,
            };
          } catch {
            return null;
          }
        })
        .filter(Boolean);

      if (pending.length > 0) {
        setPendingExams(pending);
        setIsModalOpen(true);
      }
    } catch {
      // localStorage access failed
    }
  }, []);

  const handleResume = (exam) => {
    try {
      // Restore candidate profile from the pending submission so the exam page
      // doesn't redirect us back here for missing profile
      if (exam.rawCandidate) {
        localStorage.setItem('weaver:candidateProfile', JSON.stringify(exam.rawCandidate));
      }
      localStorage.setItem('weaver:pendingExamCode', exam.examCode);
      localStorage.setItem('weaver:lastExamCode', exam.examCode);
      // Flag for useExamRouting to bypass ALL redirect guards
      sessionStorage.setItem('weaver:resumeFromBanner', 'true');
    } catch {}
    window.location.href = `/exam/${exam.examCode}`;
  };

  const handleDismiss = (key) => {
    try {
      localStorage.removeItem(key);
      setPendingExams((prev) => prev.filter((e) => e.key !== key));
      if (pendingExams.length <= 1) {
        setIsModalOpen(false);
      }
    } catch {
      // ignore
    }
  };

  if (!isModalOpen || pendingExams.length === 0) return null;

  return (
    <div
      role="dialog"
      aria-modal="true"
      className="fixed inset-0 z-banner-top flex items-center justify-center p-4"
    >
      {/* Backdrop with pulse animation */}
      <div className="absolute inset-0 bg-red-900/80 backdrop-blur-sm animate-pulse" />

      {/* Modal */}
      <div className="relative w-full max-w-2xl rounded-2xl bg-white shadow-2xl overflow-hidden">
        {/* Red warning header */}
        <div className="bg-red-600 px-6 py-4 flex items-center gap-3">
          <div className="flex h-12 w-12 items-center justify-center rounded-full bg-red-700 shrink-0">
            <svg className="h-7 w-7 text-white animate-bounce" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth="2.5">
              <path strokeLinecap="round" strokeLinejoin="round" d="M12 9v2m0 4h.01M10.29 3.86l-7.4 12.8A1 1 0 003.75 18h16.5a1 1 0 00.86-1.34l-7.4-12.8a1 1 0 00-1.72 0z" />
            </svg>
          </div>
          <div>
            <h2 className="text-xl font-bold text-white uppercase tracking-wide">
              Cảnh báo khẩn
            </h2>
            <p className="text-sm text-red-100">
              Phát hiện bài làm chưa được nộp
            </p>
          </div>
        </div>

        {/* Body */}
        <div className="px-6 py-5">
          <div className="rounded-lg bg-red-50 border border-red-200 px-4 py-3 mb-5">
            <p className="text-base font-semibold text-red-800">
              PHÁT HIỆN BÀI LÀM CHƯA ĐƯỢC NỘP, VUI LÒNG TIẾP TỤC VÀO LÀM BÀI THI ĐỂ BẢO LƯU KẾT QUẢ
            </p>
            <p className="mt-1 text-sm text-red-600">
              Your exam submission was not completed. Please return to the exam to finish submitting your answers.
            </p>
          </div>

          {/* List of pending exams */}
          <div className="space-y-3">
            {pendingExams.map((exam) => (
              <div
                key={exam.key}
                className="flex flex-col sm:flex-row sm:items-center justify-between gap-3 rounded-lg border border-gray-200 bg-gray-50 px-4 py-3"
              >
                <div className="flex-1 min-w-0">
                  <p className="text-sm font-semibold text-gray-900 truncate">
                    Mã bài thi: <span className="text-blue-700">{exam.examCode}</span>
                  </p>
                  {exam.studentName && (
                    <p className="text-xs text-gray-500 mt-0.5">
                      Thí sinh: {exam.studentName}
                    </p>
                  )}
                </div>
                <div className="flex items-center gap-2 shrink-0">
                  <button
                    onClick={() => handleResume(exam)}
                    className="rounded-lg bg-red-600 px-5 py-2.5 text-sm font-bold text-white transition hover:bg-red-700 focus:outline-none focus:ring-2 focus:ring-red-300 shadow-lg shadow-red-600/30 animate-pulse"
                  >
                    Tiếp tục nộp bài
                  </button>
                  <button
                    onClick={() => handleDismiss(exam.key)}
                    className="rounded-lg border border-gray-300 bg-white px-3 py-2.5 text-xs font-medium text-gray-500 transition hover:bg-gray-100 focus:outline-none focus:ring-2 focus:ring-gray-200"
                    title="Xoá bản nháp này (không khuyến nghị)"
                  >
                    Bỏ qua
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
};

export default PendingSubmissionBanner;
