/**
 * Strips HTML tags from a string and normalizes whitespace.
 */
const stripTags = (s) =>
  typeof s === 'string' ? s.replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim() : '';

/**
 * Cleans writing answers that are merely the prompt text (or identical to it).
 * Also attempts a DOM fallback to read the current editor content directly
 * when the state-based answer is empty or matches the prompt.
 *
 * Mutates and returns `clonedAnswers`.
 */
export const cleanWritingAnswers = (clonedAnswers, examContent) => {
  if (!clonedAnswers) return clonedAnswers;
  const writingTasks = examContent?.writing?.tasks || [];
  if (writingTasks.length === 0) return clonedAnswers;

  try {
    writingTasks.forEach((task) => {
      const id = task.id;
      const promptText = stripTags(task.prompt || '');
      const val = stripTags(clonedAnswers?.writing?.[id] || '');
      if (val && promptText && val === promptText) {
        if (clonedAnswers?.writing) clonedAnswers.writing[id] = '';
      }
    });

    // DOM fallback: if any writing answer is empty, try to read the current editor content directly
    try {
      writingTasks.forEach((task) => {
        const id = task.id;
        const current = (clonedAnswers?.writing && clonedAnswers.writing[id]) || '';
        const promptText = stripTags(task.prompt || '');
        if (!current || (promptText && stripTags(current) === promptText)) {
          try {
            const escId = `question-${'writing'}-${id}`;
            const container = document.getElementById(escId);
            if (container) {
              const editorEl = container.querySelector('.ql-editor, textarea');
              if (editorEl) {
                const val = (editorEl.tagName === 'TEXTAREA') ? (editorEl.value || '') : (editorEl.innerHTML || '');
                const cleaned = String(val || '').replace(/^<p>(?:<br>)*<\/p>$/i, '').trim();
                if (cleaned && stripTags(cleaned) !== promptText) {
                  if (!clonedAnswers.writing) clonedAnswers.writing = {};
                  clonedAnswers.writing[id] = val;
                }
              }
            }
          } catch (e) { /* fallback ignore */ }
        }
      });
    } catch (e) { /* ignore */ }
  } catch (e) { /* ignore errors in cleanup */ }

  return clonedAnswers;
};
