import React from "react";
import ReactQuill from "react-quill";
import "react-quill/dist/quill.snow.css";
import { generateId } from "../../../../utils/question/idUtils";

const toolbarModules = {
  toolbar: [
    [{ header: [1, 2, false] }],
    ["bold", "italic", "underline"],
    [{ list: "ordered" }, { list: "bullet" }],
    ["link"],
    ["clean"],
  ],
};

const shallowEqual = (objectA, objectB) => {
  if (objectA === objectB) return true;
  if (!objectA || !objectB) return false;

  const keysA = Object.keys(objectA);
  const keysB = Object.keys(objectB);
  if (keysA.length !== keysB.length) return false;

  for (const key of keysA) {
    if (objectA[key] !== objectB[key]) {
      return false;
    }
  }
  return true;
};

function WritingBuilder({ data, onChange }) {
  const writing = {
    tasks: [],
    ...data,
  };

  const updateTasks = (updater) => {
    const currentTasks = writing.tasks || [];
    const nextTasks =
      typeof updater === "function" ? updater(currentTasks) : updater;

    if (!Array.isArray(nextTasks)) {
      return;
    }

    const sameLength = currentTasks.length === nextTasks.length;
    if (
      sameLength &&
      currentTasks.every((task, index) => task === nextTasks[index])
    ) {
      return;
    }

    onChange({
      ...writing,
      tasks: nextTasks,
    });
  };

  const handleTaskChange = (index, updates) => {
    const currentTask = writing.tasks[index];
    if (!currentTask) return;

    const nextTask = { ...currentTask, ...updates };
    if (shallowEqual(currentTask, nextTask)) return;

    updateTasks((tasks) =>
      tasks.map((task, idx) => (idx === index ? nextTask : task))
    );
  };

  const handleAddTask = () => {
    updateTasks((tasks) => [
      ...tasks,
      {
        id: generateId("W"),
        title: `Task ${tasks.length + 1}`,
        prompt: "",
        minimumWords: tasks.length === 0 ? 150 : 250,
        imageUrl: "",
        imageFile: null,
      },
    ]);
  };

  const handleRemoveTask = (index) => {
    updateTasks((tasks) => tasks.filter((_, idx) => idx !== index));
  };

  const handleImageSelect = (index, file) => {
    if (!file) return;
    const currentUrl = writing.tasks?.[index]?.imageUrl;
    if (currentUrl && typeof currentUrl === "string" && currentUrl.startsWith("blob:")) {
      try {
        URL.revokeObjectURL(currentUrl);
      } catch (error) {
        // ignore revoke errors
      }
    }
    const previewUrl =
      typeof URL !== "undefined" ? URL.createObjectURL(file) : "";
    handleTaskChange(index, {
      imageFile: file,
      imageUrl: previewUrl,
    });
  };

  const handleSectionChange = (field, value) => {
    onChange({
      ...writing,
      [field]: value,
    });
  };

  return (
    <div className="space-y-8">
      <div className="space-y-4 rounded-2xl border border-slate-200 bg-slate-50 p-5">
        <h3 className="text-lg font-semibold text-slate-900">
          Writing Section Settings
        </h3>

        <div className="grid gap-4 md:grid-cols-2">
          <div>
            <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              Title
            </label>
            <input
              type="text"
              value={writing.title || ""}
              onChange={(event) =>
                handleSectionChange("title", event.target.value)
              }
              placeholder="Writing Skills"
              className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            />
          </div>

          <div>
            <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              Time Allotted
            </label>
            <input
              type="text"
              value={writing.timeAllotted || ""}
              onChange={(event) =>
                handleSectionChange("timeAllotted", event.target.value)
              }
              placeholder="15 minutes"
              className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            />
          </div>
        </div>
      </div>

      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold text-slate-900">
          Writing tasks
        </h3>
        <button
          type="button"
          onClick={handleAddTask}
          className="rounded-lg border border-blue-200 px-3 py-1.5 text-sm font-medium text-blue-700 transition hover:bg-blue-50"
        >
          + Add task
        </button>
      </div>

      <div className="space-y-6">
        {writing.tasks?.map((task, index) => (
          <div
            key={task.id}
            data-question-id={task.id}
            className="space-y-4 rounded-2xl border border-slate-200 bg-slate-50 p-5"
          >
            <div className="flex items-start justify-between gap-3">
              <input
                type="text"
                value={task.title}
                onChange={(event) =>
                  handleTaskChange(index, { title: event.target.value })
                }
                className="flex-1 rounded-xl border border-slate-200 px-4 py-2 text-sm font-semibold text-slate-800 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              />
              <button
                type="button"
                onClick={() => handleRemoveTask(index)}
                className="text-xs font-semibold text-rose-500 hover:text-rose-600"
              >
                Remove
              </button>
            </div>

            <div className="grid gap-4">
              <div>
                <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Prompt (e.g., "Write about the following topic:")
                </label>
                <input
                  type="text"
                  value={task.prompt || ""}
                  onChange={(event) =>
                    handleTaskChange(index, { prompt: event.target.value })
                  }
                  className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                />
              </div>

              <div>
                <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Topic Title
                </label>
                <textarea
                  value={task.topicTitle || ""}
                  onChange={(event) =>
                    handleTaskChange(index, { topicTitle: event.target.value })
                  }
                  rows="3"
                  className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                  placeholder="Plastic shopping bags are used widely and cause many environmental problems. Do you think it should be banned? Why/Why not?"
                />
              </div>

              <div>
                <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Instructions
                </label>
                <textarea
                  value={task.instructions || ""}
                  onChange={(event) =>
                    handleTaskChange(index, { instructions: event.target.value })
                  }
                  rows="2"
                  className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                  placeholder="Write a short paragraph (100-150 words). Try to use words and grammar that will show the best of your English."
                />
              </div>

              <div className="space-y-2">
                <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Task image (shown on the left)
                </label>
                <div className="flex flex-wrap items-center gap-3">
                  <input
                    type="file"
                    id={`writing-task-image-${index}`}
                    accept="image/*"
                    onChange={(event) =>
                      handleImageSelect(index, event.target.files?.[0])
                    }
                    className="hidden"
                  />
                  <label
                    htmlFor={`writing-task-image-${index}`}
                    className={`inline-flex items-center gap-2 rounded-lg border px-3 py-1.5 text-sm font-medium transition ${task.imageUrl
                        ? "border-green-200 text-green-700 hover:bg-green-50"
                        : "border-blue-200 text-blue-700 hover:bg-blue-50"
                      }`}
                  >
                    {task.imageUrl ? "Change image" : "Upload image"}
                  </label>
                  {task.imageUrl ? (
                    <button
                      type="button"
                      onClick={() => {
                        if (task.imageUrl && task.imageUrl.startsWith("blob:")) {
                          try {
                            URL.revokeObjectURL(task.imageUrl);
                          } catch (error) {
                            // ignore revoke errors
                          }
                        }
                        handleTaskChange(index, {
                          imageUrl: "",
                          imageFile: null,
                        });
                      }}
                      className="text-xs font-semibold text-rose-500 hover:text-rose-600"
                    >
                      Remove
                    </button>
                  ) : null}
                  <p className="text-[11px] text-slate-500">
                    Supports JPG, PNG and WebP. We will keep proportions.
                  </p>
                </div>

                {task.imageUrl ? (
                  <div className="rounded-lg border border-slate-200 bg-white p-3">
                    <p className="mb-2 text-xs font-semibold uppercase tracking-wide text-slate-500">
                      Preview
                    </p>
                    <div className="flex items-start gap-3">
                      <div className="flex h-36 w-48 flex-shrink-0 items-center justify-center overflow-hidden rounded-lg border border-dashed border-slate-200 bg-slate-50">
                        <img
                          src={task.imageUrl}
                          alt={task.title || `Writing Task ${index + 1}`}
                          className="h-full w-full object-contain"
                        />
                      </div>
                      <div className="space-y-1 text-xs text-slate-500">
                        <p>This image will appear to the left of the response area.</p>
                        <p>Use a high-contrast scan so students can read details clearly.</p>
                      </div>
                    </div>
                  </div>
                ) : null}
              </div>
            </div>

            <ReactQuill
              theme="snow"
              modules={toolbarModules}
              value={task.content || ""}
              onChange={(value) => handleTaskChange(index, { content: value })}
              className="bg-white hidden"
            />

            <div className="grid gap-4 md:grid-cols-2">
              <div>
                <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
                  Minimum words
                </label>
                <input
                  type="number"
                  value={task.minimumWords || 0}
                  onChange={(event) =>
                    handleTaskChange(index, {
                      minimumWords: Number(event.target.value) || 0,
                    })
                  }
                  className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                />
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default WritingBuilder;
