import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import AlertTabOut from "../../components/AlertTabOut";
import AlertIncompletePassage from "../../components/AlertIncompletePassage";
import AlertAudioPlaying from "../../components/AlertAudioPlaying";
import SectionCustomizer from "../../components/SectionCustomizer";
import WelcomePage from "../InformationCollect/welcome";
import { routerPaths } from "../../constants";
import { testBackendConnection } from "../../controller/useFirebase";
import ExamRenderer from "../../components/ExamRenderer";
import RegradeContext from "../../contexts/RegradeContext";
import examTrackingService from "../../controller/examTrackingService";
import { useNotesAndHighlights } from "./hooks/useNotesAndHighlights";
import { useHighlightInteraction } from "./hooks/useHighlightInteraction";
import { useExamRouting } from "./hooks/useExamRouting";
import { useExamData } from "./hooks/useExamData";
import { useExamGrading } from "./hooks/useExamGrading";
import { useSectionNavigation } from "./hooks/useSectionNavigation";
import { useHistoryMode } from "./hooks/useHistoryMode";
import { SaveIndicator, useAutosave, useSubmissionRecovery } from "./hooks/useExamPersistence";
import { useSkillTimer } from "./hooks/useSkillTimer";
import { useRegradeMode } from "./hooks/useRegradeMode";
import { useExamSubmission } from "./hooks/useExamSubmission";
import FetchFailedScreen from "./components/FetchFailedScreen";
import AutosaveRestoreModal from "./components/AutosaveRestoreModal";
import RecoveryBanner from "./components/RecoveryBanner";
import RecoverySuccessModal from "./components/RecoverySuccessModal";
import ReviewModal from "./components/ReviewModal";
import SkipReviewConfirmModal from "./components/SkipReviewConfirmModal";
import { LAYER } from "../../styles/layers";

const Examp = () => {
  const {
    urlExamCode, examCode, examCollection, location, navigate, previewDraft,
    candidateProfile, isPracticeMode, isEmbedded, isRegradeMode,
    isPreviewMode, isHistoryMode, isReload, hasCompletedInfoStep,
    studentInfo, setStudentInfo,
    isWelcomeScreenVisible, setIsWelcomeScreenVisible,
    LAST_EXAM_KEY,
  } = useExamRouting();

  //console.log('[Examp] Mode flags:', { isRegradeMode, isEmbedded, isPreviewMode, search: location.search });

  // ── Layer 5: Auto-retry failed submissions on page load ──
  const {
    hasPendingSubmission: hasPendingSubmissionRecovery,
    recoveredInThisSession: isRecoverySynced,
    isRecovering,
    recoveredResult,
  } = useSubmissionRecovery({ urlExamCode, isHistoryMode });

  // ── Autosave restore ──
  const isRestoreEnabled = useMemo(() => {
    try { return localStorage.getItem('weaver:enableRestore') !== 'false'; } catch (e) { return true; }
  }, []);
  const [autosaveRestoreModal, setAutosaveRestoreModal] = useState({ open: false, data: null, pendingInfo: null });

  // ── Answer-key editing (regrade mode only) ──────────────────────────────────
  const [answers, setAnswers] = useState({});
  const [reviewMode, setReviewMode] = useState(false);

  const {
    keyEdits,
    savedKeyPatch,
    setKeyEdit,
    hasPendingKeyEdits,
    teacherUid,
    regradeError,
    clearRegradeError,
    isSavingRegrade,
    handleSaveAndRegrade: baseHandleSaveAndRegrade,
  } = useRegradeMode({
    isRegradeMode,
    isEmbedded,
    examCode,
    answers,
    setAnswers,
    setReviewMode,
  });

  const {
    examContent,
    loading,
    fetchFailed,
    remoteExamError,
    customSections,
    setCustomSections,
    sectionTabsAll,
    sectionTabs,
    hideSectionTabs,
    answerKeyMap,
    numberingContext,
    nonSpeakingKeys,
    navigationSections,
  } = useExamData({
    examCode,
    examCollection,
    previewDraft,
    savedKeyPatch,
    hasPendingKeyEdits,
    keyEdits,
    isPreviewMode,
    LAST_EXAM_KEY,
  });

  const isSkillTimedMode = !isPreviewMode || isPracticeMode;

  const {
    questionResults,
    setQuestionResults,
    scoreSummary,
    setScoreSummary,
    gradeSection,
    handleFillAnswers,
  } = useExamGrading({
    answers,
    setAnswers,
    answerKeyMap,
    isPreviewMode,
    isPracticeMode,
  });

  // ── Shared submission state (needed by navigation + timer + submission hooks) ──
  const [hasSubmitted, setHasSubmitted] = useState(false);
  const [submittedSections, setSubmittedSections] = useState([]);
  // Practice (which absorbs former /homework/ routes) skips the welcome screen,
  // so set the start time immediately on mount. For /exam/, this stays null
  // until the student submits their info on the welcome screen.
  const [examStartedAt, setExamStartedAt] = useState(() =>
    isPracticeMode ? Date.now() : null
  );

  // ── Seed the start time for entry paths that BYPASS the welcome screen ──
  // The welcome-screen path stamps examStartedAt inside proceedStartExam. But the
  // normal placement flow (arrives from the InformationCollect form, so
  // hasCompletedInfoStep is true → welcome screen skipped), resume-from-banner, and
  // prefilled shortlinks all render the exam DIRECTLY — proceedStartExam never runs, so
  // examStartedAt stays null and the submission falls back to `_startedAt: startedAt ||
  // Date.now()` ≈ submit time. That collapses timeOnTask to ~0 across a multi-skill test
  // (the start should be the FIRST section, not the final submit). Prefer a previously
  // persisted start (resume/reload restore) over "now"; practice seeds at mount (above);
  // preview/history have no exam clock.
  useEffect(() => {
    if (!examCode) return;
    if (isPracticeMode || isPreviewMode || isHistoryMode) return;
    if (isWelcomeScreenVisible) return;   // the welcome path owns the start moment
    if (examStartedAt) return;            // already seeded (proceedStartExam, or a prior tick)
    let seed = null;
    try {
      const raw = localStorage.getItem(`weaver_${examCode}_autosave`);
      const parsed = raw ? JSON.parse(raw) : null;
      if (parsed?.examCode === examCode && parsed.startedAt) seed = parsed.startedAt;
    } catch (_) { /* ignore a corrupt autosave blob */ }
    setExamStartedAt(seed || Date.now());
  }, [examCode, isPracticeMode, isPreviewMode, isHistoryMode, isWelcomeScreenVisible, examStartedAt]);

  const {
    activeSection,
    setActiveSection,
    focusRequest,
    setFocusRequest,
    isAudioPlaying,
    setIsAudioPlaying,
    isListeningReadyPopup,
    setIsListeningReadyPopup,
    isAudioPlayingWarningOpen,
    isSectionLockedWarning,
    isIncompletePassageAlertOpen,
    incompletePassages,
    handleSelectSection,
    handleNavigateToQuestion,
    handleConfirmLeaveWhileAudioPlaying,
    handleCancelLeaveWhileAudioPlaying,
    handleSkipIncompletePassage,
    handleFocusIncompletePassage,
    isSectionSelectable,
  } = useSectionNavigation({
    sectionTabs,
    hasSubmitted,
    isSkillTimedMode,
    examContent,
    answers,
    isWelcomeScreenVisible,
    submittedSections,
  });

  // ── Skill Timer ──
  const {
    currentSkillIndex,
    skillTimeLeftSeconds,
    skillTimerRef,
    skillTimeLeftRef,
    autoAdvanceRef,
    startSkillTimerAtIndex,
    clearExistingSkillTimer,
    getSkillDurationSeconds,
  } = useSkillTimer({
    isSkillTimedMode,
    sectionTabs,
    activeSection,
    isListeningReadyPopup,
    hasSubmitted,
    examContent,
  });

  // ── answersRef for stale-closure protection (created before submission hook) ──
  const answersRef = useRef({});
  answersRef.current = answers;

  // ═══════════════════════════════════════════════════════════
  // SUBMISSION HOOK — the big extraction
  // ═══════════════════════════════════════════════════════════
  const submission = useExamSubmission({
    examCode,
    candidateProfile,
    studentInfo,
    isPreviewMode,
    isPracticeMode,
    isEmbedded,
    sectionTabs,
    sectionTabsAll,
    nonSpeakingKeys,
    examContent,
    answerKeyMap,
    answersRef,
    gradeExam: (finalAnswers, keyMap) => {
      const { gradeExam } = require("./utils/examScoring");
      return gradeExam(finalAnswers, keyMap);
    },
    setQuestionResults,
    setScoreSummary,
    scoreSummary,
    questionResults,
    setReviewMode,
    setFocusRequest,
    setActiveSection,
    startSkillTimerAtIndex,
    getSkillDurationSeconds,
    isSkillTimedMode,
    currentSkillIndex,
    gradeSection,
    hasSubmitted,
    setHasSubmitted,
    submittedSections,
    setSubmittedSections,
    startedAt: examStartedAt,
  });

  // ── Autosave (uses hasSubmitted from submission) ──
  const skillTimeLeftForAutosaveRef = useRef(null);
  const [listeningPartState, setListeningPartState] = useState({});
  // Bumped only when the parent explicitly loads a section from autosave
  // (proceedStartExam or the modal's direct-restore path). Echoes from
  // `handleListeningPartStateChange` do NOT bump this. `useListeningParts`
  // uses the version change to distinguish a real post-mount restore from
  // its own push echo — see Bug #7 in TheWeaverWiki listening_part_timestamps.
  const [listeningRestoreVersion, setListeningRestoreVersion] = useState(0);
  const handleListeningPartStateChange = useCallback((sectionKey, partState) => {
    console.log('🎧 [Parts-Update] section:', sectionKey, 'state:', partState);
    setListeningPartState(prev => {
      const next = { ...prev, [sectionKey]: partState };
      return next;
    });
  }, []);
  const { triggerSave, saveIndicator } = useAutosave({
    answers, examCode, isPreviewMode, isHistoryMode,
    hasSubmitted: submission.hasSubmitted,
    activeSection, skillTimeLeftSeconds: skillTimeLeftForAutosaveRef.current,
    submittedSections: submission.submittedSections,
    startedAt: examStartedAt,
    listeningPartState,   // NEW
  });
  skillTimeLeftForAutosaveRef.current = skillTimeLeftSeconds;

  // ── History Mode ──
  useHistoryMode({
    location, isHistoryMode, isPreviewMode, isReload,
    setAnswers, setQuestionResults, setScoreSummary, setReviewMode,
    setHasSubmitted: submission.setHasSubmitted,
    setStudentInfo,
  });

  // ── Recovery: show answers-only confirmation when a failed submission is recovered ──
  useEffect(() => {
    if (!recoveredResult || isPreviewMode || isHistoryMode) return;
    if (submission.hasSubmitted) return;
    console.log('🔔 [Recovery] Showing recovered submission confirmation');
    submission.setHasSubmitted(true);
    submission.setRecoveredSubmission(recoveredResult);
    examTrackingService.track('submissionRecovered', { examCode });
  }, [recoveredResult, isPreviewMode, isHistoryMode, submission.hasSubmitted, submission.setHasSubmitted, submission.setRecoveredSubmission]);

  // ── Recovery (same-page): flip ExamCompleteModal to success when recovery hook syncs ──
  useEffect(() => {
    if (!isRecoverySynced || isPreviewMode || isHistoryMode) return;
    if (!submission.hasSubmitted) return; // F5 path — handled by the effect above
    if (submission.submitStatus === 'success') return; // already flipped
    console.log('🔔 [Recovery] Same-page path — recovery hook synced, flipping modal to success');
    submission.setSubmitStatus('success');
    submission.clearPersistedExamStorage();
  }, [isRecoverySynced, isPreviewMode, isHistoryMode, submission.hasSubmitted, submission.submitStatus, submission.setSubmitStatus, submission.clearPersistedExamStorage]);

  const handleRecoveryConfirm = () => {
    const pendingKey = `weaver_${examCode}_pending_submission`;
    try {
      Object.keys(localStorage).forEach(k => {
        if (!k) return;
        if (k === pendingKey) return;
        localStorage.removeItem(k);
      });
      Object.keys(sessionStorage).forEach(k => {
        if (k) sessionStorage.removeItem(k);
      });
    } catch (_) { }
    try {
      const pendingRaw = localStorage.getItem(pendingKey);
      if (pendingRaw) {
        const payload = JSON.parse(pendingRaw);
        payload.synced = true;
        payload.syncedAt = Date.now();
        localStorage.setItem(pendingKey, JSON.stringify(payload));
      }
    } catch (_) { }
    navigate(routerPaths.INFORMATION_COLLECT, { state: { from: 'exam', examCode } });
  };

  // Warn user before reload or close.
  // Keep the guard alive while isSubmitting — hasSubmitted flips true before
  // the Firestore write completes, so without this check the browser allows
  // tab-close during the 0-3s write window with no warning.
  useEffect(() => {
    if ((reviewMode || submission.hasSubmitted) && !submission.isSubmitting) return;
    const handleBeforeUnload = (e) => {
      e.preventDefault();
      e.returnValue = '';
    };
    window.addEventListener('beforeunload', handleBeforeUnload);
    return () => window.removeEventListener('beforeunload', handleBeforeUnload);
  }, [reviewMode, submission.hasSubmitted, submission.isSubmitting]);

  // ── Tracking: Section Change ──
  const prevSectionRef = useRef(null);
  useEffect(() => {
    if (activeSection && examTrackingService.isActive()) {
      if (prevSectionRef.current !== activeSection) {
        examTrackingService.trackSectionChange(prevSectionRef.current, activeSection);
        prevSectionRef.current = activeSection;
      }
    }
  }, [activeSection]);

  // ── Tracking: Global Key Combos ──
  useEffect(() => {
    if (!examTrackingService.isActive()) return;
    const handleGlobalKeyDown = (e) => {
      if (e.ctrlKey || e.metaKey) {
        const key = e.key.toLowerCase();
        if (['c', 'v', 'x', 'a', 'z', 'p'].includes(key)) {
          const combo = `${e.ctrlKey ? 'Ctrl' : 'Meta'}+${key.toUpperCase()}`;
          examTrackingService.trackKeyCombo(combo);
        }
      }
      if (e.key === 'F12') {
        examTrackingService.trackKeyCombo('F12');
      }
    };
    window.addEventListener('keydown', handleGlobalKeyDown);
    return () => window.removeEventListener('keydown', handleGlobalKeyDown);
  }, []);

  // ── Notes & highlights ──
  const [isCustomizerOpen, setIsCustomizerOpen] = useState(false);
  const [activeReadingPassageId, setActiveReadingPassageId] = useState("default");
  const [activeListeningPart, setActiveListeningPart] = useState(0);

  const {
    activeNoteContextKey,
    notesForActiveContext,
    highlightsForActiveContext,
    updateNotePositionForContext,
    updateNotePreviewAngleForContext,
    updateNoteFontSizeForContext,
    updateNoteColorForContext,
    updateNoteContentForContext,
    deleteNoteForContext,
    setNoteCollapsedForContext,
    addHighlightForContext,
    createNoteForHighlightInContext,
    removeHighlightForContext,
  } = useNotesAndHighlights(activeSection, activeReadingPassageId, activeListeningPart);

  const { hoveredHighlightId } = useHighlightInteraction({
    highlightsForActiveContext,
    notesForActiveContext,
    activeNoteContextKey,
    addHighlightForContext,
    setNoteCollapsedForContext,
    createNoteForHighlightInContext,
  });

  // Release any object URLs created during preview when component unmounts
  useEffect(() => {
    return () => {
      try {
        const draft = previewDraft;
        if (draft?.reading && Array.isArray(draft.reading.passages)) {
          draft.reading.passages.forEach((passage) => {
            if (passage?.imagePreviewUrl) {
              try { URL.revokeObjectURL(passage.imagePreviewUrl); } catch (error) {}
            }
          });
        }
        if (draft?.writing && Array.isArray(draft.writing.tasks)) {
          draft.writing.tasks.forEach((task) => {
            const url = task?.imagePreviewUrl || task?.imageUrl;
            if (url && typeof url === "string" && url.startsWith("blob:")) {
              try { URL.revokeObjectURL(url); } catch (error) {}
            }
          });
        }
      } catch (error) {}
    };
  }, [previewDraft]);

  // ── Violation count ──
  const [violationCount, setViolationCount] = useState(0);
  useEffect(() => {
    submission.violationCountRef.current = violationCount;
  }, [violationCount, submission.violationCountRef]);

  // ── proceedStartExam / handleStartExam ──
  const proceedStartExam = (info, restoredAnswers, restoredSection, restoredSkillTime, restoredSubmittedSections, restoredStartedAt, restoredListeningPartState) => {
    setStudentInfo(info);
    setIsWelcomeScreenVisible(false);
    localStorage.setItem('studentInfo', JSON.stringify(info));
    if (!examStartedAt) {
      setExamStartedAt(restoredStartedAt || Date.now());
    }
    if (restoredAnswers) {
      setAnswers(restoredAnswers);
    }
    if (restoredSubmittedSections && Array.isArray(restoredSubmittedSections)) {
      console.log('🔒 [proceedStartExam] Restoring submittedSections:', restoredSubmittedSections);
      submission.setSubmittedSections(restoredSubmittedSections);
    }
    if (restoredListeningPartState && typeof restoredListeningPartState === 'object') {
      console.log('🎧 [Parts-Restore] from autosave:', restoredListeningPartState);
      setListeningPartState(restoredListeningPartState);
      setListeningRestoreVersion(v => v + 1);
    } else {
      console.log('🎧 [Parts-Restore] no listeningPartState in payload — defaulting to {}');
    }

    examTrackingService.setPhase('exam');
    examTrackingService.track('examStart', {
      sectionKeys: sectionTabs.map(t => t.key),
      examCode,
    });

    if (sectionTabs.length > 0) {
      let startIndex = 0;
      const submitted = restoredSubmittedSections || [];

      if (restoredSection && !submitted.includes(restoredSection)) {
        const restoredIdx = sectionTabs.findIndex(t => t.key === restoredSection);
        if (restoredIdx >= 0) startIndex = restoredIdx;
      } else if (submitted.includes(sectionTabs[startIndex].key)) {
        for (let i = startIndex + 1; i < sectionTabs.length; i += 1) {
          if (!submitted.includes(sectionTabs[i].key)) {
            startIndex = i;
            break;
          }
        }
      }

      setActiveSection(sectionTabs[startIndex].key);
      if (isSkillTimedMode) {
        if (restoredSkillTime != null && restoredSection && sectionTabs[startIndex]?.key === restoredSection) {
          console.log('🚀 [proceedStartExam] Restoring timer for idx:', startIndex, 'key:', sectionTabs[startIndex]?.key, 'remaining:', restoredSkillTime);
          startSkillTimerAtIndex(startIndex, restoredSkillTime);
        } else {
          const duration = getSkillDurationSeconds(startIndex) || 0;
          console.log('🚀 [proceedStartExam] Starting timer for idx:', startIndex, 'key:', sectionTabs[startIndex]?.key, 'duration:', duration);
          startSkillTimerAtIndex(startIndex, duration);
        }
      }
    }
  };

  const autosaveCheckedRef = useRef(false);
  useEffect(() => {
    if (autosaveCheckedRef.current) return;
    if (isPreviewMode || isHistoryMode || !isRestoreEnabled) {
      console.log('🔄 [Restore] Skipped — isPreviewMode:', isPreviewMode, 'isHistoryMode:', isHistoryMode, 'isRestoreEnabled:', isRestoreEnabled);
      return;
    }
    if (isWelcomeScreenVisible) {
      console.log('🔄 [Restore] Welcome visible — will check in handleStartExam instead');
      return;
    }
    if (!examCode) return;
    autosaveCheckedRef.current = true;
    try {
      const autosaveKey = `weaver_${examCode}_autosave`;
      const raw = localStorage.getItem(autosaveKey);
      console.log('🔄 [Restore] Checking localStorage key:', autosaveKey, '→', raw ? `found (${raw.length} chars)` : 'not found');
      if (!raw) return;
      const parsed = JSON.parse(raw);
      if (parsed && parsed.examCode === examCode && parsed.answers && Object.keys(parsed.answers).length > 0) {
        console.log('🔄 [Restore] Autosave matches examCode, showing restore modal. savedAt:', parsed.savedAt, 'sections:', Object.keys(parsed.answers));
        setAutosaveRestoreModal({ open: true, data: parsed, pendingInfo: null });
      } else {
        console.log('🔄 [Restore] Autosave found but examCode mismatch or empty answers. saved:', parsed?.examCode, 'current:', examCode);
      }
    } catch (e) {
      console.warn('🔄 [Restore] Error reading autosave:', e);
    }
  }, [examCode, isPreviewMode, isRestoreEnabled, isWelcomeScreenVisible, isHistoryMode]);

  const handleStartExam = (info) => {
    if (isRestoreEnabled && !isPreviewMode) {
      try {
        const autosaveKey = `weaver_${examCode}_autosave`;
        const raw = localStorage.getItem(autosaveKey);
        console.log('🔄 [Restore:handleStartExam] key:', autosaveKey, '→', raw ? `found (${raw.length} chars)` : 'not found');
        if (raw) {
          const parsed = JSON.parse(raw);
          if (parsed && parsed.examCode === examCode && parsed.answers && Object.keys(parsed.answers).length > 0) {
            console.log('🔄 [Restore:handleStartExam] Showing restore modal. savedAt:', parsed.savedAt);
            setAutosaveRestoreModal({ open: true, data: parsed, pendingInfo: info });
            return;
          }
        }
      } catch (e) {
        console.warn('🔄 [Restore:handleStartExam] Error:', e);
      }
    }
    proceedStartExam(info, null);
  };

  const handleBackToEditor = () => {
    if (location.state?.from === 'examManager') {
      navigate(routerPaths.CREATE_EXAM, {
        state: {
          returnedFromPreview: true,
          examCode: location.state.examCode
        }
      });
    } else {
      navigate(-1);
    }
  };

  const handleAnswerChange = (sectionKey, questionId, value) => {
    if (reviewMode) return;

    if (examTrackingService.isActive()) {
      if (sectionKey?.toLowerCase().includes('writing')) {
        examTrackingService.trackWriting(sectionKey, questionId, value);
      } else {
        let trackedValue = typeof value === 'boolean' ? value : String(value || '').substring(0, 100);
        let charCount = typeof value === 'string' ? value.length : 0;
        examTrackingService.track('input', { sectionKey, questionId, charCount, value: trackedValue });
      }
    }

    setAnswers((prev) => ({
      ...prev,
      [sectionKey]: {
        ...(prev[sectionKey] || {}),
        [questionId]: value,
      },
    }));
  };

  const handleSaveAndRegrade = () => baseHandleSaveAndRegrade(examContent, answerKeyMap, setScoreSummary, setQuestionResults);

  const handleReadingPassageChange = (passageId) => {
    const normalized = passageId || "default";
    setActiveReadingPassageId(normalized);
  };

  useEffect(() => {
    if (activeSection !== "reading") {
      setActiveReadingPassageId("default");
    }
  }, [activeSection]);

  // ═══════════════════════════════════════════════════════════
  // AUTO-ADVANCE EFFECTS
  // ═══════════════════════════════════════════════════════════

  // auto-advance (or auto-submit at the end) effect
  useEffect(() => {
    if (!isSkillTimedMode) return undefined;
    if (!skillTimerRef.current) {
      console.log('⏰ [Auto-advance] BAIL: no timer ref. timeLeft:', skillTimeLeftSeconds, 'idx:', currentSkillIndex);
      return undefined;
    }
    if (skillTimeLeftSeconds > 0) return undefined;
    console.log('⏰ [Auto-advance] FIRING! Time is 0, ref is valid. idx:', currentSkillIndex, 'key:', sectionTabs[currentSkillIndex]?.key);
    if (sectionTabs.length === 0) return undefined;
    const nextIndex = currentSkillIndex + 1;
    const currentKey = sectionTabs[currentSkillIndex]?.key;
    if (currentKey && !submission.submittedSections.includes(currentKey)) {
      (async () => {
        await gradeSection(currentKey);
      })();
    }
    if (nextIndex < sectionTabs.length) {
      const duration = getSkillDurationSeconds(nextIndex);
      console.log('⏰ [Auto-advance] Moving to index', nextIndex, 'key:', sectionTabs[nextIndex]?.key, 'duration:', duration);
      setActiveSection(sectionTabs[nextIndex].key);
      startSkillTimerAtIndex(nextIndex, duration);
    } else {
      clearExistingSkillTimer();
      submission.triggerAutoFinalize();
    }
    return undefined;
  }, [skillTimeLeftSeconds, isSkillTimedMode, currentSkillIndex, sectionTabs, gradeSection, setActiveSection, startSkillTimerAtIndex, getSkillDurationSeconds, clearExistingSkillTimer, submission]);

  // ── Re-init: recover a stuck-at-zero timer after late sectionTabs load ──
  useEffect(() => {
    if (!isSkillTimedMode) return;
    if (submission.hasSubmitted) return;
    if (sectionTabs.length === 0) return;
    if (skillTimerRef.current) return;
    if (skillTimeLeftRef.current > 0) return;
    const duration = getSkillDurationSeconds(currentSkillIndex);
    if (duration > 0) {
      console.log(
        '🔄 [Timer re-init] sectionTabs loaded late, restarting timer for index',
        currentSkillIndex, 'with', duration, 'seconds'
      );
      startSkillTimerAtIndex(currentSkillIndex, duration);
    }
  }, [sectionTabs, isSkillTimedMode, submission.hasSubmitted]);

  // If active section is already submitted, advance to next available section
  useEffect(() => {
    try { console.debug('📢 submittedSections changed', { submittedSections: submission.submittedSections, activeSection }); } catch (e) { }
    if (!isSkillTimedMode) return undefined;
    if (!activeSection) return undefined;
    if (autoAdvanceRef.current) return undefined;
    if (!Array.isArray(sectionTabs) || sectionTabs.length === 0) return undefined;
    if (!submission.submittedSections.includes(activeSection)) return undefined;
    const idx = sectionTabs.findIndex((t) => t.key === activeSection);
    let nextIdx = -1;
    for (let i = idx + 1; i < sectionTabs.length; i += 1) {
      if (!submission.submittedSections.includes(sectionTabs[i].key)) {
        nextIdx = i;
        break;
      }
    }
    if (nextIdx >= 0) {
      const nextKey = sectionTabs[nextIdx].key;
      try { console.debug('📢 Auto-advancing to next section: ', nextKey); } catch (e) { }
      autoAdvanceRef.current = true;
      if (nextKey !== activeSection) {
        setActiveSection(nextKey);
      }
      if (nextIdx !== currentSkillIndex) {
        const duration = getSkillDurationSeconds(nextIdx);
        startSkillTimerAtIndex(nextIdx, duration);
      }
      setTimeout(() => { autoAdvanceRef.current = false; }, 250);
    } else {
      submission.triggerAutoFinalize();
    }
    return undefined;
  }, [submission.submittedSections, isSkillTimedMode, activeSection, sectionTabs, autoAdvanceRef, setActiveSection, startSkillTimerAtIndex, getSkillDurationSeconds, currentSkillIndex, submission]);

  // When all sections are submitted, finalize the exam
  useEffect(() => {
    if (!sectionTabs || sectionTabs.length === 0) return undefined;
    const allSubmitted = sectionTabs.every((t) => submission.submittedSections.includes(t.key));
    if (!allSubmitted) return undefined;
    if (submission.hasSubmitted) return undefined;
    if (isPreviewMode) return undefined;
    (async () => {
      try {
        console.log('🐛 [ALL-SECTIONS-SUBMITTED] isPracticeMode:', isPracticeMode, 'isPreviewMode:', isPreviewMode, 'hasSubmitted:', submission.hasSubmitted, 'finalizeRef:', submission.finalizeSubmitRef.current);
        const savedStudentRaw = localStorage.getItem('studentInfo') || '{}';
        const savedStudent = studentInfo || (savedStudentRaw ? JSON.parse(savedStudentRaw) : {});
        const hasStudentInfo = savedStudent && Object.keys(savedStudent).length > 0;
        const hasCandidateProfile = !!candidateProfile;
        if (!hasStudentInfo && !hasCandidateProfile) {
          console.log('🐛 [ALL-SECTIONS-SUBMITTED] Opening SubmitConfirmModal (no student info)');
          if (!submission.isSubmitConfirmOpen) submission.setIsSubmitConfirmOpen(true);
        } else {
          console.log('🐛 [ALL-SECTIONS-SUBMITTED] Calling handleConfirmSubmit()');
          await submission.handleConfirmSubmit();
        }
      } catch (err) {
        console.error('Error in auto-finalize submit:', err);
      }
    })();
    return undefined;
  }, [submission.submittedSections, sectionTabs, submission.hasSubmitted, isPreviewMode, studentInfo, candidateProfile, submission.handleConfirmSubmit, submission.isSubmitConfirmOpen, submission.setIsSubmitConfirmOpen]);

  // ── Section validation / welcome close ──
  useEffect(() => {
    if (sectionTabs.length === 0) return;
    const isActiveValid = sectionTabs.some((tab) => tab.key === activeSection);
    if (!isActiveValid) {
      setActiveSection(sectionTabs[0].key);
    }
  }, [sectionTabs, activeSection]);

  useEffect(() => {
    if (!isWelcomeScreenVisible && sectionTabs.length > 0) {
      let candidateKey = sectionTabs[0].key;
      console.log('🔍 [WelcomeClosed] Candidate key from sectionTabs[0]:', candidateKey);

      if (submission.submittedSections?.includes(candidateKey)) {
        const startIdx = sectionTabs.findIndex((t) => t.key === candidateKey);
        for (let i = startIdx + 1; i < sectionTabs.length; i += 1) {
          if (!submission.submittedSections.includes(sectionTabs[i].key)) {
            candidateKey = sectionTabs[i].key;
            break;
          }
        }
      }
      if (!activeSection) {
        console.log("🔄 Welcome closed - defaulting active section to first tab (exam order):", candidateKey);
        setActiveSection(candidateKey);
      } else {
        console.log("🔍 [WelcomeClosed] activeSection already set to:", activeSection);
      }
    }
  }, [isWelcomeScreenVisible, sectionTabs, activeSection, examContent, submission.submittedSections]);

  const totalRemainingSeconds = useMemo(() => {
    if (!Array.isArray(sectionTabs) || sectionTabs.length === 0) return 0;
    const sum = sectionTabs.reduce((acc, tab, idx) => {
      if (submission.submittedSections.includes(tab.key)) return acc;
      if (isSkillTimedMode && tab.key === activeSection) {
        return acc + Math.max(skillTimeLeftSeconds || 0, 0);
      }
      return acc + getSkillDurationSeconds(idx);
    }, 0);
    return sum;
  }, [sectionTabs, submission.submittedSections, isSkillTimedMode, activeSection, skillTimeLeftSeconds]);

  // ═══════════════════════════════════════════════════════════
  // EARLY RETURNS
  // ═══════════════════════════════════════════════════════════
  if (fetchFailed) {
    return (
      <FetchFailedScreen
        examCode={examCode}
        error={remoteExamError}
        onGoBack={() => {
          if (examCode) { try { localStorage.setItem('weaver:pendingExamCode', examCode); } catch (e) { } }
          navigate(routerPaths.INFORMATION_COLLECT, { state: { from: 'exam', examCode } });
        }}
        onRetry={() => window.location.reload()}
      />
    );
  }

  if (isWelcomeScreenVisible && !isPreviewMode) {
    const handleWelcomeSetStep = async (stepOrFn) => {
      let computedStep = null;
      try {
        if (typeof stepOrFn === 'function') {
          computedStep = stepOrFn(1);
        } else {
          computedStep = Number(stepOrFn);
        }
      } catch (e) {
        computedStep = null;
      }
      if (computedStep >= 2) {
        try {
          console.log("🔄 Verifying backend connectivity before starting exam...");
          let realCandidate = null;
          try {
            const rawProfile = localStorage.getItem('weaver:candidateProfile');
            if (rawProfile) {
              const p = JSON.parse(rawProfile);
              realCandidate = {
                name: p.fullName || p.name || "",
                email: p.email || "",
                phone: p.phone || "",
                dob: p.dob || ""
              };
            }
          } catch (e) { }

          if (!realCandidate && studentInfo) {
            realCandidate = {
              name: studentInfo.fullName || studentInfo.name || "",
              email: studentInfo.email || "",
              phone: studentInfo.phone || ""
            };
          }

          const dummyPayload = {
            examCode: examCode || "TEST_CONNECTION",
            answers: {},
            submittedSections: [],
            questionResults: { listening: {}, reading: {} },
            summary: { totalScore: 0, bandScore: 0 },
            candidate: realCandidate || {
              name: "Test User",
              email: "test@example.com"
            },
            isProbe: true
          };

          await testBackendConnection(dummyPayload);
          console.log("✅ Backend connectivity verified. Proceeding to start exam.");
        } catch (err) {
          console.error("Backend connection test failed:", err);
          alert("Lỗi kết nối hệ thống: Không thể xác minh quyền nộp bài. Vui lòng thử lại hoặc liên hệ quản trị viên.");
          return;
        }

        let info = null;
        try {
          const raw = localStorage.getItem('weaver:candidateProfile') || localStorage.getItem('studentInfo');
          if (raw) info = JSON.parse(raw);
        } catch (e) {
          info = null;
        }
        handleStartExam(info || {});
      }
    };

    return <WelcomePage setStep={handleWelcomeSetStep} />;
  }

  // ═══════════════════════════════════════════════════════════
  // RENDER
  // ═══════════════════════════════════════════════════════════
  return (
    <RegradeContext.Provider value={{ isRegrade: isRegradeMode, keyEdits, setKeyEdit }}>
      <SaveIndicator state={saveIndicator} />
      <RecoveryBanner isRecovering={isRecovering && !isPreviewMode && !isHistoryMode} />
      {regradeError && (
        <div style={{ position: 'fixed', top: 12, left: '50%', transform: 'translateX(-50%)', zIndex: LAYER.MODAL, background: '#fef2f2', border: '1.5px solid #fca5a5', borderRadius: 8, padding: '10px 20px', color: '#991b1b', fontWeight: 600, fontSize: '0.9em', boxShadow: '0 2px 12px rgba(0,0,0,0.12)' }}>
          ⚠ {regradeError}
          <button onClick={clearRegradeError} style={{ marginLeft: 12, cursor: 'pointer', fontWeight: 700, background: 'none', border: 'none', color: '#991b1b' }}>✕</button>
        </div>
      )}
      <div className="flex h-dvh w-full justify-center bg-[#f4f6fb]" spellCheck={false}>
        <ExamRenderer
          sectionTabs={sectionTabs}
          activeSectionKey={activeSection}
          onSelectSection={handleSelectSection}
          isSectionSelectable={isSectionSelectable}
          hideSectionTabs={hideSectionTabs}
          examName={examContent?.examName || ""}
          answers={answers}
          onAnswerChange={handleAnswerChange}
          focusRequest={focusRequest}
          reviewMode={reviewMode}
          answerKeyMap={answerKeyMap}
          questionResults={questionResults}
          navigationSections={navigationSections}
          onNavigateToQuestion={handleNavigateToQuestion}
          onSubmit={(isSkillTimedMode && !isPracticeMode) ? () => submission.handleSubmitSection(null, activeSection) : submission.handleSubmitExam}
          isSubmitting={submission.isSubmitting}
          loading={loading}
          isPreviewMode={isPreviewMode}
          hasSubmitted={submission.hasSubmitted}
          totalSeconds={totalRemainingSeconds}
          submittedSections={submission.submittedSections}
          onBackToEditor={handleBackToEditor}
          backButtonLabel="Back to editor"
          showSubmitButton={!isHistoryMode}
          isEmbedded={isEmbedded}
          onFillAnswers={handleFillAnswers}
          isRegradeMode={isRegradeMode}
          onRegrade={handleSaveAndRegrade}
          isSavingRegrade={isSavingRegrade}
          hasPendingKeyEdits={hasPendingKeyEdits}
          examCode={examCode}
          studentInfo={studentInfo}
          onAudioPlayingChange={setIsAudioPlaying}
          onReadyPopupChange={setIsListeningReadyPopup}
          isTimerPaused={isListeningReadyPopup}
          floatingTools={{
            contextKey: activeNoteContextKey,
            notes: notesForActiveContext,
            highlights: highlightsForActiveContext,
            hoveredHighlightId,
            onUpdateNotePosition: (noteId, x, y) =>
              updateNotePositionForContext(activeNoteContextKey, noteId, x, y),
            onUpdatePreviewAngle: (noteId, angle) =>
              updateNotePreviewAngleForContext(activeNoteContextKey, noteId, angle),
            onUpdateNoteFontSize: (noteId, fontSize) =>
              updateNoteFontSizeForContext(activeNoteContextKey, noteId, fontSize),
            onUpdateNoteColor: (noteId, color) =>
              updateNoteColorForContext(activeNoteContextKey, noteId, color),
            onUpdateNoteContent: (noteId, content) =>
              updateNoteContentForContext(activeNoteContextKey, noteId, content),
            onDeleteNote: (noteId) =>
              deleteNoteForContext(activeNoteContextKey, noteId),
            onToggleNoteCollapsed: (noteId, collapsed) =>
              setNoteCollapsedForContext(activeNoteContextKey, noteId, collapsed),
            onRemoveHighlight: (highlightId) =>
              removeHighlightForContext(activeNoteContextKey, highlightId),
            onAddNoteForHighlight: (highlight) =>
              createNoteForHighlightInContext(activeNoteContextKey, highlight),
            overlayActive: submission.isResultModalOpen || submission.isSpeakingFollowupOpen,
          }}
          onReadingPassageChange={handleReadingPassageChange}
          onActivePartChange={setActiveListeningPart}
          numbering={numberingContext}
          currentSkillTimeLeftSeconds={skillTimeLeftSeconds}
          currentSkillIndex={currentSkillIndex}
          isSkillTimedMode={isSkillTimedMode}
          restoredListeningPartState={isPracticeMode ? null : listeningPartState}
          onListeningPartStateChange={isPracticeMode ? undefined : handleListeningPartStateChange}
          listeningRestoreVersion={listeningRestoreVersion}
        />
      </div>

      <AlertTabOut isSuppressed={
        isPreviewMode || submission.hasSubmitted || submission.submittedSections?.includes(activeSection) ||
        (sectionTabs?.some && (() => {
          const speakingKey = sectionTabs.find((t) => (t.type === 'speaking') || String(t.key || '').toLowerCase().includes('speaking'))?.key;
          return speakingKey ? submission.submittedSections?.includes(speakingKey) : false;
        })())
      } onViolation={() => setViolationCount(v => v + 1)} />

      <AlertIncompletePassage
        isOpen={isIncompletePassageAlertOpen && !submission.hasSubmitted}
        incompletePassages={incompletePassages}
        onSkip={handleSkipIncompletePassage}
        onFocus={handleFocusIncompletePassage}
      />
      <AlertAudioPlaying
        isOpen={isAudioPlayingWarningOpen}
        onConfirm={handleConfirmLeaveWhileAudioPlaying}
        onCancel={handleCancelLeaveWhileAudioPlaying}
      />
      <SectionCustomizer
        isOpen={isCustomizerOpen}
        onClose={() => setIsCustomizerOpen(false)}
        sections={customSections}
        onSave={(updatedSections) => {
          setCustomSections(updatedSections);
          const enabledSections = updatedSections.filter(s => s.enabled);
          if (!enabledSections.find(s => s.key === activeSection) && enabledSections.length > 0) {
            setActiveSection(enabledSections[0].key);
          }
        }}
      />

      {/* Submission modals */}
      <submission.Modals activeSection={activeSection} />

      {/* Review modals — rendered here (not inside <submission.Modals>) so
          their state survives the surrounding useMemo's dep-driven remounts. */}
      <ReviewModal
        isOpen={submission.isReviewModalOpen}
        category={submission.reviewCategory}
        isSubmitting={submission.isSubmitting}
        difficulty={submission.reviewDraftDifficulty}
        selectedDomains={submission.reviewDraftDomains}
        comment={submission.reviewDraftComment}
        onSelectDifficulty={submission.setReviewDraftDifficulty}
        onToggleDomain={submission.toggleReviewDraftDomain}
        onCommentChange={submission.setReviewDraftComment}
        onSubmit={submission.handleReviewSubmit}
        onSkipRequest={submission.handleReviewSkipRequest}
      />
      <SkipReviewConfirmModal
        isOpen={submission.isSkipReviewConfirmOpen}
        onConfirm={submission.handleReviewSkipConfirm}
        onCancel={submission.handleReviewSkipCancel}
      />

      {/* Recovery modals */}
      <AutosaveRestoreModal
        isOpen={autosaveRestoreModal.open}
        examCode={examCode}
        autosaveData={autosaveRestoreModal.data}
        onRestore={(payload) => {
          const info = autosaveRestoreModal.pendingInfo;
          const savedAnswers = payload?.answers || payload;
          const savedSection = payload?.activeSection || null;
          const savedTime = payload?.skillTimeLeftSeconds ?? null;
          const savedSubmitted = payload?.submittedSections || [];
          const savedStartedAt = payload?.startedAt || null;
          const savedPartState = payload?.listeningPartState || null;   // NEW
          console.log('🔄 [Restore] User chose RESTORE. path:', info ? 'welcome' : 'direct', 'sections:', Object.keys(savedAnswers || {}), 'activeSection:', savedSection, 'skillTimeLeft:', savedTime, 'submittedSections:', savedSubmitted, 'startedAt:', savedStartedAt, 'listeningPartState:', savedPartState);
          setAutosaveRestoreModal({ open: false, data: null, pendingInfo: null });
          if (info) {
            proceedStartExam(info, savedAnswers, savedSection, savedTime, savedSubmitted, savedStartedAt, savedPartState);
          } else {
            setAnswers(savedAnswers);
            if (savedStartedAt) setExamStartedAt(savedStartedAt);
            if (savedSubmitted && Array.isArray(savedSubmitted) && savedSubmitted.length > 0) {
              submission.setSubmittedSections(savedSubmitted);
            }
            if (savedPartState && typeof savedPartState === 'object') {     // NEW
              console.log('🎧 [Parts-Restore-Direct] from autosave:', savedPartState);
              setListeningPartState(savedPartState);
              setListeningRestoreVersion(v => v + 1);
            }
            if (savedSection && !savedSubmitted?.includes(savedSection)) {
              setActiveSection(savedSection);
            } else if (savedSubmitted?.includes(savedSection)) {
              const idx = sectionTabs.findIndex(t => t.key === savedSection);
              for (let i = idx + 1; i < sectionTabs.length; i += 1) {
                if (!savedSubmitted.includes(sectionTabs[i].key)) {
                  setActiveSection(sectionTabs[i].key);
                  break;
                }
              }
            }
            if (isSkillTimedMode && savedTime != null && savedSection) {
              const sectionIdx = sectionTabs.findIndex(t => t.key === savedSection);
              if (sectionIdx >= 0) startSkillTimerAtIndex(sectionIdx, savedTime);
            }
          }
        }}
        onDiscard={() => {
          const info = autosaveRestoreModal.pendingInfo;
          console.log('🔄 [Restore] User chose START FRESH. path:', info ? 'welcome' : 'direct');
          try { localStorage.removeItem(`weaver_${examCode}_autosave`); } catch (e) { }
          setAutosaveRestoreModal({ open: false, data: null, pendingInfo: null });
          if (info) {
            proceedStartExam(info, null);
          }
        }}
      />
      <RecoverySuccessModal
        isOpen={!!submission.recoveredSubmission}
        recoveredResult={submission.recoveredSubmission}
        examContent={examContent}
        onConfirm={handleRecoveryConfirm}
      />
    </RegradeContext.Provider>
  );
};

export default Examp;
