import React from "react";
import ReactDOM from "react-dom/client";
import { Provider } from "react-redux";
import "./index.css";
import "@fortawesome/fontawesome-free/css/all.min.css";
import store from "./store";
import Header from "./components/Header";
import { createBrowserRouter, RouterProvider } from "react-router-dom";
import { routerPaths } from "./constants/index.js";
//===========Pages
import Examp from "./Pages/Examp";
import InformationCollect from "./Pages/InformationCollect"
import TeacherLogin from "./Pages/Teacher/index.jsx";
import ExamManager from "./_legacy/ExamCustomCreation/index.jsx";
import BookingFlow from "./Pages/Booking/BookingFlow.jsx";
//===========Pages

const AppLayout = () => {
  const isEmbedded = new URLSearchParams(window.location.search).get('embedded') === 'true';

  return (
    <div className="h-full">
      {!isEmbedded && <Header />}
      <main className="h-full">
        <RouterProvider router={router} />
      </main>
    </div>
  );
};

const router = createBrowserRouter([
  {
    path: "/",
    element: <InformationCollect />,
  },
  {
    path: `${routerPaths.EXAM}/:examCode`,
    element: <Examp />,
  },
  {
    path: routerPaths.EXAM,
    element: <Examp />,
  },
  {
    path: `${routerPaths.PRACTICE}/:examCode`,
    element: <Examp />,
  },
  {
    path: routerPaths.INFORMATION_COLLECT,
    element: <InformationCollect />,
  },
  {
    path: routerPaths.HISTORY,
    element: <Examp />,
  },
  {
    path: `${routerPaths.HISTORY}/:examCode`,
    element: <Examp />,
  },
  {
    path: routerPaths.TEACHER,
    element: <TeacherLogin />,
  },
  {
    path: routerPaths.CREATE_EXAM,
    element: <ExamManager />,
  },
  {
    path: `${routerPaths.HOMEWORK}/:examCode`,
    element: <Examp />,
  },
  {
    path: routerPaths.HOMEWORK,
    element: <Examp />,
  },
  {
    path: "/booking",
    element: <BookingFlow />,
  },
  {
    path: "/booking/:step",
    element: <BookingFlow />,
  },
]);

const root = ReactDOM.createRoot(document.getElementById("root"));
root.render(
  <Provider store={store}>
    <AppLayout />
  </Provider>
);
