import { useState, useEffect } from 'react';
import { syncToBackupSubmit } from '../../../controller/useFirebase';
import { restorePayloadFromFirestore } from '../utils/submissionPayload';

/**
 * useHistoryMode
 *
 * Handles the /history route: reads the most recent pending_submission from
 * localStorage and hydrates the exam view into read-only review mode.
 *
 * Isolated from live exam state — safe to change without touching
 * the submission safety net.
 *
 */
export function useHistoryMode({
  location,
  isHistoryMode,
  isPreviewMode,
  isReload,
  setAnswers,
  setQuestionResults,
  setScoreSummary,
  setReviewMode,
  setHasSubmitted,
  setStudentInfo,
}) {
  const [historyExamCode] = useState(() => {
    if (typeof window === 'undefined' || !location.pathname.startsWith('/history')) return null;
    const fromStorage =
      localStorage.getItem('weaver:lastExamCode') ||
      localStorage.getItem('weaver:pendingExamCode');
    if (fromStorage) return fromStorage;
    for (let i = 0; i < localStorage.length; i++) {
      const key = localStorage.key(i);
      if (key && key.startsWith('weaver_') && key.endsWith('_pending_submission')) {
        return key.replace('weaver_', '').replace('_pending_submission', '');
      }
    }
    return null;
  });

  useEffect(() => {
    if (isPreviewMode) return;
    if (isReload) return;
    if (!isHistoryMode || !historyExamCode) return;

    const targetCode = historyExamCode;
    const pendingKey = `weaver_${targetCode}_pending_submission`;
    const raw = localStorage.getItem(pendingKey);

    if (!raw) {
      console.warn('⚠️ [History] No records found in localStorage for:', targetCode);
      return;
    }

    try {
      const payload = JSON.parse(raw);

      setAnswers(restorePayloadFromFirestore(payload.answers || {}));
      setQuestionResults(restorePayloadFromFirestore(payload.questionResults || {}));
      setScoreSummary(payload.summary || null);
      setReviewMode(true);
      setHasSubmitted(true);
      setStudentInfo(payload.candidate || {});

      // Sync to backup_submit only when explicitly requested via ?sync=true
      const queryParams = new URLSearchParams(location.search);
      if (queryParams.get('sync') === 'true') {
        console.log('🔄 [History] Triggering manual sync to backup_submit (Force Sync mode)...');
        syncToBackupSubmit(targetCode, payload)
          .then(() => {
            const updated = { ...payload, syncedToBackup: true, lastBackupAt: Date.now() };
            localStorage.setItem(pendingKey, JSON.stringify(updated));
            console.log('✅ [History] Sync to backup_submit successful.');
          })
          .catch((err) => {
            console.error('❌ [History] Sync to backup_submit failed:', err);
          });
      }
    } catch (e) {
      console.error('Failed to parse history payload:', e);
    }
  }, [isHistoryMode, historyExamCode, location.search, isPreviewMode, isReload, setStudentInfo]);

  return { historyExamCode };
}
