import React from "react";

const FetchFailedScreen = ({ examCode, error, onGoBack, onRetry }) => {
  return (
    <div className="flex min-h-screen w-full items-center justify-center bg-[#f4f6fb] px-6">
      <div className="max-w-lg w-full rounded-2xl bg-white p-8 shadow-lg border border-amber-200">
        <h2 className="text-xl font-semibold text-red-600 mb-2">Unable to load this exam</h2>
        <p className="text-sm text-gray-700">
          We couldn&apos;t load exam code <span className="font-mono font-semibold">{examCode}</span>.
          Please verify the code or try again.
        </p>
        {error && (
          <p className="mt-3 text-xs text-gray-500 break-words">
            Details: {error.message || String(error)}
          </p>
        )}
        <div className="mt-6 flex gap-3">
          <button
            type="button"
            className="inline-flex items-center justify-center rounded-lg bg-orange-500 px-4 py-2 text-sm font-semibold text-white shadow hover:bg-orange-600"
            onClick={onGoBack}
          >
            Go back
          </button>
          <button
            type="button"
            className="inline-flex items-center justify-center rounded-lg border border-gray-300 px-4 py-2 text-sm font-semibold text-gray-700 hover:bg-gray-50"
            onClick={onRetry}
          >
            Retry
          </button>
        </div>
      </div>
    </div>
  );
};

export default FetchFailedScreen;
