import React from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";
import { generateId } from "../../../utils/question/idUtils";

const BlankAnswerList = () => {
  const {
    question,
    numberingPrefix,
    updateQuestion,
    addPromptBlank,
    addInlineBlank,
  } = useQuestionContext();

  const prefix = numberingPrefix || question?.questionNumber || "";
  const blanks = Array.isArray(question?.subQuestions) ? question.subQuestions : [];

  const handleAnswerChange = (index, value) => {
    updateQuestion((current = question) => {
      const existing = Array.isArray(current.subQuestions) ? [...current.subQuestions] : [];
      const nextSubQuestions = existing.map((sub, idx) => ({
        ...sub,
        number: `${prefix}.${idx + 1}`,
      }));

      while (nextSubQuestions.length <= index) {
        const blankIndex = nextSubQuestions.length;
        nextSubQuestions.push({
          id: generateId("SQ"),
          number: `${prefix}.${blankIndex + 1}`,
          type: "text",
          correctAnswers: [""],
          prompt: `Answer for blank ${blankIndex + 1}`,
        });
      }

      nextSubQuestions[index] = {
        ...nextSubQuestions[index],
        correctAnswers: [value],
      };

      return {
        ...current,
        subQuestions: nextSubQuestions,
      };
    });
  };

  const handleAddBlank = () => {
    if (question?.type === "inline-blank" && typeof addInlineBlank === "function") {
      addInlineBlank();
      return;
    }
    if (typeof addPromptBlank === "function") {
      addPromptBlank();
    }
  };

  if (!blanks.length) {
    return (
      <div className="mt-2 rounded-lg border border-slate-200 bg-slate-50 p-4 text-center">
        <p className="text-sm text-slate-600">No blanks added yet.</p>
        <div className="mt-3 flex justify-center">
          <button
            type="button"
            onClick={handleAddBlank}
            className="rounded border px-3 py-2 text-xs font-semibold text-blue-600 hover:bg-blue-50"
          >
            + Add blank
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="mt-2 space-y-3">
      {blanks.map((subQuestion, index) => (
        <div key={subQuestion.id || `${prefix}-${index}`} className="flex items-center gap-3">
          <div className="min-w-[40px] text-sm font-medium text-slate-600">
            {subQuestion.number || `${prefix}.${index + 1}`}
          </div>
          <input
            type="text"
            value={subQuestion.correctAnswers?.[0] || ""}
            onChange={(event) => handleAnswerChange(index, event.target.value)}
            className="flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            placeholder={`Answer for blank ${index + 1}`}
          />
        </div>
      ))}
    </div>
  );
};

export default BlankAnswerList;
