import React, { useMemo } from "react";

const normalizeAnswer = (value) => {
  if (value === null || value === undefined) return "";
  return String(value).trim().toUpperCase();
};

const intToLetter = (num) => {
  // Converts 1 to A, 2 to B, 3 to C, etc.
  return String.fromCharCode(64 + num);
};

const WhichTruePreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  placeholder,
  name,
  questionNumber = 1,
}) => {
  const statementItems = useMemo(() => {
    if (!question) {
      return ["Add statements in the exam builder."];
    }
    if (Array.isArray(question.whichTrueItems) && question.whichTrueItems.length) {
      return question.whichTrueItems;
    }
    return ["Add statements in the exam builder."];
  }, [question]);

  if (!question) {
    return null;
  }

  const normalizedCorrect = correctAnswers
    .map((answer) => normalizeAnswer(answer))
    .filter(Boolean);
  const isInteractive = typeof onChange === "function";
  
  // Determine number of answer rows based on correctAnswers length
  const answerCount = Array.isArray(correctAnswers) ? correctAnswers.length : 1;
  
  // Parse question number - could be "1" or "1 - 3"
  const startingNumber = typeof questionNumber === "string"
    ? parseInt(String(questionNumber).split(" ")[0]) || 1
    : parseInt(String(questionNumber)) || 1;
  
  return (
    <div className="space-y-3">
      <div className="rounded-lg border border-orange-200 bg-orange-50/30 px-3 py-2">
        <div className="space-y-1 text-sm text-slate-700">
          {statementItems.map((item, index) => {
            const letterLabel = intToLetter(index + 1);
            return (
              <div key={`which-true-item-${index}`} className="flex gap-2 leading-relaxed">
                <span className="flex-shrink-0 font-semibold">{letterLabel}.</span>
                <span>{item && item.trim().length > 0 ? item : `Statement ${letterLabel}`}</span>
              </div>
            );
          })}
        </div>
      </div>

      <div>
        <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
          Your answer
        </label>
        <div className="mt-2 space-y-2">
          {Array.from({ length: answerCount }).map((_, answerIndex) => {
            const answerNumber = startingNumber + answerIndex;
            const userValue = Array.isArray(value) ? value[answerIndex] : (answerIndex === 0 ? value : "");
            const normalizedUserValue = normalizeAnswer(userValue);
            const isAnswerCorrect =
              reviewMode && normalizedCorrect.length > answerIndex
                ? normalizeAnswer(correctAnswers[answerIndex]) === normalizedUserValue
                : false;
            
            return (
              <div
                key={`answer-${answerIndex}`}
                className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-2 py-1.5"
              >
                <span className="inline-flex h-6 w-6 flex-shrink-0 items-center justify-center rounded border border-orange-200 bg-orange-50 text-xs font-semibold text-orange-600">
                  {answerNumber}
                </span>
                <select
                  value={userValue ?? ""}
                  onChange={(event) => {
                    // Always work with array format for multiple answers
                    const currentArray = Array.isArray(value) 
                      ? value 
                      : (value ? [value] : []);
                    
                    // Ensure array is long enough
                    while (currentArray.length <= answerIndex) {
                      currentArray.push("");
                    }
                    
                    // Update the specific answer
                    currentArray[answerIndex] = event.target.value;
                    onChange?.(currentArray);
                  }}
                  disabled={disabled || (reviewMode) || !isInteractive}
                  data-question-slot-number={answerNumber}
                  className={`flex-1 rounded-lg border bg-white px-2 py-1 text-sm text-slate-800 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200 ${
                    reviewMode
                      ? isAnswerCorrect
                        ? "border-green-400 bg-green-50"
                        : "border-red-300"
                      : ""
                  }`}
                >
                  <option value="">Select</option>
                  {statementItems.map((_, index) => {
                    const letterLabel = intToLetter(index + 1);
                    return (
                      <option key={letterLabel} value={letterLabel}>
                        {letterLabel}
                      </option>
                    );
                  })}
                </select>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default WhichTruePreview;
