import React from "react";

const IncompleteQuestionsModal = ({ isOpen, items = [], onClose, onFocusFirst, onSkipSubmit }) => {
  if (!isOpen) return null;
  return (
    <div className="fixed inset-0 z-alert flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
      <div className="w-full max-w-lg rounded-2xl bg-white p-6 shadow-2xl">
        <h2 className="text-lg font-semibold text-orange-600">Incomplete questions</h2>
        <p className="mt-2 text-sm text-gray-700">
          Please finish the questions below before submitting this section.
        </p>
        <ul className="mt-4 space-y-2 max-h-64 overflow-y-auto">
          {items.map((q) => (
            <li key={q.id} className="rounded border border-orange-100 bg-orange-50 px-3 py-2 text-sm text-orange-700">
              {q.label || `Question: ${q.id}`}
            </li>
          ))}
        </ul>
        <div className="mt-6 flex gap-3">
          <button
            type="button"
            onClick={onFocusFirst}
            className="flex-1 rounded-lg bg-orange-500 px-4 py-2 text-sm font-semibold text-white transition hover:bg-orange-600 focus:outline-none focus:ring-2 focus:ring-orange-200"
          >
            Focus
          </button>
          {items.some(q => (q.label || '').includes('(Topic Selection)')) ? null : (
            <button
              type="button"
              onClick={onSkipSubmit}
              className="flex-1 rounded-lg border border-orange-200 px-4 py-2 text-sm font-semibold text-orange-600 transition hover:bg-orange-50 focus:outline-none focus:ring-2 focus:ring-orange-200"
            >
              Skip
            </button>
          )}
          <button
            type="button"
            onClick={onClose}
            className="flex-1 rounded-lg border border-gray-300 px-4 py-2 text-sm font-semibold text-gray-700 transition hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-gray-200"
          >
            Close
          </button>
        </div>
      </div>
    </div>
  );
};

export default IncompleteQuestionsModal;
