import React, { useState } from "react";
import { routerPaths } from "../../constants";
import { useNavigate } from "react-router-dom";
import { signInWithEmailAndPassword } from "firebase/auth";
import { auth } from "../../controller/firebase";

const TeacherLogin = () => {
    const navigate = useNavigate();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
  
    const handleLogin = async () => {
        try {
            setError('');
            await signInWithEmailAndPassword(auth, email, password);
            navigate(routerPaths.CREATE_EXAM);
        } catch (error) {
            setError(error.message || "Unable to sign in. Please try again.");
        }
    };

    return (
        <div className="flex w-full h-[100vh] justify-center bg-gradient-to-br from-slate-900 via-blue-900 to-slate-800">
            <div className="flex flex-col w-2/4 pl-[48px] pr-[48px] justify-center">
                <div className="flex w-full flex-col items-stretch gap-4 bg-white/95 py-8 rounded-[20px] px-8 shadow-2xl backdrop-blur">
                    <div className="flex flex-col items-center gap-1.25">
                        <p className="text-base font-bold lg:text-2xl text-center lg:!text-base">
                            WEAVER TEACHER
                        </p>
                        <p className="text-sm text-center">
                            Enter your account to login
                        </p>
                    </div>
                    <div>
                        <div className="relative w-full rounded border border-input-border">
                            <input
                                onChange={(e) => setEmail(e.target.value)}
                                onKeyDown={(e) => e.keyCode === 13 && handleLogin()}
                                value={email}
                                type="email"
                                inputMode="text"
                                name="givenName"
                                placeholder=" "
                                className="peer w-full rounded px-4 disabled:border-disabled disabled:bg-disabled/30 _input_1wwzg_1 focus-visible:outline-primary pb-3 pt-5"
                                data-test-id="form-field-text-input"
                                defaultValue=""
                            />
                            <label
                                title="Email"
                                className="pointer-events-none absolute left-0 right-4 top-0 line-clamp-1 translate-x-4 translate-y-4 scale-100 transition ease-in-out origin-top-left text-light-contrast/50 peer-focus-visible:text-primary"
                            >
                                {email ? '' : '* Email'}
                            </label>
                        </div>
                    </div>
                    <div>
                        <div className="relative w-full rounded border border-input-border">
                            <input
                                onChange={(e) => setPassword(e.target.value)}
                                onKeyDown={(e) => e.keyCode === 13 && handleLogin()}
                                value={password}
                                type="password"
                                inputMode="text"
                                name="familyName"
                                placeholder=" "
                                className="peer w-full rounded px-4 disabled:border-disabled disabled:bg-disabled/30 _input_1wwzg_1 focus-visible:outline-primary pb-3 pt-5"
                                data-test-id="form-field-text-input"
                                defaultValue=""
                            />
                            <label
                                title="Password"
                                className="pointer-events-none absolute left-0 right-4 top-0 line-clamp-1 translate-x-4 translate-y-4 scale-100 transition ease-in-out origin-top-left text-light-contrast/50 peer-focus-visible:text-primary"
                            >
                                {password ? '' : '* Password'}
                            </label>
                        </div>
                    </div>
                    {error ? (
                        <p className="text-sm text-rose-500 text-center">{error}</p>
                    ) : null}
                    <button onClick={() => handleLogin()} className="flex min-h-[48px] items-center justify-center gap-x-2.5 rounded-full px-9 py-2 bg-orange-300 hover:brightness-110">
                        <span className="font-medium text-primary-contrast">Next</span>
                    </button>
                </div>
            </div>
        </div>
    )
}

export default TeacherLogin;
