import React, { useEffect, useMemo, useRef, useState } from 'react';
import { useNavigate, useParams } from 'react-router-dom';
import { motion, AnimatePresence } from 'framer-motion';
import './Booking.css';
import { normalizeVnPhone, isValidVnPhone, formatVnPhone } from '../../utils/phone';
import {
  DURATIONS, SKILLS, GOALS, SLOTS, VI_WEEKDAYS,
  startOfToday, toISO, monthLabel, buildMonthGrid, isoRange, formatISOVi,
  submitBooking, savePendingLead, genCandidateId, toPrefillParam, watchForSubmission, getEmailNotifyFlag,
  clearSubmissionBreadcrumb, hasFreshPlacementSubmission, preloadRecaptcha,
} from './bookingData';

const STAGE = {
  IDENTITY: 'identity', WAIT_TEST: 'wait_test', CONSULT: 'consult', DATES: 'dates',
  SLOTS: 'slots', REVIEW: 'review', DONE: 'done',
};
// Stages that can be resumed after a reload (DONE finalizes → start fresh next time).
const RESUMABLE = [STAGE.WAIT_TEST, STAGE.CONSULT, STAGE.DATES, STAGE.SLOTS, STAGE.REVIEW];
const LS_KEY = 'wv_booking_lead';

// Stage ↔ URL slug (the route is /booking/:step; the URL is the source of truth so
// the browser Back button maps to the previous step for free).
const STAGE_SLUGS = {
  [STAGE.IDENTITY]: 'info',
  [STAGE.WAIT_TEST]: 'test',
  [STAGE.CONSULT]: 'consult',
  [STAGE.DATES]: 'dates',
  [STAGE.SLOTS]: 'time',
  [STAGE.REVIEW]: 'review',
  [STAGE.DONE]: 'done',
};
const SLUG_TO_STAGE = Object.fromEntries(Object.entries(STAGE_SLUGS).map(([s, slug]) => [slug, s]));

function readSavedLead() {
  try {
    const s = JSON.parse(localStorage.getItem(LS_KEY) || 'null');
    return s && typeof s === 'object' ? s : null;
  } catch (e) {
    return null;
  }
}

// Single source of truth for the in-progress booking. Erased on finalization.
function clearBookingArtifacts() {
  try { localStorage.removeItem(LS_KEY); } catch (e) { /* ignore */ }
  clearSubmissionBreadcrumb();
}

const fade = {
  initial: { opacity: 0, y: 24 },
  animate: { opacity: 1, y: 0 },
  exit: { opacity: 0, y: -16 },
  transition: { duration: 0.28, ease: 'easeOut' },
};

function Logo() {
  return (
    <div className="wv-logo">
      <span className="wv-logo-mark">W</span>
      <span className="wv-logo-text">WEAVER<small>ENGLISH</small></span>
    </div>
  );
}

function Stepper({ current }) {
  const steps = ['Thông tin', 'Tư vấn', 'Chọn ngày', 'Chọn giờ', 'Xác nhận'];
  return (
    <div className="wv-stepper">
      {steps.map((s, i) => (
        <div key={s} className={'wv-step' + (i === current ? ' is-on' : i < current ? ' is-done' : '')}>
          <span className="wv-step-dot">{i < current ? '✓' : i + 1}</span>
          <span className="wv-step-label">{s}</span>
        </div>
      ))}
    </div>
  );
}

// 1 — Identity + the two choices
function IdentityForm({ initial, examTaken, onTest, onConsult }) {
  const [f, setF] = useState(initial);
  const [err, setErr] = useState({});
  const set = (k) => (e) => setF((s) => ({ ...s, [k]: e.target.value }));

  function validate() {
    const e = {};
    if (!f.name.trim()) e.name = 'Vui lòng nhập họ tên';
    if (!f.phone.trim()) e.phone = 'Vui lòng nhập số điện thoại / Zalo';
    else if (!isValidVnPhone(f.phone)) e.phone = 'Số điện thoại không hợp lệ (VD: 0901234567)';
    if (!f.email.trim()) e.email = 'Vui lòng nhập email';
    else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(f.email)) e.email = 'Email chưa hợp lệ';
    // dob is REQUIRED so the placement test never needs a second info screen — a
    // complete booking identity lets the exam skip its own StudentInfo form. Skip
    // the check once the exam is taken (fields are locked → can't be a blocker for
    // pre-existing in-flight bookings that predate this requirement).
    if (!examTaken && (!f.dob || !f.dob.trim())) e.dob = 'Vui lòng nhập ngày sinh';
    setErr(e);
    return Object.keys(e).length === 0;
  }
  const go = (fn) => () => { if (validate()) fn(f); };

  return (
    <div className="wv-card">
      <Logo />
      <p className="wv-kicker">GETTING TO KNOW EACH OTHER</p>
      <h1 className="wv-h1">Chúng ta làm quen một chút nhé</h1>
      <p className="wv-sub">Điền vài thông tin để Weaver hỗ trợ bạn tốt nhất.</p>

      <div className="wv-field">
        <label className="wv-label">Họ và tên</label>
        <input className="wv-input" value={f.name} onChange={set('name')} placeholder="Nguyễn Văn A" disabled={examTaken} />
        {err.name && <span className="wv-err">{err.name}</span>}
      </div>
      <div className="wv-row">
        <div className="wv-field">
          <label className="wv-label">Ngày sinh</label>
          <input className="wv-input" type="date" value={f.dob} onChange={set('dob')} disabled={examTaken} />
          {err.dob && <span className="wv-err">{err.dob}</span>}
        </div>
        <div className="wv-field">
          <label className="wv-label">SĐT / Zalo</label>
          <input className="wv-input" value={formatVnPhone(f.phone)} onChange={(e) => setF((s) => ({ ...s, phone: normalizeVnPhone(e.target.value) }))} placeholder="09xx xxx xxx" inputMode="tel" disabled={examTaken} />
          {err.phone && <span className="wv-err">{err.phone}</span>}
        </div>
      </div>
      <div className="wv-field">
        <label className="wv-label">Email</label>
        <input className="wv-input" type="email" value={f.email} onChange={set('email')} placeholder="ban@email.com" inputMode="email" disabled={examTaken} />
        {err.email && <span className="wv-err">{err.email}</span>}
      </div>
      {examTaken && <p className="wv-locked-note">🔒 Thông tin đã khoá sau khi bạn nộp bài thi. Tiếp tục để lên lịch tư vấn.</p>}

      <p className="wv-choose">Bạn muốn bắt đầu thế nào?</p>
      <div className="wv-choices">
        <button
          type="button"
          className="wv-cta wv-cta--ghost"
          onClick={go(onTest)}
          disabled={examTaken}
          title={examTaken ? 'Bạn đã nộp bài thi rồi' : undefined}
        >
          <span className="wv-cta-em">{examTaken ? '✓ Bạn đã nộp bài thi rồi' : '📝 Làm bài thi online'}</span>
          <span className="wv-cta-sub">{examTaken ? 'Tiếp tục lên lịch tư vấn nhé' : 'Kiểm tra trình độ trước khi tư vấn'}</span>
        </button>
        <button type="button" className="wv-cta" onClick={go(onConsult)}>
          <span className="wv-cta-em">📅 Lên lịch tư vấn</span>
          <span className="wv-cta-sub">Đặt lịch nói chuyện với Weaver</span>
        </button>
      </div>
    </div>
  );
}

