function MonthPanel({ year, month, todayISO, selected, anchor, hover, onDown, onEnter }) {
  const cells = useMemo(() => buildMonthGrid(year, month), [year, month]);
  const [lo, hi] = anchor && hover ? (anchor <= hover ? [anchor, hover] : [hover, anchor]) : [null, null];
  return (
    <div className="wv-cal">
      <div className="wv-cal-title">{monthLabel(year, month)}</div>
      <div className="wv-cal-dow">{VI_WEEKDAYS.map((d) => <span key={d}>{d}</span>)}</div>
      <div className="wv-cal-grid">
        {cells.map((c, i) => {
          if (!c) return <span key={'b' + i} className="wv-day is-blank" />;
          const disabled = c.iso < todayISO;
          const cls = ['wv-day'];
          if (disabled) cls.push('is-disabled');
          if (selected.has(c.iso)) cls.push('is-sel');
          if (lo && c.iso >= lo && c.iso <= hi && !disabled) cls.push('is-preview');
          return (
            <button
              type="button"
              key={c.iso}
              className={cls.join(' ')}
              disabled={disabled}
              onPointerDown={(e) => { if (!disabled) { e.preventDefault(); onDown(c.iso); } }}
              onPointerEnter={() => { if (!disabled) onEnter(c.iso); }}
            >
              {c.day}
            </button>
          );
        })}
      </div>
    </div>
  );
}

// 3 — Date picker (current + next month, tap or click-drag)
function DatePicker({ initial, onBack, onNext }) {
  const today = useMemo(() => startOfToday(), []);
  const todayISO = toISO(today);
  const cur = { y: today.getFullYear(), m: today.getMonth() };
  const nextM = today.getMonth() === 11
    ? { y: today.getFullYear() + 1, m: 0 }
    : { y: today.getFullYear(), m: today.getMonth() + 1 };

  const [selected, setSelected] = useState(() => new Set(initial || []));
  const [anchor, setAnchor] = useState(null);
  const [hover, setHover] = useState(null);
  const modeRef = useRef('add');

  const onDown = (iso) => { setAnchor(iso); setHover(iso); modeRef.current = selected.has(iso) ? 'remove' : 'add'; };
  const onEnter = (iso) => { if (anchor) setHover(iso); };

  useEffect(() => {
    if (!anchor) return undefined;
    const commit = () => {
      setSelected((prev) => {
        const next = new Set(prev);
        isoRange(anchor, hover || anchor).forEach((iso) => {
          if (iso < todayISO) return;
          if (modeRef.current === 'add') next.add(iso);
          else next.delete(iso);
        });
        return next;
      });
      setAnchor(null);
      setHover(null);
    };
    window.addEventListener('pointerup', commit);
    window.addEventListener('pointercancel', commit);
    return () => {
      window.removeEventListener('pointerup', commit);
      window.removeEventListener('pointercancel', commit);
    };
  }, [anchor, hover, todayISO]);

  const count = selected.size;
  return (
    <div className="wv-card">
      <Stepper current={2} />
      <h1 className="wv-h1">Chọn ngày bạn rảnh</h1>
      <p className="wv-sub">Chạm để chọn từng ngày, hoặc kéo để chọn một khoảng ngày liên tục.</p>
      <div className="wv-cals">
        <MonthPanel year={cur.y} month={cur.m} todayISO={todayISO} selected={selected} anchor={anchor} hover={hover} onDown={onDown} onEnter={onEnter} />
        <MonthPanel year={nextM.y} month={nextM.m} todayISO={todayISO} selected={selected} anchor={anchor} hover={hover} onDown={onDown} onEnter={onEnter} />
      </div>
      <div className="wv-nav">
        <button type="button" className="wv-back" onClick={onBack}>← Quay lại</button>
        <span className="wv-count">{count > 0 ? `Đã chọn ${count} ngày` : 'Chưa chọn ngày'}</span>
        <button type="button" className="wv-cta wv-cta--inline" disabled={count === 0} onClick={() => onNext([...selected].sort())}>Tiếp tục →</button>
      </div>
    </div>
  );
}

