// Shown after "Làm bài thi online" — the test runs in a new tab; this screen keeps
// the booking flow + the user's info alive until they return and continue.
function TestWait({ since, onDetected, onContinue, onSkip }) {
  const cb = useRef(onDetected);
  cb.current = onDetected;
  useEffect(() => watchForSubmission({ since }, (res) => cb.current(res)), [since]);
  return (
    <div className="wv-card wv-thanks">
      <div className="wv-check" style={{ background: 'linear-gradient(155deg,#f59e0b,#d97706)' }}>📝</div>
      <h1 className="wv-h1">Bài thi đang mở ở tab mới</h1>
      <p className="wv-sub">Hãy hoàn thành và nộp bài ở tab vừa mở — màn hình này sẽ tự chuyển khi bạn nộp xong. Hoặc bấm nút bên dưới để tiếp tục ngay. Thông tin của bạn vẫn được giữ nguyên.</p>
      <div className="wv-choices" style={{ marginTop: 8 }}>
        <button type="button" className="wv-cta" onClick={onContinue}>
          <span className="wv-cta-em">✓ Tôi đã hoàn thành bài thi</span>
          <span className="wv-cta-sub">Tiếp tục lên lịch tư vấn</span>
        </button>
        <button type="button" className="wv-cta wv-cta--ghost" onClick={onSkip}>
          <span className="wv-cta-em">Bỏ qua, đặt lịch luôn</span>
        </button>
      </div>
    </div>
  );
}

/**
 * BookingFlow — lead/consultant booking wizard for Weaver IELTS.
 *
 * Props:
 *  - onTakeTest(lead): optional override. Called when the user picks "Làm bài thi online".
 *    Default: persist the lead in localStorage + open the placement test in a new tab
 *    (with ?prefill= carrying the student's info), then wait on the WAIT_TEST screen —
 *    which auto-advances when the submission lands, or via the manual "I've finished" button.
 */
export default function BookingFlow({ onTakeTest }) {
  const navigate = useNavigate();
  const { step } = useParams();

  // Resume from a saved lead so the round-trip + any reload restores the EXACT step.
  const saved = readSavedLead();
  const [busy, setBusy] = useState(false);
  // Set once the booking is finalized (CF resolved). In-memory only (NOT persisted): a fresh
  // page load starts a new booking, but within THIS mount it locks the flow on /done so the
  // browser Back button can't walk back to Review and re-submit (which re-fires notifications).
  const finalizedRef = useRef(false);
  const [data, setData] = useState(() => {
    const s = saved || {};
    return {
      name: '', dob: '', email: '', phone: '',
      path: 'consult',
      profile: { duration: '', skills: [], goal: '' },
      dates: [], slot: '',
      testTaken: false,
      submissionId: '',
      testStartedAt: 0,
      candidateId: '',
      ...s,
      stage: undefined, // legacy field — stage now lives in the URL
    };
  });

  // The URL slug is the source of truth for the stage. Linear steps are pushed so
  // the browser Back button walks them; in-app "Quay lại" is navigate(-1) (mirrors
  // Back). The catch: arriving via resume/test-return would otherwise be a single
  // replace with no step entries behind it (Back would exit to the exam page) — so on
  // entry we REBUILD the history prefix [info … target] from scratch.
  const stage = SLUG_TO_STAGE[step] || STAGE.IDENTITY;
  const slugPath = (st) => '/booking/' + STAGE_SLUGS[st];
  const go = (st) => navigate(slugPath(st));
  const back = () => navigate(-1);

  // Replace current entry with `info`, then push each step up to `target`, so Back
  // steps backward through the real prior stages. (Routes have no loaders → these
  // sequential navigations each create a history entry in createBrowserRouter.)
  const ORDER = [STAGE.IDENTITY, STAGE.CONSULT, STAGE.DATES, STAGE.SLOTS, STAGE.REVIEW];
  const rebuildTo = (target) => {
    const idx = Math.max(0, ORDER.indexOf(target));
    navigate(slugPath(ORDER[0]), { replace: true });
    for (let i = 1; i <= idx; i++) navigate(slugPath(ORDER[i]));
  };

  // Has the placement test been completed in THIS booking session? `testTaken` is set
  // when the watcher confirms a submission landed (or the user manually continues). The
  // real submission lives in examSubmissions/{submissionId} — the lead stores only that
  // pointer, never a denormalized copy. Gates the test button + locks the identity step.
  const examTaken = !!data.testTaken;

  // One-time entry normalization + history reconstruction.
  //
  // Resume target priority:
  //   1. an explicit, valid URL slug (deep-link / reload)
  //   2. a test in flight — `testStartedAt > 0` and not yet detected. This is the
  //      AUTHORITATIVE test-path signal (written synchronously before redirect), used
  //      instead of the persisted `stage`, which races: navigating same-tab into the
  //      exam lets the persist effect overwrite stage back to 'identity'.
  //   3. an otherwise-resumable saved stage
  const initedRef = useRef(false);
  useEffect(() => {
    if (initedRef.current) return;
    initedRef.current = true;
    let target;
    if (step && SLUG_TO_STAGE[step]) {
      target = SLUG_TO_STAGE[step];
    } else if (saved && saved.testStartedAt > 0 && !saved.testTaken) {
      target = STAGE.WAIT_TEST;
    } else if (saved && saved.stage && RESUMABLE.includes(saved.stage)) {
      target = saved.stage;
    } else {
      target = STAGE.IDENTITY;
    }
    if (target === STAGE.WAIT_TEST) {
      navigate(slugPath(STAGE.WAIT_TEST), { replace: true }); // resolves → CONSULT, which rebuilds
    } else if (target === STAGE.DONE) {
      navigate(slugPath(STAGE.IDENTITY), { replace: true });  // never resume a finalized booking
    } else {
      rebuildTo(target);
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Persist the in-progress lead + current stage so a reload/return resumes exactly
  // here. DONE is finalized — submit() already erased the key, so don't re-write it.
  // NOTE: resume keys off testStartedAt/testTaken (above), not `stage` — so the brief
  // window where this writes stage:'identity' while redirecting into the test is benign.
  useEffect(() => {
    if (stage === STAGE.DONE || finalizedRef.current) return; // never resurrect a finalized lead
    try { localStorage.setItem(LS_KEY, JSON.stringify({ ...data, stage })); } catch (e) { /* ignore */ }
  }, [data, stage]);

  // A finalized session must stay on /done. Browser Back off /done re-renders an intact
  // in-memory `data` at an earlier step (localStorage was cleared on finalize, but React
  // state survives the same-mount route change) — without this the user could walk forward
  // to Review and Confirm again. The CF is idempotent on the doc, but re-fires notifications.
  useEffect(() => {
    if (finalizedRef.current && stage !== STAGE.DONE) navigate(slugPath(STAGE.DONE), { replace: true });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [stage]);

  // Read + cache the email feature flag on mount (config/featureFlag).
  const emailFlagRef = useRef(false);
  useEffect(() => { getEmailNotifyFlag().then((v) => { emailFlagRef.current = v; }); }, []);

  // Warm the reCAPTCHA Enterprise script on mount so token minting at submit is instant.
  useEffect(() => { preloadRecaptcha(); }, []);

  // Fire-and-forget early lead capture (lead_booking/{candidateId}, status 'pending')
  // so an abandoned booking is still a reachable lead. Idempotent server-side; never blocks
  // the UI. `createConsultationLead` reconciles this same doc on finalize via candidateId.
  const firePending = (lead) => {
    if (!(lead.name && lead.phone && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(lead.email || ''))) return;
    savePendingLead({
      candidateId: lead.candidateId, name: lead.name, email: lead.email,
      phone: lead.phone, dob: lead.dob, path: lead.path,
    }).catch((e) => { try { console.warn('[booking] pending lead failed:', e && e.message); } catch (_) {} });
  };

  const handleTest = (identity) => {
    // Already submitted a placement test this session → don't let them re-take it;
    // jump straight to consult. (Belt-and-suspenders; the button is also disabled.)
    if (data.testTaken || hasFreshPlacementSubmission(data.testStartedAt || 0)) {
      setData((d) => ({ ...d, ...identity }));
      rebuildTo(STAGE.CONSULT);
      return;
    }
    const candidateId = data.candidateId || genCandidateId();
    const lead = { ...data, ...identity, path: 'test', candidateId, testStartedAt: Date.now() };
    setData(lead);
    firePending(lead);
    if (onTakeTest) { onTakeTest(lead); return; }
    // Persist first, then redirect SAME-TAB into the placement test (no new tab):
    // the ExamCompleteModal auto-returns to /booking/test on submit, where we resume
    // and resolve the submission breadcrumb. Info carries via ?prefill= (no retyping).
    try { localStorage.setItem(LS_KEY, JSON.stringify({ ...lead, stage: STAGE.WAIT_TEST })); } catch (e) { /* ignore */ }
    // `_source: 'booking'` tells the exam's InformationCollect that identity was
    // already collected on /booking — it skips its own StudentInfo form (the merge).
    // Canonical identity for the cross-app prefill (see lead_intake_fields.schema.json):
    // the exam's InformationCollect reads `fullName` (legacy `name` only as a fallback),
    // so we emit `fullName` alone — no alias. Booking's OWN lead_booking storage keeps
    // `name` (its subsystem); the CRM bridge canonicalizes that to candidate.fullName.
    const prefill = toPrefillParam({
      fullName: lead.name, email: lead.email,
      dob: lead.dob, phone: lead.phone, candidateId, _source: 'booking',
    });
    window.location.assign('/?prefill=' + encodeURIComponent(prefill));
  };
  const handleConsult = (identity) => {
    const candidateId = data.candidateId || genCandidateId();
    const lead = { ...data, ...identity, path: data.testTaken ? 'test' : 'consult', candidateId };
    setData(lead);
    firePending(lead);
    go(STAGE.CONSULT);
  };

  const submit = async () => {
    if (finalizedRef.current) { navigate(slugPath(STAGE.DONE), { replace: true }); return; } // already booked
    setBusy(true);
    try {
      // Finalized only when the CF resolves (lead doc written + notifications fired).
      await submitBooking({ ...data, emailNotification: emailFlagRef.current });
      finalizedRef.current = true; // lock the flow before clearing artifacts / navigating
      clearBookingArtifacts(); // erase the in-progress flag + the test breadcrumb
      navigate(slugPath(STAGE.DONE), { replace: true }); // replace REVIEW so Back doesn't return to a submitted form
    } finally {
      setBusy(false);
    }
  };

  return (
    <div className="wv-booking">
      <div className="wv-glow" aria-hidden />
      <div className="wv-page">
        <AnimatePresence mode="wait">
          <motion.div key={stage} {...fade} className="wv-stage">
            {stage === STAGE.IDENTITY && (
              <IdentityForm initial={data} examTaken={examTaken} onTest={handleTest} onConsult={handleConsult} />
            )}
            {stage === STAGE.WAIT_TEST && (
              <TestWait
                since={data.testStartedAt || 0}
                onDetected={(submissionId) => { clearSubmissionBreadcrumb(); setData((d) => ({ ...d, testTaken: true, submissionId, path: 'test', testStartedAt: 0 })); rebuildTo(STAGE.CONSULT); }}
                onContinue={() => { clearSubmissionBreadcrumb(); setData((d) => ({ ...d, testTaken: true, testStartedAt: 0 })); rebuildTo(STAGE.CONSULT); }}
                onSkip={() => { clearSubmissionBreadcrumb(); setData((d) => ({ ...d, testStartedAt: 0 })); rebuildTo(STAGE.CONSULT); }}
              />
            )}
            {stage === STAGE.CONSULT && (
              <ConsultForm
                initial={data.profile}
                onBack={back}
                onNext={(profile) => { setData((d) => ({ ...d, profile })); go(STAGE.DATES); }}
              />
            )}
            {stage === STAGE.DATES && (
              <DatePicker
                initial={data.dates}
                onBack={back}
                onNext={(dates) => { setData((d) => ({ ...d, dates })); go(STAGE.SLOTS); }}
              />
            )}
            {stage === STAGE.SLOTS && (
              <SlotPicker
                initial={data.slot}
                onBack={back}
                onNext={(slot) => { setData((d) => ({ ...d, slot })); go(STAGE.REVIEW); }}
              />
            )}
            {stage === STAGE.REVIEW && (
              <Review data={data} busy={busy} onBack={back} onSubmit={submit} />
            )}
            {stage === STAGE.DONE && <ThankYou data={data} />}
          </motion.div>
        </AnimatePresence>
      </div>
    </div>
  );
}
