import React from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";
import { INLINE_BLANK_TOKEN } from "../../../utils/question/questionTokens";
import BlankAnswerList from "../shared/BlankAnswerList";

const InlineBlankBuilder = () => {
  const {
    question,
    inlineFieldId,
    addInlineBlank,
    handleInlineTemplateChange,
  } = useQuestionContext();

  return (
    <div className="space-y-4">
      <div className="space-y-2">
        <div className="flex items-center justify-between">
          <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Sentence with blank
          </label>
          <button
            type="button"
            onClick={addInlineBlank}
            className="text-xs font-semibold text-blue-600 hover:text-blue-700"
          >
            + Add blank
          </button>
        </div>
        <textarea
          id={inlineFieldId}
          value={question?.inlineTemplate || ""}
          onChange={(event) => handleInlineTemplateChange(event.target.value)}
          rows={3}
          placeholder={`Write the sentence and click "Add blank" to insert ${INLINE_BLANK_TOKEN}`}
          className="min-h-[96px] w-full rounded-xl border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
        />
        <p className="text-[11px] text-slate-500">
          Use <span className="font-mono">{INLINE_BLANK_TOKEN}</span> wherever the learner should enter an answer.
        </p>
      </div>

      <div>
        <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
          Correct answer(s)
        </label>
        <BlankAnswerList />
      </div>
    </div>
  );
};

export default InlineBlankBuilder;
