import React, { useState, useRef, useCallback } from "react";

const ResizableSplit = ({ left, right, initialPercent = 50, minPercent = 25, maxPercent = 75 }) => {
  const [percent, setPercent] = useState(initialPercent);
  const containerRef = useRef(null);
  const isDragging = useRef(false);

  const handleMouseDown = useCallback((e) => {
    e.preventDefault();
    isDragging.current = true;
    document.body.style.userSelect = "none";
    document.body.style.cursor = "col-resize";
  }, []);

  const handleMouseMove = useCallback((e) => {
    if (!isDragging.current || !containerRef.current) return;
    const rect = containerRef.current.getBoundingClientRect();
    const newPercent = ((e.clientX - rect.left) / rect.width) * 100;
    setPercent(Math.min(maxPercent, Math.max(minPercent, newPercent)));
  }, [minPercent, maxPercent]);

  const handleMouseUp = useCallback(() => {
    isDragging.current = false;
    document.body.style.userSelect = "";
    document.body.style.cursor = "";
  }, []);

  React.useEffect(() => {
    document.addEventListener("mousemove", handleMouseMove);
    document.addEventListener("mouseup", handleMouseUp);
    return () => {
      document.removeEventListener("mousemove", handleMouseMove);
      document.removeEventListener("mouseup", handleMouseUp);
    };
  }, [handleMouseMove, handleMouseUp]);

  return (
    <>
      <div className="flex flex-col md:hidden w-full gap-4">
        <div className="w-full">{left}</div>
        <div className="w-full">{right}</div>
      </div>
      <div ref={containerRef} className="hidden md:flex w-full gap-0 select-none h-full">
        <div style={{ width: `${percent}%` }} className="min-w-0 h-full">
          {left}
        </div>
        <div
          onMouseDown={handleMouseDown}
          className="w-1.5 cursor-col-resize bg-gray-200 hover:bg-blue-400 active:bg-blue-500 transition-colors rounded-sm flex-shrink-0"
        />
        <div style={{ width: `${100 - percent}%` }} className="min-w-0 h-full">
          {right}
        </div>
      </div>
    </>
  );
};

const WritingSection = ({
  sectionKey,
  section,
  answers = {},
  onAnswerChange,
  examName = "",
}) => {
  // No rich text editor required. Using plain textarea inputs for writing tasks.
  if (!section) {
    return (
      <div className="flex h-full items-center justify-center bg-white">
        <p className="text-sm text-gray-500">
          Writing content is not available for this exam.
        </p>
      </div>
    );
  }

  return (
    <>
      {/* Using simple textarea; removed rich text editor styles */}
      <div className="flex h-full flex-col overflow-hidden bg-white">
        {/* Scrollable Content */}
        <div
          className="flex-1 overflow-y-auto bg-white relative"
          data-highlight-surface-id="writing-content-surface"
        >
          {/* Header - scrolls with content */}
          <div className="border-b border-gray-200 bg-white px-3 py-2">
            <h2 className="text-base font-bold text-blue-950 text-center uppercase">{examName || section.title}</h2>
            {section.intro && <p className="text-xs text-gray-600 mt-0.5 text-center">{section.intro}</p>}
          </div>

          <div className="space-y-6 px-5 py-5">

            {section.tasks?.map((task, index) => {
              const answerValue = answers[task.id] || "";
              const wordCount = getWordCount(answerValue);
              const minWords = Number(task.minimumWords) || 0;
              const isShort = minWords > 0 && minWords <= 40;
              const imageSrc = task.imageUrl || task.imagePreviewUrl || "";

              return (
                <article
                  key={task.id}
                  id={`question-${sectionKey}-${task.id}`}
                  className="flex flex-col gap-4 rounded-lg border border-gray-200 bg-white px-6 py-5 shadow-sm min-h-[400px]"
                  tabIndex={-1}
                >
                  {/* Task Header */}
                  <header className="flex flex-wrap items-center justify-between gap-3">
                    <div className="flex-1 w-full">
                      {!task.title && (
                        <p className="text-xs uppercase tracking-wide font-semibold text-gray-500">
                          Writing Task {index + 1}
                        </p>
                      )}
                      {task.title && (
                        <div
                          className="text-base font-semibold text-gray-900 uppercase"
                          dangerouslySetInnerHTML={{ __html: task.title }}
                        />
                      )}
                    </div>
                    <div className="flex items-center gap-3 text-xs text-gray-500 pt-1">
                      {minWords > 0 && (
                        <span className="rounded-full bg-orange-50 px-2 py-1 font-semibold text-orange-600 border border-orange-100">
                          Minimum: {minWords} words
                        </span>
                      )}
                      <span className="rounded-full bg-blue-50 px-2 py-1 font-semibold text-blue-700 border border-blue-100">
                        Words: {wordCount}
                      </span>
                    </div>
                  </header>

                  <div className={`flex flex-col w-full flex-1 gap-4`}>
                    {/* Prompt at the top for all tasks */}
                    {task.prompt && (
                      <div
                        className="w-full text-base text-gray-900 mb-4"
                        dangerouslySetInnerHTML={{ __html: task.prompt }}
                      />
                    )}

                    {/* Topics Table for Choice Tasks */}
                    {task.topics && task.topics.length > 0 && (
                      <div className="w-full h-auto border border-gray-200 rounded-md overflow-x-auto">
                        <table className="min-w-full divide-y divide-gray-300">
                          <thead className="bg-gray-50 sticky top-0 z-10">
                            <tr>
                              <th scope="col" className="py-3.5 pl-4 pr-3 text-center text-xs font-semibold text-gray-900 border-r border-gray-300 w-12">
                                #
                              </th>
                              <th scope="col" className="px-3 py-3.5 text-left text-xs font-semibold text-gray-900">
                                Topic
                              </th>
                            </tr>
                          </thead>
                          <tbody className="divide-y divide-gray-200 bg-white">
                            {task.topics.map((topic) => (
                              <tr key={topic.number}>
                                <td className="whitespace-nowrap py-3 pl-4 pr-3 text-xs font-bold text-gray-900 border-r border-gray-300 w-12 text-center align-top">
                                  {topic.number}
                                </td>
                                <td className="px-3 py-3 text-xs text-gray-700 align-top leading-relaxed">
                                  {topic.text}
                                </td>
                              </tr>
                            ))}
                          </tbody>
                        </table>
                      </div>
                    )}

                    {/* Topic Selection Input */}
                    {task.requireTopicSelection && task.topics && (
                      <div id={`question-${sectionKey}-${task.id}_topic`} className="flex items-center gap-4 py-2">
                        <span className="text-sm font-semibold italic text-gray-800">
                          The topic I chose:
                        </span>
                        <div className="flex items-center gap-4">
                          {task.topics.map((topic) => (
                            <label key={topic.number} className="flex items-center gap-2 cursor-pointer">
                              <input
                                type="radio"
                                name={`topic-selection-${task.id}`}
                                value={topic.number}
                                checked={answers[`${task.id}_topic`] === String(topic.number)}
                                onChange={(e) => {
                                  const val = e.target.value;
                                  onAnswerChange?.(sectionKey, `${task.id}_topic`, val);
                                }}
                                className="h-4 w-4 border-gray-300 text-blue-600 focus:ring-blue-600"
                              />
                              <span className="text-sm text-gray-700 font-medium">{topic.number}</span>
                            </label>
                          ))}
                        </div>
                      </div>
                    )}

                    {imageSrc ? (
                      <ResizableSplit
                        initialPercent={50}
                        minPercent={30}
                        maxPercent={70}
                        left={
                          <div className="flex flex-col w-full h-full space-y-1 pr-3 md:pr-3">
                            {task.topicTitle && (
                              <div
                                className="text-sm font-semibold text-gray-900"
                                dangerouslySetInnerHTML={{ __html: task.topicTitle }}
                              />
                            )}
                            {task.instructions && (
                              <div
                                className="text-sm text-gray-600 italic"
                                dangerouslySetInnerHTML={{ __html: task.instructions }}
                              />
                            )}
                            <div className="flex w-full items-center justify-center overflow-hidden rounded-lg border border-gray-200 bg-gray-50">
                              <img
                                src={imageSrc}
                                alt={task.title ? stripHtmlTags(task.title) : `Writing task ${index + 1}`}
                                className="max-h-[65vh] max-w-full object-contain"
                              />
                            </div>
                          </div>
                        }
                        right={
                          <div className="flex flex-col w-full h-full pl-3">
                            {isShort ? (
                              <input
                                type="text"
                                className="rounded-lg bg-white border border-gray-200 p-3 w-full"
                                value={answerValue}
                                onChange={(e) => {
                                  const val = e.target.value;
                                  try { console.debug('✍️ Writing input onChange', { sectionKey, questionId: task.id, len: String(val || '').length, preview: String(val || '').slice(0, 120) }); } catch (e) { }
                                  onAnswerChange?.(sectionKey, task.id, val);
                                }}
                                onBlur={(e) => {
                                  try {
                                    const val = e.target.value;
                                    console.debug('✍️ Writing input onBlur', { questionId: task.id, len: String(val || '').length, preview: String(val || '').slice(0, 120) });
                                    onAnswerChange?.(sectionKey, task.id, val);
                                  } catch (err) {
                                    console.warn('Writing input onBlur error', err);
                                  }
                                }}
                                aria-label={`Short answer for writing task ${index + 1}`}
                              />
                            ) : (
                              <textarea
                                className="grow w-full rounded-lg bg-white border border-gray-200 p-3 min-h-[220px] resize-none box-border"
                                value={answerValue}
                                placeholder={`Please write at least ${minWords} words...`}
                                onChange={(e) => {
                                  const val = e.target.value;
                                  try { console.debug('✍️ Writing textarea onChange', { sectionKey, questionId: task.id, len: String(val || '').length, preview: String(val || '').slice(0, 120) }); } catch (e) { }
                                  onAnswerChange?.(sectionKey, task.id, val);
                                }}
                                onBlur={(e) => {
                                  try {
                                    const val = e.target.value;
                                    console.debug('✍️ Writing textarea onBlur', { questionId: task.id, len: String(val || '').length, preview: String(val || '').slice(0, 120) });
                                    onAnswerChange?.(sectionKey, task.id, val);
                                  } catch (err) {
                                    console.warn('Writing textarea onBlur error', err);
                                  }
                                }}
                                aria-label={`Answer for writing task ${index + 1}`}
                              />
                            )}
                          </div>
                        }
                      />
                    ) : (
                      <div className="flex flex-col gap-3 w-full">
                        <div className="space-y-1">
                          {task.topicTitle && (
                            <div
                              className="text-sm font-semibold text-gray-900"
                              dangerouslySetInnerHTML={{ __html: task.topicTitle }}
                            />
                          )}
                          {task.instructions && (
                            <div
                              className="text-sm text-gray-600 italic"
                              dangerouslySetInnerHTML={{ __html: task.instructions }}
                            />
                          )}
                        </div>
                        {isShort ? (
                          <input
                            type="text"
                            className="rounded-lg bg-white border border-gray-200 p-3 w-full"
                            value={answerValue}
                            onChange={(e) => {
                              const val = e.target.value;
                              try { console.debug('✍️ Writing input onChange', { sectionKey, questionId: task.id, len: String(val || '').length, preview: String(val || '').slice(0, 120) }); } catch (e) { }
                              onAnswerChange?.(sectionKey, task.id, val);
                            }}
                            onBlur={(e) => {
                              try {
                                const val = e.target.value;
                                console.debug('✍️ Writing input onBlur', { questionId: task.id, len: String(val || '').length, preview: String(val || '').slice(0, 120) });
                                onAnswerChange?.(sectionKey, task.id, val);
                              } catch (err) {
                                console.warn('Writing input onBlur error', err);
                              }
                            }}
                            aria-label={`Short answer for writing task ${index + 1}`}
                          />
                        ) : (
                          <textarea
                            className="grow w-full rounded-lg bg-white border border-gray-200 p-3 min-h-[220px] resize-vertical box-border"
                            value={answerValue}
                            placeholder={`Please write at least ${minWords} words...`}
                            onChange={(e) => {
                              const val = e.target.value;
                              try { console.debug('✍️ Writing textarea onChange', { sectionKey, questionId: task.id, len: String(val || '').length, preview: String(val || '').slice(0, 120) }); } catch (e) { }
                              onAnswerChange?.(sectionKey, task.id, val);
                            }}
                            onBlur={(e) => {
                              try {
                                const val = e.target.value;
                                console.debug('✍️ Writing textarea onBlur', { questionId: task.id, len: String(val || '').length, preview: String(val || '').slice(0, 120) });
                                onAnswerChange?.(sectionKey, task.id, val);
                              } catch (err) {
                                console.warn('Writing textarea onBlur error', err);
                              }
                            }}
                            aria-label={`Answer for writing task ${index + 1}`}
                          />
                        )}
                      </div>
                    )}
                  </div>
                </article>
              );
            })}
          </div>
        </div>
      </div>
    </>
  );
};


function stripHtmlTags(input) {
  if (input == null) return "";
  // Ensure input is a string before applying replace
  const str = typeof input === "string" ? input : String(input);
  return str.replace(/<[^>]+>/g, " ");
}

function getWordCount(content) {
  const text = stripHtmlTags(content)
    .replace(/\s+/g, " ")
    .trim();
  if (!text) return 0;
  return text.split(" ").length;
}

export default WritingSection;
