import React, { useMemo } from "react";
import QuestionCard from "../Question/QuestionCard";
import { cloneDefaultOptions } from "../../../../utils/question/questionUtils";
import { getQuestionSlotCount } from "../../../../utils/question/questionMetrics";
import { DEFAULT_MATCHING_HEADING_TITLE } from "../../../../utils/question/questionDefaults";
import { generateId } from "../../../../utils/question/idUtils";
import { useNumbering } from "../../../../contexts/NumberingContext";

const createBaseQuestion = () => ({
  id: generateId("GQ"),
  type: "multiple-choice",
  inputMode: "radio",
  description: "",
  prompt: "",
  placeholder: "",
  options: cloneDefaultOptions(),
  correctAnswers: [],
  inlineTemplate: "",
  subQuestions: [],
  matchingHeadingListTitle: DEFAULT_MATCHING_HEADING_TITLE,
  matchingHeadingItems: ["", "", ""],
  matchingHeadingAnswers: ["", "", ""],
});

const ensureArray = (value) => (Array.isArray(value) ? value : []);

function GrammarBuilder({
  data,
  onChange,
  sectionKey = "grammar",
}) {
  const grammar = useMemo(
    () => ({
      title: "",
      intro: "",
      timeAllotted: "",
      questions: [],
      ...data,
    }),
    [data]
  );

  const applyUpdate = (updates) => {
    onChange({
      ...grammar,
      ...updates,
    });
  };

  const updateQuestions = (updater) => {
    const current = ensureArray(grammar.questions);
    const next = typeof updater === "function" ? updater(current) : updater;
    applyUpdate({ questions: next });
  };

  const handleSectionFieldChange = (field, value) => {
    applyUpdate({ [field]: value });
  };

  const handleAddQuestion = () => {
    updateQuestions((questions) => [...questions, createBaseQuestion()]);
  };

  const handleRemoveQuestion = (questionIndex) => {
    updateQuestions((questions) =>
      questions.filter((_, idx) => idx !== questionIndex)
    );
  };

  const handleDuplicateQuestion = (questionIndex) => {
    updateQuestions((questions) => {
      const target = questions[questionIndex];
      if (!target) return questions;
      const clone = {
        ...target,
        id: generateId("GQ"),
        prompt: target.prompt || "",
      };
      return [
        ...questions.slice(0, questionIndex + 1),
        clone,
        ...questions.slice(questionIndex + 1),
      ];
    });
  };

  const handleQuestionChange = (questionIndex, patchOrUpdater, value) => {
    updateQuestions((questions) =>
      questions.map((question, qIdx) => {
        if (qIdx !== questionIndex) return question;
        if (typeof patchOrUpdater === "function") {
          const next = patchOrUpdater(question);
          return next || question;
        }
        if (patchOrUpdater && typeof patchOrUpdater === "object") {
          return { ...question, ...patchOrUpdater };
        }
        if (typeof patchOrUpdater === "string") {
          return { ...question, [patchOrUpdater]: value };
        }
        return question;
      })
    );
  };

  const { getQuestionNumber } = useNumbering();

  return (
    <div className="space-y-8">
      <section className="space-y-4 rounded-2xl border border-slate-200 bg-white p-5">
        <div className="grid gap-6 md:grid-cols-2">
          <div>
            <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              Section title
            </label>
            <input
              type="text"
              value={grammar.title}
              onChange={(event) => handleSectionFieldChange("title", event.target.value)}
              className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              placeholder="Grammar & Vocabulary"
            />
          </div>
          <div>
            <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              Time allotted
            </label>
            <input
              type="text"
              value={grammar.timeAllotted}
              onChange={(event) => handleSectionFieldChange("timeAllotted", event.target.value)}
              className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              placeholder="e.g., 15 minutes"
            />
          </div>
        </div>

        <div>
          <label className="text-xs font-semibold uppercase tracking-wide text-slate-500">
            Introduction / Instructions
          </label>
          <textarea
            value={grammar.intro}
            onChange={(event) => handleSectionFieldChange("intro", event.target.value)}
            rows={3}
            className="mt-1 w-full rounded-xl border border-slate-200 px-4 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
            placeholder="Describe the focus of the section or add instructions..."
          />
        </div>

        <div className="flex items-center justify-between">
          <h3 className="text-lg font-semibold text-slate-900">Questions</h3>
          <button
            type="button"
            onClick={handleAddQuestion}
            className="rounded-lg border border-blue-200 px-3 py-1.5 text-sm font-medium text-blue-700 transition hover:bg-blue-50"
          >
            + Add question
          </button>
        </div>
      </section>

      <div className="space-y-3">
        {ensureArray(grammar.questions).map((question, questionIndex) => {
          const questionNumber = getQuestionNumber("grammar", null, question.id);

          return (
            <QuestionCard
              key={question.id || `question-${questionIndex}`}
              question={question}
              questionNumber={questionNumber}
              numberingPrefix={questionNumber}
              onChange={(updates) =>
                handleQuestionChange(questionIndex, updates)
              }
              sectionMeta={{
                sectionKey: sectionKey,
                type: "standalone",
                questionIndex,
              }}
              renderActions={() => (
                <div className="flex items-center gap-2">
                  <button
                    type="button"
                    onClick={() => handleDuplicateQuestion(questionIndex)}
                    className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
                  >
                    Duplicate
                  </button>
                  <button
                    type="button"
                    onClick={() => handleRemoveQuestion(questionIndex)}
                    className="rounded border border-rose-200 px-3 py-1 text-xs font-semibold text-rose-600 hover:bg-rose-50"
                  >
                    Remove
                  </button>
                </div>
              )}
            />
          );
        })}
      </div>
    </div>
  );
}

export default GrammarBuilder;
