import { useMemo, useState, useEffect, useRef } from "react";

const useListeningParts = (
  section,
  sectionKey,
  restoredForThisSection,
  isPreviewMode,
  reviewMode,
  onActivePartChange,
  onListeningPartStateChange,
  audioTimestampsRef,
  pendingSeekRef,
  restoreVersion = 0
) => {
  const audioParts = useMemo(() => {
    if (!section?.questionGroups) return [];
    const parts = [];
    section.questionGroups.forEach((group) => {
      if (group.title && group.audioUrl) {
        parts.push({
          id: group.id,
          title: group.title,
          audioUrl: group.audioUrl,
        });
      }
    });
    return parts;
  }, [section?.questionGroups]);

  const [activePartIndex, setActivePartIndex] = useState(
    restoredForThisSection?.activePartIndex ?? 0
  );

  const [completedParts, setCompletedParts] = useState(
    Array.isArray(restoredForThisSection?.completedParts)
      ? restoredForThisSection.completedParts
      : []
  );

  const currentAudioUrl =
    audioParts.length > 0
      ? audioParts[activePartIndex]?.audioUrl
      : section?.questionGroups?.[0]?.audioUrl;

  const isPartLocked = (index) => {
    if (isPreviewMode || reviewMode) return false;
    if (index === 0) return false;
    return !completedParts.includes(index - 1);
  };

  const pushEnabledRef = useRef(false);

  // Wait 200ms before allowing pushes so the restore-sync effect can
  // fire first and set correct state. Without this, the initial
  // zero-state push overwrites parent state before restore data arrives.
  useEffect(() => {
    const timer = setTimeout(() => {
      pushEnabledRef.current = true;
    }, 200);
    return () => clearTimeout(timer);
  }, []);

  // Sync from restore data when it arrives after initial mount (e.g. F5 + autosave restore).
  // State (activePartIndex, completedParts) is only applied on a REAL restore.
  // On echo syncs (from our own pushes), only the audioTimestampsRef is updated
  // — calling setState with new array refs for completedParts causes re-renders
  // which trigger more pushes, creating a flicker loop.
  //
  // Real-vs-echo discrimination uses two signals:
  //   1. `isFirstEffectRun` — first effect run with non-null data IS a real
  //      restore (parent delivered the data synchronously before mount, e.g.
  //      via `proceedStartExam` batched with `setIsWelcomeScreenVisible(false)`).
  //   2. `versionChanged` — parent bumped `restoreVersion`, indicating a
  //      post-mount restore from the autosave modal direct path (where
  //      ListeningSection was already mounted with empty `listeningPartState`
  //      when the user clicked RESTORE).
  // Anything else (data arriving after a null tick, with no version bump) is
  // by causality a push echo — our own state coming back via the parent.
  const restoredSnapshotRef = useRef("");
  const initialRestoreDoneRef = useRef(false);
  const isFirstEffectRunRef = useRef(true);
  const lastRestoreVersionRef = useRef(restoreVersion);
  useEffect(() => {
    const isFirstEffectRun = isFirstEffectRunRef.current;
    isFirstEffectRunRef.current = false;

    if (!restoredForThisSection) return;
    const snap = JSON.stringify(restoredForThisSection);
    if (restoredSnapshotRef.current === snap) return;

    const versionChanged = restoreVersion !== lastRestoreVersionRef.current;
    lastRestoreVersionRef.current = restoreVersion;
    const isFirstRestore = isFirstEffectRun || versionChanged;
    restoredSnapshotRef.current = snap;

    if (isFirstRestore) {
      setActivePartIndex(restoredForThisSection.activePartIndex ?? 0);
      if (Array.isArray(restoredForThisSection.completedParts)) {
        setCompletedParts(restoredForThisSection.completedParts);
      }
    }

    // Always update the ref with latest timestamps (persists across echoes).
    const restored =
      restoredForThisSection.audioTimestamps ||
      (typeof restoredForThisSection.audioTimestamp === "number"
        ? { [restoredForThisSection.activePartIndex ?? 0]: restoredForThisSection.audioTimestamp }
        : null);
    if (restored && typeof restored === "object") {
      audioTimestampsRef.current = { ...audioTimestampsRef.current, ...restored };
    }

    if (isFirstRestore) {
      const seekTs = audioTimestampsRef.current[restoredForThisSection.activePartIndex ?? 0];
      if (typeof seekTs === "number" && seekTs > 0) {
        pendingSeekRef.current = seekTs;
      }
      initialRestoreDoneRef.current = true;
      console.log(
        "🎧 [Parts-Sync] Initial restore. activePartIndex:",
        restoredForThisSection.activePartIndex,
        "completedParts:",
        restoredForThisSection.completedParts,
        "seekTarget:",
        pendingSeekRef.current
      );
      // Direct push on initial restore to immediately populate parent state.
      if (onListeningPartStateChange) {
        const idx = restoredForThisSection.activePartIndex ?? 0;
        onListeningPartStateChange(sectionKey, {
          activePartIndex: idx,
          completedParts: Array.isArray(restoredForThisSection.completedParts)
            ? restoredForThisSection.completedParts
            : [],
          audioTimestamps: audioTimestampsRef.current,
          audioTimestamp: audioTimestampsRef.current[idx] ?? 0,
        });
      }
    } else {
      console.log(
        "🎧 [Parts-Sync] Echo — timestamps only. audioTimestamps:",
        restored
      );
    }
  }, [restoredForThisSection, onListeningPartStateChange, sectionKey, audioTimestampsRef, pendingSeekRef, restoreVersion]);

  // Notify parent whenever active part changes (for highlight context scoping)
  useEffect(() => {
    if (onActivePartChange) onActivePartChange(activePartIndex);
  }, [activePartIndex, onActivePartChange]);

  // Push listening part state changes upward for autosave persistence.
  // Delayed start: skips pushes for the first 200ms so restore-sync
  // can fire first and set correct state. The restore-sync effect
  // pushes directly, bypassing this guard.
  useEffect(() => {
    if (!onListeningPartStateChange) return;
    if (!pushEnabledRef.current) return;
    console.log(
      "🎧 [Parts-Push] sectionKey:",
      sectionKey,
      "activePartIndex:",
      activePartIndex,
      "completedParts:",
      completedParts,
      "audioTimestamps:",
      audioTimestampsRef.current
    );
    onListeningPartStateChange(sectionKey, {
      activePartIndex,
      completedParts,
      audioTimestamps: audioTimestampsRef.current,
      audioTimestamp: audioTimestampsRef.current[activePartIndex] ?? 0,
    });
  }, [
    activePartIndex,
    completedParts,
    sectionKey,
    onListeningPartStateChange,
    audioTimestampsRef,
  ]);

  return {
    activePartIndex,
    setActivePartIndex,
    completedParts,
    setCompletedParts,
    audioParts,
    currentAudioUrl,
    isPartLocked,
  };
};

export default useListeningParts;