import React from "react";

const Header = ({ onBack, onPreview, examCode, isSaving, isAISidebarOpen, isStructureSidebarOpen }) => {
  const currentPath = typeof window !== 'undefined' ? window.location.pathname : '';
  // Center the logo only on the exam, examp, information-collect and root routes
  const centerLogo = /^\/(examp|exam)(\/|$)|^\/$|^\/information-collect(\/|$)/.test(
    currentPath
  );

  // Calculate dynamic padding classes
  const getPaddingClasses = () => {
    if (centerLogo) return "px-6";

    // Base padding
    let classes = "py-3 transition-all duration-300 ";

    // Left padding (AI Sidebar - 420px)
    // Add extra spacing (24px) for aesthetics
    classes += isAISidebarOpen ? "pl-[444px] " : "pl-6 ";

    // Right padding (Structure Sidebar - 20rem/320px)
    // Add extra spacing (24px) for aesthetics
    classes += isStructureSidebarOpen ? "pr-[344px]" : "pr-6";

    return classes;
  };

  return (
    <header
      className="fixed top-0 left-0 right-0 z-app-header bg-white"
      style={{ boxShadow: "0 4px 4px -4px rgba(0, 0, 0, .2)" }}
    >
      <div
        className={
          centerLogo
            ? "flex w-full items-center justify-center py-1"
            : `relative flex w-full items-center justify-between ${getPaddingClasses()}`
        }
      >
        {/* Back Button - Left Side (next to AI sidebar) */}
        <div className="flex-shrink-0">
          {onBack && (
            <button
              type="button"
              onClick={onBack}
              className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-slate-50 px-6 py-2.5 text-sm font-semibold text-slate-700 shadow-sm transition hover:bg-slate-100 hover:border-slate-300"
            >
              <span className="text-base leading-none">&lt;</span>
              <span>Back to dashboard</span>
            </button>
          )}
        </div>

        {/* Logo - Center */}
        <div className="flex-1 flex justify-center">
          <img style={{ height: 'min(32px, 4vmin)' }} src="/assets/images/WE-BLACK.png" alt="Weaver Test Online" />
        </div>

        {/* Preview Button - Right Side (next to Exam Structure sidebar) */}
        <div className="flex-shrink-0">
          {onPreview && (
            <button
              type="button"
              onClick={onPreview}
              disabled={isSaving || !examCode?.trim()}
              className="inline-flex items-center justify-center rounded-xl border border-slate-200 bg-slate-100 px-6 py-2.5 text-sm font-semibold text-slate-700 shadow-sm transition hover:bg-slate-200 hover:border-slate-300 disabled:opacity-50 disabled:cursor-not-allowed"
            >
              Preview exam
            </button>
          )}
        </div>
      </div>
    </header>
  );
};

export default Header;
