import React, { useMemo, useState } from "react";

const SECTION_LABELS = {
  listening: 'Listening',
  reading: 'Reading',
  grammar: 'Grammar & Vocabulary',
  writing: 'Writing',
  speaking: 'Speaking',
};

function AnswerRow({ questionId, answer }) {
  if (answer == null || answer === '') return null;

  if (Array.isArray(answer)) {
    if (answer.length === 0 || answer.every(a => a === '' || a == null)) return null;
  }

  const isBlob = answer && typeof answer === 'object' && !Array.isArray(answer) && (answer.blob || answer.url);

  // Make question IDs look prettier (e.g. question_1 -> Q1, EX1 -> Ex 1)
  const formatQID = (id) => {
    return id
      .replace(/question_/i, 'Q')
      .replace(/passage_(\d+)_q(\d+)/i, 'P$1-Q$2')
      .replace(/ex(\d+)/i, 'Ex $1')
      .toUpperCase();
  };

  const isLongForm = !isBlob && typeof answer === 'string' && String(answer).length > 80;
  let content = null;

  if (isBlob) {
    content = (
      <span className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-md bg-emerald-50 text-emerald-600 text-xs font-semibold shadow-sm border border-emerald-100">
        🎤 {answer.url ? 'Đã ghi âm' : 'Đang xử lý'}
      </span>
    );
  } else if (Array.isArray(answer)) {
    if (answer.length > 0 && typeof answer[0] === 'object' && answer[0] !== null && 'correction' in answer[0]) {
      content = (
        <div className="flex flex-wrap items-center justify-end gap-2">
          {answer.filter(a => a.correction).map((a, i) => (
            <div key={i} className="inline-flex items-center gap-2 px-2.5 py-1 rounded-md bg-rose-50 border border-rose-100 text-xs">
              <span className="text-slate-500 line-through decoration-slate-400">{a.error || '(trống)'}</span>
              <span className="text-rose-400 font-bold">→</span>
              <span className="text-rose-700 font-bold">{a.correction}</span>
            </div>
          ))}
        </div>
      );
    } else {
      content = (
        <div className="flex flex-wrap items-center justify-end gap-1.5">
          {answer.map((a, i) => (
            <span key={i} className="px-2 py-1 bg-slate-100 border border-slate-200 text-slate-700 text-xs font-semibold rounded shadow-sm">
              {a === '' ? <span className="text-slate-400 italic">_</span> : a}
            </span>
          ))}
        </div>
      );
    }
  } else if (typeof answer === 'object') {
     content = <span className="text-xs font-mono text-slate-600 bg-slate-50 border border-slate-100 px-2 py-1 rounded shadow-sm break-all">{JSON.stringify(answer)}</span>;
  } else {
     const strVal = String(answer);
     if (isLongForm) {
       content = (
         <div className="w-full mt-2 bg-slate-50 border border-slate-200 shadow-inner rounded-xl p-4 text-sm text-slate-700 font-medium leading-relaxed whitespace-pre-wrap">
           {strVal}
         </div>
       );
     } else {
       content = <span className="text-sm border-b border-transparent text-slate-800 font-bold bg-slate-50 px-3 py-1 rounded-lg border-slate-200 shadow-sm">{strVal}</span>;
     }
  }

  return (
    <div className={`py-3 px-4 border-b border-slate-100 last:border-0 flex ${isLongForm ? 'flex-col items-start' : 'items-center justify-between'} gap-3 hover:bg-slate-50/70 transition-colors`}>
      <span className="text-[11px] font-bold text-slate-400 tracking-widest shrink-0 mt-0.5" title={questionId}>
        {formatQID(questionId)}
      </span>
      <div className={`${isLongForm ? 'w-full' : 'flex-1 flex justify-end text-right'}`}>
        {content}
      </div>
    </div>
  );
}

function SectionBlock({ sectionKey, answers }) {
  const [expanded, setExpanded] = useState(true);

  if (!answers || typeof answers !== 'object') return null;

  const entries = Object.entries(answers).filter(([, v]) => {
    if (v == null || v === '') return false;
    if (Array.isArray(v)) return v.some(val => val !== '' && val != null && !(typeof val === 'object' && !val.correction));
    return true;
  });

  if (entries.length === 0) return null;

  return (
    <div className="border border-slate-200 rounded-lg overflow-hidden">
      <button
        className="w-full flex items-center justify-between px-4 py-2.5 bg-slate-50 hover:bg-slate-100 transition-colors text-left"
        onClick={() => setExpanded(e => !e)}
      >
        <div className="flex items-center gap-2">
          <span className="text-sm font-semibold text-slate-700 capitalize">
            {SECTION_LABELS[sectionKey] || sectionKey}
          </span>
          <span className="text-xs text-slate-400">
            {entries.length} câu
          </span>
        </div>
        <svg
          className={`h-4 w-4 text-slate-400 transition-transform ${expanded ? 'rotate-180' : ''}`}
          fill="none" viewBox="0 0 24 24" stroke="currentColor"
        >
          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
        </svg>
      </button>

      {expanded && (
        <div className="max-h-64 overflow-y-auto">
          {entries.map(([qId, ans]) => (
            <AnswerRow key={qId} questionId={qId} answer={ans} />
          ))}
        </div>
      )}
    </div>
  );
}

const RecoverySuccessModal = ({ isOpen, recoveredResult, onConfirm }) => {
  const sectionBlocks = useMemo(() => {
    if (!recoveredResult?.answers) return [];
    return Object.entries(recoveredResult.answers)
      .map(([key, answers]) => ({ key, answers }))
      .filter(({ answers }) => answers && typeof answers === 'object' && Object.values(answers).some(v => v != null && v !== ''));
  }, [recoveredResult]);

  if (!isOpen || !recoveredResult) return null;

  return (
    <div className="fixed inset-0 z-alert-recovery flex items-center justify-center bg-black/50 p-4 backdrop-blur-sm">
      <div className="w-full max-w-2xl rounded-2xl bg-white shadow-2xl flex flex-col max-h-[90vh]">

        {/* Header */}
        <div className="shrink-0 px-6 py-5 border-b border-slate-200">
          <div className="flex items-center gap-3 mb-2">
            <div className="flex h-10 w-10 items-center justify-center rounded-full bg-emerald-100 shrink-0">
              <svg className="h-5 w-5 text-emerald-600" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
              </svg>
            </div>
            <div>
              <h2 className="text-base font-semibold text-slate-900">
                Bài thi đã được gửi thành công
              </h2>
              <p className="text-xs text-slate-500">
                Tất cả câu trả lời đã được bảo toàn và gửi đi.
              </p>
            </div>
          </div>
          <div className="rounded-lg bg-amber-50 border border-amber-200 px-3 py-2 text-xs text-amber-800">
            Kết quả bài thi sẽ được thông báo sau. Vui lòng nhấn <strong>Xác nhận</strong> bên dưới để kết thúc.
          </div>
        </div>

        {/* Scrollable answer list */}
        <div className="flex-1 overflow-y-auto px-6 py-4 space-y-3">
          <p className="text-xs text-slate-400 mb-1">Dưới đây là các câu trả lời bạn đã nộp:</p>
          {sectionBlocks.length === 0 ? (
            <p className="text-sm text-slate-500 text-center py-4">Không tìm thấy dữ liệu câu trả lời.</p>
          ) : (
            sectionBlocks.map(({ key, answers }) => (
              <SectionBlock key={key} sectionKey={key} answers={answers} />
            ))
          )}
        </div>

        {/* Footer */}
        <div className="shrink-0 px-6 py-4 border-t border-slate-200">
          <button
            onClick={onConfirm}
            className="w-full rounded-lg bg-emerald-600 py-3 text-sm font-semibold text-white transition hover:bg-emerald-700"
          >
            Xác nhận
          </button>
        </div>

      </div>
    </div>
  );
};

export default RecoverySuccessModal;
