/**
 * reviewDomains — student-friendly labels mapped to canonical domain values.
 *
 * Source of truth for the canonical values: the 9-value cognitive enum in
 * TheWeaverWiki/schemas/testBank_index_schema.md § domain Values. The vote
 * doc stores `value` (canonical, machine-aggregable). The modal renders
 * `label` (plain English, no jargon).
 *
 * Never edit `value` strings — they must round-trip with testBank_index.domain
 * when the cron retags.
 */

export const DOMAINS_BY_CATEGORY = {
  Reading: [
    { value: 'Main Idea / Gist',          label: 'Tìm ý chính của một đoạn' },
    { value: 'Detail Identification',     label: 'Tìm đúng câu chứa thông tin' },
    { value: 'Inference',                 label: 'Xác định được ẩn ý' },
    { value: 'Paraphrase Detection',      label: 'Xác định được paraphrase' },
    { value: 'Matching & Classification', label: 'Ghép/Phân loại thông tin với nhau' },
    { value: 'Comparison',                label: 'So sánh thông tin với nhau' },
  ],
  Listening: [
    { value: 'Detail Identification',     label: 'Nghe được thông tin cụ thể' },
    { value: 'Paraphrase Detection',      label: 'Xác định được paraphrase' },
    { value: 'Speaker / Writer Attitude', label: "Xác định được sự thái độ của người nói (Cùng / Không cùng ý kiến với nhau)" },
    { value: 'Prediction & Anticipation', label: 'Theo được ngữ cảnh, khoanh vùng được thông tin' },
    { value: 'Phonological Decoding',     label: 'Nghe được những từ phát âm khó, ít gặp' },
  ],
};

/**
 * Returns the {value,label} array for a given category. Empty array for
 * unsupported categories (Writing, Speaking, Grammar, Vocabulary) — caller
 * should not render the domain section in those cases.
 */
export function getDomainsForCategory(category) {
  return DOMAINS_BY_CATEGORY[category] || [];
}

/**
 * v1 modal is gated to Reading/Listening only. Use this to decide whether
 * the modal should open at all (W/S/G/V categories bypass the modal).
 */
export const REVIEW_ENABLED_CATEGORIES = new Set(['Reading', 'Listening']);

export function isReviewEnabledForCategory(category) {
  return REVIEW_ENABLED_CATEGORIES.has(category);
}
