import React, { useCallback, useEffect, useMemo, useRef, useState } from "react";
import jspreadsheet from "jspreadsheet-ce";
import "jspreadsheet-ce/dist/jspreadsheet.css";
import "jsuites/dist/jsuites.css";

import { ensureGapFillTable } from "../../../utils/question/gapFillTable";
import { parseGapContent } from "../../../utils/question/gapFilling";

const coerceDisplayValue = (cell) => {
  if (cell === null || cell === undefined) {
    return "";
  }
  if (typeof cell === "string" || typeof cell === "number") {
    return String(cell);
  }
  if (typeof cell === "object") {
    if (typeof cell.m === "string") {
      return cell.m;
    }
    if (cell.v !== undefined && cell.v !== null) {
      return String(cell.v);
    }
  }
  return "";
};

const normalizeMatrix = (matrix) => {
  if (!Array.isArray(matrix) || matrix.length === 0) {
    return [];
  }

  const columnCount = matrix.reduce((max, row) => {
    if (!Array.isArray(row)) {
      return max;
    }
    return Math.max(max, row.length);
  }, 0);

  if (columnCount === 0) {
    return [];
  }

  return matrix.map((row = []) => {
    const normalizedRow = [];
    for (let columnIndex = 0; columnIndex < columnCount; columnIndex += 1) {
      normalizedRow.push(coerceDisplayValue(row[columnIndex]));
    }
    return normalizedRow;
  });
};

const columnIndexToName = (index) => {
  if (!Number.isInteger(index) || index < 0) {
    return "A";
  }

  let dividend = index + 1;
  let name = "";

  while (dividend > 0) {
    const modulo = (dividend - 1) % 26;
    name = String.fromCharCode(65 + modulo) + name;
    dividend = Math.floor((dividend - modulo) / 26);
  }

  return name;
};

const cellNameToCoords = (name) => {
  if (typeof name !== "string") {
    return null;
  }

  const match = name.toUpperCase().match(/^([A-Z]+)(\d+)$/);
  if (!match) {
    return null;
  }

  const [, letterPart, numberPart] = match;
  let columnIndex = 0;
  for (let index = 0; index < letterPart.length; index += 1) {
    columnIndex *= 26;
    columnIndex += letterPart.charCodeAt(index) - 64;
  }

  const rowIndex = Number.parseInt(numberPart, 10) - 1;
  if (!Number.isInteger(rowIndex) || rowIndex < 0) {
    return null;
  }

  return { x: columnIndex - 1, y: rowIndex };
};

const getSelectionRange = (instance, fallbackRange = null) => {
  if (!instance) {
    return fallbackRange;
  }

  if (instance.__lastSelectionRange) {
    const { xStart, xEnd, yStart, yEnd } = instance.__lastSelectionRange;
    return { xStart, xEnd, yStart, yEnd };
  }

  if (typeof instance.getSelection === "function") {
    const coords = instance.getSelection();
    if (Array.isArray(coords) && coords.length === 4) {
      const [x1, y1, x2, y2] = coords;
      return {
        xStart: Math.min(x1, x2),
        xEnd: Math.max(x1, x2),
        yStart: Math.min(y1, y2),
        yEnd: Math.max(y1, y2),
      };
    }

    if (typeof coords === "string") {
      const [startRef, endRef] = coords.split(":");
      const startCoords = cellNameToCoords(startRef || coords);
      const endCoords = cellNameToCoords(endRef || startRef || coords);

      if (startCoords && endCoords) {
        return {
          xStart: Math.min(startCoords.x, endCoords.x),
          xEnd: Math.max(startCoords.x, endCoords.x),
          yStart: Math.min(startCoords.y, endCoords.y),
          yEnd: Math.max(startCoords.y, endCoords.y),
        };
      }
    }
  }

  if (Array.isArray(instance.highlighted) && instance.highlighted.length) {
    const xs = instance.highlighted.map((cell) => cell.x);
    const ys = instance.highlighted.map((cell) => cell.y);
    return {
      xStart: Math.min(...xs),
      xEnd: Math.max(...xs),
      yStart: Math.min(...ys),
      yEnd: Math.max(...ys),
    };
  }

  return fallbackRange;
};

const readCellValue = (instance, x, y) => {
  if (!instance || x < 0 || y < 0) {
    return "";
  }

  try {
    if (typeof instance.getValueFromCoords === "function") {
      const value = instance.getValueFromCoords(x, y, false);
      return value === null || value === undefined ? "" : String(value);
    }

    if (typeof instance.getValue === "function") {
      const cellName = `${columnIndexToName(x)}${y + 1}`;
      const value = instance.getValue(cellName, false);
      return value === null || value === undefined ? "" : String(value);
    }
  } catch (error) {
    console.warn("Unable to read jspreadsheet cell", error);
  }

  const data = instance?.options?.data;
  if (Array.isArray(data) && Array.isArray(data[y])) {
    return coerceDisplayValue(data[y][x]);
  }

  return "";
};

const writeCellValue = (instance, x, y, value) => {
  if (!instance || x < 0 || y < 0) {
    return;
  }

  try {
    if (typeof instance.setValueFromCoords === "function") {
      instance.setValueFromCoords(x, y, value);
      return;
    }

    if (typeof instance.setValue === "function") {
      const cellName = `${columnIndexToName(x)}${y + 1}`;
      instance.setValue(cellName, value);
      return;
    }
  } catch (error) {
    console.warn("Unable to write jspreadsheet cell", error);
  }

  const data = instance?.options?.data;
  if (Array.isArray(data)) {
    if (!Array.isArray(data[y])) {
      data[y] = [];
    }
    data[y][x] = value;
    if (typeof instance.refresh === "function") {
      try {
        instance.refresh();
      } catch (refreshError) {
        console.warn("Unable to refresh jspreadsheet after manual write", refreshError);
      }
    }
  }
};

const toCellName = (x, y) => `${columnIndexToName(x)}${y + 1}`;

const stretchToContainer = (instance, container) => {
  if (!instance || !container) {
    return;
  }

  const candidateElements = [
    container,
    instance.element,
    instance.content,
  ];

  candidateElements.forEach((element) => {
    if (element) {
      element.style.width = "100%";
      element.style.height = "100%";
      element.style.maxHeight = "none";
    }
  });

  if (instance.table) {
    instance.table.style.width = "100%";
    instance.table.style.height = "100%";
    instance.table.style.maxHeight = "none";
  }

  const columnCount = instance.options?.columns?.length
    ?? instance.options?.data?.[0]?.length
    ?? 0;

  if (!columnCount) {
    return;
  }

  const headerOffset = 60;
  const availableWidth = Math.max(
    0,
    (instance.content?.clientWidth || container.clientWidth || 0) - headerOffset
  );

  if (availableWidth <= 0) {
    return;
  }

  const targetWidth = Math.max(80, Math.floor(availableWidth / columnCount));

  for (let columnIndex = 0; columnIndex < columnCount; columnIndex += 1) {
    try {
      instance.setWidth(columnIndex, targetWidth);
    } catch (error) {
      console.warn("Failed to stretch column", columnIndex, error);
      break;
    }
  }
};

const GapFillTableSpreadsheetEditor = ({
  isOpen,
  table,
  onCancel,
  onApply,
}) => {
  const normalizedTable = useMemo(() => ensureGapFillTable(table), [table]);
  const [caption, setCaption] = useState(normalizedTable.caption || "");
  const [loadError, setLoadError] = useState(null);
  const [isReady, setIsReady] = useState(false);
  const containerRef = useRef(null);
  const containerId = useMemo(
    () => `gap-fill-sheet-${Math.random().toString(36).slice(2, 9)}`,
    []
  );
  const spreadsheetRef = useRef(null);
  const selectionRef = useRef(null);
  const [toolbarState, setToolbarState] = useState({
    bold: false,
    italic: false,
    underline: false,
    align: "left",
    fontFamily: "Verdana",
    fontSize: "12px",
  });
  const [textColor, setTextColor] = useState("#000000");
  const [fillColor, setFillColor] = useState("#ffffff");

  const getFallbackRange = useCallback(
    () => selectionRef.current || { xStart: 0, xEnd: 0, yStart: 0, yEnd: 0 },
    []
  );

  const applyToSelection = useCallback(
    (visitor) => {
      const instance = spreadsheetRef.current;
      if (!instance || typeof visitor !== "function") {
        return null;
      }

      const fallbackRange = getFallbackRange();
      const range = getSelectionRange(instance, fallbackRange) || fallbackRange;
      if (!range) {
        return null;
      }

      for (let rowIndex = range.yStart; rowIndex <= range.yEnd; rowIndex += 1) {
        for (let columnIndex = range.xStart; columnIndex <= range.xEnd; columnIndex += 1) {
          const cellName = toCellName(columnIndex, rowIndex);
          visitor(instance, cellName, columnIndex, rowIndex);
        }
      }

      return range;
    },
    [getFallbackRange]
  );

  const applyStyleToSelection = useCallback(
    (property, value) => {
      if (!property) {
        return;
      }

      applyToSelection((instance, cellName) => {
        if (typeof instance.setStyle === "function") {
          instance.setStyle(cellName, property, value);
          return;
        }

        if (instance.parent && typeof instance.parent.setStyle === "function") {
          instance.parent.setStyle(cellName, property, value);
        }
      });
    },
    [applyToSelection]
  );

  const handleUndo = useCallback(() => {
    const instance = spreadsheetRef.current;
    if (!instance) {
      return;
    }

    if (typeof instance.undo === "function") {
      instance.undo();
      return;
    }

    if (instance.parent && typeof instance.parent.undo === "function") {
      instance.parent.undo();
    }
  }, []);

  const handleRedo = useCallback(() => {
    const instance = spreadsheetRef.current;
    if (!instance) {
      return;
    }

    if (typeof instance.redo === "function") {
      instance.redo();
      return;
    }

    if (instance.parent && typeof instance.parent.redo === "function") {
      instance.parent.redo();
    }
  }, []);

  const toggleStyle = useCallback(
    (key, property, activeValue, inactiveValue) => {
      setToolbarState((previous) => {
        const nextActive = !previous[key];
        applyStyleToSelection(property, nextActive ? activeValue : inactiveValue);
        return {
          ...previous,
          [key]: nextActive,
        };
      });
    },
    [applyStyleToSelection]
  );

  const handleAlign = useCallback(
    (value) => {
      applyStyleToSelection("textAlign", value);
      setToolbarState((previous) => ({
        ...previous,
        align: value,
      }));
    },
    [applyStyleToSelection]
  );

  const handleFontFamilyChange = useCallback(
    (event) => {
      const value = event?.target?.value || "";
      if (!value) {
        return;
      }
      applyStyleToSelection("fontFamily", value);
      setToolbarState((previous) => ({
        ...previous,
        fontFamily: value,
      }));
    },
    [applyStyleToSelection]
  );

  const handleFontSizeChange = useCallback(
    (event) => {
      const value = event?.target?.value || "";
      if (!value) {
        return;
      }
      const normalized = value.endsWith("px") ? value : `${value}px`;
      applyStyleToSelection("fontSize", normalized);
      setToolbarState((previous) => ({
        ...previous,
        fontSize: normalized,
      }));
    },
    [applyStyleToSelection]
  );

  const handleTextColorChange = useCallback(
    (event) => {
      const value = event?.target?.value || "#000000";
      setTextColor(value);
      applyStyleToSelection("color", value);
    },
    [applyStyleToSelection]
  );

  const handleFillColorChange = useCallback(
    (event) => {
      const value = event?.target?.value || "#ffffff";
      setFillColor(value);
      applyStyleToSelection("backgroundColor", value);
    },
    [applyStyleToSelection]
  );

  const handleClearFormatting = useCallback(() => {
    const defaults = {
      fontWeight: "normal",
      fontStyle: "normal",
      textDecoration: "none",
      textAlign: "left",
      color: "#000000",
      backgroundColor: "#ffffff",
      fontFamily: "Verdana",
      fontSize: "12px",
    };

    Object.entries(defaults).forEach(([property, value]) => {
      applyStyleToSelection(property, value);
    });

    setToolbarState((previous) => ({
      ...previous,
      bold: false,
      italic: false,
      underline: false,
      align: "left",
      fontFamily: "Verdana",
      fontSize: "12px",
    }));
    setTextColor("#000000");
    setFillColor("#ffffff");
  }, [applyStyleToSelection]);

  useEffect(() => {
    setCaption(normalizedTable.caption || "");
  }, [normalizedTable.caption]);

  const extractMatrix = useCallback(() => {
    const instance = spreadsheetRef.current;
    if (!instance) {
      return [];
    }

    try {
      if (typeof instance.getData === "function") {
        return normalizeMatrix(instance.getData());
      }

      if (typeof instance.getJson === "function") {
        const json = instance.getJson();
        if (Array.isArray(json?.data)) {
          return normalizeMatrix(json.data);
        }
      }

      if (Array.isArray(instance.options?.data)) {
        return normalizeMatrix(instance.options.data);
      }
    } catch (matrixError) {
      console.warn("Unable to extract jspreadsheet matrix", matrixError);
    }

    return [];
  }, []);

  useEffect(() => {
    if (!isOpen) {
      return undefined;
    }

    const container = containerRef.current;
    if (!container) {
      setLoadError("Spreadsheet container is not available.");
      return undefined;
    }

    let disposed = false;
    setIsReady(false);
    setLoadError(null);

    container.innerHTML = "";
    selectionRef.current = null;

    const sheetData = normalizedTable.rows.map((row) =>
      row.cells.map((cell) => (cell.isSpanned ? "" : cell.content || ""))
    );

    const mergeCellsOption = {};
    normalizedTable.rows.forEach((row, rowIndex) => {
      row.cells.forEach((cell, columnIndex) => {
        if (cell.isSpanned) {
          return;
        }

        const colSpan = Number.isInteger(cell.colSpan) && cell.colSpan > 1 ? cell.colSpan : 1;
        const rowSpan = Number.isInteger(cell.rowSpan) && cell.rowSpan > 1 ? cell.rowSpan : 1;

        if (colSpan > 1 || rowSpan > 1) {
          mergeCellsOption[toCellName(columnIndex, rowIndex)] = [colSpan, rowSpan];
        }
      });
    });

    const minimumRows = Math.max(sheetData.length, 10);
    const minimumColumns = Math.max(
      sheetData.reduce((max, row) => Math.max(max, row.length), 0),
      3
    );

    try {
      const handleWorksheetSelection = (_sheet, x1, y1, x2, y2) => {
        const xStart = Math.min(x1 ?? 0, x2 ?? x1 ?? 0);
        const xEnd = Math.max(x1 ?? 0, x2 ?? x1 ?? 0);
        const yStart = Math.min(y1 ?? 0, y2 ?? y1 ?? 0);
        const yEnd = Math.max(y1 ?? 0, y2 ?? y1 ?? 0);

        const range = { xStart, xEnd, yStart, yEnd };
        selectionRef.current = range;


        if (spreadsheetRef.current) {
          spreadsheetRef.current.__lastSelectionRange = range;
        }
      };

      const worksheetOptions = {
        data: sheetData,
        minDimensions: [minimumColumns, minimumRows],
        tableWidth: "100%",
        tableHeight: "100%",
        tableOverflow: true,
        allowInsertColumn: true,
        allowInsertRow: true,
        allowManualInsertColumn: true,
        allowManualInsertRow: true,
        columnDrag: true,
        rowDrag: true,
        rowResize: true,
        columnResize: true,
      };

      if (Object.keys(mergeCellsOption).length > 0) {
        worksheetOptions.mergeCells = mergeCellsOption;
      }

      const workbookOptions = {
        worksheets: [worksheetOptions],
        onselection: handleWorksheetSelection,
      };

      const instances = jspreadsheet(container, workbookOptions);

      const spreadsheetInstance = Array.isArray(instances) ? instances[0] : instances;
      const worksheetInstance = Array.isArray(spreadsheetInstance?.worksheets)
        ? spreadsheetInstance.worksheets[0]
        : spreadsheetInstance;

      if (!worksheetInstance) {
        throw new Error("Jspreadsheet did not return a worksheet instance.");
      }

      spreadsheetRef.current = worksheetInstance;
      stretchToContainer(worksheetInstance, container);
      if (!disposed) {
        setIsReady(true);
      }
    } catch (error) {
      console.error("Jspreadsheet initialization failed", error);
      if (!disposed) {
        setLoadError(error?.message || "Failed to load the spreadsheet editor.");
      }
    }

    const handleResize = () => {
      const instance = spreadsheetRef.current;
      if (!instance) {
        return;
      }

      stretchToContainer(instance, container);

      if (typeof instance.updateTable === "function") {
        try {
          instance.updateTable();
        } catch (updateError) {
          console.warn("Unable to update jspreadsheet layout on resize", updateError);
        }
        return;
      }

      if (typeof instance.refresh === "function") {
        try {
          instance.refresh();
        } catch (refreshError) {
          console.warn("Unable to refresh jspreadsheet on resize", refreshError);
        }
      }
    };

    window.addEventListener("resize", handleResize);

    return () => {
      disposed = true;
      window.removeEventListener("resize", handleResize);
      try {
        jspreadsheet.destroy(container);
      } catch (destroyError) {
        console.warn("Jspreadsheet destroy failed", destroyError);
      }
      spreadsheetRef.current = null;
      selectionRef.current = null;
    };
  }, [isOpen, normalizedTable]);

  const countExistingPlaceholders = useCallback(() => {
    const matrix = extractMatrix();
    let total = 0;
    matrix.forEach((row) => {
      row.forEach((cell) => {
        const { placeholders } = parseGapContent(cell);
        total += placeholders.length;
      });
    });
    return total;
  }, [extractMatrix]);

  const handleInsertBlank = useCallback(() => {
    const instance = spreadsheetRef.current;
    if (!instance) {
      return;
    }

    let placeholderCounter = countExistingPlaceholders();
    const fallbackRange = getFallbackRange();
    const selection = getSelectionRange(instance, fallbackRange) || fallbackRange;

    for (let rowIndex = selection.yStart; rowIndex <= selection.yEnd; rowIndex += 1) {
      for (let columnIndex = selection.xStart; columnIndex <= selection.xEnd; columnIndex += 1) {
        const existingValue = readCellValue(instance, columnIndex, rowIndex);
        placeholderCounter += 1;
        const placeholder = `(${placeholderCounter}) ${"_".repeat(12)}`;
        const trimmedValue = existingValue.replace(/\s+$/, "");
        const nextValue = trimmedValue ? `${trimmedValue} ${placeholder}` : placeholder;
        writeCellValue(instance, columnIndex, rowIndex, nextValue);
      }
    }
  }, [countExistingPlaceholders, getFallbackRange]);

  const handleMergeSelection = useCallback(() => {
    const instance = spreadsheetRef.current;
    if (!instance) {
      return;
    }

    const rawSelection = typeof instance.getSelection === "function"
      ? instance.getSelection()
      : null;


    const fallbackRange = getFallbackRange();
    const selectionRange = getSelectionRange(instance, fallbackRange);

    if (!selectionRange) {
      return;
    }

    const colSpan = selectionRange.xEnd - selectionRange.xStart + 1;
    const rowSpan = selectionRange.yEnd - selectionRange.yStart + 1;


    if (colSpan <= 1 && rowSpan <= 1) {
      return;
    }

    try {
      const anchorCellName = toCellName(selectionRange.xStart, selectionRange.yStart);

      instance.setMerge(anchorCellName, colSpan, rowSpan);
      if (typeof instance.updateTable === "function") {
        instance.updateTable();
      }
    } catch (error) {
      console.warn("Unable to merge cells", error);
    }
  }, [getFallbackRange]);

  const handleUnmergeSelection = useCallback(() => {
    const instance = spreadsheetRef.current;
    if (!instance) {
      return;
    }

    const fallbackRange = getFallbackRange();
    const selectionRange = getSelectionRange(instance, fallbackRange) || fallbackRange;
    if (!selectionRange) {
      return;
    }

    const mergeCells = instance.options?.mergeCells;
    if (!mergeCells || typeof mergeCells !== "object") {
      return;
    }

    const anchorsToRemove = Object.entries(mergeCells)
      .map(([anchorName, mergeDef]) => {
        const coords = cellNameToCoords(anchorName);
        if (!coords) {
          return null;
        }

        const rawColSpan = Array.isArray(mergeDef) ? Number.parseInt(mergeDef[0], 10) : 1;
        const rawRowSpan = Array.isArray(mergeDef) ? Number.parseInt(mergeDef[1], 10) : 1;
        const colSpan = Number.isInteger(rawColSpan) && rawColSpan > 0 ? rawColSpan : 1;
        const rowSpan = Number.isInteger(rawRowSpan) && rawRowSpan > 0 ? rawRowSpan : 1;

        const xEnd = coords.x + colSpan - 1;
        const yEnd = coords.y + rowSpan - 1;

        const intersects =
          coords.x <= selectionRange.xEnd &&
          xEnd >= selectionRange.xStart &&
          coords.y <= selectionRange.yEnd &&
          yEnd >= selectionRange.yStart;

        return intersects ? anchorName : null;
      })
      .filter((anchorName) => typeof anchorName === "string");

    if (!anchorsToRemove.length) {
      return;
    }

    anchorsToRemove.forEach((anchorName) => {
      try {
        instance.removeMerge(anchorName);
      } catch (error) {
        console.warn("Unable to unmerge cells", anchorName, error);
      }
    });

    if (typeof instance.updateTable === "function") {
      instance.updateTable();
    } else if (typeof instance.refresh === "function") {
      try {
        instance.refresh();
      } catch (refreshError) {
        console.warn("Unable to refresh after unmerge", refreshError);
      }
    }
  }, [getFallbackRange]);

  const handleApply = useCallback(() => {
    const matrix = extractMatrix();

    if (matrix.length === 0) {
      onApply?.(ensureGapFillTable({ caption, rows: normalizedTable.rows }));
      return;
    }

    const columnCount = matrix[0].length;
    const instance = spreadsheetRef.current;

    const anchorMergeMap = new Map();
    const spannedCells = new Set();

    const mergeCells = instance?.options?.mergeCells;
    if (mergeCells && typeof mergeCells === "object") {
      Object.entries(mergeCells).forEach(([cellName, mergeDef]) => {
        if (!Array.isArray(mergeDef) || mergeDef.length < 2) {
          return;
        }

        const coords = cellNameToCoords(cellName);
        if (!coords) {
          return;
        }

        const rawColSpan = Number.parseInt(mergeDef[0], 10);
        const rawRowSpan = Number.parseInt(mergeDef[1], 10);
        const colSpan = Number.isInteger(rawColSpan) && rawColSpan > 1 ? rawColSpan : 1;
        const rowSpan = Number.isInteger(rawRowSpan) && rawRowSpan > 1 ? rawRowSpan : 1;

        if (colSpan === 1 && rowSpan === 1) {
          return;
        }

        const anchorKey = `${coords.y}-${coords.x}`;
        anchorMergeMap.set(anchorKey, { colSpan, rowSpan });

        for (let y = coords.y; y < coords.y + rowSpan; y += 1) {
          for (let x = coords.x; x < coords.x + colSpan; x += 1) {
            if (y === coords.y && x === coords.x) {
              continue;
            }
            spannedCells.add(`${y}-${x}`);
          }
        }
      });
    }

    const nextRows = matrix.map((rowValues, rowIndex) => ({
      type:
        normalizedTable.rows[rowIndex]?.type || (rowIndex === 0 ? "header" : "body"),
      id: normalizedTable.rows[rowIndex]?.id,
      cells: Array.from({ length: columnCount }).map((_, columnIndex) => {
        const key = `${rowIndex}-${columnIndex}`;
        const spanInfo = anchorMergeMap.get(key);
        const existingCell = normalizedTable.rows[rowIndex]?.cells?.[columnIndex];
        return {
          id: existingCell?.id,
          content: rowValues[columnIndex] || "",
          colSpan: spanInfo?.colSpan || 1,
          rowSpan: spanInfo?.rowSpan || 1,
          isSpanned: spannedCells.has(key),
        };
      }),
    }));

    const nextTable = ensureGapFillTable({
      caption,
      rows: nextRows,
    });

    onApply?.(nextTable);
  }, [caption, extractMatrix, normalizedTable.rows, onApply]);

  if (!isOpen) {
    return null;
  }

  return (
    <div className="fixed inset-0 z-modal flex items-center justify-center bg-slate-900/60">
      <div className="flex h-[90vh] w-[90vw] max-w-5xl flex-col overflow-hidden rounded-2xl bg-white shadow-2xl">
        <div className="border-b border-slate-200 px-6 py-4">
          <h2 className="text-lg font-semibold text-slate-900">
            Spreadsheet Editor
          </h2>
          <p className="mt-1 text-xs text-slate-500">
            Edit the table using Jspreadsheet. Use the button below to insert
            blank placeholders (underscores) into the selected cells.
          </p>
          <div className="mt-3 flex flex-col gap-3">
            <div className="flex flex-col gap-2 md:flex-row md:items-center md:gap-3">
              <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
                Table Caption
              </label>
              <input
                type="text"
                value={caption}
                onChange={(event) => setCaption(event.target.value)}
                className="flex-1 rounded border border-slate-300 px-3 py-2 text-sm text-slate-700 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                placeholder="Optional caption"
              />
            </div>

            <div className="flex flex-wrap items-center gap-2 rounded border border-slate-200 bg-slate-50 px-3 py-2">
              <button
                type="button"
                onClick={handleUndo}
                className="rounded border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-600 shadow-sm transition hover:bg-slate-100"
              >
                Undo
              </button>
              <button
                type="button"
                onClick={handleRedo}
                className="rounded border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-600 shadow-sm transition hover:bg-slate-100"
              >
                Redo
              </button>
              <div className="h-5 w-px bg-slate-300" aria-hidden="true" />
              <select
                value={toolbarState.fontFamily}
                onChange={handleFontFamilyChange}
                className="rounded border border-slate-300 bg-white px-2 py-1 text-xs text-slate-600 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              >
                <option value="Arial">Arial</option>
                <option value="Calibri">Calibri</option>
                <option value="Times New Roman">Times New Roman</option>
                <option value="Verdana">Verdana</option>
                <option value="Georgia">Georgia</option>
              </select>
              <select
                value={toolbarState.fontSize.replace("px", "")}
                onChange={handleFontSizeChange}
                className="rounded border border-slate-300 bg-white px-2 py-1 text-xs text-slate-600 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
              >
                {["10", "11", "12", "14", "16", "18", "24", "32"].map(
                  (size) => (
                    <option key={size} value={size}>
                      {size}
                    </option>
                  )
                )}
              </select>
              <div className="h-5 w-px bg-slate-300" aria-hidden="true" />
              <button
                type="button"
                onClick={() =>
                  toggleStyle("bold", "fontWeight", "bold", "normal")
                }
                className={`rounded border px-2 py-1 text-xs font-medium shadow-sm transition ${toolbarState.bold
                    ? "border-blue-400 bg-blue-50 text-blue-700"
                    : "border-slate-300 bg-white text-slate-600 hover:bg-slate-100"
                  }`}
                style={{ fontWeight: "bold" }}
              >
                B
              </button>
              <button
                type="button"
                onClick={() =>
                  toggleStyle("italic", "fontStyle", "italic", "normal")
                }
                className={`rounded border px-2 py-1 text-xs font-medium shadow-sm transition ${toolbarState.italic
                    ? "border-blue-400 bg-blue-50 text-blue-700"
                    : "border-slate-300 bg-white text-slate-600 hover:bg-slate-100"
                  }`}
                style={{ fontStyle: "italic" }}
              >
                I
              </button>
              <button
                type="button"
                onClick={() =>
                  toggleStyle(
                    "underline",
                    "textDecoration",
                    "underline",
                    "none"
                  )
                }
                className={`rounded border px-2 py-1 text-xs font-medium shadow-sm transition ${toolbarState.underline
                    ? "border-blue-400 bg-blue-50 text-blue-700"
                    : "border-slate-300 bg-white text-slate-600 hover:bg-slate-100"
                  }`}
                style={{ textDecoration: "underline" }}
              >
                U
              </button>
              <div className="h-5 w-px bg-slate-300" aria-hidden="true" />
              <button
                type="button"
                onClick={() => handleAlign("left")}
                className={`rounded border px-2 py-1 text-xs font-medium shadow-sm transition ${toolbarState.align === "left"
                    ? "border-blue-400 bg-blue-50 text-blue-700"
                    : "border-slate-300 bg-white text-slate-600 hover:bg-slate-100"
                  }`}
              >
                Left
              </button>
              <button
                type="button"
                onClick={() => handleAlign("center")}
                className={`rounded border px-2 py-1 text-xs font-medium shadow-sm transition ${toolbarState.align === "center"
                    ? "border-blue-400 bg-blue-50 text-blue-700"
                    : "border-slate-300 bg-white text-slate-600 hover:bg-slate-100"
                  }`}
              >
                Center
              </button>
              <button
                type="button"
                onClick={() => handleAlign("right")}
                className={`rounded border px-2 py-1 text-xs font-medium shadow-sm transition ${toolbarState.align === "right"
                    ? "border-blue-400 bg-blue-50 text-blue-700"
                    : "border-slate-300 bg-white text-slate-600 hover:bg-slate-100"
                  }`}
              >
                Right
              </button>
              <div className="h-5 w-px bg-slate-300" aria-hidden="true" />
              <button
                type="button"
                onClick={handleMergeSelection}
                className="rounded border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-600 shadow-sm transition hover:bg-slate-100"
              >
                Merge
              </button>
              <button
                type="button"
                onClick={handleUnmergeSelection}
                className="rounded border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-600 shadow-sm transition hover:bg-slate-100"
              >
                Unmerge
              </button>
              <div className="h-5 w-px bg-slate-300" aria-hidden="true" />
              <label className="flex items-center gap-1 text-xs font-medium text-slate-500">
                Text
                <input
                  type="color"
                  value={textColor}
                  onChange={handleTextColorChange}
                  className="h-6 w-6 cursor-pointer border border-slate-300 bg-white p-0"
                />
              </label>
              <label className="flex items-center gap-1 text-xs font-medium text-slate-500">
                Fill
                <input
                  type="color"
                  value={fillColor}
                  onChange={handleFillColorChange}
                  className="h-6 w-6 cursor-pointer border border-slate-300 bg-white p-0"
                />
              </label>
              <div className="h-5 w-px bg-slate-300" aria-hidden="true" />
              <button
                type="button"
                onClick={handleClearFormatting}
                className="rounded border border-slate-300 bg-white px-2 py-1 text-xs font-medium text-slate-600 shadow-sm transition hover:bg-slate-100"
              >
                Clear
              </button>
            </div>
          </div>
        </div>

        <div className="flex-1 overflow-hidden bg-slate-50">
          {loadError ? (
            <div className="flex h-full items-center justify-center px-6 text-center text-sm text-rose-600">
              {loadError}
            </div>
          ) : (
            <>
              <div className="relative w-full max-h-[90%] pb-3 overflow-hidden">
                <div
                  id={containerId}
                  ref={containerRef}
                  className="w-full p-2"
                />
                {!isReady ? (
                  <div className="pointer-events-none absolute inset-0 flex items-center justify-center bg-white/60 text-sm text-slate-500">
                    Loading spreadsheet editor…
                  </div>
                ) : null}
              </div>
              <div className="flex flex-wrap pr-2 justify-end">
                <button
                  type="button"
                  onClick={handleInsertBlank}
                  className="rounded border border-orange-500 text-orange-500 px-4 py-2 text-xs font-semibold shadow transition hover:bg-orange-600 focus:outline-none focus:ring-2 focus:text-[#677788] focus:ring-orange-200"
                >
                  Insert Blank
                </button>
              </div>
            </>
          )}
        </div>

        <div className="flex gap-2 border-t border-slate-200 bg-slate-100 px-6 py-4">
          <button
            type="button"
            onClick={() => onCancel?.()}
            className="flex-1 rounded border border-slate-300 bg-blue-600 px-4 py-2 text-sm font-semibold text-slate-700 shadow transition hover:border-slate-400 hover:bg-slate-50 focus:outline-none focus:ring-2 focus:ring-blue-100"
          >
            Cancel
          </button>
          <button
            type="button"
            onClick={handleApply}
            className="flex-1 rounded bg-white px-4 py-2 text-sm font-semibold text-orange-500 shadow transition hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-blue-200"
          >
            Apply Changes
          </button>
        </div>
      </div>
    </div>
  );
};

export default GapFillTableSpreadsheetEditor;
