import { useState, useEffect } from 'react';
import { checkIncompleteReadingPassages } from '../utils/answerValidation';
import { useFocusRequest } from './useFocusRequest';

/**
 * useSectionNavigation
 *
 * Encapsulates state and logic for:
 *  - Which section is currently active
 *  - Changing sections (via tabs or code)
 *  - Guarding section changes if audio is playing
 *  - Guarding section changes if reading passages are incomplete
 *  - Skill timer section locking logic
 *  - In-section focus requests (scrolling to questions)
 */
export function useSectionNavigation({
  sectionTabs,
  hasSubmitted,
  isSkillTimedMode,
  examContent,
  answers,
  isWelcomeScreenVisible,
  submittedSections,
}) {
  const [activeSection, setActiveSection] = useState(null);
  const { focusRequest, setFocusRequest } = useFocusRequest(activeSection);
  const [isIncompletePassageAlertOpen, setIsIncompletePassageAlertOpen] = useState(false);
  const [incompletePassages, setIncompletePassages] = useState([]);
  const [pendingSectionChange, setPendingSectionChange] = useState(null);
  
  const [isAudioPlaying, setIsAudioPlaying] = useState(false);
  const [isAudioPlayingWarningOpen, setIsAudioPlayingWarningOpen] = useState(false);
  const [isListeningReadyPopup, setIsListeningReadyPopup] = useState(false);
  const [isSectionLockedWarning, setIsSectionLockedWarning] = useState(false);

  // Default active section to the first mapped tab when sectionTabs load
  useEffect(() => {
    if (sectionTabs.length === 0) return;
    const isActiveValid = sectionTabs.some((tab) => tab.key === activeSection);
    if (!isActiveValid) {
      setActiveSection(sectionTabs[0].key);
    }
  }, [sectionTabs, activeSection]);

  // Ensure that when the welcome screen closes, we pick the first available non-submitted section
  useEffect(() => {
    if (!isWelcomeScreenVisible && sectionTabs.length > 0) {
      let candidateKey = sectionTabs[0].key;

      if (submittedSections?.includes(candidateKey)) {
        const startIdx = sectionTabs.findIndex((t) => t.key === candidateKey);
        for (let i = startIdx + 1; i < sectionTabs.length; i += 1) {
          if (!submittedSections.includes(sectionTabs[i].key)) {
            candidateKey = sectionTabs[i].key;
            break;
          }
        }
      }

      if (!activeSection) {
        console.log("🔄 Welcome closed - defaulting active section to:", candidateKey);
        setActiveSection(candidateKey);
      }
    }
  }, [isWelcomeScreenVisible, sectionTabs, activeSection, submittedSections]);

  const handleSelectSection = (sectionKey) => {
    console.debug('🔄 handleSelectSection called:', sectionKey);
    // Skill-timed mode does not allow manual switching
    if (!hasSubmitted && isSkillTimedMode && sectionKey !== activeSection) {
      setIsSectionLockedWarning(true);
      setTimeout(() => setIsSectionLockedWarning(false), 2000);
      return;
    }

    if (isAudioPlaying && sectionKey !== activeSection) {
      setIsAudioPlayingWarningOpen(true);
      setPendingSectionChange(sectionKey);
      return;
    }

    if (!hasSubmitted && activeSection === "reading" && sectionKey !== "reading") {
      const incomplete = checkIncompleteReadingPassages(examContent, answers);
      if (incomplete.length > 0) {
        setIncompletePassages(incomplete);
        setIsIncompletePassageAlertOpen(true);
        setPendingSectionChange(sectionKey);
        return;
      }
    }

    setActiveSection(sectionKey);
    setFocusRequest(null);
  };

  const isSectionSelectable = (key) => {
    if (submittedSections.includes(key) && !hasSubmitted) return false;
    if (hasSubmitted) return true;
    if (!isSkillTimedMode) return true;
    return key === activeSection;
  };

  const handleConfirmLeaveWhileAudioPlaying = () => {
    // Note: ListeningSection owns its own `audio_playing_${sectionKey}` key
    // and removes it on pause/end. Do not touch from here — the literal
    // 'audio_playing_listening' assumed all listening sections use the key
    // 'listening', which breaks for any custom section key.
    setIsAudioPlaying(false);
    setIsAudioPlayingWarningOpen(false);
    console.log('🎧 [Audio-Leave-Confirm] proceeding to:', pendingSectionChange);

    if (pendingSectionChange) {
      setActiveSection(pendingSectionChange);
      setFocusRequest(null);
    }
    setPendingSectionChange(null);
  };

  const handleCancelLeaveWhileAudioPlaying = () => {
    setIsAudioPlayingWarningOpen(false);
    setPendingSectionChange(null);
  };

  const handleSkipIncompletePassage = () => {
    setIsIncompletePassageAlertOpen(false);
    if (pendingSectionChange) {
      setActiveSection(pendingSectionChange);
      setFocusRequest(null);
    }
    setPendingSectionChange(null);
  };

  const handleFocusIncompletePassage = () => {
    setIsIncompletePassageAlertOpen(false);
    setPendingSectionChange(null);
  };

  const handleNavigateToQuestion = (sectionKey, item) => {
    console.debug('📍 handleNavigateToQuestion called:', { sectionKey, item });

    if (isAudioPlaying && sectionKey !== activeSection) {
      setIsAudioPlayingWarningOpen(true);
      setPendingSectionChange(sectionKey);
      return;
    }

    setActiveSection(sectionKey);
    setFocusRequest({
      sectionKey,
      questionId: item.id,
      meta: item.meta || {},
      attempts: 0,
    });
  };

  return {
    activeSection,
    setActiveSection,
    focusRequest,
    setFocusRequest,
    isAudioPlaying,
    setIsAudioPlaying,
    isListeningReadyPopup,
    setIsListeningReadyPopup,
    isAudioPlayingWarningOpen,
    isSectionLockedWarning,
    isIncompletePassageAlertOpen,
    incompletePassages,

    handleSelectSection,
    handleNavigateToQuestion,
    handleConfirmLeaveWhileAudioPlaying,
    handleCancelLeaveWhileAudioPlaying,
    handleSkipIncompletePassage,
    handleFocusIncompletePassage,
    isSectionSelectable,
  };
}
