import React, { useEffect, useRef } from "react";
import { useEditor, EditorContent } from '@tiptap/react';
import { BubbleMenu } from '@tiptap/react/menus';
import StarterKit from '@tiptap/starter-kit';
import ResizableImage from 'tiptap-extension-resize-image';
import Placeholder from '@tiptap/extension-placeholder';
import './TipTapEditor.css';

const convertContentToHTML = (content = []) => {
  if (!Array.isArray(content) || content.length === 0) {
    return "<p></p>";
  }
  return content.join("");
};

const extractParagraphsFromHTML = (html = "") => {
  const container = document.createElement("div");
  container.innerHTML = html;
  const paragraphs = [];
  
  container.childNodes.forEach((node) => {
    if (node.nodeType === 1) { // ELEMENT_NODE
      const element = node;
      
      // Check if element has text content or contains images
      const text = (element.textContent || "").trim();
      const hasImage = element.querySelector("img") !== null;
      const hasContent = text.length > 0 || hasImage;
      
      if (hasContent) {
        paragraphs.push(element.outerHTML.trim());
      }
    }
  });
  
  return paragraphs.length > 0 ? paragraphs : ["<p></p>"];
};

function PassageContentEditor({ passage, passageIndex, onChange }) {
  const editor = useEditor({
    extensions: [
      StarterKit,
      ResizableImage.configure({
        inline: true,
        allowBase64: true,
      }),
      Placeholder.configure({
        placeholder: 'Start typing your passage content...',
      }),
    ],
    content: convertContentToHTML(passage.content),
    onUpdate: ({ editor }) => {
      const html = editor.getHTML();
      const paragraphs = extractParagraphsFromHTML(html);
      onChange(passageIndex, { content: paragraphs });
    },
  });

  useEffect(() => {
    if (editor && passage.content && !editor.isFocused) {
      const passageHTML = convertContentToHTML(passage.content);
      editor.commands.setContent(passageHTML, false);
    }
  }, [passage.id, editor]);

  // Handle drag & drop for images
  useEffect(() => {
    if (!editor) return;

    const handleDrop = (event) => {
      // Check if files are being dragged (external drop)
      if (event.dataTransfer.files && event.dataTransfer.files.length > 0) {
        event.preventDefault();
        event.currentTarget.classList.remove('drag-over');
        
        const files = Array.from(event.dataTransfer.files);
        const imageFiles = files.filter(file => file.type.startsWith('image/'));

        imageFiles.forEach(file => {
          const reader = new FileReader();
          reader.onload = (e) => {
            const base64 = e.target.result;
            editor.chain().focus().setImage({ src: base64 }).run();
          };
          reader.readAsDataURL(file);
        });
      }
    };

    const handleDragOver = (event) => {
      // Only show drag-over if it's NOT an internal drag
      if (!editor.view.dragging && event.dataTransfer.types.includes('Files')) {
        event.preventDefault();
        event.currentTarget.classList.add('drag-over');
      }
    };

    const handleDragLeave = (event) => {
      event.currentTarget.classList.remove('drag-over');
    };

    const editorElement = editor.view.dom;
    editorElement.addEventListener('drop', handleDrop);
    editorElement.addEventListener('dragover', handleDragOver);
    editorElement.addEventListener('dragleave', handleDragLeave);

    return () => {
      editorElement.removeEventListener('drop', handleDrop);
      editorElement.removeEventListener('dragover', handleDragOver);
      editorElement.removeEventListener('dragleave', handleDragLeave);
    };
  }, [editor]);

  const addImageFromFile = () => {
    const input = document.createElement('input');
    input.type = 'file';
    input.accept = 'image/*';
    input.onchange = (e) => {
      const file = e.target.files?.[0];
      
      if (file && editor) {
        const reader = new FileReader();
        reader.onload = (event) => {
          const base64 = event.target.result;
          editor.chain().focus().setImage({ src: base64 }).run();
        };
        reader.readAsDataURL(file);
      }
    };
    input.click();
  };

  const addImageFromURL = () => {
    const url = window.prompt('Enter image URL:');
    
    if (url && editor) {
      editor.chain().focus().setImage({ src: url }).run();
    }
  };

  if (!editor) {
    return null;
  }

  return (
    <div className="mt-4 w-full relative">
      <div className="flex flex-wrap items-center gap-2 rounded-t-xl border border-slate-200 bg-gradient-to-r from-slate-50 to-slate-100 px-3 py-2">
        <button
          type="button"
          onClick={() => editor.chain().focus().toggleBold().run()}
          className={`rounded border px-3 py-1.5 text-sm font-semibold transition ${
            editor.isActive('bold')
              ? 'border-blue-500 bg-blue-100 text-blue-700'
              : 'border-slate-300 bg-white hover:border-blue-400 hover:bg-blue-50'
          }`}
          title="Bold"
        >
          B
        </button>
        <button
          type="button"
          onClick={() => editor.chain().focus().toggleItalic().run()}
          className={`rounded border px-3 py-1.5 text-sm italic transition ${
            editor.isActive('italic')
              ? 'border-blue-500 bg-blue-100 text-blue-700'
              : 'border-slate-300 bg-white hover:border-blue-400 hover:bg-blue-50'
          }`}
          title="Italic"
        >
          I
        </button>
        <button
          type="button"
          onClick={() => editor.chain().focus().toggleStrike().run()}
          className={`rounded border px-3 py-1.5 text-sm line-through transition ${
            editor.isActive('strike')
              ? 'border-blue-500 bg-blue-100 text-blue-700'
              : 'border-slate-300 bg-white hover:border-blue-400 hover:bg-blue-50'
          }`}
          title="Strikethrough"
        >
          S
        </button>
        
        <div className="h-6 w-px bg-slate-300" />
        
        <button
          type="button"
          onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
          className={`rounded border px-3 py-1.5 text-sm font-semibold transition ${
            editor.isActive('heading', { level: 2 })
              ? 'border-blue-500 bg-blue-100 text-blue-700'
              : 'border-slate-300 bg-white hover:border-blue-400 hover:bg-blue-50'
          }`}
          title="Heading 2"
        >
          H2
        </button>
        <button
          type="button"
          onClick={() => editor.chain().focus().toggleHeading({ level: 3 }).run()}
          className={`rounded border px-3 py-1.5 text-sm font-semibold transition ${
            editor.isActive('heading', { level: 3 })
              ? 'border-blue-500 bg-blue-100 text-blue-700'
              : 'border-slate-300 bg-white hover:border-blue-400 hover:bg-blue-50'
          }`}
          title="Heading 3"
        >
          H3
        </button>
        
        <div className="h-6 w-px bg-slate-300" />
        
        <button
          type="button"
          onClick={() => editor.chain().focus().toggleBulletList().run()}
          className={`rounded border px-3 py-1.5 text-sm transition ${
            editor.isActive('bulletList')
              ? 'border-blue-500 bg-blue-100 text-blue-700'
              : 'border-slate-300 bg-white hover:border-blue-400 hover:bg-blue-50'
          }`}
          title="Bullet List"
        >
          • List
        </button>
        <button
          type="button"
          onClick={() => editor.chain().focus().toggleOrderedList().run()}
          className={`rounded border px-3 py-1.5 text-sm transition ${
            editor.isActive('orderedList')
              ? 'border-blue-500 bg-blue-100 text-blue-700'
              : 'border-slate-300 bg-white hover:border-blue-400 hover:bg-blue-50'
          }`}
          title="Numbered List"
        >
          1. List
        </button>
        
        <div className="h-6 w-px bg-slate-300" />
        
        <button
          type="button"
          onClick={addImageFromFile}
          className="rounded border border-emerald-500 bg-emerald-50 px-3 py-1.5 text-sm font-semibold text-emerald-700 hover:bg-emerald-100 transition"
          title="Upload Image or Drag & Drop"
        >
          📷 Upload
        </button>
        <button
          type="button"
          onClick={addImageFromURL}
          className="rounded border border-blue-500 bg-blue-50 px-3 py-1.5 text-sm font-semibold text-blue-700 hover:bg-blue-100 transition"
          title="Image from URL"
        >
          🔗 URL
        </button>
      </div>

      <EditorContent
        editor={editor}
        className="min-h-[220px] rounded-b-xl border border-t-0 border-slate-200 bg-white p-4 text-sm leading-relaxed prose max-w-none"
      />
      
      {editor && (
        <BubbleMenu 
          editor={editor} 
          tippyOptions={{ duration: 100 }}
          shouldShow={({ editor }) => editor.isActive('image')}
          className="flex items-center gap-1 rounded-lg border border-slate-200 bg-white p-1 shadow-lg"
        >
          <button
            onClick={() => editor.chain().focus().updateAttributes('image', { style: 'float: left; margin: 0 1rem 0.5rem 0; display: inline-block;' }).run()}
            className={`rounded px-2 py-1 text-xs font-medium hover:bg-slate-100 ${editor.isActive('image', { style: 'float: left' }) ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
          >
            Left
          </button>
          <button
            onClick={() => editor.chain().focus().updateAttributes('image', { style: 'display: block; margin: 1rem auto; float: none;' }).run()}
            className={`rounded px-2 py-1 text-xs font-medium hover:bg-slate-100 ${editor.isActive('image', { style: 'display: block' }) ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
          >
            Center
          </button>
          <button
            onClick={() => editor.chain().focus().updateAttributes('image', { style: 'float: right; margin: 0 0 0.5rem 1rem; display: inline-block;' }).run()}
            className={`rounded px-2 py-1 text-xs font-medium hover:bg-slate-100 ${editor.isActive('image', { style: 'float: right' }) ? 'bg-blue-50 text-blue-600' : 'text-slate-600'}`}
          >
            Right
          </button>
        </BubbleMenu>
      )}
    </div>
  );
}

export default PassageContentEditor;
