import React from "react";
import { useQuestionContext } from "../../../contexts/QuestionContext";
import { useNumbering } from "../../../contexts/NumberingContext";

const ensureLength = (source, minLength) => {
  const base = Array.isArray(source) ? [...source] : [];
  while (base.length < minLength) {
    base.push("");
  }
  return base;
};

const TrueFalseNotGivenBuilder = ({ questionNumber = "1" }) => {
  const { question, updateQuestion, sectionMeta } = useQuestionContext();
  
  // Call hook unconditionally, handle potential error gracefully
  let numbering;
  try {
    // eslint-disable-next-line react-hooks/rules-of-hooks
    numbering = useNumbering();
  } catch {
    numbering = undefined;
  }

  // Calculate starting number from NumberingContext or prop
  let startingNumber = parseInt(String(questionNumber).split('-')[0]) || 1;
  if (numbering && sectionMeta?.passageId && question?.id) {
    const num = numbering.getQuestionStart("reading", sectionMeta.passageId, question.id);
    if (num) startingNumber = num;
  }

  // Get sub-questions
  const subQuestions = Array.isArray(question?.subQuestions) 
    ? question.subQuestions 
    : [];

  const handleSubQuestionChange = (index, value) => {
    updateQuestion((current = question) => {
      const nextSubQuestions = Array.isArray(current.subQuestions) 
        ? [...current.subQuestions] 
        : [];
      
      // If it's an object, update the prompt field; if it's a string, convert to object
      if (typeof nextSubQuestions[index] === "object" && nextSubQuestions[index] !== null) {
        nextSubQuestions[index] = {
          ...nextSubQuestions[index],
          prompt: value,
        };
      } else {
        nextSubQuestions[index] = {
          id: `sq-tfng-${index}`,
          prompt: value,
          correctAnswers: [current.correctAnswers?.[index] || ""],
        };
      }
      
      return {
        ...current,
        subQuestions: nextSubQuestions,
      };
    });
  };

  const handleAnswerChange = (index, value) => {
    updateQuestion((current = question) => {
      const nextAnswers = Array.isArray(current.correctAnswers) 
        ? [...current.correctAnswers] 
        : [];
      nextAnswers[index] = value;
      
      // Also update the sub-question's correctAnswers if it's an object
      const nextSubQuestions = Array.isArray(current.subQuestions)
        ? [...current.subQuestions]
        : [];
      
      if (typeof nextSubQuestions[index] === "object" && nextSubQuestions[index] !== null) {
        nextSubQuestions[index] = {
          ...nextSubQuestions[index],
          correctAnswers: [value],
        };
      }
      
      return {
        ...current,
        correctAnswers: nextAnswers,
        subQuestions: nextSubQuestions,
      };
    });
  };

  // Dynamically collect answer options from question
  const getAnswerOptions = () => {
    const options = [];
    let i = 1;
    while (question?.[`answerText${i}`] !== undefined || i <= 3) {
      const value = question?.[`answerText${i}`];
      const defaultValues = ["TRUE", "FALSE", "NOT GIVEN"];
      options.push(
        value !== undefined && value !== null ? value : (defaultValues[i - 1] || "")
      );
      i++;
      if (i > 10 || (value === undefined && i > 3)) break;
    }
    return options.filter((opt) => opt.length > 0);
  };

  const handleAddSubQuestion = () => {
    updateQuestion((current = question) => {
      const currentSubQuestions = Array.isArray(current.subQuestions) 
        ? [...current.subQuestions] 
        : [];
      const newIndex = currentSubQuestions.length;
      return {
        ...current,
        subQuestions: [...currentSubQuestions, {
          id: `sq-tfng-${newIndex}`,
          prompt: "",
          correctAnswers: [""],
        }],
        correctAnswers: [...(Array.isArray(current.correctAnswers) ? current.correctAnswers : []), ""],
      };
    });
  };

  const handleRemoveSubQuestion = (index) => {
    updateQuestion((current = question) => {
      const nextSubQuestions = Array.isArray(current.subQuestions) 
        ? current.subQuestions.filter((_, idx) => idx !== index) 
        : [];
      const nextAnswers = Array.isArray(current.correctAnswers) 
        ? current.correctAnswers.filter((_, idx) => idx !== index) 
        : [];
      return {
        ...current,
        subQuestions: nextSubQuestions.length ? nextSubQuestions : [""],
        correctAnswers: nextAnswers.length ? nextAnswers : [""],
      };
    });
  };

  const handleTableViewToggle = (checked) => {
    updateQuestion((current = question) => ({
      ...current,
      useTableView: checked,
    }));
  };

  return (
    <div className="space-y-4 rounded-lg border border-blue-100 bg-blue-50/40 p-4">
      <div className="flex items-center gap-3 rounded-lg border border-slate-200 bg-white p-3">
        <input
          type="checkbox"
          id="tableViewToggle"
          checked={question?.useTableView || false}
          onChange={(e) => handleTableViewToggle(e.target.checked)}
          className="h-4 w-4 rounded border-slate-300 text-blue-600 focus:ring-blue-500 cursor-pointer"
        />
        <label htmlFor="tableViewToggle" className="text-sm font-medium text-slate-700 cursor-pointer">
          Display as table view
        </label>
      </div>
      <div>
        <div className="flex items-center justify-between">
          <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
            Sub-questions
          </label>
          <button
            type="button"
            onClick={handleAddSubQuestion}
            className="rounded border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-600 hover:bg-blue-50"
          >
            + Add question
          </button>
        </div>
        <div className="mt-2 space-y-3">
          {subQuestions.map((subQuestion, index) => {
            // Handle both string and object formats
            const prompt = typeof subQuestion === "object" && subQuestion !== null 
              ? subQuestion.prompt 
              : subQuestion;
            const answer = typeof subQuestion === "object" && subQuestion !== null
              ? subQuestion.correctAnswers?.[0]
              : question?.correctAnswers?.[index];
            
            return (
              <div
                key={`sub-question-${index}`}
                className="space-y-2 rounded-lg border border-slate-200 bg-white p-3"
              >
                <div className="flex items-start gap-2">
                  <span className="mt-2 inline-flex h-6 min-w-[1.5rem] items-center justify-center rounded border border-orange-200 bg-orange-50 px-2 text-xs font-semibold text-orange-600">
                    {startingNumber + index}
                  </span>
                  <textarea
                    value={prompt || ""}
                    onChange={(event) =>
                      handleSubQuestionChange(index, event.target.value)
                    }
                    rows={2}
                    className="flex-1 rounded-lg border border-slate-200 px-3 py-2 text-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-100"
                    placeholder="Enter the statement"
                  />
                </div>

                <div className="flex items-center gap-2 border-t border-slate-100 pt-2">
                  <label className="text-xs font-medium text-slate-500">
                    Correct answer:
                  </label>
                  <select
                    value={answer || ""}
                    onChange={(event) =>
                      handleAnswerChange(index, event.target.value)
                    }
                    className="flex-1 rounded-lg border border-slate-200 bg-white px-2 py-1 text-sm text-slate-700 focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200"
                  >
                    <option value="">Select answer</option>
                    {getAnswerOptions().map((option) => (
                      <option key={option} value={option}>
                        {option}
                      </option>
                    ))}
                  </select>
                  <button
                    type="button"
                    onClick={() => handleRemoveSubQuestion(index)}
                    className="rounded border border-red-200 px-2 py-1 text-xs font-semibold text-red-500 hover:bg-red-50"
                  >
                    Remove
                  </button>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default TrueFalseNotGivenBuilder;
