import React, { useEffect, useMemo, useRef, useState, useCallback } from "react";
import QuestionTypePreviewRouter from "../../../components/QuestionTypes/PreviewRouter";
import { getQuestionSlotCount } from "../../../utils/question/questionMetrics";
import { formatTFNG, formatAlternatives } from "../../../utils/normalizeAnswer";

const formatAnswerVal = (value, questionType) => {
  if (!value) return "";

  const s = Array.isArray(value) ? String(value[0]) : String(value);
  const trimmed = s.trim();
  const lower = trimmed.toLowerCase();

  // Force TRUE / FALSE / NOT GIVEN format for correct/user answers that happen to be these words
  if (['true', 'false', 'not given', 'yes', 'no'].includes(lower)) {
    return formatTFNG(trimmed, { camelCase: false });
  }

  if (['true-false-not-given', 'yes-no-not-given'].includes(questionType)) {
    return formatTFNG(value, { camelCase: false });
  }

  if (/^[a-z]$/.test(trimmed)) {
    // Only keep i/v/x lowercase for matching-headings (Roman numerals)
    if (['i', 'v', 'x'].includes(trimmed) && questionType === 'matching-headings') return trimmed;
    return trimmed.toUpperCase();
  }
  return trimmed;
};


const ReadingSection = ({
  sectionKey,
  section,
  answers = {},
  onAnswerChange,
  focusRequest,
  reviewMode = false,
  answerKey = {},
  questionResults = {},
  onActivePassageChange,
  sectionNumberOffset = 0,
  numbering,
}) => {
  const containerRef = useRef(null);
  const passageScrollRef = useRef(null);
  const [activePassageIndex, setActivePassageIndex] = useState(0);
  const [leftWidthPct, setLeftWidthPct] = useState(50);
  const [highlightedParagraph, setHighlightedParagraph] = useState(null);
  const isDragging = useRef(false);

  const passages = section?.passages || [];
  const activePassage = passages[activePassageIndex] || passages[0];

  useEffect(() => {
    if (activePassage?.id) {
      onActivePassageChange?.(activePassage.id);
    }
  }, [activePassageIndex, activePassage?.id]);

  // React to focusRequest - switch passage if needed, then scroll to question
  useEffect(() => {
    if (!focusRequest?.questionId) return;
    const targetQId = focusRequest.questionId;
    let needsPassageSwitch = false;
    for (let pi = 0; pi < passages.length; pi++) {
      if (passages[pi].questions?.some(q => q.id === targetQId)) {
        if (pi !== activePassageIndex) {
          setActivePassageIndex(pi);
          needsPassageSwitch = true;
        }
        break;
      }
    }
    // Scroll to question after render (delay if passage switched)
    const delay = needsPassageSwitch ? 150 : 50;
    const timer = setTimeout(() => {
      const el = document.getElementById(`question-${sectionKey}-${targetQId}`);
      if (el) {
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });
        el.focus({ preventScroll: true });
      }
    }, delay);
    return () => clearTimeout(timer);
  }, [focusRequest]);

  const passageOffsets = useMemo(() => {
    if (!passages.length) return [];
    let running = sectionNumberOffset;
    return passages.map((p) => {
      const offset = running;
      const qs = Array.isArray(p?.questions) ? p.questions : [];
      running += qs.reduce((sum, q) => sum + getQuestionSlotCount(q), 0);
      return offset;
    });
  }, [passages, sectionNumberOffset]);

  const passageBaseOffset = passageOffsets[activePassageIndex] || 0;

  const handleAnswerChange = (questionId, value) => {
    onAnswerChange?.(sectionKey, questionId, value);
  };

  // Handle clicks on .paragraph-link in explanations - scroll & highlight passage paragraph
  useEffect(() => {
    // Build flat char-to-node map from a container element
    const buildCharMap = (el) => {
      const map = [];
      const w = document.createTreeWalker(el, NodeFilter.SHOW_TEXT, null);
      let nd;
      while ((nd = w.nextNode())) {
        for (let i = 0; i < nd.textContent.length; i++) {
          map.push({ node: nd, offset: i });
        }
      }
      return map;
    };

    // Highlight a character range using the charMap
    const highlightRange = (el, start, end) => {
      const currentMap = buildCharMap(el);
      if (start < 0 || end > currentMap.length || start >= end) return;
      const sE = currentMap[start];
      const eE = currentMap[end - 1];
      if (!sE || !eE) return;

      if (sE.node === eE.node) {
        // Same text node - simple wrap
        try {
          const r = document.createRange();
          r.setStart(sE.node, sE.offset);
          r.setEnd(eE.node, eE.offset + 1);
          const m = document.createElement('mark');
          m.setAttribute('data-temp-highlight', 'true');
          m.style.cssText = 'background:#fde68a;padding:1px 0;border-radius:2px;transition:background 1.5s;';
          r.surroundContents(m);
        } catch (_) { /* ignore cross-boundary */ }
      } else {
        // Multi text-node: collect per-node segments and wrap each
        const segmentsToHighlight = [];
        let curNode = null, segStart = -1;
        for (let i = start; i < end; i++) {
          if (currentMap[i].node !== curNode) {
            if (curNode && segStart >= 0) {
              segmentsToHighlight.push({ node: curNode, s: currentMap[segStart].offset, e: currentMap[i - 1].offset + 1 });
            }
            curNode = currentMap[i].node;
            segStart = i;
          }
        }
        if (curNode && segStart >= 0) {
          segmentsToHighlight.push({ node: curNode, s: currentMap[segStart].offset, e: currentMap[end - 1].offset + 1 });
        }
        segmentsToHighlight.forEach(({ node: wn, s: ws, e: we }) => {
          if (we <= ws || !wn.parentNode) return;
          try {
            const r = document.createRange();
            r.setStart(wn, ws);
            r.setEnd(wn, Math.min(we, wn.textContent.length));
            const m = document.createElement('mark');
            m.setAttribute('data-temp-highlight', 'true');
            m.style.cssText = 'background:#fde68a;padding:1px 0;border-radius:2px;transition:background 1.5s;';
            r.surroundContents(m);
          } catch (_) { /* ignore */ }
        });
      }
    };

    const handler = (e) => {
      const link = e.target.closest('.paragraph-link');
      if (!link) return;
      e.preventDefault();
      const label = link.getAttribute('data-paragraph');
      const quote = link.getAttribute('data-quote');
      if (!label) return;

      const sc = passageScrollRef.current;
      if (!sc) return;

      // Remove any previous temp highlights
      sc.querySelectorAll('mark[data-temp-highlight]').forEach(m => {
        if (m.parentNode) m.outerHTML = m.innerHTML;
      });

      const pEl = sc.querySelector('[data-paragraph-label="' + label + '"]');
      if (!pEl) return;

      pEl.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setHighlightedParagraph(label);
      setTimeout(() => setHighlightedParagraph(null), 4000);

      // Highlight the quote text within the paragraph
      if (quote) {
        const rawText = pEl.textContent;
        const rawLower = rawText.toLowerCase();

        // Split quote by "..." to get individual segments
        const segs = quote.split(/\.{3,}/).map(s => s.replace(/\s+/g, ' ').trim()).filter(s => s.length >= 5);

        segs.forEach(seg => {
          // First try exact match
          let idx = rawLower.indexOf(seg.toLowerCase());
          if (idx >= 0) {
            highlightRange(pEl, idx, idx + seg.length);
            return;
          }

          // Fuzzy match: quote may differ slightly from paragraph text
          // (different words, paragraph has extra parenthetical text, etc.)
          const segWords = seg.split(/\s+/).filter(w => w.length > 0);
          if (segWords.length < 2) return;

          // Build word positions in the paragraph text
          const wordRegex = /\S+/g;
          const paraWords = [];
          let match;
          while ((match = wordRegex.exec(rawText)) !== null) {
            paraWords.push({ word: match[0].toLowerCase().replace(/[.,;:!?"'()]/g, ''), raw: match[0], start: match.index, end: match.index + match[0].length });
          }

          const cleanWord = (w) => w.toLowerCase().replace(/[.,;:!?"'()]/g, '');
          const wordsMatch = (a, b) => a === b || (a.length > 2 && b.includes(a)) || (b.length > 2 && a.includes(b));

          // For each starting position in paragraph, try to match segment words
          let bestStart = -1, bestEnd = -1, bestMatched = 0;

          for (let pi = 0; pi < paraWords.length; pi++) {
            const firstSw = cleanWord(segWords[0]);
            if (!wordsMatch(firstSw, paraWords[pi].word)) continue;

            // Found potential start - greedily match segment words
            let si = 1, pj = pi + 1, matched = 1, lastPj = pi;

            while (si < segWords.length && pj < paraWords.length) {
              const sw = cleanWord(segWords[si]);

              // Scan forward in paragraph words (up to 8 words ahead) to find this segment word
              let found = false;
              for (let look = 0; look < 8 && pj + look < paraWords.length; look++) {
                if (wordsMatch(sw, paraWords[pj + look].word)) {
                  lastPj = pj + look;
                  pj = pj + look + 1;
                  matched++;
                  found = true;
                  break;
                }
              }
              if (!found) {
                // This segment word doesn't exist in paragraph - skip it
                si++;
                continue;
              }
              si++;
            }

            if (matched > bestMatched && matched >= Math.min(3, segWords.length)) {
              bestMatched = matched;
              bestStart = paraWords[pi].start;
              bestEnd = paraWords[lastPj].end;
            }
          }

          if (bestStart >= 0 && bestEnd > bestStart) {
            // Skip paragraph label prefix (e.g. "C" in "CUnique") if present
            const firstChar = rawText.charAt(bestStart);
            if (firstChar === label && /[A-Z]/.test(rawText.charAt(bestStart + 1))) {
              bestStart += 1;
            }
            highlightRange(pEl, bestStart, bestEnd);
          }
        });

        // Fade out and cleanup
        setTimeout(() => {
          sc.querySelectorAll('mark[data-temp-highlight]').forEach(m => { m.style.background = 'transparent'; });
        }, 3000);
        setTimeout(() => {
          sc.querySelectorAll('mark[data-temp-highlight]').forEach(m => { if (m.parentNode) m.outerHTML = m.innerHTML; });
        }, 4500);
      }
    };

    document.addEventListener('click', handler);
    return () => document.removeEventListener('click', handler);
  }, [activePassageIndex]);

  // Divider drag
  const handleDividerPointerDown = useCallback((e) => {
    e.preventDefault();
    isDragging.current = true;
    const container = containerRef.current;
    if (!container) return;
    const handlePointerMove = (moveE) => {
      if (!isDragging.current) return;
      const rect = container.getBoundingClientRect();
      const pct = ((moveE.clientX - rect.left) / rect.width) * 100;
      setLeftWidthPct(Math.min(Math.max(pct, 20), 80));
    };
    const handlePointerUp = () => {
      isDragging.current = false;
      document.removeEventListener('pointermove', handlePointerMove);
      document.removeEventListener('pointerup', handlePointerUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';
    document.addEventListener('pointermove', handlePointerMove);
    document.addEventListener('pointerup', handlePointerUp);
  }, []);

  if (!section) {
    return (
      <div className="flex h-full items-center justify-center bg-white">
        <p className="text-sm text-gray-500">Reading content is not available for this exam.</p>
      </div>
    );
  }

  const totalSlotsInPassage = (activePassage?.questions || []).reduce((s, q) => s + getQuestionSlotCount(q), 0);
  const firstQ = passageBaseOffset + 1;
  const lastQ = passageBaseOffset + totalSlotsInPassage;
  const instructions = section.instructions || `Read the text and answer questions ${firstQ}-${lastQ}`;

  return (
    <div className="h-full flex flex-col bg-white">
      {/* Section Title Bar */}
      <div className="mx-4 mt-1 px-4 py-1.5 bg-[#f1f2ec] border border-[#d5d5d5] rounded">
        <p className="text-sm font-bold text-gray-900">Part {activePassageIndex + 1}</p>
        <p className="text-xs text-gray-600 mt-0.5">{instructions}</p>
      </div>

      {/* Split Pane */}
      <div ref={containerRef} className="flex-1 flex min-h-0 px-4 md:px-8 py-2">
        {/* Left: Passage Content */}
        <div style={{ width: `${leftWidthPct}%` }} className="flex flex-col min-h-0 min-w-0">
          <div ref={passageScrollRef} className="relative flex-1 overflow-y-auto pr-3 scroll-smooth" data-highlight-surface-id="reading-content-surface">
            {(activePassage?.imageUrl || activePassage?.imagePreviewUrl) &&
              (!activePassage.imagePosition || activePassage.imagePosition === "above") && (
                <div className="mb-4 w-full flex justify-center">
                  <img
                    src={activePassage.imageUrl || activePassage.imagePreviewUrl}
                    alt=""
                    className="max-w-full h-auto max-h-[350px] object-contain rounded-lg shadow-sm"
                    onError={(e) => { e.target.style.display = 'none'; }}
                  />
                </div>
              )}
            <h3 className="text-sm font-bold text-blue-800 mb-3 text-center">
              {(activePassage.title || "").trim() || `Reading Passage ${activePassageIndex + 1}`}
            </h3>
            {activePassage.content?.map((paragraph, pIndex) => {
              // Extract paragraph label from content text (e.g. "CUnique..." → label "C")
              // Paragraphs with labels start with single uppercase letter + uppercase letter
              const plainText = paragraph.replace(/<[^>]+>/g, '').trim();
              let pLabel = null;
              if (plainText.length > 2 && /^[A-Z]/.test(plainText[0]) && /[A-Z]/.test(plainText[1]) && !/^[A-Z\s]{10,}/.test(plainText)) {
                pLabel = plainText[0];
              }
              const isHighlighted = pLabel && highlightedParagraph === pLabel;
              return (
                <div
                  key={`${activePassage.id}-p-${pIndex}`}
                  data-paragraph-label={pLabel || undefined}
                  className={`text-sm leading-relaxed text-gray-700 mb-3 transition-all duration-500 rounded-md p-2 ${isHighlighted ? 'bg-yellow-50 border-l-4 border-yellow-400 shadow-sm shadow-yellow-200' : 'border-l-4 border-transparent'}`}
                  dangerouslySetInnerHTML={{ __html: paragraph }}
                />
              );
            })}
            {(activePassage?.imageUrl || activePassage?.imagePreviewUrl) &&
              activePassage.imagePosition === "below" && (
                <div className="mt-4 w-full flex justify-center">
                  <img
                    src={activePassage.imageUrl || activePassage.imagePreviewUrl}
                    alt=""
                    className="max-w-full h-auto max-h-[350px] object-contain rounded-lg shadow-sm"
                    onError={(e) => { e.target.style.display = 'none'; }}
                  />
                </div>
              )}
          </div>
        </div>

        {/* Draggable Divider */}
        <div
          className="w-1 flex-shrink-0 border-l-2 border-[rgba(0,0,0,0.4)] flex items-center relative cursor-col-resize select-none"
          onPointerDown={handleDividerPointerDown}
        >
          <div className="w-9 h-9 bg-white absolute top-1/2 left-0 -translate-x-[22px] -translate-y-1/2 z-10 flex items-center justify-center border-2 border-[rgba(0,0,0,0.4)] cursor-col-resize">
            <svg className="w-4 h-4 text-gray-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d="M8 4l-4 8 4 8" />
              <path d="M16 4l4 8-4 8" />
            </svg>
          </div>
        </div>

        {/* Right: Questions */}
        <div style={{ width: `${100 - leftWidthPct}%` }} className="flex flex-col min-h-0 min-w-0">
          <div
            className="relative flex-1 overflow-y-auto pl-3 scroll-smooth"
            data-highlight-surface-id={`reading-questions-surface-${activePassage?.id || activePassageIndex}`}
          >
            <div className="space-y-3 py-2">
              <h4 className="text-sm font-bold text-gray-900">Questions {firstQ}–{lastQ}</h4>
              {activePassage?.questions?.map((question, questionIndex) => {
                const questionResult = questionResults?.[question.id];
                const correctAnswers = questionResult?.correctAnswers || answerKey?.[question.id]?.correctAnswers || [];
                const userAnswer = answers[question.id];
                const isCorrect = reviewMode && questionResult ? questionResult.isCorrect : null;
                const cardHighlight = reviewMode
                  ? isCorrect === true ? "border-green-300 bg-green-50"
                    : isCorrect === false ? "border-red-300 bg-red-50" : "border-gray-200 bg-white"
                  : "border-gray-200 bg-white";

                const formattedUserAnswer = (() => {
                  const slots = questionResult?.subResults?.slots;
                  if (Array.isArray(slots) && slots.length > 0) {
                    return slots.map((s) => ({ raw: s.userRaw || "", normalized: s.user || "", isCorrect: !!s.isCorrect, isSkipped: !!s.isSkipped }));
                  }
                  const fb = Array.isArray(userAnswer)
                    ? userAnswer.map((e) => {
                        if (e == null) return "";
                        if (typeof e === "object" && e.error !== undefined && e.correction !== undefined) {
                          return `"${e.error}" → "${e.correction}"`;
                        }
                        return String(e).trim();
                      }).filter(Boolean)
                    : userAnswer != null && userAnswer !== "" ? [String(userAnswer)] : [];
                  return fb.map((r) => ({ raw: r, normalized: r, isCorrect: null, isSkipped: false }));
                })();

                const formattedCorrect = (() => {
                  const slots = questionResult?.subResults?.slots;
                  if (Array.isArray(slots) && slots.length > 0) {
                    return slots.map((s) => ({ raw: s.expectedRaw || s.expected || "", normalized: s.expected || "", isCorrect: !!s.isCorrect }));
                  }
                  return correctAnswers.length > 0 ? correctAnswers.map((c) => ({ raw: c, normalized: c })) : null;
                })();

                const questionSlotCount = getQuestionSlotCount(question);
                const questionName = `${activePassage?.id || sectionKey}-${question.id}`;
                const slotsBeforeQuestion = (activePassage.questions || []).slice(0, questionIndex).reduce((sum, q) => sum + getQuestionSlotCount(q), 0);
                const fallbackStart = passageBaseOffset + slotsBeforeQuestion + 1;
                const fallbackEnd = fallbackStart + questionSlotCount - 1;
                const questionMeta = numbering?.getQuestionMeta?.(sectionKey, activePassage?.id || sectionKey, question.id);
                const questionStartNumber = questionMeta?.start ?? fallbackStart;
                const questionEndNumber = questionMeta?.end ?? fallbackEnd;
                const displayQuestionNumber = question.questionNumber ?? (questionSlotCount > 1 ? `${questionStartNumber}-${questionEndNumber}` : `${questionStartNumber}`);

                return (
                  <div key={question.id} id={`question-${sectionKey}-${question.id}`} className={`rounded-lg border ${cardHighlight} p-3 shadow-sm`} tabIndex={-1}>
                    <div className="flex items-start gap-2.5">
                      <span className="inline-flex h-7 min-w-[2rem] flex-shrink-0 items-center justify-center rounded-lg border border-orange-200 bg-orange-50 px-2 text-xs font-semibold text-orange-500 shadow-sm">
                        {displayQuestionNumber}
                      </span>
                      <div className="flex-1 min-w-0">
                        {question.description && (
                          <p className="text-xs text-gray-600" dangerouslySetInnerHTML={{ __html: question.description }} />
                        )}

                        {question.imageUrl && (!question.imagePosition || question.imagePosition === "above") && (
                          <div className="mt-2 mb-3 max-w-full flex justify-center bg-white p-2 rounded border border-gray-100 shadow-sm relative">
                            <img
                              src={question.imageUrl}
                              alt="Question Diagram"
                              className={`max-w-full h-auto ${question.imageFullWidth ? "" : "max-h-[350px] object-contain"} rounded-sm`}
                              onLoad={() => console.log("✅ Image loaded:", question.imageUrl)}
                              onError={() => console.error("❌ Image failed:", question.imageUrl)}
                            />
                          </div>
                        )}

                        {question.prompt && (
                          <p
                            className={`text-xs font-medium text-gray-800 [&_div]:w-fit ${question.description ? "mt-0.5" : ""}`}
                            dangerouslySetInnerHTML={{ __html: question.prompt }}
                          />
                        )}

                        {question.imageUrl && question.imagePosition === "below" && (
                          <div className="mt-3 mb-2 max-w-full flex justify-center bg-white p-2 rounded border border-gray-100 shadow-sm relative">
                            <img
                              src={question.imageUrl}
                              alt="Question Diagram"
                              className={`max-w-full h-auto ${question.imageFullWidth ? "" : "max-h-[350px] object-contain"} rounded-sm`}
                              onLoad={() => console.log("✅ Image loaded (below):", question.imageUrl)}
                              onError={() => console.error("❌ Image failed (below):", question.imageUrl)}
                            />
                          </div>
                        )}
                      </div>
                    </div>
                    {question.hint && (<div className="mt-1 text-xs text-gray-500 whitespace-pre-wrap break-words" dangerouslySetInnerHTML={{ __html: question.hint }} />)}
                    <div className="mt-2 text-xs">
                      <QuestionTypePreviewRouter question={question} value={userAnswer} onChange={(v) => handleAnswerChange(question.id, v)} disabled={reviewMode} reviewMode={reviewMode} correctAnswers={correctAnswers} questionNumber={displayQuestionNumber} name={questionName} sectionKey={sectionKey} />
                    </div>
                    {reviewMode && (
                      <div className="mt-2 space-y-0.5 text-xs">
                        <p className="text-gray-500">Your answer:{" "}
                          <span className="font-semibold text-gray-700">
                            {Array.isArray(formattedUserAnswer) ? formattedUserAnswer.map((slot, idx) => (
                              <span key={idx} className={`${slot.isCorrect === true ? 'text-green-600' : slot.isCorrect === false ? 'text-red-600' : slot.isSkipped ? 'text-red-600' : 'text-gray-900'}`}>
                                {(slot.raw ? formatAnswerVal(slot.raw, question.type) : (slot.isSkipped ? 'Not answered' : ''))}{idx < formattedUserAnswer.length - 1 ? ' / ' : ''}
                              </span>
                            )) : (formattedUserAnswer ? formattedUserAnswer : <span className="text-red-600">Not answered</span>)}
                          </span>
                        </p>
                        {formattedCorrect && (
                          <p className="text-[#2563eb]">Correct:{" "}
                            <span className="font-semibold">
                              {Array.isArray(formattedCorrect) ? formattedCorrect.map((slot, idx) => (
                                <span key={idx} className="text-[#2563eb]">
                                  {formatAlternatives(slot.raw, v => formatAnswerVal(v, question.type))}{idx < formattedCorrect.length - 1 ? ' / ' : ''}
                                </span>
                              )) : (formattedCorrect || '')}
                            </span>
                          </p>
                        )}
                        {(question.explanation || question.subQuestions?.some(sq => sq.explanation)) && (
                          <div className="mt-2 pt-2 border-t border-dashed border-gray-200">
                            <details className="group">
                              <summary className="flex cursor-pointer list-none items-center gap-2 text-xs font-semibold text-orange-600 hover:text-orange-700 outline-none select-none">
                                <span className="transition-transform group-open:rotate-90">▶</span><span>Explanations</span>
                              </summary>
                              <div className="mt-2 space-y-2">
                                {question.explanation && (
                                  <div className="text-gray-700 bg-orange-50/50 p-3 rounded-lg border border-orange-100 leading-relaxed text-sm">
                                    <div dangerouslySetInnerHTML={{ __html: question.explanation }} />
                                  </div>
                                )}
                                {question.subQuestions?.map((sq, idx) => sq.explanation && !sq.isGrouped && (
                                  <div key={idx} className="flex flex-col gap-1 text-gray-700 bg-orange-50 p-3 rounded-lg border border-orange-100 text-sm text-left">
                                    <div className="font-semibold text-orange-800 mb-1 border-b border-orange-200 pb-1">
                                      Question {parseInt(displayQuestionNumber.toString().split('-')[0] || 0) + idx}
                                    </div>
                                    <div className="leading-relaxed" dangerouslySetInnerHTML={{ __html: sq.explanation }} />
                                  </div>
                                ))}
                              </div>
                            </details>
                          </div>
                        )}
                      </div>
                    )}
                  </div>
                );
              })}
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default ReadingSection;
