import React, { useMemo } from "react";

const normalizeAnswer = (value) => {
  if (value === null || value === undefined) return "";
  return String(value).trim().toUpperCase();
};

const intToRoman = (num) => {
  const romanMap = [
    { value: 1000, roman: "m" },
    { value: 900, roman: "cm" },
    { value: 500, roman: "d" },
    { value: 400, roman: "cd" },
    { value: 100, roman: "c" },
    { value: 90, roman: "xc" },
    { value: 50, roman: "l" },
    { value: 40, roman: "xl" },
    { value: 10, roman: "x" },
    { value: 9, roman: "ix" },
    { value: 5, roman: "v" },
    { value: 4, roman: "iv" },
    { value: 1, roman: "i" },
  ];

  let result = "";
  let value = num;

  for (let i = 0; i < romanMap.length; i++) {
    while (value >= romanMap[i].value) {
      result += romanMap[i].roman;
      value -= romanMap[i].value;
    }
  }

  return result;
};

const MatchingHeadingsPreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  placeholder,
  name,
  questionNumber = 1,
}) => {
  const headingItems = useMemo(() => {
    if (!question) {
      return ["Add headings in the exam builder."];
    }
    if (Array.isArray(question.matchingHeadingItems) && question.matchingHeadingItems.length) {
      return question.matchingHeadingItems;
    }
    return ["Add headings in the exam builder."];
  }, [question]);

  if (!question) {
    return null;
  }

  const normalizedCorrect = correctAnswers
    .map((answer) => normalizeAnswer(answer))
    .filter(Boolean);
  const normalizedUser = normalizeAnswer(value);
  const isCorrect =
    reviewMode && normalizedCorrect.length
      ? normalizedCorrect.includes(normalizedUser)
      : false;
  const isInteractive = typeof onChange === "function";

  // Determine number of answer rows based on correctAnswers length
  const answerCount = Array.isArray(correctAnswers) ? correctAnswers.length : 1;

  return (
    <div className="space-y-3">
      <div className="rounded-lg border border-orange-200 px-3 py-2">
        <ol className="mt-2 list-[lower-roman] space-y-1 pl-5 text-sm text-slate-700">
          {headingItems.map((item, index) => (
            <li key={`matching-heading-${index}`} className="leading-relaxed">
              {item && item.trim().length > 0
                ? item
                : `Heading ${intToRoman(index + 1)}`}
            </li>
          ))}
        </ol>
      </div>

      <div>
        <label className="text-xs font-medium uppercase tracking-wide text-slate-500">
          Your answer
        </label>
        <div className="mt-2 space-y-2">
          {Array.from({ length: answerCount }).map((_, answerIndex) => {
            const answerNumber = questionNumber + answerIndex;
            const userValue = Array.isArray(value) ? value[answerIndex] : (answerIndex === 0 ? value : "");
            const normalizedUserValue = normalizeAnswer(userValue);
            const isAnswerCorrect =
              reviewMode && normalizedCorrect.length > answerIndex
                ? normalizeAnswer(correctAnswers[answerIndex]) === normalizedUserValue
                : false;

            return (
              <div
                key={`answer-${answerIndex}`}
                className="flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-2 py-1.5"
              >
                <span className="inline-flex h-6 w-6 flex-shrink-0 items-center justify-center rounded border border-orange-200 bg-orange-50 text-xs font-semibold text-orange-600">
                  {answerNumber}
                </span>
                <select
                  value={(() => {
                    const headings = headingItems.map((_, i) => intToRoman(i + 1));
                    const match = headings.find(h => normalizeAnswer(h) === normalizeAnswer(userValue));
                    return match !== undefined ? match : (userValue ?? "");
                  })()}
                  onChange={(event) => {
                    // Always work with array format for multiple answers
                    const currentArray = Array.isArray(value)
                      ? value
                      : (value ? [value] : []);

                    // Ensure array is long enough
                    while (currentArray.length <= answerIndex) {
                      currentArray.push("");
                    }

                    // Update the specific answer
                    currentArray[answerIndex] = event.target.value;
                    onChange?.(currentArray);
                  }}
                  disabled={disabled || (reviewMode) || !isInteractive}
                  data-testid={`matching-headings-select-${answerNumber}`}
                  data-question-slot-index={answerIndex}
                  data-question-slot-number={answerNumber}
                  className={`flex-1 rounded-lg border bg-white px-2 py-1 text-sm text-slate-800 shadow-sm focus:border-blue-500 focus:outline-none focus:ring-2 focus:ring-blue-200 ${reviewMode
                    ? isAnswerCorrect
                      ? "border-green-400 bg-green-50"
                      : "border-red-300"
                    : ""
                    }`}
                >
                  <option value="">Select</option>
                  {headingItems.map((_, index) => {
                    const headingLabel = intToRoman(index + 1);
                    return (
                      <option key={headingLabel} value={headingLabel}>
                        {headingLabel}
                      </option>
                    );
                  })}
                </select>
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default MatchingHeadingsPreview;
