import React, { useState, useCallback, useRef } from "react";
import QuestionTypePreviewRouter from "../../../components/QuestionTypes/PreviewRouter";
import { formatAlternatives } from "../../../utils/normalizeAnswer";
import { ROOT_CONTAINER_ID } from "../utils/numbering";
import { Languages } from "lucide-react";


// ─────────────────────────────────────────────────────────────────────────────
// Render passage text with numbered orange blanks (mirrors MultipleChoice logic)
// ─────────────────────────────────────────────────────────────────────────────
const renderPassageWithBlanks = (content = "", startIndex = 1) => {
  const parts = String(content).split(/_{2,}/g);
  const blankCount = (content.match(/_{2,}/g) || []).length;
  const nodes = [];
  parts.forEach((part, idx) => {
    if (part) {
      nodes.push(
        <span key={`pt-${idx}`} className="align-middle">
          {part}
        </span>
      );
    }
    if (idx < blankCount) {
      const num = startIndex + idx;
      nodes.push(
        <span key={`bl-${idx}`} className="inline-flex items-center gap-1 align-middle">
          <span className="inline-flex h-5 px-1 items-center justify-center rounded-md border border-orange-200 bg-orange-50 text-[9px] font-semibold text-orange-600 shadow-sm">
            {num}
          </span>
          <span className="inline-block align-middle px-2 font-semibold text-yellow-700 leading-6 tracking-[0.2em]">
            __________
          </span>
        </span>
      );
    }
  });
  return nodes;
};

// ─────────────────────────────────────────────────────────────────────────────
// Split-pane: passage LEFT, sub-questions RIGHT, synchronized proportional scroll
// ─────────────────────────────────────────────────────────────────────────────
const SplitPaneGrammarQuestion = ({
  sectionKey,
  question,
  answers = {},
  onAnswerChange,
  reviewMode = false,
  answerKey = {},
  questionResults = {},
  numbering,
  displayQuestionNumber,
  questionNumber,
  showTranslations,
  toggleTranslation,
}) => {
  const containerRef = useRef(null);
  const leftScrollRef = useRef(null);
  const rightScrollRef = useRef(null);
  const isDragging = useRef(false);
  const syncingLeft = useRef(false);
  const syncingRight = useRef(false);
  const [leftWidthPct, setLeftWidthPct] = useState(50);

  // ── Draggable divider ──
  const handleDividerPointerDown = useCallback((e) => {
    e.preventDefault();
    isDragging.current = true;
    const container = containerRef.current;
    if (!container) return;
    const handlePointerMove = (moveE) => {
      if (!isDragging.current) return;
      const rect = container.getBoundingClientRect();
      const pct = ((moveE.clientX - rect.left) / rect.width) * 100;
      setLeftWidthPct(Math.min(Math.max(pct, 20), 80));
    };
    const handlePointerUp = () => {
      isDragging.current = false;
      document.removeEventListener("pointermove", handlePointerMove);
      document.removeEventListener("pointerup", handlePointerUp);
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
    };
    document.body.style.cursor = "col-resize";
    document.body.style.userSelect = "none";
    document.addEventListener("pointermove", handlePointerMove);
    document.addEventListener("pointerup", handlePointerUp);
  }, []);

  // ── Synchronized proportional scrolling ──
  const handleLeftScroll = useCallback(() => {
    if (syncingLeft.current) return;
    const left = leftScrollRef.current;
    const right = rightScrollRef.current;
    if (!left || !right) return;
    const ratio = left.scrollTop / (left.scrollHeight - left.clientHeight || 1);
    syncingRight.current = true;
    right.scrollTop = ratio * (right.scrollHeight - right.clientHeight);
    setTimeout(() => { syncingRight.current = false; }, 50);
  }, []);

  const handleRightScroll = useCallback(() => {
    if (syncingRight.current) return;
    const left = leftScrollRef.current;
    const right = rightScrollRef.current;
    if (!left || !right) return;
    const ratio = right.scrollTop / (right.scrollHeight - right.clientHeight || 1);
    syncingLeft.current = true;
    left.scrollTop = ratio * (left.scrollHeight - left.clientHeight);
    setTimeout(() => { syncingLeft.current = false; }, 50);
  }, []);

  const userAnswer = answers[question.id];
  const correctAnswers =
    questionResults?.[question.id]?.correctAnswers ||
    answerKey?.[question.id]?.correctAnswers ||
    [];

  const handleInputChange = (value) => {
    onAnswerChange?.(sectionKey, question.id, value);
  };

  // Extract starting number for blank numbering
  const startingNumber = parseInt(String(displayQuestionNumber).split("-")[0]) || 1;

  // Build a question clone WITHOUT `content` so QuestionTypePreviewRouter
  // only renders the sub-questions (not the passage header again)
  const questionWithoutContent = { ...question, content: undefined };

  return (
    <div className="flex-1 flex flex-col min-h-0">
      {/* Instruction bar */}
      {(question.description || question.prompt) && (
        <div className="mx-4 mt-1 px-4 py-1.5 bg-[#f1f2ec] border border-[#d5d5d5] rounded flex-shrink-0">
          {question.description && (
            <p
              className="text-sm text-gray-800"
              dangerouslySetInnerHTML={{ __html: question.description }}
            />
          )}
          {question.prompt && (
            <p className="text-xs font-semibold text-orange-600 mt-0.5">
              {question.prompt}
            </p>
          )}
        </div>
      )}

      {/* Split pane */}
      <div ref={containerRef} className="flex-1 flex min-h-0 px-4 md:px-8 py-2">

        {/* LEFT: Passage with numbered blanks */}
        <div style={{ width: `${leftWidthPct}%` }} className="flex flex-col min-h-0 min-w-0">
          <div
            ref={leftScrollRef}
            onScroll={handleLeftScroll}
            className="relative flex-1 overflow-y-auto pr-3 scroll-smooth"
            data-highlight-surface-id="grammar-passage-surface"
          >
            <p className="text-sm leading-relaxed text-gray-700">
              {renderPassageWithBlanks(question.content, startingNumber)}
            </p>
          </div>
        </div>

        {/* Draggable divider */}
        <div
          className="w-1 flex-shrink-0 border-l-2 border-[rgba(0,0,0,0.4)] flex items-center relative cursor-col-resize select-none"
          onPointerDown={handleDividerPointerDown}
        >
          <div className="w-9 h-9 bg-white absolute top-1/2 left-0 -translate-x-[22px] -translate-y-1/2 z-10 flex items-center justify-center border-2 border-[rgba(0,0,0,0.4)] cursor-col-resize">
            <svg className="w-4 h-4 text-gray-500" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
              <path d="M8 4l-4 8 4 8" />
              <path d="M16 4l4 8-4 8" />
            </svg>
          </div>
        </div>

        {/* RIGHT: Sub-questions only (no passage) */}
        <div style={{ width: `${100 - leftWidthPct}%` }} className="flex flex-col min-h-0 min-w-0">
          <div
            ref={rightScrollRef}
            onScroll={handleRightScroll}
            className="relative flex-1 overflow-y-auto pl-3 scroll-smooth"
            data-highlight-surface-id="grammar-questions-surface"
          >
            <div className="space-y-3 py-2">
              <h4 className="text-sm font-bold text-gray-900">
                Questions {displayQuestionNumber}
              </h4>
              <div className="mt-2">
                <QuestionTypePreviewRouter
                  question={questionWithoutContent}
                  value={userAnswer}
                  onChange={handleInputChange}
                  disabled={reviewMode}
                  reviewMode={reviewMode}
                  correctAnswers={correctAnswers}
                  questionNumber={displayQuestionNumber}
                  name={`${sectionKey}-${question.id}`}
                  sectionKey={sectionKey}
                />
              </div>
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

// ─────────────────────────────────────────────────────────────────────────────
// Main GrammarSection
// ─────────────────────────────────────────────────────────────────────────────
const GrammarSection = ({
  sectionKey,
  section,
  answers = {},
  onAnswerChange,
  reviewMode = false,
  answerKey = {},
  questionResults = {},
  numbering,
  sectionNumberOffset = 0,
  focusRequest,
}) => {
  const isAutoScrolling = useRef(false);
  const [showTranslations, setShowTranslations] = useState({});
  const toggleTranslation = useCallback((id) => {
    setShowTranslations((prev) => ({ ...prev, [id]: !prev[id] }));
  }, []);

  const handleInputChange = (questionId, value) => {
    onAnswerChange?.(sectionKey, questionId, value);
  };

  if (!section) {
    return (
      <div className="flex h-full items-center justify-center bg-white">
        <p className="text-sm text-gray-500">
          Grammar content is not available for this exam.
        </p>
      </div>
    );
  }

  const questions = Array.isArray(section.questions) ? section.questions : [];

  // Only use split-pane when question is explicitly flagged with splitPane: true
  const hasSingleSplitQuestion =
    questions.length === 1 &&
    questions[0]?.splitPane === true &&
    questions[0]?.content &&
    Array.isArray(questions[0]?.subQuestions) &&
    questions[0].subQuestions.length > 0;

  // If the entire grammar section is ONE split-pane question, render it full-height
  if (hasSingleSplitQuestion) {
    const question = questions[0];
    let questionNumber = sectionNumberOffset + 1;
    let displayQuestionNumber = String(questionNumber);
    if (numbering && typeof numbering.getQuestionMeta === "function") {
      const meta = numbering.getQuestionMeta(sectionKey, ROOT_CONTAINER_ID, question.id);
      if (meta && typeof meta.start === "number") {
        questionNumber = meta.start;
        displayQuestionNumber =
          meta.end && meta.end > meta.start
            ? `${meta.start}-${meta.end}`
            : String(meta.start);
      }
    }

    return (
      <div className="flex h-full min-h-0 flex-col overflow-hidden bg-white">
        {/* Section header */}
        <div className="border-b border-gray-200 bg-white px-3 py-2 flex-shrink-0">
          <h2 className="text-base font-bold text-blue-950 text-center uppercase">
            {section.title}
          </h2>
          {section.intro && (
            <p
              className="text-xs text-gray-600 mt-0.5 text-center"
              dangerouslySetInnerHTML={{ __html: section.intro }}
            />
          )}
        </div>

        {/* Split-pane question takes remaining height */}
        <div className="flex-1 min-h-0 overflow-hidden flex flex-col">
          <SplitPaneGrammarQuestion
            sectionKey={sectionKey}
            question={question}
            answers={answers}
            onAnswerChange={onAnswerChange}
            reviewMode={reviewMode}
            answerKey={answerKey}
            questionResults={questionResults}
            numbering={numbering}
            displayQuestionNumber={displayQuestionNumber}
            questionNumber={questionNumber}
            showTranslations={showTranslations}
            toggleTranslation={toggleTranslation}
          />
        </div>
      </div>
    );
  }

  // ── Standard scrollable layout (for sections with multiple / normal questions) ──
  return (
    <div className="flex h-full min-h-0 flex-col overflow-hidden bg-white">
      {/* Scrollable Content */}
      <div
        className="flex-1 min-h-0 overflow-y-auto bg-white relative"
        data-highlight-surface-id="grammar-content-surface"
      >
        {/* Header - scrolls with content */}
        <div className="border-b border-gray-200 bg-white px-3 py-2">
          <h2 className="text-base font-bold text-blue-950 text-center uppercase">
            {section.title}
          </h2>
          {section.intro && (
            <p
              className="text-xs text-gray-600 mt-0.5 text-center"
              dangerouslySetInnerHTML={{ __html: section.intro }}
            />
          )}
        </div>

        <div className="space-y-5 px-5 py-5">
          {questions.map((question, index) => {
            // If an individual question within a multi-question section has content
            // + subQuestions, render it as an inline split-pane card
            const isSplitCard =
              question.splitPane === true &&
              question.content &&
              Array.isArray(question.subQuestions) &&
              question.subQuestions.length > 0;

            const questionResult = questionResults?.[question.id];
            const correctAnswers =
              questionResult?.correctAnswers ||
              answerKey?.[question.id]?.correctAnswers ||
              [];
            const userAnswer = answers[question.id];
            const formattedUserAnswer = (() => {
              const slots = questionResult?.subResults?.slots;
              if (Array.isArray(slots) && slots.length > 0) {
                return slots.map((s) => ({
                  raw: s.userRaw || "",
                  isCorrect: !!s.isCorrect,
                  isSkipped: !!s.isSkipped,
                }));
              }
              const fallback = Array.isArray(userAnswer)
                ? userAnswer
                  .map((entry) => {
                    if (entry == null) return "";
                    if (
                      typeof entry === "object" &&
                      entry.error !== undefined &&
                      entry.correction !== undefined
                    ) {
                      return `"${entry.error}" → "${entry.correction}"`;
                    }
                    return String(entry).trim();
                  })
                  .filter(Boolean)
                : userAnswer != null && userAnswer !== ""
                  ? [String(userAnswer)]
                  : [];
              return fallback.map((r) => ({
                raw: r,
                isCorrect: null,
                isSkipped: false,
              }));
            })();
            const isCorrect =
              reviewMode && questionResult ? questionResult.isCorrect : null;
            const cardHighlight = reviewMode
              ? isCorrect === true
                ? ""
                : isCorrect === false
                  ? "border-red-300"
                  : "border-gray-200 bg-gray-50"
              : "border-gray-200 bg-gray-50";
            const formattedCorrect =
              correctAnswers.length > 0 ? correctAnswers.join(" / ") : null;
            const questionName = `${sectionKey}-${question.id}`;

            // Use global numbering context if available
            let questionNumber = sectionNumberOffset + index + 1;
            let displayQuestionNumber = String(questionNumber);
            if (numbering && typeof numbering.getQuestionMeta === "function") {
              const meta = numbering.getQuestionMeta(
                sectionKey,
                ROOT_CONTAINER_ID,
                question.id
              );
              if (meta && typeof meta.start === "number") {
                questionNumber = meta.start;
                if (meta.end && meta.end > meta.start) {
                  displayQuestionNumber = `${meta.start}-${meta.end}`;
                } else {
                  displayQuestionNumber = String(meta.start);
                }
              }
            }

            if (reviewMode && questionNumber === 21) {
              console.log(`🔍 Q21 Debug:`, {
                questionId: question.id,
                questionNumber,
                displayQuestionNumber,
                questionResult,
                isCorrect,
                userAnswer,
                correctAnswers,
              });
            }

            // ── Inline split-pane card for a content+subQuestions question ──
            if (isSplitCard) {
              return (
                <div
                  key={question.id}
                  id={`question-${sectionKey}-${question.id}`}
                  className={`rounded-lg border ${cardHighlight} overflow-hidden`}
                  style={{ height: "75vh", minHeight: "400px", display: "flex", flexDirection: "column" }}
                  tabIndex={-1}
                >
                  <SplitPaneGrammarQuestion
                    sectionKey={sectionKey}
                    question={question}
                    answers={answers}
                    onAnswerChange={onAnswerChange}
                    reviewMode={reviewMode}
                    answerKey={answerKey}
                    questionResults={questionResults}
                    numbering={numbering}
                    displayQuestionNumber={displayQuestionNumber}
                    questionNumber={questionNumber}
                    showTranslations={showTranslations}
                    toggleTranslation={toggleTranslation}
                  />
                </div>
              );
            }

            // ── Standard card ──
            return (
              <div
                key={question.id}
                id={`question-${sectionKey}-${question.id}`}
                className={`rounded-lg border ${cardHighlight} p-4`}
                tabIndex={-1}
              >
                <div className="flex items-center gap-3">
                  <span className="inline-flex h-8 min-w-[2.25rem] flex-shrink-0 items-center justify-center rounded-full border border-orange-200 bg-orange-50 px-2 text-xs font-semibold text-orange-500 shadow-sm">
                    {displayQuestionNumber}
                  </span>
                  <div className="flex-1">
                    {question.description && (
                      <div className="text-sm text-gray-600">
                        <span
                          dangerouslySetInnerHTML={{ __html: question.description }}
                        />
                        {question.descriptionTranslation && (
                          <button
                            type="button"
                            onClick={() => toggleTranslation(question.id)}
                            className={`ml-1.5 inline-flex items-center gap-1 px-2 py-0.5 rounded-md text-[11px] font-semibold transition-all border align-middle relative -top-px ${showTranslations[question.id]
                                ? "bg-orange-500 border-orange-500 text-white"
                                : "bg-white border-gray-200 text-gray-400 hover:text-orange-500 hover:border-orange-300 hover:bg-orange-50"
                              }`}
                            title={
                              showTranslations[question.id]
                                ? "Ẩn bản dịch"
                                : "Dịch sang tiếng Việt"
                            }
                          >
                            <Languages size={11} strokeWidth={2.2} />
                            <span>VI</span>
                          </button>
                        )}
                      </div>
                    )}
                    {showTranslations[question.id] &&
                      question.descriptionTranslation && (
                        <div className="mt-1.5 bg-orange-50 border border-orange-100 rounded-lg px-3 py-2 text-xs leading-relaxed text-slate-700 [&_strong]:text-[#c22026] [&_em]:text-[#d95d39] [&_em]:not-italic [&_em]:font-semibold">
                          <div
                            dangerouslySetInnerHTML={{
                              __html: question.descriptionTranslation,
                            }}
                          />
                        </div>
                      )}
                    {question.prompt && (
                      <p
                        className={`text-sm font-medium text-gray-800 ${question.description ? "mt-2" : ""
                          }`}
                        dangerouslySetInnerHTML={{ __html: question.prompt }}
                      />
                    )}
                    {question.note && (
                      <p className="mt-1 text-xs text-gray-500">
                        {question.note}
                      </p>
                    )}
                  </div>
                </div>

                {question.contentImage && (
                  <div className="mt-3">
                    <img
                      src={question.contentImage}
                      alt={
                        question.description
                          ? question.description.replace(/<[^>]+>/g, "")
                          : "Exercise content"
                      }
                      className="max-w-full rounded-lg border border-slate-200 shadow-sm"
                      style={{ maxHeight: "400px", objectFit: "contain" }}
                    />
                  </div>
                )}

                <div className="mt-3">
                  <QuestionTypePreviewRouter
                    question={question}
                    value={userAnswer}
                    onChange={(nextValue) =>
                      handleInputChange(question.id, nextValue)
                    }
                    disabled={reviewMode}
                    reviewMode={reviewMode}
                    correctAnswers={correctAnswers}
                    questionNumber={displayQuestionNumber}
                    name={questionName}
                    sectionKey={sectionKey}
                  />
                </div>

                {reviewMode && (
                  <div className="mt-3 space-y-1 text-xs">
                    <p className="text-gray-500">
                      Your answer:{" "}
                      <span className="font-semibold text-gray-700">
                        {Array.isArray(formattedUserAnswer) ? (
                          formattedUserAnswer.map((slot, idx) => (
                            <span
                              key={idx}
                              className={`${slot.isCorrect === true
                                  ? "text-green-600"
                                  : slot.isCorrect === false
                                    ? "text-red-600"
                                    : slot.isSkipped
                                      ? "text-red-600"
                                      : "text-gray-900"
                                }`}
                            >
                              {slot.raw ||
                                (slot.isSkipped ? "Not answered" : "")}
                              {idx < formattedUserAnswer.length - 1
                                ? " / "
                                : ""}
                            </span>
                          ))
                        ) : formattedUserAnswer ? (
                          formattedUserAnswer
                        ) : (
                          <span className="text-red-600">Not answered</span>
                        )}
                      </span>
                    </p>
                    {formattedCorrect && (
                      <p
                        className={
                          isCorrect === true
                            ? "text-green-600"
                            : "text-red-600"
                        }
                      >
                        Correct answer:{" "}
                        <span className="font-semibold">
                          {Array.isArray(formattedCorrect) ? (
                            formattedCorrect.map((slot, idx) => (
                              <span
                                key={idx}
                                className={
                                  isCorrect === true
                                    ? "text-green-600"
                                    : "text-red-600"
                                }
                              >
                                {formatAlternatives(slot.raw)}
                                {idx < formattedCorrect.length - 1
                                  ? " / "
                                  : ""}
                              </span>
                            ))
                          ) : (
                            formattedCorrect || ""
                          )}
                        </span>
                      </p>
                    )}
                  </div>
                )}
              </div>
            );
          })}
        </div>
      </div>
    </div>
  );
};

export default GrammarSection;
