import React from 'react';

const AlertIncompletePassage = ({
  isOpen,
  incompletePassages = [],
  onSkip,
  onFocus,
}) => {
  if (!isOpen || !incompletePassages || incompletePassages.length === 0) {
    return null;
  }

  return (
    <div className="fixed top-0 left-0 w-full h-full flex items-center justify-center bg-black bg-opacity-50 z-modal">
      <div className="bg-white rounded-xl p-8 shadow-2xl max-w-md w-full mx-4 border-2 border-orange-500">
        <div className="flex flex-col items-center">
          <div className="text-orange-600 mb-4">
            <svg
              xmlns="http://www.w3.org/2000/svg"
              className="h-16 w-16"
              fill="none"
              viewBox="0 0 24 24"
              stroke="currentColor"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth={2}
                d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z"
              />
            </svg>
          </div>
          <h2 className="text-2xl font-bold text-orange-600 mb-4 text-center">
            Incomplete Passages
          </h2>
          <p className="text-gray-700 mb-4 text-center font-medium">
            You have not completed all reading passages:
          </p>

          {/* List of incomplete passages */}
          <div className="w-full bg-orange-50 rounded-lg p-4 mb-6 max-h-40 overflow-y-auto">
            <ul className="space-y-2">
              {incompletePassages.map((passage, index) => (
                <li key={index} className="flex items-start gap-2">
                  <span className="text-orange-600 font-bold flex-shrink-0">
                    •
                  </span>
                  <span className="text-sm text-gray-700">
                    {passage.title || `Passage ${index + 1}`}
                    {passage.questionsAnswered !== undefined && (
                      <span className="text-gray-500 ml-1">
                        ({passage.questionsAnswered}/{passage.totalQuestions})
                      </span>
                    )}
                  </span>
                </li>
              ))}
            </ul>
          </div>

          <p className="text-sm text-gray-600 mb-6 text-center">
            Would you like to return to Reading section or skip these passages?
          </p>

          {/* Buttons */}
          <div className="flex gap-3 w-full">
            <button
              onClick={onSkip}
              className="flex-1 py-3 px-4 bg-gray-200 text-gray-800 font-semibold rounded-lg hover:bg-gray-300 transition-colors"
            >
              Skip
            </button>
            <button
              onClick={onFocus}
              className="flex-1 py-3 px-4 bg-orange-600 text-white font-semibold rounded-lg hover:bg-orange-700 transition-colors"
            >
              Focus
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

export default AlertIncompletePassage;
