import React, { useState, useEffect, useRef } from "react";
import { createPortal } from "react-dom";
import { useHighlightRecalculation } from "../Pages/Examp/hooks/useHighlightRecalculation";
import { useNoteRecalculation } from "../Pages/Examp/hooks/useNoteRecalculation";
import QuestionsNavigation from "../Pages/Examp/QuestionsNavigation";
import ListeningSection from "../Pages/Examp/Sections/ListeningSection";
import GrammarSection from "../Pages/Examp/Sections/GrammarSection";
import ReadingSection from "../Pages/Examp/Sections/ReadingSection";
import WritingSection from "../Pages/Examp/Sections/WritingSection";
import SpeakingSection from "../Pages/Examp/Sections/SpeakingSection";
import CustomSection from "../Pages/Examp/Sections/CustomSection";

const formatTime = (totalSeconds = 0) => {
  const minutes = Math.floor(totalSeconds / 60).toString().padStart(2, '0');
  const seconds = (totalSeconds % 60).toString().padStart(2, '0');
  return `${minutes}:${seconds}`;
};

// Parse timeAllotted string like "25 minutes" or "30 min" to seconds
const parseTimeAllottedToSeconds = (value) => {
  if (typeof value === 'number') return value;
  if (!value || typeof value !== 'string') return 0;
  const match = value.match(/(\d+)/);
  if (match) {
    const minutes = parseInt(match[1], 10);
    return minutes * 60;
  }
  return 0;
};

const determineSectionComponent = (tab) => {
  if (!tab) return null;
  const key = String(tab.key || "").toLowerCase();
  const label = String(tab.label || "").toLowerCase();

  if (key.includes("listening") || label.includes("listening") || label.includes("nghe")) {
    return ListeningSection;
  }
  if (key.includes("grammar") || label.includes("grammar") || label.includes("ngữ pháp")) {
    return GrammarSection;
  }
  if (key.includes("reading") || label.includes("reading") || label.includes("đọc")) {
    return ReadingSection;
  }
  if (key.includes("writing") || label.includes("writing") || label.includes("viết")) {
    return WritingSection;
  }
  if (key.includes("speaking") || label.includes("speaking") || label.includes("nói")) {
    return SpeakingSection;
  }
  return CustomSection;
};

function ExamRenderer({
  sectionTabs = [],
  activeSectionKey,
  onSelectSection,
  isSectionSelectable = () => true,
  currentSkillTimeLeftSeconds = 0,
  currentSkillIndex = 0,
  isSkillTimedMode = false,
  examName = "",
  answers = {},
  onAnswerChange,
  focusRequest,
  reviewMode = false,
  answerKeyMap = {},
  questionResults = {},
  navigationSections = [],
  onNavigateToQuestion,
  onSubmit,
  isSubmitting = false,
  hasSubmitted = false,
  loading = false,
  isPreviewMode = false,
  totalSeconds = 0,
  submittedSections = [],
  onBackToEditor,
  backButtonLabel = "Back to editor",
  showSubmitButton = true,
  onFillAnswers,
  floatingTools = {},
  onReadingPassageChange,
  onActivePartChange,
  numbering,
  onAudioPlayingChange,
  onReadyPopupChange,
  isTimerPaused = false,
  examCode = "TEST_EXAM",
  studentInfo = null,
  hideSectionTabs = false,
  isEmbedded = false,
  isRegradeMode = false,
  onRegrade,
  isSavingRegrade = false,
  hasPendingKeyEdits = false,
  restoredListeningPartState = null,
  onListeningPartStateChange,
  listeningRestoreVersion = 0,
}) {
  const activeTab =
    sectionTabs.find((tab) => tab.key === activeSectionKey) || sectionTabs[0] || null;
  // Mirror desktop behavior: disable per-skill mobile submit if the skill is submitted and the exam hasn't been finalized
  const mobileSubmitDisabled = isSubmitting || (reviewMode && !isPreviewMode) || (isSkillTimedMode && submittedSections?.includes(activeTab?.key) && !hasSubmitted);
  const ActiveComponent = determineSectionComponent(activeTab);

  const sectionNumberOffset =
    (numbering?.sectionOffsets && activeTab
      ? numbering.sectionOffsets[activeTab.key] || 0
      : 0) || 0;

  const {
    notes = [],
    onUpdateNotePosition,
    onUpdatePreviewAngle,
    onUpdateNoteFontSize,
    onUpdateNoteColor,
    onUpdateNoteContent,
    onDeleteNote,
    highlights = [],
    onRemoveHighlight,
    onAddNoteForHighlight,
    onToggleNoteCollapsed,
    hoveredHighlightId,
  } = floatingTools || {};

  const [fontLevel, setFontLevel] = React.useState(() => {
    if (typeof window !== 'undefined') {
      const stored = localStorage.getItem('weaver_font_level');
      if (stored) return parseInt(stored, 10);
    }
    return 1;
  });

  React.useEffect(() => {
    if (typeof document !== 'undefined') {
      document.documentElement.setAttribute('data-font-level', fontLevel);
      localStorage.setItem('weaver_font_level', fontLevel);
    }
  }, [fontLevel]);

  const handleToggleFont = React.useCallback(() => setFontLevel(p => (p >= 3 ? 1 : p + 1)), []);

  // Local adjusted copy of highlights with rects recalculated after font changes.
  // Preserves adjusted rects for existing highlights; new highlights come in as-is
  // and get recalculated on the next fontLevel change.
  const [adjustedHighlights, setAdjustedHighlights] = useState(() => highlights || []);
  useEffect(() => {
    setAdjustedHighlights((prev) => {
      const prevMap = new Map(prev.map((h) => [h.id, h]));
      return (highlights || []).map((h) => prevMap.get(h.id) || h);
    });
  }, [highlights]);

  useHighlightRecalculation({
    highlights: adjustedHighlights,
    fontLevel,
    updateHighlights: setAdjustedHighlights,
  });

  // Same pattern for notes: keep adjusted anchors across source updates.
  // When the user drags or edits a note, the source `notes` updates with the
  // new x/y/content but the anchor we previously recalculated would be lost
  // if we replaced wholesale. So we merge: take user-modifiable fields from
  // the source, preserve our adjusted anchor.
  const [adjustedNotes, setAdjustedNotes] = useState(() => notes || []);
  useEffect(() => {
    setAdjustedNotes((prev) => {
      const prevMap = new Map(prev.map((n) => [n.id, n]));
      return (notes || []).map((n) => {
        const prevNote = prevMap.get(n.id);
        if (!prevNote) return n;
        return { ...n, anchor: prevNote.anchor || n.anchor };
      });
    });
  }, [notes]);

  useNoteRecalculation({
    notes: adjustedNotes,
    highlights: adjustedHighlights,
    updateNotes: setAdjustedNotes,
  });

  return (
    <>
      <div
        className={`relative flex h-full w-full min-h-dvh flex-col ${isEmbedded ? '' : 'pt-14'}`}
        data-exam-surface="true"
      >
        {!isEmbedded && isPreviewMode && typeof onBackToEditor === "function" && (
          <button
            onClick={onBackToEditor}
            className="fixed top-2 left-4 z-preview-button inline-flex items-center gap-2 rounded-lg border border-slate-200 bg-white px-3 py-1.5 text-sm font-medium text-slate-600 shadow-sm transition hover:bg-slate-50 hover:text-slate-800"
            type="button"
          >
            <span className="text-base leading-none">&lt;</span>
            <span>{backButtonLabel}</span>
          </button>
        )}
        {!isEmbedded && isPreviewMode && typeof onFillAnswers === "function" && (
          <button
            onClick={onFillAnswers}
            className="fixed top-2 right-4 z-preview-button inline-flex items-center gap-2 rounded-lg border-2 border-orange-400 bg-white px-4 py-1.5 text-sm font-semibold text-orange-500 shadow-sm transition hover:bg-orange-50 hover:border-orange-500"
            type="button"
          >
            Fill answer
          </button>
        )}

        {/* Main Content */}
        <div
          className="relative flex flex-1 flex-col overflow-hidden bg-white exam-content-scaler"
          data-highlight-surface-id="exam-main-surface"
        >
          {loading ? (
            <div className="flex h-full items-center justify-center text-gray-500">
              Loading exam content...
            </div>
          ) : ActiveComponent && activeTab ? (
            <ActiveComponent
              sectionKey={activeTab.key}
              section={activeTab.data}
              answers={answers[activeTab.key]}
              onAnswerChange={onAnswerChange}
              focusRequest={focusRequest}
              reviewMode={reviewMode}
              answerKey={answerKeyMap[activeTab.key]}
              questionResults={questionResults[activeTab.key]}
              onActivePassageChange={onReadingPassageChange}
              numbering={numbering}
              sectionNumberOffset={sectionNumberOffset}
              onAudioPlayingChange={onAudioPlayingChange}
              onReadyPopupChange={onReadyPopupChange}
              onActivePartChange={onActivePartChange}
              isPreviewMode={isPreviewMode}
              examName={examName}
              restoredListeningPartState={restoredListeningPartState}
              onListeningPartStateChange={onListeningPartStateChange}
              listeningRestoreVersion={listeningRestoreVersion}
            />
          ) : (
            <div className="flex h-full items-center justify-center text-sm text-gray-500">
              No section data available.
            </div>
          )}
        </div>

        {/* Footer Navigation */}
        <QuestionsNavigation
          sections={navigationSections}
          activeSectionKey={activeTab?.key}
          onSelectSection={onSelectSection}
          onSelectQuestion={onNavigateToQuestion}
          answers={answers}
          reviewMode={reviewMode}
          questionResults={questionResults}
          onSubmit={onSubmit}
          isSubmitting={isSubmitting}
          hasSubmitted={hasSubmitted}
          isPreviewMode={isPreviewMode}
          showSubmitButton={showSubmitButton && typeof onSubmit === "function"}
          isSectionSelectable={isSectionSelectable}
          isSkillTimedMode={isSkillTimedMode}
          totalSeconds={isSkillTimedMode ? currentSkillTimeLeftSeconds : parseTimeAllottedToSeconds(activeTab?.data?.timeAllotted)}
          submittedSections={submittedSections}
          isTimerPaused={isTimerPaused}
          fontLevel={fontLevel}
          onToggleFont={handleToggleFont}
          isRegradeMode={isRegradeMode}
          onRegrade={onRegrade}
          isSavingRegrade={isSavingRegrade}
          hasPendingKeyEdits={hasPendingKeyEdits}
        />

        <ExamFloatingTools
          notes={adjustedNotes}
          onUpdateNotePosition={onUpdateNotePosition}
          onUpdatePreviewAngle={onUpdatePreviewAngle}
          onUpdateNoteFontSize={onUpdateNoteFontSize}
          onUpdateNoteColor={onUpdateNoteColor}
          onUpdateNoteContent={onUpdateNoteContent}
          onDeleteNote={onDeleteNote}
          highlights={adjustedHighlights}
          onRemoveHighlight={onRemoveHighlight}
          onAddNoteForHighlight={onAddNoteForHighlight}
          onToggleNoteCollapsed={onToggleNoteCollapsed}
          hoveredHighlightId={hoveredHighlightId}
        />
      </div>
    </>
  );
}

export default ExamRenderer;

// Per-note color palette. Each scheme drives: the highlight rect bg, the X
// delete button, the note editor + sticky preview backgrounds, and the
// preview's tail triangle. Stored as `note.color` (key from this list);
// missing = default yellow. The four 100/400/900-shade families cover the
// "chat bubble" use case without becoming a rainbow.
const NOTE_COLORS = [
  { key: "yellow", label: "Yellow", swatch: "#facc15", editorBg: "rgba(254, 252, 232, 0.95)", border: "rgba(250, 204, 21, 0.7)", rectBg: "rgba(254, 240, 138, 0.7)", text: "#713f12" },
  { key: "pink",   label: "Pink",   swatch: "#f472b6", editorBg: "rgba(253, 242, 248, 0.95)", border: "rgba(244, 114, 182, 0.7)", rectBg: "rgba(251, 207, 232, 0.7)", text: "#831843" },
  { key: "sky",    label: "Sky",    swatch: "#38bdf8", editorBg: "rgba(240, 249, 255, 0.95)", border: "rgba(56, 189, 248, 0.7)",  rectBg: "rgba(186, 230, 253, 0.7)", text: "#0c4a6e" },
  { key: "green",  label: "Green",  swatch: "#34d399", editorBg: "rgba(240, 253, 244, 0.95)", border: "rgba(52, 211, 153, 0.7)",  rectBg: "rgba(167, 243, 208, 0.7)", text: "#064e3b" },
];
const NOTE_COLOR_BY_KEY = Object.fromEntries(NOTE_COLORS.map((c) => [c.key, c]));
const DEFAULT_NOTE_COLOR = NOTE_COLORS[0];
const getNoteColor = (note) => NOTE_COLOR_BY_KEY[note?.color] || DEFAULT_NOTE_COLOR;

const ExamFloatingTools = ({
  notes = [],
  onUpdateNotePosition,
  onUpdatePreviewAngle,
  onUpdateNoteFontSize,
  onUpdateNoteColor,
  onUpdateNoteContent,
  onDeleteNote,
  highlights = [],
  onRemoveHighlight,
  onAddNoteForHighlight,
  onToggleNoteCollapsed,
  hoveredHighlightId,
}) => {
  const highlightIds = React.useMemo(() => {
    const set = new Set();
    if (!Array.isArray(highlights)) {
      return set;
    }
    highlights.forEach((highlight) => {
      if (highlight?.id) {
        set.add(highlight.id);
      }
    });
    return set;
  }, [highlights]);

  const notesByHighlight = React.useMemo(() => {
    const map = new Map();
    if (!Array.isArray(notes)) {
      return map;
    }
    notes.forEach((note) => {
      if (note?.highlightId) {
        map.set(note.highlightId, note);
      }
    });
    return map;
  }, [notes]);

  const collapsedNotesWithoutHighlight = React.useMemo(() => {
    if (!Array.isArray(notes)) {
      return [];
    }
    return notes.filter(
      (note) => note?.isCollapsed && (!note.highlightId || !highlightIds.has(note.highlightId))
    );
  }, [notes, highlightIds]);

  const expandedNotes = React.useMemo(() => {
    if (!Array.isArray(notes)) {
      return [];
    }
    return notes.filter((note) => !note?.isCollapsed);
  }, [notes]);

  return (
    <>
      {Array.isArray(highlights) &&
        highlights.map((highlight) => {
          const noteForHighlight = notesByHighlight.get(highlight.id) || null;
          const colorScheme = getNoteColor(noteForHighlight);
          const showPreview =
            noteForHighlight &&
            noteForHighlight.isCollapsed &&
            typeof noteForHighlight.content === "string" &&
            noteForHighlight.content.trim().length > 0;
          return (
            <React.Fragment key={highlight.id}>
              <HighlightOverlay
                highlight={highlight}
                isHovered={hoveredHighlightId === highlight.id}
                hasNote={!!noteForHighlight}
                onRemove={onRemoveHighlight}
                onAddNote={onAddNoteForHighlight}
                colorScheme={colorScheme}
              />
              {showPreview && (
                <StickyNotePreview
                  note={noteForHighlight}
                  highlight={highlight}
                  onUpdatePreviewAngle={onUpdatePreviewAngle}
                  colorScheme={colorScheme}
                />
              )}
            </React.Fragment>
          );
        })}

      {collapsedNotesWithoutHighlight.map((note) => (
        <CollapsedNoteDot
          key={`${note.id}-collapsed`}
          note={note}
          onExpand={() => onToggleNoteCollapsed?.(note.id, false)}
        />
      ))}

      {expandedNotes.map((note) => (
        <DraggableNote
          key={note.id}
          note={note}
          colorScheme={getNoteColor(note)}
          onUpdateNotePosition={onUpdateNotePosition}
          onUpdateNoteContent={onUpdateNoteContent}
          onUpdateNoteFontSize={onUpdateNoteFontSize}
          onUpdateNoteColor={onUpdateNoteColor}
          onDeleteNote={onDeleteNote}
          onToggleNoteCollapsed={onToggleNoteCollapsed}
        />
      ))}
    </>
  );
};

const NoteIcon = ({ className = "" }) => (
  <svg
    viewBox="0 0 24 24"
    xmlns="http://www.w3.org/2000/svg"
    className={className}
    aria-hidden="true"
  >
    <path
      d="M7.4 3h7.9L20 7.7V18.6A2.4 2.4 0 0117.6 21H7.4A2.4 2.4 0 015 18.6V5.4A2.4 2.4 0 017.4 3z"
      fill="currentColor"
      fillOpacity="0.88"
    />
    <path
      d="M15.3 3v3.3a1.4 1.4 0 001.4 1.4H20"
      stroke="currentColor"
      strokeWidth="1.3"
      strokeLinecap="round"
      strokeLinejoin="round"
      opacity="0.7"
    />
    <path
      d="M8.6 11.6h6.3"
      stroke="currentColor"
      strokeWidth="1.3"
      strokeLinecap="round"
    />
    <path
      d="M8.6 15.2h4.3"
      stroke="currentColor"
      strokeWidth="1.3"
      strokeLinecap="round"
      opacity="0.85"
    />
  </svg>
);

const HighlightOverlay = ({
  highlight,
  isHovered = false,
  hasNote = false,
  onRemove,
  onAddNote,
  colorScheme = DEFAULT_NOTE_COLOR,
}) => {
  if (!highlight || !Array.isArray(highlight.rects)) return null;

  const container =
    typeof document !== "undefined" && highlight.surfaceId
      ? document.querySelector(
        `[data-highlight-surface-id="${highlight.surfaceId}"]`
      )
      : null;

  if (!container) return null;

  const firstRect = highlight.rects[0];
  const containerWidth = container?.clientWidth || null;
  const canRemove = typeof onRemove === "function";
  const canAddNote = typeof onAddNote === "function" && !hasNote;

  // Position the X mostly outside the top-right corner of the first rect.
  // Only the bottom-left ~3px of the button overlaps the highlight, so the
  // yellow corner is just kissed — minimal intrusion on the highlighted text.
  // The add-note affordance sits just to the left of the X, sharing the same
  // top edge.
  const X_SIZE = 18;
  let deleteStyle = null;
  let addNoteStyle = null;
  if (firstRect) {
    const baseLeft = firstRect.x + firstRect.width - 3;
    const baseTop = firstRect.y - X_SIZE + 3;
    const top = Math.max(baseTop, 0);
    const maxLeft = containerWidth != null ? Math.max(containerWidth - X_SIZE, 0) : null;
    const clampedLeft = maxLeft != null ? Math.min(Math.max(baseLeft, 0), maxLeft) : Math.max(baseLeft, 0);
    deleteStyle = { left: clampedLeft, top };
    addNoteStyle = { left: Math.max(clampedLeft - (X_SIZE + 4), 0), top };
  }

  // The affordances are revealed on hover only: invisible + non-interactive at
  // rest so they never block text selection over the highlighted passage. The
  // hover keepalive in useHighlightInteraction (300ms) keeps them reachable.
  const affordanceVisibility = {
    opacity: isHovered ? 1 : 0,
    pointerEvents: isHovered ? "auto" : "none",
    transition: "opacity 150ms ease",
  };

  return createPortal(
    <>
      {highlight.rects.map((rect, index) => (
        <div
          key={`${highlight.id}-rect-${index}`}
          className="pointer-events-none absolute z-exam-highlight !m-0 rounded mix-blend-multiply"
          style={{
            left: rect.x,
            top: rect.y,
            width: rect.width,
            height: rect.height,
            backgroundColor: colorScheme.rectBg,
            boxShadow: isHovered ? `0 0 0 2px ${colorScheme.swatch}` : "none",
          }}
        />
      ))}
      {canAddNote && firstRect && (
        <button
          type="button"
          data-highlight-addnote="true"
          data-highlight-id={highlight.id}
          onClick={(event) => {
            event.stopPropagation();
            onAddNote(highlight);
          }}
          className="absolute z-exam-highlight-delete flex h-[18px] w-[18px] items-center justify-center rounded-full border shadow-sm focus-visible:outline-none focus-visible:ring-2"
          style={{
            ...(addNoteStyle || {}),
            ...affordanceVisibility,
            backgroundColor: colorScheme.editorBg,
            borderColor: colorScheme.swatch,
            color: colorScheme.text,
          }}
          aria-label="Add note"
          title="Add note"
        >
          <NoteIcon className="h-3 w-3" />
        </button>
      )}
      {canRemove && firstRect && (
        <button
          type="button"
          data-highlight-delete="true"
          data-highlight-id={highlight.id}
          onClick={(event) => {
            event.stopPropagation();
            onRemove(highlight.id);
          }}
          className="absolute z-exam-highlight-delete flex h-[18px] w-[18px] items-center justify-center rounded-full border text-xs font-bold shadow-sm focus-visible:outline-none focus-visible:ring-2"
          style={{
            ...(deleteStyle || {}),
            ...affordanceVisibility,
            backgroundColor: colorScheme.swatch,
            borderColor: colorScheme.swatch,
            color: colorScheme.text,
          }}
          aria-label="Delete highlight"
          title="Delete highlight"
        >
          ×
        </button>
      )}
    </>,
    container
  );
};

const PREVIEW_TAIL_BASE = 12;
const PREVIEW_TAIL_HEIGHT = 8;

const StickyNotePreview = ({ note, highlight, onUpdatePreviewAngle, colorScheme = DEFAULT_NOTE_COLOR }) => {
  const previewRef = useRef(null);
  const [previewSize, setPreviewSize] = useState({ w: 80, h: 36 });
  const previewFontSize = typeof note?.fontSize === "number" ? note.fontSize : NOTE_FONT_DEFAULT;

  // Measure rendered size whenever the text or font size changes — content-
  // sized, so width/height depend on both. Synchronous (useLayoutEffect)
  // prevents a flicker frame where position would be computed against the
  // wrong size.
  React.useLayoutEffect(() => {
    const el = previewRef.current;
    if (!el) return;
    const w = el.offsetWidth;
    const h = el.offsetHeight;
    setPreviewSize((prev) => (prev.w === w && prev.h === h ? prev : { w, h }));
  }, [note?.content, previewFontSize]);

  if (!note || !highlight) return null;
  if (typeof note.content !== "string" || note.content.trim().length === 0) return null;

  const container =
    typeof document !== "undefined" && highlight.surfaceId
      ? document.querySelector(`[data-highlight-surface-id="${highlight.surfaceId}"]`)
      : null;
  if (!container) return null;

  const rects = Array.isArray(highlight.rects) ? highlight.rects : [];
  if (rects.length === 0) return null;

  const minX = Math.min(...rects.map((r) => r.x));
  const maxX = Math.max(...rects.map((r) => r.x + r.width));
  const minY = Math.min(...rects.map((r) => r.y));
  const maxY = Math.max(...rects.map((r) => r.y + r.height));

  const hx = (minX + maxX) / 2;
  const hy = (minY + maxY) / 2;
  const hw = (maxX - minX) / 2;
  const hh = (maxY - minY) / 2;
  const GAP = 12;

  // Default angle = π/2 (preview sits below the highlight).
  const angle = typeof note.previewAngle === "number" ? note.previewAngle : Math.PI / 2;

  // Preview center lies on an ellipse around the highlight, sized so the
  // preview's edges clear the highlight by `GAP` at the four cardinal points.
  const radiusX = hw + previewSize.w / 2 + GAP;
  const radiusY = hh + previewSize.h / 2 + GAP;
  const centerX = hx + radiusX * Math.cos(angle);
  const centerY = hy + radiusY * Math.sin(angle);
  const renderX = centerX - previewSize.w / 2;
  const renderY = centerY - previewSize.h / 2;

  const handlePointerDown = (event) => {
    if (typeof onUpdatePreviewAngle !== "function") return;
    event.preventDefault();
    event.stopPropagation();

    const onMove = (moveEvent) => {
      moveEvent.preventDefault();
      // Recompute the highlight's viewport center per-move so the orbit stays
      // correct if the surface scrolls during the drag.
      const surfaceRect = container.getBoundingClientRect();
      const scrollLeft = container.scrollLeft || 0;
      const scrollTop = container.scrollTop || 0;
      const hxViewport = surfaceRect.left + hx - scrollLeft;
      const hyViewport = surfaceRect.top + hy - scrollTop;
      const dx = moveEvent.clientX - hxViewport;
      const dy = moveEvent.clientY - hyViewport;
      if (dx === 0 && dy === 0) return;
      onUpdatePreviewAngle(note.id, Math.atan2(dy, dx));
    };
    const onUp = () => {
      window.removeEventListener("pointermove", onMove);
      window.removeEventListener("pointerup", onUp);
      window.removeEventListener("pointercancel", onUp);
    };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    window.addEventListener("pointercancel", onUp);
  };

  const preview = note.content.length > 200 ? `${note.content.slice(0, 200)}…` : note.content;

  // Tail triangle pointing back at the highlight.
  // tailAngle = direction from the preview's center to the highlight's center.
  // Place the triangle's center on the preview's rectangular border at that
  // angle, then nudge outward by half the triangle's height so the base sits
  // flush with the border and the apex pokes out toward the highlight.
  const tailAngle = angle + Math.PI;
  const tailCos = Math.cos(tailAngle);
  const tailSin = Math.sin(tailAngle);
  const halfW = Math.max(previewSize.w / 2, 1);
  const halfH = Math.max(previewSize.h / 2, 1);
  const tBoundX = Math.abs(tailCos) > 1e-6 ? Math.abs(halfW / tailCos) : Infinity;
  const tBoundY = Math.abs(tailSin) > 1e-6 ? Math.abs(halfH / tailSin) : Infinity;
  const tBound = Math.min(tBoundX, tBoundY);
  const tailRadius = tBound + PREVIEW_TAIL_HEIGHT / 2;
  const tailOffsetX = tailRadius * tailCos;
  const tailOffsetY = tailRadius * tailSin;
  // CSS rotate(0deg) draws the border-triangle pointing up (math angle -π/2),
  // so add π/2 to align math direction with CSS rotation.
  const tailCssDeg = (tailAngle + Math.PI / 2) * (180 / Math.PI);

  return createPortal(
    <div
      ref={previewRef}
      data-sticky-preview="true"
      data-note-id={note.id}
      className="absolute z-exam-note-preview inline-block w-max cursor-grab select-none whitespace-pre-wrap break-words rounded-lg border px-3 py-2 font-medium leading-snug shadow-md backdrop-blur active:cursor-grabbing"
      style={{
        left: renderX,
        top: renderY,
        maxWidth: 280,
        fontSize: previewFontSize,
        backgroundColor: colorScheme.editorBg,
        borderColor: colorScheme.border,
        color: colorScheme.text,
      }}
      onPointerDown={handlePointerDown}
    >
      {preview}
      <span
        aria-hidden="true"
        className="pointer-events-none absolute"
        style={{
          left: `calc(50% + ${tailOffsetX - PREVIEW_TAIL_BASE / 2}px)`,
          top: `calc(50% + ${tailOffsetY - PREVIEW_TAIL_HEIGHT / 2}px)`,
          width: 0,
          height: 0,
          borderLeftWidth: PREVIEW_TAIL_BASE / 2,
          borderRightWidth: PREVIEW_TAIL_BASE / 2,
          borderBottomWidth: PREVIEW_TAIL_HEIGHT,
          borderLeftColor: "transparent",
          borderRightColor: "transparent",
          borderBottomColor: colorScheme.border,
          borderStyle: "solid",
          transform: `rotate(${tailCssDeg}deg)`,
          transformOrigin: "center center",
        }}
      />
    </div>,
    container
  );
};

const NOTE_FONT_DEFAULT = 14;
const NOTE_FONT_MIN = 10;
const NOTE_FONT_MAX = 24;
const NOTE_FONT_STEP = 2;

const DraggableNote = ({
  note,
  colorScheme = DEFAULT_NOTE_COLOR,
  onUpdateNotePosition,
  onUpdateNoteContent,
  onUpdateNoteFontSize,
  onUpdateNoteColor,
  onDeleteNote,
  onToggleNoteCollapsed,
}) => {
  const noteRef = useRef(null);

  // Gentle entrance: the editor is a large panel, so popping it in at full size
  // the instant a highlight is clicked feels jarring and blocks the page before
  // the student registers what appeared. Scale + fade it in from the highlight
  // corner over ~170ms so it grows into view instead.
  const [entered, setEntered] = useState(false);
  useEffect(() => {
    const raf = requestAnimationFrame(() => setEntered(true));
    return () => cancelAnimationFrame(raf);
  }, []);

  // Local draft state for the textarea. The parent → adjustedNotes pipe lags by
  // one render after each keystroke, which would otherwise reset the controlled
  // value mid-edit and snap the cursor to the end (preventing mid-string typing).
  const [draftContent, setDraftContent] = useState(note?.content ?? "");
  const lastExternalContentRef = useRef(note?.content ?? "");

  useEffect(() => {
    const incoming = note?.content ?? "";
    if (incoming !== lastExternalContentRef.current) {
      lastExternalContentRef.current = incoming;
      setDraftContent(incoming);
    }
  }, [note?.content]);

  if (!note) return null;

  const { id, x = 160, y = 180 } = note;
  const fontSize = typeof note.fontSize === "number" ? note.fontSize : NOTE_FONT_DEFAULT;

  const handleContentChange = (event) => {
    const next = event.target.value;
    setDraftContent(next);
    lastExternalContentRef.current = next;
    onUpdateNoteContent?.(id, next);
  };

  // Enter saves+closes; Shift+Enter inserts a newline (standard textarea pattern).
  const handleContentKeyDown = (event) => {
    if (event.key === "Enter" && !event.shiftKey) {
      event.preventDefault();
      onToggleNoteCollapsed?.(id, true);
    }
  };

  const adjustFontSize = (delta) => {
    const next = Math.max(NOTE_FONT_MIN, Math.min(NOTE_FONT_MAX, fontSize + delta));
    if (next !== fontSize) onUpdateNoteFontSize?.(id, next);
  };

  const handlePointerDown = (event) => {
    if (typeof onUpdateNotePosition !== "function") return;
    event.preventDefault();

    const startX = event.clientX;
    const startY = event.clientY;
    const offsetX = startX - x;
    const offsetY = startY - y;

    const handlePointerMove = (moveEvent) => {
      moveEvent.preventDefault();
      onUpdateNotePosition(id, moveEvent.clientX - offsetX, moveEvent.clientY - offsetY);
    };

    const handlePointerUp = () => {
      window.removeEventListener("pointermove", handlePointerMove);
      window.removeEventListener("pointerup", handlePointerUp);
      window.removeEventListener("pointercancel", handlePointerUp);
    };

    window.addEventListener("pointermove", handlePointerMove);
    window.addEventListener("pointerup", handlePointerUp);
    window.addEventListener("pointercancel", handlePointerUp);
  };

  return (
    <div
      ref={noteRef}
      role="region"
      aria-label="Sticky note editor"
      className="group/note fixed z-exam-note-editor flex flex-col overflow-hidden rounded-xl border p-2 shadow-[0_14px_28px_-16px_rgba(180,137,14,0.65)] backdrop-blur"
      style={{
        left: x,
        top: y,
        width: 320,
        height: 220,
        minWidth: 220,
        minHeight: 140,
        resize: 'both',
        backgroundColor: colorScheme.editorBg,
        borderColor: colorScheme.border,
        color: colorScheme.text,
        opacity: entered ? 1 : 0,
        transform: entered ? 'scale(1)' : 'scale(0.94)',
        transformOrigin: 'top left',
        transition: 'opacity 170ms ease-out, transform 170ms cubic-bezier(0.22, 1, 0.36, 1)',
      }}
      data-note-id={id}
    >
      <div className="flex shrink-0 items-center justify-between text-xs font-semibold">
        <div className="flex items-center gap-1">
          <button
            type="button"
            className="cursor-move rounded px-1 text-[11px] uppercase tracking-wide"
            onPointerDown={handlePointerDown}
            title="Drag to move"
          >
            Note
          </button>
          <button
            type="button"
            onPointerDown={(event) => event.stopPropagation()}
            onClick={() => adjustFontSize(-NOTE_FONT_STEP)}
            disabled={fontSize <= NOTE_FONT_MIN}
            className="flex h-5 w-5 items-center justify-center rounded text-[11px] transition hover:bg-black/5 disabled:opacity-30 disabled:cursor-not-allowed"
            aria-label="Decrease note font size"
            title="Decrease font size"
          >
            A−
          </button>
          <button
            type="button"
            onPointerDown={(event) => event.stopPropagation()}
            onClick={() => adjustFontSize(NOTE_FONT_STEP)}
            disabled={fontSize >= NOTE_FONT_MAX}
            className="flex h-5 w-5 items-center justify-center rounded text-[13px] transition hover:bg-black/5 disabled:opacity-30 disabled:cursor-not-allowed"
            aria-label="Increase note font size"
            title="Increase font size"
          >
            A+
          </button>
          <span className="mx-0.5 h-3 w-px bg-black/10" aria-hidden="true" />
          {NOTE_COLORS.map((c) => {
            const active = c.key === colorScheme.key;
            return (
              <button
                key={c.key}
                type="button"
                onPointerDown={(event) => event.stopPropagation()}
                onClick={() => onUpdateNoteColor?.(id, c.key)}
                className="h-3.5 w-3.5 rounded-full border transition hover:scale-110"
                style={{
                  backgroundColor: c.swatch,
                  borderColor: c.border,
                  outline: active ? `2px solid ${c.text}` : "none",
                  outlineOffset: 1,
                }}
                aria-label={`Set color to ${c.label}`}
                title={c.label}
              />
            );
          })}
        </div>
        <div className="flex items-center gap-1 opacity-0 transition group-hover/note:opacity-100">
          <button
            type="button"
            onPointerDown={(event) => event.stopPropagation()}
            onClick={() => onToggleNoteCollapsed?.(id, true)}
            className="rounded px-1 text-xs transition hover:bg-black/5"
            aria-label="Collapse note"
            title="Collapse note"
          >
            ✔
          </button>
          <button
            type="button"
            onPointerDown={(event) => event.stopPropagation()}
            onClick={() => onDeleteNote?.(id)}
            className="rounded px-1 text-xs transition hover:bg-black/5"
            aria-label="Remove note"
            title="Remove note"
          >
            ✕
          </button>
        </div>
      </div>
      <textarea
        className="mt-2 w-full flex-1 min-h-0 resize-none rounded-lg border px-2 py-1.5 leading-snug focus:outline-none focus:ring-2"
        style={{
          fontSize,
          backgroundColor: colorScheme.rectBg,
          borderColor: colorScheme.border,
          color: colorScheme.text,
        }}
        value={draftContent}
        onChange={handleContentChange}
        onKeyDown={handleContentKeyDown}
        placeholder="Type your note..."
        autoFocus
      />
    </div>
  );
};

const CollapsedNoteDot = ({ note, onExpand }) => {
  if (!note) return null;

  const handleClick = () => onExpand?.();

  const dot = (
    <button
      type="button"
      className="flex h-6 w-6 items-center justify-center rounded-full border border-yellow-500/70 bg-yellow-300 text-yellow-900 shadow-[0_6px_12px_-6px_rgba(180,137,14,0.8)] transition hover:scale-110 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-yellow-400"
      onClick={handleClick}
      aria-label="Expand note"
      title="Expand note"
    >
      <NoteIcon className="h-3.5 w-3.5" />
    </button>
  );

  if (note.anchor?.surfaceId) {
    const container =
      typeof document !== "undefined"
        ? document.querySelector(
          `[data-highlight-surface-id="${note.anchor.surfaceId}"]`
        )
        : null;
    if (container) {
      const maxLeft = Math.max((container.scrollWidth || 0) - 20, 0);
      const left = Math.max(
        Math.min((note.anchor.x ?? 0), maxLeft),
        0
      );
      const verticalSource =
        (typeof note.anchor.y === "number" ? note.anchor.y : null) ??
        note.anchor.baseline ??
        0;
      const top = Math.max(
        Math.min(verticalSource - 25, container.scrollHeight - 25),
        0
      );
      return createPortal(
        <div
          className="absolute z-exam-note-dot"
          style={{ left, top }}
          data-note-anchor={note.id}
        >
          {dot}
        </div>,
        container
      );
    }
  }

  return (
    <div
      className="fixed z-exam-note-dot"
      style={{
        left: Math.max((note.x ?? 0) - 10, 0),
        top: Math.max((note.y ?? 0) - 6, 0),
      }}
      data-note-anchor={note.id}
    >
      {dot}
    </div>
  );
};

