export function startOfToday() {
  const n = new Date();
  return new Date(n.getFullYear(), n.getMonth(), n.getDate());
}

export function toISO(d) {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return `${y}-${m}-${day}`;
}

export function monthLabel(year, month) {
  return `Tháng ${month + 1}, ${year}`;
}

// Monday-first grid. Leading nulls pad to the first weekday; trailing nulls
// complete the last week so the CSS grid stays rectangular.
export function buildMonthGrid(year, month) {
  const daysInMonth = new Date(year, month + 1, 0).getDate();
  const firstDow = (new Date(year, month, 1).getDay() + 6) % 7; // Mon=0 … Sun=6
  const cells = [];
  for (let i = 0; i < firstDow; i++) cells.push(null);
  for (let d = 1; d <= daysInMonth; d++) {
    cells.push({ day: d, iso: toISO(new Date(year, month, d)) });
  }
  while (cells.length % 7 !== 0) cells.push(null);
  return cells;
}

// Inclusive ISO range. 'YYYY-MM-DD' strings compare correctly lexicographically,
// so this also works across a month boundary.
export function isoRange(a, b) {
  const [lo, hi] = a <= b ? [a, b] : [b, a];
  const out = [];
  const cur = new Date(lo + 'T00:00:00');
  const end = new Date(hi + 'T00:00:00');
  while (cur <= end) {
    out.push(toISO(cur));
    cur.setDate(cur.getDate() + 1);
  }
  return out;
}

export function formatISOVi(iso) {
  const [y, m, d] = iso.split('-');
  return `${d}/${m}/${y}`;
}

// --- Persistence -----------------------------------------------------------
// Calls the `createConsultationLead` Cloud Function (region asia-southeast1 — must
// match the deployed function), which writes the lead doc and fans out the
// Resend + Telegram + FCM notifications.
export async function submitBooking(payload) {
  // Mint a fresh reCAPTCHA Enterprise token at submit time (single-use, ~2-min TTL). Null on
  // failure — the CF is log-only in Phase 1, so a missing token never blocks the booking.
  const recaptchaToken = await executeBookingRecaptcha('booking_submit');
  const functions = getFunctions(getApp(), 'asia-southeast1');
  const call = httpsCallable(functions, 'createConsultationLead');
  const res = await call({ ...payload, recaptchaToken });
  return res.data; // { ok, id }
}

// Best-effort EARLY capture: the moment the 3 required fields exist (user advanced past
// the info step via either choice), write lead_booking/{candidateId} with status
// 'pending' so sales can follow up even if the booking is abandoned. `createConsultationLead`
// later reconciles the SAME doc (keyed by candidateId) → status 'new'. Fire-and-forget —
// callers should .catch() and never block the UI on it.
export async function savePendingLead(payload) {
  const recaptchaToken = await executeBookingRecaptcha('booking_pending');
  const functions = getFunctions(getApp(), 'asia-southeast1');
  const call = httpsCallable(functions, 'savePendingLead');
  const res = await call({ ...payload, recaptchaToken });
  return res.data; // { ok, id, status }
}

// --- Test round-trip helpers ----------------------------------------------
export function genCandidateId() {
  return 'wv-' + Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 8);
}

// UTF-8-safe base64 for InformationCollect's ?prefill= param, so the student's
// info carries into the placement test (no retyping) and is tagged with candidateId.
export function toPrefillParam(obj) {
  const bytes = new TextEncoder().encode(JSON.stringify(obj));
  let bin = '';
  bytes.forEach((b) => { bin += String.fromCharCode(b); });
  return btoa(bin);
}

export const LAST_SUBMISSION_KEY = 'wv_last_submission';

// Clear the exam→booking breadcrumb once consumed so it can't re-resolve a later
// visit (e.g. after a reload mid-booking, or the NEXT person booking on this machine)
// against a stale prior submission. This one-shot lifecycle is exactly why we rely on
// the breadcrumb rather than the exam's permanent pending_submission copy.
export function clearSubmissionBreadcrumb() {
  try { localStorage.removeItem(LAST_SUBMISSION_KEY); } catch (e) { /* ignore */ }
}

// True if a placement submission for THIS booking exists (breadcrumb newer than
// `since` = testStartedAt). Used as a belt-and-suspenders gate in handleTest.
//
// `since <= 0` means NO test has started in this booking yet — so nothing can be
// "fresh for this booking", and we MUST return false. Otherwise the `>= since`
// gate degenerates to `>= 0`, which any stale breadcrumb passes — e.g. a prior
// standalone /information-collect test (which never clears wv_last_submission)
// would make a brand-new booking skip the test + savePendingLead and jump
// straight to consult with the just-typed /info data. The since-gate is THE
// defense (Gotcha 5); since=0 must not defeat it.
export function hasFreshPlacementSubmission(since = 0) {
  if (!(since > 0)) return false;
  try {
    const c = JSON.parse(localStorage.getItem(LAST_SUBMISSION_KEY) || 'null');
    return !!(c && c.docId && (c.at || 0) >= since);
  } catch (e) {
    return false;
  }
}

// Detect THIS booking's placement submission via the wv_last_submission breadcrumb
// {docId, at} (written by the exam app on a successful write), gated by `since` so a
// stale prior submission can't false-trigger. We then fetch the LIVE examSubmissions
// doc — deliberately not the exam's permanent local copy, so a second booking on the
// same machine (corrected info / different user) starts clean. Same-origin tabs share
// localStorage + fire 'storage' events, so this covers same-tab return and a crumb
// that landed before mount. Returns an unsubscribe fn.
export function watchForSubmission({ since = 0 } = {}, onFound) {
  let stopped = false;

  const readCrumb = () => {
    if (!(since > 0)) return null; // no test started → any crumb is a stale prior one (see hasFreshPlacementSubmission)
    try {
      const c = JSON.parse(localStorage.getItem(LAST_SUBMISSION_KEY) || 'null');
      return c && c.docId && (c.at || 0) >= since ? c : null;
    } catch (e) {
      return null;
    }
  };

  const resolve = async (crumb) => {
    if (stopped || !crumb) return;
    try {
      const snap = await getDoc(doc(db, 'examSubmissions', crumb.docId));
      if (stopped) return;
      if (snap.exists()) {
        stopped = true;
        window.removeEventListener('storage', onStorage);
        try { console.info('[booking] submission detected →', crumb.docId); } catch (e) { /* noop */ }
        // Pass only the submissionId — the lead stores a POINTER, never a denormalized
        // score copy. Anyone needing the result joins to examSubmissions/{submissionId}
        // (so a later regrade is automatically reflected).
        onFound(snap.id);
      }
    } catch (e) {
      try { console.warn('[booking] resolve failed:', e && e.message); } catch (e2) { /* noop */ }
    }
  };

  const onStorage = (ev) => {
    if (ev.key === LAST_SUBMISSION_KEY) resolve(readCrumb());
  };

  window.addEventListener('storage', onStorage);
  resolve(readCrumb()); // covers same-tab return + a crumb that landed before mount

  return () => { stopped = true; window.removeEventListener('storage', onStorage); };
}

// Email feature flag, read once + cached: config/featureFlag.bookingEmailNotification.
let _emailFlag;
export async function getEmailNotifyFlag() {
  if (_emailFlag !== undefined) return _emailFlag;
  try {
    const snap = await getDoc(doc(db, 'config', 'featureFlag'));
    _emailFlag = !!(snap.exists() && snap.data() && snap.data().bookingEmailNotification === true);
  } catch (e) {
    _emailFlag = false;
  }
  return _emailFlag;
}
