import React, { useMemo, useState, useEffect } from "react";
import { createPortal } from "react-dom";
import AudioPlayer from "react-h5-audio-player";
import "react-h5-audio-player/lib/styles.css";
import QuestionTypePreviewRouter from "../../../components/QuestionTypes/PreviewRouter";
import { getQuestionSlotCount } from "../../../utils/question/questionMetrics";
import { formatAlternatives } from "../../../utils/normalizeAnswer";
import { resolveListeningContainerId } from "../utils/numbering";
import useListeningParts from "./hooks/useListeningParts";
import useAudioPlayer from "./hooks/useAudioPlayer";
import useReadyPopup from "./hooks/useReadyPopup";
import { LAYER } from "../../../styles/layers";

const ListeningSection = ({
  sectionKey,
  section,
  answers = {},
  onAnswerChange,
  reviewMode = false,
  answerKey = {},
  questionResults = {},
  numbering,
  sectionNumberOffset = 0,
  onAudioPlayingChange,
  onReadyPopupChange,
  onActivePartChange,
  focusRequest,
  isPreviewMode: isPreviewModeProp = false,
  restoredListeningPartState = null,
  onListeningPartStateChange,
  listeningRestoreVersion = 0,
}) => {
  const restoredForThisSection =
    restoredListeningPartState?.[sectionKey] || null;

  const audioPlayerRef = React.useRef(null);
  const audioTimestampsRef = React.useRef({});
  const pendingSeekRef = React.useRef(null);

  // Per-part user-placed timestamp markers: { [partIndex]: [{ id, time, label }] }
  const [markersByPart, setMarkersByPart] = useState({});
  // Open right-click menu: { x, y, markerId, mode: 'menu' | 'editing', draftLabel } | null
  const [markerMenu, setMarkerMenu] = useState(null);
  // .rhap_progress-container (20px clickable wrapper) — for event listeners.
  // .rhap_progress-bar (the inner 4px bar with position:relative) — for the portal.
  // Container is position:static, so it can't host absolutely-positioned markers.
  const [progressContainerEl, setProgressContainerEl] = useState(null);
  const [progressBarEl, setProgressBarEl] = useState(null);
  const [audioDuration, setAudioDuration] = useState(0);

  // Check if in preview mode (prop from parent, or URL param / sessionStorage fallback)
  const isPreviewMode = useMemo(() => {
    if (isPreviewModeProp) return true;
    try {
      const params = new URLSearchParams(window.location.search);
      if (params.get("preview") === "true") return true;
      const draftKey = `weaver_preview_draft_${sectionKey?.split("_")[0] || ""}`;
      if (sessionStorage.getItem(draftKey)) return true;
    } catch (e) {}
    return false;
  }, [isPreviewModeProp, sectionKey]);

  const { activePartIndex, setActivePartIndex, completedParts, setCompletedParts, audioParts, currentAudioUrl, isPartLocked } =
    useListeningParts(
      section,
      sectionKey,
      restoredForThisSection,
      isPreviewMode,
      reviewMode,
      onActivePartChange,
      onListeningPartStateChange,
      audioTimestampsRef,
      pendingSeekRef,
      listeningRestoreVersion
    );

  const { showReadyPopup, isVolumeCheckPlaying, handleReadyClick, handleVolumeCheck } =
    useReadyPopup(sectionKey, reviewMode, audioPlayerRef, onReadyPopupChange);

  const { audioPlayed, setAudioPlayed, playbackSpeed, handleSpeedChange, handleAudioPlay, handleAudioPause, handleAudioEnded, SPEED_OPTIONS } =
    useAudioPlayer({
      audioPlayerRef,
      audioTimestampsRef,
      pendingSeekRef,
      audioParts,
      activePartIndex,
      completedParts,
      currentAudioUrl,
      sectionKey,
      setActivePartIndex,
      setCompletedParts,
      isPreviewMode,
      reviewMode,
      showReadyPopup,
      restoredForThisSection,
      onAudioPlayingChange,
      onListeningPartStateChange,
    });

  const handleInputChange = (questionId, value) => {
    onAnswerChange?.(sectionKey, questionId, value);
  };

  // Capture both progress DOM nodes after AudioPlayer mounts (and on remount when src changes).
  // The library's `progressBar` ref points to .rhap_progress-container; the actual bar is a child.
  useEffect(() => {
    setProgressContainerEl(null);
    setProgressBarEl(null);
    const captureNodes = () => {
      let container = audioPlayerRef.current?.progressBar?.current;
      if (!container) {
        const outer = audioPlayerRef.current?.container?.current;
        container = outer?.querySelector?.(".rhap_progress-container") || null;
      }
      if (container) {
        setProgressContainerEl(container);
        const bar = container.querySelector?.(".rhap_progress-bar");
        if (bar) setProgressBarEl(bar);
      }
    };
    captureNodes();
    const t = setTimeout(captureNodes, 0);
    return () => clearTimeout(t);
  }, [currentAudioUrl]);

  // Track audio duration via direct listener — the library's onLoadedMetaData prop
  // is misspelled in our JSX (`onLoadedMetadata`) and never fires. Going direct
  // also handles the cached-audio case where metadata is ready before mount.
  useEffect(() => {
    const audio = audioPlayerRef.current?.audio?.current;
    if (!audio) {
      setAudioDuration(0);
      return undefined;
    }
    const sync = () => {
      if (audio.duration && isFinite(audio.duration)) {
        setAudioDuration(audio.duration);
      }
    };
    sync();
    audio.addEventListener("loadedmetadata", sync);
    audio.addEventListener("durationchange", sync);
    return () => {
      audio.removeEventListener("loadedmetadata", sync);
      audio.removeEventListener("durationchange", sync);
    };
  }, [currentAudioUrl]);

  // Right-click on bar → add marker; right-click on existing marker → remove it.
  // Native contextmenu listener: doesn't conflict with the library's React-bound
  // mousedown seek handler (different event), so seeking still works untouched.
  // Gated on isPreviewMode — in real exam mode the scrubber is locked to prevent
  // rewinding, and click-to-seek markers would defeat that lock.
  // Listeners attach to the .rhap_progress-container (20px hit area), but X→time
  // math uses the inner .rhap_progress-bar's rect since that's what visual % maps to.
  useEffect(() => {
    if (!progressContainerEl || !progressBarEl) return;
    if (!isPreviewMode) return;
    const handler = (e) => {
      e.preventDefault();
      // Always close any open menu first; reopen below if right-click was on a triangle.
      setMarkerMenu(null);
      const audio = audioPlayerRef.current?.audio?.current;
      const duration = audio?.duration;
      if (!duration || !isFinite(duration)) return;

      const triangleEl = e.target?.closest?.("[data-marker-id]");
      if (triangleEl) {
        setMarkerMenu({
          x: e.clientX,
          y: e.clientY,
          markerId: triangleEl.dataset.markerId,
          mode: "menu",
          draftLabel: "",
        });
        return;
      }

      const rect = progressBarEl.getBoundingClientRect();
      const ratio = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
      const time = ratio * duration;
      const id =
        typeof crypto !== "undefined" && crypto.randomUUID
          ? crypto.randomUUID()
          : `m_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
      setMarkersByPart((prev) => {
        const list = prev[activePartIndex] || [];
        return { ...prev, [activePartIndex]: [...list, { id, time }] };
      });
    };
    // Block non-left-click mousedown from reaching the library's seek handler.
    // The library's React mousedown fires for any button, then its window-level
    // mouseup seeks audio — without this, right-click both adds the marker AND
    // seeks. Capture-phase stopPropagation preempts React's delegated listener.
    const blockNonLeftClick = (ev) => {
      if (ev.button !== 0) ev.stopPropagation();
    };

    progressContainerEl.addEventListener("contextmenu", handler);
    progressContainerEl.addEventListener("mousedown", blockNonLeftClick, true);
    return () => {
      progressContainerEl.removeEventListener("contextmenu", handler);
      progressContainerEl.removeEventListener("mousedown", blockNonLeftClick, true);
    };
  }, [progressContainerEl, progressBarEl, activePartIndex, isPreviewMode]);

  const formatMarkerTime = (s) => {
    const m = Math.floor(s / 60);
    const sec = Math.floor(s % 60).toString().padStart(2, "0");
    return `${m}:${sec}`;
  };

  const handleStartLabelEdit = (id) => {
    const current = (markersByPart[activePartIndex] || []).find((m) => m.id === id);
    setMarkerMenu((prev) =>
      prev
        ? { ...prev, mode: "editing", draftLabel: current?.label || "" }
        : prev
    );
  };

  const handleSaveLabel = () => {
    if (!markerMenu || markerMenu.mode !== "editing") return;
    const { markerId, draftLabel } = markerMenu;
    const next = (draftLabel || "").trim();
    setMarkersByPart((prev) => {
      const list = prev[activePartIndex] || [];
      return {
        ...prev,
        [activePartIndex]: list.map((m) =>
          m.id === markerId ? { ...m, label: next } : m
        ),
      };
    });
    setMarkerMenu(null);
  };

  const handleRemoveMarker = (id) => {
    setMarkerMenu(null);
    setMarkersByPart((prev) => {
      const list = prev[activePartIndex] || [];
      return { ...prev, [activePartIndex]: list.filter((m) => m.id !== id) };
    });
  };

  // Close marker menu on outside click or Escape.
  // In editing mode, do NOT attach the mousedown closer — it would unmount the
  // input before its onBlur could fire, dropping the save. The input's onBlur
  // handles outside-click saves in editing mode (blur fires on any focus loss).
  useEffect(() => {
    if (!markerMenu) return undefined;
    const onKey = (e) => {
      if (e.key === "Escape") setMarkerMenu(null);
    };
    document.addEventListener("keydown", onKey);

    let onDown = null;
    if (markerMenu.mode !== "editing") {
      onDown = (e) => {
        if (e.target?.closest?.("[data-marker-menu]")) return;
        setMarkerMenu(null);
      };
      document.addEventListener("mousedown", onDown);
    }

    return () => {
      document.removeEventListener("keydown", onKey);
      if (onDown) document.removeEventListener("mousedown", onDown);
    };
  }, [markerMenu]);

  const groupSlotMetadata = useMemo(() => {
    const groups = Array.isArray(section?.questionGroups)
      ? section.questionGroups
      : [];
    let runningOffset = sectionNumberOffset;

    return groups.map((group, groupIndex) => {
      const questions = Array.isArray(group?.questions) ? group.questions : [];
      const containerId = resolveListeningContainerId(group, groupIndex);

      const range = numbering?.getQuestionRangeForContainer?.(
        sectionKey,
        containerId,
        questions
      );

      if (range) {
        const { start, end, slots } = range;
        const offset =
          typeof start === "number" && !Number.isNaN(start)
            ? start - 1
            : runningOffset;
        const meta = {
          containerId,
          start,
          end,
          slots,
          offset,
        };
        runningOffset = offset + (slots || 0);
        return meta;
      }

      const slots = questions.reduce(
        (sum, question) => sum + getQuestionSlotCount(question),
        0
      );
      const start = slots > 0 ? runningOffset + 1 : null;
      const end = slots > 0 ? runningOffset + slots : null;
      const meta = {
        containerId,
        start,
        end,
        slots,
        offset: runningOffset,
      };
      runningOffset += slots;
      return meta;
    });
  }, [section?.questionGroups, numbering, sectionKey, sectionNumberOffset]);

  const formatRangeLabel = (start, end) => {
    if (typeof start !== "number" || Number.isNaN(start)) return null;
    if (typeof end !== "number" || Number.isNaN(end) || end === start) {
      return `${start}`;
    }
    return `${start}-${end}`;
  };

  const stripPrefix = (text, prefix) => {
    if (!text || !prefix) return text;
    try {
      const escapedPrefix = prefix.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const regex = new RegExp(`^${escapedPrefix}[:.\\-]?\\s*`, "i");
      return text.replace(regex, "");
    } catch (e) {
      return text;
    }
  };

  if (!section) {
    return (
      <div className="flex h-full items-center justify-center bg-white">
        <p className="text-sm text-gray-500">
          Listening content is not available for this exam.
        </p>
      </div>
    );
  }

  return (
    <div className="flex h-full min-h-0 flex-col overflow-hidden bg-white relative">
      {/* Ready Popup Modal — portaled to body. Sticky elements (audio bar) get
          auto-composited by Chrome, which can render them above non-composited
          siblings regardless of logical z-index. translateZ(0) forces this modal
          onto its own composited layer too, making z-index actually decisive. */}
      {showReadyPopup && createPortal(
        <div
          className="fixed inset-0 z-modal flex items-center justify-center"
          style={{
            backgroundColor: "rgba(0, 0, 0, 0.6)",
            backdropFilter: "blur(4px)",
            transform: "translateZ(0)",
            isolation: "isolate",
          }}
        >
          <div className="bg-white rounded-xl shadow-2xl p-8 max-w-md mx-4 text-center">
            <div className="w-16 h-16 mx-auto mb-4 rounded-full bg-orange-100 flex items-center justify-center">
              <svg
                className="w-8 h-8 text-orange-500"
                fill="currentColor"
                viewBox="0 0 24 24"
              >
                <path d="M12 1C7.03 1 3 5.03 3 10v7c0 1.66 1.34 3 3 3h1c.55 0 1-.45 1-1v-6c0-.55-.45-1-1-1H5v-2c0-3.87 3.13-7 7-7s7 3.13 7 7v2h-2c-.55 0-1 .45-1 1v6c0 .55.45 1 1 1h1c1.66 0 3-1.34 3-3v-7c0-4.97-4.03-9-9-9z" />
              </svg>
            </div>
            <h3 className="text-xl font-bold text-gray-900 mb-2">
              Ready to Start?
            </h3>
            <p className="text-gray-600 mb-4 text-sm">
              The audio will play automatically when you click the button below.
              <br />
              Make sure your headphones/speakers are ready.
            </p>

            {/* Check Volume Button */}
            <button
              type="button"
              aria-pressed={isVolumeCheckPlaying}
              onClick={handleVolumeCheck}
              className={`mb-4 flex items-center justify-center gap-2 w-full py-2.5 px-4 rounded-lg border-2 font-semibold transition-all text-sm ${
                isVolumeCheckPlaying
                  ? "bg-blue-50 border-blue-400 text-blue-600"
                  : "bg-white border-gray-200 text-gray-600 hover:border-blue-400 hover:text-blue-600"
              }`}
            >
              {isVolumeCheckPlaying ? (
                <span className="flex items-end gap-[2px] h-5">
                  <style>{`
                    @keyframes soundBarAnim {
                      0%, 100% { transform: scaleY(0.3); }
                      50% { transform: scaleY(1); }
                    }
                  `}</style>
                  <span
                    style={{
                      width: "4px",
                      height: "16px",
                      backgroundColor: "#f97316",
                      borderRadius: "2px",
                      transformOrigin: "bottom",
                      animation:
                        "soundBarAnim 0.5s ease-in-out infinite",
                    }}
                  />
                  <span
                    style={{
                      width: "4px",
                      height: "16px",
                      backgroundColor: "#f97316",
                      borderRadius: "2px",
                      transformOrigin: "bottom",
                      animation:
                        "soundBarAnim 0.5s ease-in-out infinite 0.1s",
                    }}
                  />
                  <span
                    style={{
                      width: "4px",
                      height: "16px",
                      backgroundColor: "#f97316",
                      borderRadius: "2px",
                      transformOrigin: "bottom",
                      animation:
                        "soundBarAnim 0.5s ease-in-out infinite 0.2s",
                    }}
                  />
                  <span
                    style={{
                      width: "4px",
                      height: "16px",
                      backgroundColor: "#f97316",
                      borderRadius: "2px",
                      transformOrigin: "bottom",
                      animation:
                        "soundBarAnim 0.5s ease-in-out infinite 0.3s",
                    }}
                  />
                </span>
              ) : (
                <span className="text-lg">🔊</span>
              )}
              <span>
                {isVolumeCheckPlaying ? "Stop Audio" : "Check Volume"}
              </span>
            </button>

            <button
              onClick={handleReadyClick}
              className="w-full py-3 px-6 bg-orange-500 hover:bg-orange-600 text-white font-semibold rounded-lg transition-colors shadow-lg hover:shadow-xl"
            >
              I'm Ready - Start Listening
            </button>
          </div>
        </div>,
        document.body
      )}

      {/* Scrollable Content */}
      <div
        className={`flex-1 min-h-0 overflow-y-auto bg-white relative ${
          showReadyPopup ? "pointer-events-none" : ""
        }`}
        data-highlight-surface-id="listening-content-surface"
      >
        {/* Header (title + part tabs + intro) - scrolls naturally; only the audio bar below sticks. */}
        <div className="border-b border-gray-200 bg-white px-3 py-2">
          <h2 className="text-base font-bold text-blue-950 text-center uppercase">
            {section.title}
          </h2>

          {/* Audio Part Tabs */}
          {audioParts.length > 1 && (
            <div className="flex items-center justify-center space-x-1 mt-1">
              {audioParts.map((part, idx) => {
                const locked = isPartLocked(idx);
                const active = idx === activePartIndex;

                return (
                  <button
                    key={part.id || idx}
                    onClick={() => {
                      if (locked) return;
                      const savedPos = audioTimestampsRef.current[idx];
                      if (typeof savedPos === "number" && savedPos > 0) {
                        pendingSeekRef.current = savedPos;
                      } else {
                        pendingSeekRef.current = null;
                      }
                      setActivePartIndex(idx);
                      setAudioPlayed(false);
                    }}
                    disabled={locked}
                    style={{
                      backgroundColor: locked
                        ? "#f3f4f6"
                        : active
                        ? "#f97316"
                        : "white",
                      color: locked
                        ? "#9ca3af"
                        : active
                        ? "white"
                        : "#374151",
                      borderColor: locked
                        ? "#e5e7eb"
                        : active
                        ? "#f97316"
                        : "#d1d5db",
                      cursor: locked ? "not-allowed" : "pointer",
                    }}
                    className="px-3 py-0.5 text-[10px] rounded-full border transition-colors font-medium uppercase"
                  >
                    {part.title}
                    {locked && <span className="ml-1">🔒</span>}
                  </button>
                );
              })}
            </div>
          )}

          {section.intro && (
            <p
              className="text-xs text-gray-600 mt-0.5 text-center"
              dangerouslySetInnerHTML={{ __html: section.intro }}
            />
          )}
        </div>

        {/* Sticky audio bar — pinned to top on md+ screens, scrolls naturally on mobile. */}
        <div className="md:sticky md:top-0 md:z-exam-sticky-bar bg-white border-b border-gray-200 px-3 py-2 md:shadow-sm">
          {/* Main Audio Player */}
          {currentAudioUrl && (
            <div className="rounded border border-gray-200 bg-gray-50 p-0.5">
              <style>{`
              .rhap_container .rhap_main-controls button:not(.rhap_play-pause-button),
              .rhap_container .rhap_additional-controls,
              .rhap_container .rhap_repeat-button,
              .rhap_container button[title*="skip"],
              .rhap_container button[title*="rewind"],
              .rhap_container button[title*="forward"],
              .rhap_container button[title*="backward"],
              .rhap_container [aria-label*="skip"],
              .rhap_container [aria-label*="rewind"],
              .rhap_container [aria-label*="forward"],
              .rhap_container button[title*="speed"],
              .rhap_container button[title*="playback"],
              .rhap_container [aria-label*="speed"],
              .rhap_container [aria-label*="playback"],
              .rhap_container button.rhap_skip-button,
              .rhap_container .rhap_skip-button {
                display: none !important;
                visibility: hidden !important;
                pointer-events: none !important;
                width: 0 !important;
                height: 0 !important;
                margin: 0 !important;
                padding: 0 !important;
              }
              .rhap_container .rhap_progress-container {
                ${isPreviewMode ? "" : "pointer-events: none !important; cursor: not-allowed;"}
                opacity: 0.9;
                margin: 0 5px !important;
                height: 20px !important;
              }
              .rhap_container .rhap_progress-bar {
                ${isPreviewMode ? "cursor: pointer !important;" : "cursor: not-allowed !important;"}
                height: 4px !important;
                line-height: 0 !important;
              }
              .rhap_container .rhap_progress-indicator {
                width: 10px !important;
                height: 10px !important;
                top: -3px !important;
              }
              .rhap_container {
                padding: 4px 8px !important;
                box-shadow: none !important;
                background: transparent !important;
              }
              .rhap_container .rhap_volume-controls {
                justify-content: flex-end;
              }
              .rhap_container .rhap_volume-bar-area {
                min-width: 60px;
              }
              .rhap_controls-section {
                flex: none !important;
                margin-right: 5px !important;
              }
              .rhap_main-controls {
                justify-content: center;
              }
              .listening-question-content img {
                width: 100%;
                height: auto;
                object-fit: contain;
                margin: 5px 0;
                display: block;
              }
              .listening-question-content h2,
              .listening-question-content h3,
              .listening-question-content h4 {
                font-weight: 700 !important;
                margin-bottom: 12px;
              }
              ${
                audioPlayed && !isPreviewMode
                  ? `
                .rhap_container .rhap_play-pause-button {
                  pointer-events: none;
                  opacity: 0.3;
                  cursor: not-allowed;
                }
              `
                  : ""
              }
            `}</style>
              <AudioPlayer
                ref={audioPlayerRef}
                key={currentAudioUrl}
                autoPlay={false}
                src={currentAudioUrl}
                onSeek={(audio, newTime) => {
                  // Bypass the library's audio.load() reset path. Without this,
                  // when readyState < HAVE_CURRENT_DATA (common on mobile where
                  // browsers ignore preload=auto), the library reloads the audio
                  // source on every seek — causing the "jump to 0:00 then to
                  // clicked position, ~1s lag" UX. Setting currentTime directly
                  // lets the browser buffer-and-seek without resetting the element.
                  try {
                    audio.currentTime = newTime;
                  } catch (e) {
                    console.warn("Audio seek failed:", e);
                  }
                  return Promise.resolve();
                }}
                onPlay={(e) => {
                  if (isPreviewMode && e?.target)
                    e.target.playbackRate = playbackSpeed;
                  handleAudioPlay();
                }}
                onListen={(e) => {
                  if (
                    e?.target &&
                    typeof e.target.currentTime === "number"
                  ) {
                    const pos = e.target.currentTime;
                    const seekTarget = pendingSeekRef.current;
                    if (seekTarget != null && seekTarget > 0 && Math.abs(pos - seekTarget) < 1) {
                      pendingSeekRef.current = null;
                    }
                    // While a seek is pending, don't overwrite the saved
                    // timestamp with the pre-seek position (which is ~0).
                    if (!seekTarget || seekTarget <= 0 || Math.abs(pos - seekTarget) < 1) {
                      audioTimestampsRef.current[activePartIndex] = pos;
                    }
                  }
                }}
                onLoadedMetadata={(e) => {
                  const seekTarget = pendingSeekRef.current;
                  if (e?.target && seekTarget != null && seekTarget > 0) {
                    e.target.currentTime = seekTarget;
                    console.log(
                      "🎧 [Audio-Seek] Seeking to restored timestamp:",
                      seekTarget
                    );
                  }
                  if (e?.target?.duration && isFinite(e.target.duration)) {
                    setAudioDuration(e.target.duration);
                  }
                }}
                onPause={handleAudioPause}
                onEnded={handleAudioEnded}
                showJumpControls={false}
                customAdditionalControls={[]}
                showDownloadProgress={false}
                showFilledProgress={false}
                layout="horizontal"
                className="!bg-transparent !shadow-none !p-0"
              />
              {isPreviewMode && progressBarEl && audioDuration > 0 &&
                createPortal(
                  <div
                    style={{
                      position: "absolute",
                      inset: 0,
                      pointerEvents: "none",
                    }}
                  >
                    {(markersByPart[activePartIndex] || []).map((m) => (
                      <React.Fragment key={m.id}>
                        {m.label && (
                          <div
                            style={{
                              position: "absolute",
                              left: `${(m.time / audioDuration) * 100}%`,
                              transform: "translateX(-50%)",
                              top: "-30px",
                              background: "#f97316",
                              color: "white",
                              fontSize: "9px",
                              fontWeight: 600,
                              lineHeight: 1.2,
                              padding: "1px 5px",
                              borderRadius: "3px",
                              whiteSpace: "nowrap",
                              maxWidth: "140px",
                              overflow: "hidden",
                              textOverflow: "ellipsis",
                              boxShadow: "0 1px 2px rgba(0,0,0,0.2)",
                              pointerEvents: "none",
                              zIndex: 5,
                            }}
                          >
                            {m.label}
                          </div>
                        )}
                        <button
                          type="button"
                          data-marker-id={m.id}
                          title={
                            m.label
                              ? `${m.label} (${formatMarkerTime(m.time)}) — right-click for options`
                              : `Seek to ${formatMarkerTime(m.time)} — right-click for options`
                          }
                          onMouseDown={(e) => {
                            e.stopPropagation();
                            const audio = audioPlayerRef.current?.audio?.current;
                            if (audio) audio.currentTime = m.time;
                          }}
                          style={{
                            position: "absolute",
                            left: `${(m.time / audioDuration) * 100}%`,
                            transform: "translateX(-50%)",
                            top: "-16px",
                            width: "24px",
                            height: "20px",
                            background: "transparent",
                            border: "none",
                            padding: 0,
                            cursor: "pointer",
                            pointerEvents: "auto",
                            display: "flex",
                            alignItems: "flex-start",
                            justifyContent: "center",
                            zIndex: 4,
                          }}
                        >
                          <span
                            style={{
                              width: 0,
                              height: 0,
                              borderLeft: "7px solid transparent",
                              borderRight: "7px solid transparent",
                              borderTop: "11px solid #f97316",
                              filter: "drop-shadow(0 1px 1px rgba(0,0,0,0.2))",
                              pointerEvents: "none",
                            }}
                          />
                        </button>
                      </React.Fragment>
                    ))}
                  </div>,
                  progressBarEl
                )}
              {markerMenu &&
                createPortal(
                  <div
                    data-marker-menu
                    style={{
                      position: "fixed",
                      left: markerMenu.x,
                      top: markerMenu.y,
                      background: "white",
                      border: "1px solid #d1d5db",
                      borderRadius: "6px",
                      boxShadow: "0 4px 14px rgba(0,0,0,0.15)",
                      zIndex: LAYER.MODAL,
                      padding: markerMenu.mode === "editing" ? "6px" : "4px 0",
                      minWidth: "180px",
                      fontSize: "12px",
                    }}
                  >
                    {markerMenu.mode === "editing" ? (
                      <input
                        type="text"
                        autoFocus
                        value={markerMenu.draftLabel}
                        placeholder="Marker label…"
                        onChange={(e) =>
                          setMarkerMenu((prev) =>
                            prev ? { ...prev, draftLabel: e.target.value } : prev
                          )
                        }
                        onKeyDown={(e) => {
                          if (e.key === "Enter") {
                            e.preventDefault();
                            handleSaveLabel();
                          } else if (e.key === "Escape") {
                            e.preventDefault();
                            setMarkerMenu(null);
                          }
                        }}
                        onBlur={handleSaveLabel}
                        style={{
                          width: "100%",
                          padding: "5px 8px",
                          border: "1px solid #f97316",
                          borderRadius: "4px",
                          outline: "none",
                          fontSize: "12px",
                          color: "#374151",
                          boxSizing: "border-box",
                        }}
                      />
                    ) : (
                      <>
                        <button
                          type="button"
                          onClick={() => handleStartLabelEdit(markerMenu.markerId)}
                          style={{
                            display: "block",
                            width: "100%",
                            textAlign: "left",
                            padding: "6px 12px",
                            background: "transparent",
                            border: "none",
                            cursor: "pointer",
                            color: "#374151",
                          }}
                          onMouseEnter={(e) => (e.currentTarget.style.background = "#f3f4f6")}
                          onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
                        >
                          Label
                        </button>
                        <button
                          type="button"
                          onClick={() => handleRemoveMarker(markerMenu.markerId)}
                          style={{
                            display: "block",
                            width: "100%",
                            textAlign: "left",
                            padding: "6px 12px",
                            background: "transparent",
                            border: "none",
                            cursor: "pointer",
                            color: "#dc2626",
                          }}
                          onMouseEnter={(e) => (e.currentTarget.style.background = "#fef2f2")}
                          onMouseLeave={(e) => (e.currentTarget.style.background = "transparent")}
                        >
                          Remove
                        </button>
                      </>
                    )}
                  </div>,
                  document.body
                )}
              {isPreviewMode && (
                <div className="flex items-center justify-center gap-1 pb-1">
                  {SPEED_OPTIONS.map((speed) => (
                    <button
                      key={speed}
                      onClick={() => handleSpeedChange(speed)}
                      className={`px-2 py-0.5 text-[10px] rounded border font-semibold transition-colors ${
                        playbackSpeed === speed
                          ? "bg-orange-500 text-white border-orange-500"
                          : "bg-white text-gray-600 border-gray-300 hover:border-orange-400 hover:text-orange-500"
                      }`}
                    >
                      {speed}x
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}

          {/* Fallback Audio Preview (if needed) */}
          {section.questionGroups?.[0]?.audioPreviewUrl &&
            !section.questionGroups?.[0]?.audioUrl && (
              <div className="mt-1 rounded border border-gray-200 bg-gray-50 p-0.5">
                <style>{`
              .rhap_container .rhap_main-controls button:not(.rhap_play-pause-button),
              .rhap_container .rhap_additional-controls,
              .rhap_container .rhap_volume-button-down,
              .rhap_container .rhap_volume-button-up {
                display: none !important;
              }
              .rhap_container {
                padding: 4px 8px !important;
                box-shadow: none !important;
                background: transparent !important;
              }
            `}</style>
                <AudioPlayer
                  autoPlay={false}
                  src={section.questionGroups[0].audioPreviewUrl}
                  onPlay={handleAudioPlay}
                  onPause={handleAudioPause}
                  onEnded={handleAudioEnded}
                  showJumpControls={false}
                  customAdditionalControls={[]}
                  customVolumeControls={[]}
                  showDownloadProgress={false}
                  showFilledProgress={false}
                  layout="horizontal-reverse"
                  className="!bg-transparent !shadow-none !p-0"
                />
              </div>
            )}
        </div>

        <div className="space-y-8 px-3 py-2">
          {section.questionGroups
            ?.filter((group, idx) => {
              if (audioParts.length > 1) {
                return idx === activePartIndex;
              }
              return true;
            })
            ?.map((group, filteredIndex) => {
              const groupIndex =
                audioParts.length > 1 ? activePartIndex : filteredIndex;
              const fallbackContainerId = resolveListeningContainerId(
                group,
                groupIndex
              );
              const meta = groupSlotMetadata[groupIndex] || {
                containerId: fallbackContainerId,
                offset: sectionNumberOffset,
                start: null,
                end: null,
                slots: 0,
              };

              const groupStart =
                typeof meta.start === "number" && !Number.isNaN(meta.start)
                  ? meta.start
                  : meta.slots > 0
                  ? meta.offset + 1
                  : null;
              const groupEnd =
                typeof meta.end === "number" && !Number.isNaN(meta.end)
                  ? meta.end
                  : meta.slots > 0
                  ? meta.offset + meta.slots
                  : null;
              const groupRangeLabel = formatRangeLabel(groupStart, groupEnd);
              const groupTitleFallback = groupRangeLabel
                ? `Questions ${groupRangeLabel}`
                : "Questions";

              const rawCustomTitle =
                typeof group?.title === "string" ? group.title.trim() : "";

              const computedRangeHeading = groupRangeLabel
                ? `Questions ${groupRangeLabel}`
                : "";

              let headingLabel = "";
              let secondaryLabel = "";

              if (rawCustomTitle) {
                headingLabel = rawCustomTitle;
                if (
                  computedRangeHeading &&
                  !rawCustomTitle.includes(computedRangeHeading)
                ) {
                  secondaryLabel = computedRangeHeading;
                }
              } else {
                headingLabel = computedRangeHeading || "Questions";
              }
              const containerId = meta.containerId || fallbackContainerId;

              return (
                <article
                  key={group.id || `listening-group-${groupIndex}`}
                  id={`listening-group-${containerId}`}
                  className="space-y-4"
                >
                  <div className="space-y-5">
                    {group.questions?.map((question, index) => {
                      const questionResult =
                        questionResults?.[question.id];
                      const correctAnswers =
                        questionResult?.correctAnswers ||
                        answerKey?.[question.id]?.correctAnswers ||
                        [];
                      const userAnswer = answers[question.id];
                      const formattedUserAnswer = (() => {
                        const slots =
                          questionResult?.subResults?.slots;
                        if (Array.isArray(slots) && slots.length > 0) {
                          return slots.map((s, i) => ({
                            raw: s.userRaw || "",
                            normalized: s.user || "",
                            isCorrect: !!s.isCorrect,
                            isSkipped: !!s.isSkipped,
                            index: i,
                          }));
                        }
                        const fallback = Array.isArray(userAnswer)
                          ? userAnswer
                              .map((entry) => {
                                if (entry == null) return "";
                                if (
                                  typeof entry === "object" &&
                                  entry.error !== undefined &&
                                  entry.correction !== undefined
                                ) {
                                  return `"${entry.error}" → "${entry.correction}"`;
                                }
                                return String(entry).trim();
                              })
                              .filter(Boolean)
                          : userAnswer != null && userAnswer !== ""
                          ? [String(userAnswer)]
                          : [];
                        return fallback.map((r) => ({
                          raw: r,
                          normalized: r,
                          isCorrect: null,
                          isSkipped: false,
                        }));
                      })();
                      const isCorrect =
                        reviewMode && questionResult
                          ? questionResult.isCorrect
                          : null;
                      const cardHighlight = reviewMode
                        ? isCorrect === true
                          ? ""
                          : isCorrect === false
                          ? "border-red-300"
                          : "border-gray-200 bg-gray-50"
                        : "border-gray-200 bg-gray-50";
                      const formattedCorrect = (() => {
                        const slots =
                          questionResult?.subResults?.slots;
                        if (
                          Array.isArray(slots) &&
                          slots.length > 0
                        ) {
                          return slots.map((s) => ({
                            raw:
                              s.expectedRaw ||
                              s.expected ||
                              "",
                            normalized: s.expected || "",
                            isCorrect: !!s.isCorrect,
                          }));
                        }
                        if (
                          Array.isArray(correctAnswers) &&
                          correctAnswers.length > 0
                        ) {
                          return correctAnswers.map((c) => ({
                            raw: c,
                            normalized: c,
                            isCorrect: null,
                          }));
                        }
                        return null;
                      })();
                      const questionName = `${group.id || sectionKey}-${
                        question.id
                      }`;
                      const questionSlotCount =
                        getQuestionSlotCount(question);

                      const slotsBeforeQuestion = (
                        group.questions || []
                      )
                        .slice(0, index)
                        .reduce(
                          (sum, q) =>
                            sum + getQuestionSlotCount(q),
                          0
                        );

                      const fallbackStart =
                        (meta.offset || 0) +
                        slotsBeforeQuestion +
                        1;
                      const fallbackEnd =
                        fallbackStart + questionSlotCount - 1;

                      const questionMeta =
                        numbering?.getQuestionMeta?.(
                          sectionKey,
                          containerId,
                          question.id
                        );

                      const questionStartNumber =
                        questionMeta?.start ?? fallbackStart;
                      const questionEndNumber =
                        questionMeta?.end ?? fallbackEnd;

                      const displayQuestionNumber =
                        formatRangeLabel(
                          questionStartNumber,
                          questionEndNumber
                        ) || `${questionStartNumber}`;

                      const questionRangeLabel =
                        questionSlotCount > 1 && displayQuestionNumber
                          ? `Questions ${displayQuestionNumber}`
                          : `Question ${questionStartNumber}`;
                      const rawDescription =
                        typeof question.description === "string"
                          ? question.description
                          : "";
                      const normalizedDescription =
                        rawDescription.trim();
                      const questionDescription =
                        normalizedDescription &&
                        !/^question\s+\d+/i.test(
                          normalizedDescription
                        )
                          ? rawDescription
                          : questionRangeLabel;
                      const hasImage =
                        question.prompt &&
                        (question.prompt.includes("<img") ||
                          question.prompt.includes(".png") ||
                          question.prompt.includes(".jpg") ||
                          question.prompt.includes(".jpeg"));

                      const renderQuestionInput = (targetQuestion) => (
                        <QuestionTypePreviewRouter
                          question={targetQuestion}
                          value={answers[targetQuestion.id]}
                          onChange={(nextValue) =>
                            handleInputChange(
                              targetQuestion.id,
                              nextValue
                            )
                          }
                          disabled={reviewMode}
                          reviewMode={reviewMode}
                          correctAnswers={
                            targetQuestion.correctAnswers
                          }
                          questionNumber={displayQuestionNumber}
                          name={`${group.id || sectionKey}-${
                            targetQuestion.id
                          }`}
                          sectionKey={sectionKey}
                        />
                      );

                      let displayPrompt = question.prompt;
                      let finalDescription = questionDescription;

                      if (index === 0) {
                        const parts = [];

                        if (headingLabel) {
                          parts.push(
                            `<div class="mb-1 font-bold text-gray-900">${headingLabel}</div>`
                          );
                        }
                        if (secondaryLabel) {
                          parts.push(
                            `<div class="mb-1 font-bold text-gray-900">${secondaryLabel}</div>`
                          );
                        }

                        let textParts = [
                          group.intro,
                          group.instruction,
                        ].filter(Boolean);

                        textParts.forEach((t) => {
                          let clean = t;
                          if (headingLabel)
                            clean = stripPrefix(
                              clean,
                              headingLabel
                            );
                          if (secondaryLabel)
                            clean = stripPrefix(
                              clean,
                              secondaryLabel
                            );
                          if (clean)
                            parts.push(
                              `<div class="mb-2 text-gray-700">${clean}</div>`
                            );
                        });

                        if (questionDescription) {
                          let cleanDesc = questionDescription;
                          if (headingLabel)
                            cleanDesc = stripPrefix(
                              cleanDesc,
                              headingLabel
                            );
                          if (secondaryLabel)
                            cleanDesc = stripPrefix(
                              cleanDesc,
                              secondaryLabel
                            );

                          if (cleanDesc) {
                            const isAlreadyIncluded = parts.some(
                              (p) =>
                                p.includes(`>${cleanDesc}<`)
                            );
                            if (!isAlreadyIncluded) {
                              parts.push(
                                `<div class="mb-2 text-gray-700">${cleanDesc}</div>`
                              );
                            }
                          }
                        }

                        if (parts.length > 0) {
                          finalDescription = parts.join("");
                        }

                        if (displayPrompt) {
                          if (headingLabel)
                            displayPrompt = stripPrefix(
                              displayPrompt,
                              headingLabel
                            );
                          if (secondaryLabel)
                            displayPrompt = stripPrefix(
                              displayPrompt,
                              secondaryLabel
                            );
                        }
                      }

                      return (
                        <div
                          key={question.id}
                          id={`question-${sectionKey}-${question.id}`}
                          className={`rounded-xl border ${cardHighlight} p-4 transition-colors`}
                          tabIndex={-1}
                        >
                          <div
                            className={`flex gap-4 ${
                              hasImage
                                ? "flex-row items-stretch"
                                : "flex-col"
                            }`}
                          >
                            {/* Left Content: Description, Prompt (Image), Note */}
                            <div
                              className={`${
                                hasImage ? "w-[45%]" : "w-full"
                              }`}
                            >
                              <span className="float-left mr-2 mt-0.5 inline-flex h-6 min-w-[2rem] flex-shrink-0 items-center justify-center rounded-full border border-orange-200 bg-orange-50 px-1.5 text-xs font-semibold text-orange-500 shadow-sm">
                                {displayQuestionNumber}
                              </span>
                              <div
                                className="text-sm text-gray-600"
                                dangerouslySetInnerHTML={{
                                  __html: finalDescription,
                                }}
                              />
                              {displayPrompt && (
                                <div
                                  className={`text-sm font-medium text-gray-800 listening-question-content ${
                                    question.description
                                      ? "mt-2"
                                      : ""
                                  } clear-both`}
                                  dangerouslySetInnerHTML={{
                                    __html: displayPrompt,
                                  }}
                                />
                              )}
                              {question.note && (
                                <div className="mt-2 text-xs italic text-gray-500">
                                  {question.note}
                                </div>
                              )}
                            </div>

                            {/* Right Content: Question Inputs */}
                            <div
                              className={`${
                                hasImage
                                  ? "w-[55%] border-l pl-4 border-gray-200"
                                  : "w-full mt-3"
                              } text-xs`}
                            >
                              {(!question.subQuestions ||
                                question.subQuestions.length ===
                                  0 ||
                                question.type ===
                                  "complete-sentences" ||
                                question.type ===
                                  "multiple-choice") &&
                                renderQuestionInput(
                                  question,
                                  index
                                )}

                              {question.subQuestions &&
                                question.subQuestions.length > 0 &&
                                question.type !== "complete-sentences" &&
                                question.type !== "multiple-choice" && (
                                  <div className="space-y-3">
                                    {question.subQuestions.map(
                                      (subQ, subIndex) => (
                                        <div
                                          key={subQ.id}
                                          className="space-y-1"
                                        >
                                          {subQ.prompt && (
                                            <div
                                              className="text-sm font-medium text-gray-800 listening-question-content mb-1"
                                              dangerouslySetInnerHTML={{
                                                __html:
                                                  subQ.prompt,
                                              }}
                                            />
                                          )}
                                          {renderQuestionInput({
                                            ...subQ,
                                            type:
                                              subQ.type ||
                                              question.type,
                                          })}
                                        </div>
                                      )
                                    )}
                                  </div>
                                )}
                            </div>
                          </div>

                          {reviewMode && (
                            <div className="mt-3 space-y-1 text-xs">
                              <p className="text-gray-500">
                                Your answer:{" "}
                                <span className="font-semibold text-gray-700">
                                  {Array.isArray(formattedUserAnswer) ? (
                                    formattedUserAnswer.map(
                                      (slot, idx) => (
                                        <span
                                          key={idx}
                                          className={`${
                                            slot.isCorrect === true
                                              ? "text-green-600"
                                              : slot.isCorrect ===
                                                false
                                              ? "text-red-600"
                                              : slot.isSkipped
                                              ? "text-red-600"
                                              : "text-gray-900"
                                          }`}
                                        >
                                          {slot.raw ||
                                            (slot.isSkipped
                                              ? "Not answered"
                                              : "")}
                                          {idx <
                                          formattedUserAnswer.length -
                                            1
                                            ? " / "
                                            : ""}
                                        </span>
                                      )
                                    )
                                  ) : formattedUserAnswer ? (
                                    formattedUserAnswer
                                  ) : (
                                    <span className="text-red-600">
                                      Not answered
                                    </span>
                                  )}
                                </span>
                              </p>
                              {formattedCorrect && (
                                <p className="text-[#2563eb]">
                                  Correct answer:{" "}
                                  <span className="font-semibold">
                                    {Array.isArray(formattedCorrect) ? (
                                      formattedCorrect.map(
                                        (slot, idx) => (
                                          <span
                                            key={idx}
                                            className="text-[#2563eb]"
                                          >
                                            {formatAlternatives(
                                              slot.raw
                                            )}
                                            {idx <
                                            formattedCorrect.length -
                                              1
                                              ? " / "
                                              : ""}
                                          </span>
                                        )
                                      )
                                    ) : (
                                      formattedCorrect || ""
                                    )}
                                  </span>
                                </p>
                              )}
                            </div>
                          )}
                        </div>
                      );
                    })}
                  </div>
                </article>
              );
            })}
        </div>
      </div>
    </div>
  );
};

export default ListeningSection;
