import React, { useMemo, useContext } from "react";
import { INLINE_BLANK_TOKEN } from "../../../utils/question/questionTokens";
import RegradeContext from "../../../contexts/RegradeContext";
import AnswerKeyEditor from "../_shared/AnswerKeyEditor";
import { normalizeAnswer, matchesAnswer } from "../../../utils/normalizeAnswer";

const ensureArray = (value) => {
  if (Array.isArray(value)) return value;
  if (value === null || value === undefined) return [];
  return [value];
};

const InlineBlankPreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  questionNumber,
  sectionKey = '',
}) => {
  const template = useMemo(() => {
    if (!question) {
      return "";
    }
    if (question.inlineTemplate && question.inlineTemplate.includes(INLINE_BLANK_TOKEN)) {
      return question.inlineTemplate;
    }
    if (question.inlinePrompt) {
      const before = question.inlinePrompt.before || "";
      const after = question.inlinePrompt.after || "";
      return `${before}${INLINE_BLANK_TOKEN}${after}`;
    }
    return question.prompt || "";
  }, [question]);
  const { isRegrade, setKeyEdit } = useContext(RegradeContext);

  if (!question) {
    return null;
  }

  const parts = template.split(INLINE_BLANK_TOKEN);
  const answers = ensureArray(value);
  const fallbackCorrect = Array.isArray(correctAnswers) && correctAnswers.length
    ? correctAnswers
    : Array.isArray(question?.subQuestions)
      ? question.subQuestions.map((sub) => sub?.correctAnswers?.[0] ?? "")
      : [];
  const correct = Array.isArray(fallbackCorrect) ? fallbackCorrect : [fallbackCorrect];

  const isInteractive = typeof onChange === "function";

  const handleBlankChange = (index, nextValue) => {
    if (!isInteractive) return;
    const nextAnswers = [...answers];
    while (nextAnswers.length <= index) {
      nextAnswers.push("");
    }
    nextAnswers[index] = nextValue;
    onChange(nextAnswers);
  };

  const baseNumber = parseInt(String(questionNumber).split("-")[0]) || 1;

  return (
    <div className="text-[15px] leading-relaxed text-slate-700">
      {parts.map((segment, index) => {
        const isLast = index === parts.length - 1;
        const blankValue = answers[index] ?? "";
        const correctValue = correct[index] ?? correct[0] ?? "";
        const normalizedUser = normalizeAnswer(blankValue);
        const hasKey = correctValue !== null && correctValue !== undefined && correctValue !== "";
        // Shared matcher: handles "/" + "|" + bracket variants identically to
        // examScoring.js so review-mode highlighting can't drift from the grader.
        const isCorrectHighlight = reviewMode && hasKey && matchesAnswer(blankValue, correctValue);
        const highlightClass = reviewMode && hasKey
          ? isCorrectHighlight
            ? "border-green-400 bg-green-50 text-green-700"
            : normalizedUser
              ? "border-red-300 bg-red-50 text-red-700"
              : ""
          : "";

        return (
          <React.Fragment key={`inline-part-${index}`}>
            {segment ? <span className="whitespace-pre-wrap" dangerouslySetInnerHTML={{ __html: segment }} /> : null}
            {!isLast ? (
              <span data-answer-blank className="mx-1 inline-flex items-center gap-1 align-baseline">
                <span className="inline-flex h-[18px] min-w-[18px] px-1 flex-shrink-0 items-center justify-center rounded bg-slate-100 text-[10px] font-medium text-slate-500 shadow-sm relative -top-0.5">
                  {`${baseNumber + index}`}
                </span>
                <input
                  type="text"
                  value={blankValue}
                  onChange={(event) => handleBlankChange(index, event.target.value)}
                  disabled={disabled}
                  readOnly={reviewMode || !isInteractive}
                  className={`w-28 border-0 border-b-2 border-slate-300 bg-transparent px-1 pb-0.5 text-center text-[15px] font-medium text-orange-700 transition-colors focus:border-orange-500 focus:outline-none focus:ring-0 ${highlightClass}`}
                  data-question-slot-number={baseNumber + index}
                />
              </span>
            ) : null}
          </React.Fragment>
        );
      })}
      {isRegrade && reviewMode && (
        <AnswerKeyEditor
          correctAnswers={question.correctAnswers}
          questionType={question.type}
          onChange={(patch) => setKeyEdit(sectionKey, question.id, patch)}
        />
      )}
    </div>
  );
};

export default InlineBlankPreview;
