import React, { useContext } from "react";

import { normalizeAnswer, normalizeTFNG, formatTFNG, splitAlternatives } from "../../../utils/normalizeAnswer";
import RegradeContext from "../../../contexts/RegradeContext";
import AnswerKeyEditor from "../_shared/AnswerKeyEditor";


const CompleteSentencesPreview = ({
  question,
  value,
  onChange,
  disabled = false,
  reviewMode = false,
  correctAnswers = [],
  name,
  questionNumber = 1,
  sectionKey = '',
}) => {
  const { isRegrade, setKeyEdit } = useContext(RegradeContext);
  if (!question) {
    return null;
  }

  const subQuestions = Array.isArray(question.subQuestions)
    ? question.subQuestions
    : [];

  if (subQuestions.length === 0) {
    return (
      <div className="rounded border border-dashed border-slate-300 bg-slate-50 px-3 py-2 text-sm text-slate-500">
        Add sentences to complete to preview this question.
      </div>
    );
  }

  const isInteractive = typeof onChange === "function";

  // Handle value as an array of answers (one per sub-question)
  const userAnswers = Array.isArray(value) ? value : [];

  // Parse question number - could be "4" or "4 - 10"
  const startingNumber = typeof questionNumber === "string"
    ? parseInt(String(questionNumber).split(" ")[0]) || 1
    : parseInt(String(questionNumber)) || 1;


  // Build a map from subQuestion index → answer index (skipping examples)
  let answerIndexCounter = 0;
  const answerIndexMap = subQuestions.map(sq => {
    if (sq.isExample) return -1;
    return answerIndexCounter++;
  });

  const handleAnswerChange = (answerIndex, answer) => {
    if (!isInteractive || disabled || (reviewMode)) return;

    const nextAnswers = [...userAnswers];
    nextAnswers[answerIndex] = answer;
    onChange(nextAnswers);
  };

  return (
    <div className="flex flex-col">
      {subQuestions.map((subQuestion, subQuestionIndex) => {
        const answerIndex = answerIndexMap[subQuestionIndex];
        const isExample = !!subQuestion.isExample;

        // ── Example row ───────────────────────────────────────────────
        if (isExample) {
          return (
            <div
              key={`sub-question-${subQuestionIndex}`}
              className="flex items-start gap-3 py-2.5 border-b border-slate-100 last:border-0"
            >
              <span className="inline-flex h-7 min-w-[2.5rem] flex-shrink-0 items-center justify-center rounded bg-blue-100 px-2 text-xs font-semibold text-blue-600">
                Ex.
              </span>
              <div className="flex-1 pt-0.5">
                {subQuestion.prompt && (
                  <span
                    className="text-[15px] text-slate-700 leading-relaxed rich-text-content [&_u]:underline [&_u]:decoration-orange-400 [&_u]:decoration-2 [&_u]:underline-offset-2 [&_s]:line-through [&_s]:text-slate-400"
                    dangerouslySetInnerHTML={{ __html: subQuestion.prompt }}
                  />
                )}
                {subQuestion.exampleAnswer && (
                  <span className="ml-2 inline-flex items-center gap-1 rounded-full bg-green-50 border border-green-200 px-2.5 py-0.5 text-xs font-semibold text-green-700">
                    <svg width="11" height="11" viewBox="0 0 12 12" fill="none" className="flex-shrink-0"><path d="M2 6.5L4.5 9L10 3" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" /></svg>
                    {subQuestion.exampleAnswer}
                  </span>
                )}
              </div>
            </div>
          );
        }

        // ── Regular answerable row ─────────────────────────────────────
        const answerNumber = startingNumber + answerIndex;
        const initialText = subQuestion.initialText || "";
        let userAnswer = userAnswers[answerIndex];
        if (userAnswer === undefined) {
          userAnswer = initialText;
        }
        const normalizedUserAnswer = normalizeAnswer(userAnswer);

        // Get all acceptable answers for this sub-question
        const acceptableAnswers = Array.isArray(subQuestion?.correctAnswers)
          ? subQuestion.correctAnswers.flatMap(a => splitAlternatives(a)).map(normalizeAnswer)
          : [];

        // Fallback to global correctAnswers array if subQuestion doesn't have its own
        const fallbackAnswer = correctAnswers[answerIndex];
        if (acceptableAnswers.length === 0 && fallbackAnswer) {
          if (Array.isArray(fallbackAnswer)) {
            acceptableAnswers.push(...fallbackAnswer.map(normalizeAnswer));
          } else {
            acceptableAnswers.push(normalizeAnswer(fallbackAnswer));
          }
        }

        // Detect if this is likely a TFNG/YNNG question based on correct answers
        const isTFNG = acceptableAnswers.some(a => ["t", "f", "true", "false", "yes", "no", "y", "n", "not given"].includes(a));

        // Check if user answer matches ANY acceptable answer
        const isCorrect = reviewMode && acceptableAnswers.length > 0
          ? (isTFNG
            ? acceptableAnswers.some(a => normalizeTFNG(a) === normalizeTFNG(normalizedUserAnswer))
            : acceptableAnswers.includes(normalizedUserAnswer))
          : false;

        const isIncorrect = reviewMode
          && acceptableAnswers.length > 0
          && normalizedUserAnswer
          && !isCorrect;

        // Display hint if available, otherwise use acceptable answers joined for correction
        const displayCorrectAnswer = subQuestion.correctAnswerHint || acceptableAnswers.map(a => formatTFNG(a)).join(" / ");

        // Auto-capitalize first letter if the expected answer or initialText starts with uppercase
        const firstCorrect = (Array.isArray(subQuestion.correctAnswers) ? subQuestion.correctAnswers[0] : null) || subQuestion.initialText || "";
        const shouldCapitalize = firstCorrect.length > 0 && firstCorrect[0] === firstCorrect[0].toUpperCase() && firstCorrect[0] !== firstCorrect[0].toLowerCase();

        const applyCapitalize = (val) => {
          if (!shouldCapitalize || !val) return val;
          return val.charAt(0).toUpperCase() + val.slice(1);
        };


        const options = subQuestion?.options || question?.options;
        const isSelectBox = Array.isArray(options) && options.length > 0;
        const isReading = String(question?.id).startsWith("reading");
        const forceVertical = isReading && isSelectBox;

        return (
          <div
            key={`sub-question-${subQuestionIndex}`}
            className={`flex flex-col ${forceVertical ? "" : "sm:flex-row"} sm:items-start gap-2 sm:gap-4 py-3 border-b border-slate-100 last:border-0`}
          >
            <div className={`flex items-start gap-3 ${subQuestion?.prompt ? 'w-full' : 'shrink-0'}`}>
              <span className="inline-flex h-7 min-w-[1.75rem] flex-shrink-0 items-center justify-center rounded bg-slate-100 px-2 text-xs font-medium text-slate-600">
                {answerNumber}
              </span>

              {subQuestion?.prompt ? (
                <div
                  className="flex-1 pt-0.5 text-[15px] text-slate-700 leading-relaxed rich-text-content [&_u]:underline [&_u]:decoration-orange-400 [&_u]:decoration-2 [&_u]:underline-offset-2 [&_s]:line-through [&_s]:text-red-400"
                  dangerouslySetInnerHTML={{
                    __html: (() => {
                      // Strip leading number if it matches the computed answerNumber to avoid duplication
                      const promptStr = subQuestion.prompt;
                      const numStr = String(answerNumber);
                      const pattern = new RegExp(`^\\s*${numStr}\\.\\s*`);
                      return promptStr.replace(pattern, '');
                    })()
                  }}
                />
              ) : null}
            </div>

            <div className={`pl-0 w-full ${subQuestion?.prompt && !forceVertical ? 'sm:w-[280px] sm:flex-shrink-0' : 'flex-1'}`}>
              {(() => {
                const baseClasses = `w-full rounded-lg border px-3 py-2 text-sm shadow-sm transition-all focus:outline-none focus:ring-2 ${reviewMode
                  ? isCorrect
                    ? "border-green-400 bg-green-50 focus:ring-green-200"
                    : isIncorrect
                      ? "border-red-300 focus:ring-red-200"
                      : "border-slate-200 focus:ring-blue-200"
                  : "border-slate-200 focus:border-blue-500 focus:ring-blue-200"
                  }`;

                if (isSelectBox) {
                  return (
                    <select
                      value={(() => {
                        // Try to find a matching option case-insensitively
                        const match = options.find(opt => {
                          const optVal = typeof opt === 'object' ? opt.value : opt;
                          return String(optVal).trim().toLowerCase() === String(userAnswer).trim().toLowerCase();
                        });
                        return match !== undefined ? (typeof match === 'object' ? match.value : match) : userAnswer;
                      })()}
                      onChange={(event) =>
                        handleAnswerChange(answerIndex, event.target.value)
                      }
                      disabled={disabled || (reviewMode) || !isInteractive}
                      className={`${baseClasses} appearance-none cursor-pointer bg-white`}
                      data-question-slot-number={answerNumber}
                    >
                      <option value="">Select answer...</option>
                      {options.map((opt) => {
                        const optValue = typeof opt === 'object' ? opt.value : opt;
                        const optLabel = typeof opt === 'object' ? opt.label : opt;
                        // If label already starts with the value (e.g. "a. It was..."), show label only
                        const labelStr = String(optLabel || '');
                        const valueStr = String(optValue || '');
                        const labelStartsWithValue = labelStr.toLowerCase().startsWith(valueStr.toLowerCase() + '.') ||
                          labelStr.toLowerCase().startsWith(valueStr.toLowerCase() + ' ') ||
                          labelStr.toLowerCase().startsWith(valueStr.toLowerCase() + '-');
                        const displayLabel = typeof opt === 'object' && opt.label && opt.value !== opt.label && !labelStartsWithValue
                          ? `${opt.value} - ${opt.label.length > 60 ? opt.label.substring(0, 60) + '...' : opt.label}`
                          : optLabel;
                        return (
                          <option key={optValue} value={optValue}>
                            {displayLabel}
                          </option>
                        );
                      })}
                    </select>
                  );
                }

                const isTextarea = question?.inputMode === "textarea";

                if (isTextarea) {
                  return (
                    <textarea
                      rows={2}
                      value={userAnswer}
                      onChange={(event) =>
                        handleAnswerChange(answerIndex, applyCapitalize(event.target.value))
                      }
                      disabled={disabled || (reviewMode) || !isInteractive}
                      data-testid={`complete-sentences-input-${answerNumber}`}
                      data-question-slot-index={answerIndex}
                      data-question-slot-id={subQuestion?.id || undefined}
                      data-question-slot-number={answerNumber}
                      className={`${baseClasses} resize-y min-h-[60px] leading-relaxed`}
                      placeholder="Type your complete sentence here..."
                    />
                  );
                }

                return (
                  <input
                    type="text"
                    value={userAnswer}
                    onChange={(event) =>
                      handleAnswerChange(answerIndex, applyCapitalize(event.target.value))
                    }
                    disabled={disabled || (reviewMode) || !isInteractive}
                    data-testid={`complete-sentences-input-${answerNumber}`}
                    data-question-slot-index={answerIndex}
                    data-question-slot-id={subQuestion?.id || undefined}
                    data-question-slot-number={answerNumber}
                    className={baseClasses}
                    placeholder="Type your answer"
                  />
                );
              })()}

              {reviewMode && (
                <div className="mt-1 flex items-center gap-2 text-xs">
                  {isCorrect && (
                    <span className="font-semibold text-green-600">
                      ✓ Correct
                    </span>
                  )}
                  {isIncorrect && (
                    <span className="font-semibold text-red-600">
                      ✗ Incorrect (Answer: {displayCorrectAnswer})
                    </span>
                  )}
                </div>
              )}
            </div>
          </div>
        );
      })}
      {isRegrade && reviewMode && (
        <AnswerKeyEditor
          correctAnswers={question.correctAnswers}
          subQuestions={Array.isArray(question.subQuestions) && question.subQuestions.length > 0 ? question.subQuestions : undefined}
          questionType={question.type}
          onChange={(patch) => setKeyEdit(sectionKey, question.id, patch)}
        />
      )}
    </div>
  );
};

export default CompleteSentencesPreview;
